-- =============================================================================
-- 405 — LE CATALOGUE DES CONTRÔLES BLANCS : 2de (maths, musique, physique-chimie, ses, snt, sport, svt)
--
-- 357 sujets écrits d'avance et relus : pour chaque fiche, un sujet
-- Facile, un Moyen, un Difficile, chacun avec son barème sur 20 et son corrigé
-- type (`contenu.corrige`, jamais envoyé à l'élève avant sa copie). L'IA ne fait
-- plus que les corriger ; elle ne rédige que « Un autre sujet ».
--
-- ⚠️ FICHIER GÉNÉRÉ — ne pas éditer à la main. Source : contenu/controles/.
--    Regénérer : node node_modules/jiti/lib/jiti-cli.mjs scripts/controles-sql.ts --num 405 --niveau 2de --matieres maths,musique,physique-chimie,ses,snt,sport,svt
--
--   maths.19r                    60 sujets · 20 fiches
--   musique.15r                   9 sujets · 3 fiches
--   physique-chimie.17ra         36 sujets · 12 fiches
--   physique-chimie.17rb         33 sujets · 11 fiches
--   ses.13ra                     36 sujets · 12 fiches
--   ses.13rb                     33 sujets · 11 fiches
--   snt.18ra                     42 sujets · 14 fiches
--   snt.18rb                     42 sujets · 14 fiches
--   sport.11r                     9 sujets · 3 fiches
--   svt.12a                      30 sujets · 10 fiches
--   svt.12r                      27 sujets · 9 fiches
--
-- L'identifiant d'un sujet est dérivé de (fiche, niveau) : rejouer la migration
-- met le sujet à jour au lieu de le dupliquer. Une fiche absente est sautée.
--
-- PRÉREQUIS : 360 puis 364. Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

INSERT INTO public.chapter_exercices
  (id, chapter_id, style, contenu, difficulte, origine, created_by)
SELECT
  md5('exercice-catalogue:' || v.chapter_id::text || ':' || v.difficulte::text)::uuid,
  v.chapter_id,
  v.style,
  v.contenu,
  v.difficulte,
  'catalogue',
  NULL
FROM (VALUES
  ('fab3ca92-b4d6-53e0-b06b-eb3174505645'::uuid, 1, 'probleme', $exo${"titre":"Ranger les nombres, écrire les intervalles","consigne":"Réponds à chaque question en justifiant brièvement.","enonce":"1. Pour chacun des nombres suivants, donne le **plus petit** ensemble (parmi ℕ, ℤ, ⅅ, ℚ, ℝ) auquel il appartient : −4 ; 0,75 ; 2/3 ; π ; 12/4.\n2. Écris sous forme d'intervalle l'ensemble des réels x tels que :\n   a. −2 < x ≤ 5\n   b. x ≥ 1\n   c. x < 0\n3. Calcule |−3,5| et |4 − 9|.","bareme":[{"critere":"Les cinq nombres rangés dans le bon plus petit ensemble, avec une justification","points":8},{"critere":"Les trois intervalles écrits avec les bons crochets (ouverts du côté de l'infini)","points":9},{"critere":"Les deux valeurs absolues justes","points":3}],"dureeMin":7,"corrige":"1.\n- −4 : entier négatif, donc dans **ℤ** (pas dans ℕ).\n- 0,75 = 75/100 : écriture décimale finie, donc **ⅅ** (pas entier).\n- 2/3 = 0,666… : quotient de deux entiers mais écriture décimale infinie, donc **ℚ** (pas décimal).\n- π : irrationnel, donc seulement **ℝ**.\n- 12/4 = 3 : entier positif, donc **ℕ**.\n2.\n   a. **]−2 ; 5]** (−2 exclu, 5 compris).\n   b. **[1 ; +∞[** (crochet ouvert du côté de l'infini).\n   c. **]−∞ ; 0[** (0 exclu).\n3. |−3,5| = **3,5** (distance de −3,5 à 0) ; |4 − 9| = |−5| = **5**."}$exo$::jsonb),
  ('fab3ca92-b4d6-53e0-b06b-eb3174505645'::uuid, 2, 'probleme', $exo${"titre":"Deux poissons, un seul aquarium","consigne":"Lis la situation, puis réponds en écrivant chaque ensemble de solutions sous forme d'intervalle.","enonce":"**Situation.** Maya veut installer deux espèces de poissons dans le même aquarium.\n- Le poisson A ne supporte qu'une température T (en °C) telle que |T − 26| ≤ 2.\n- Le poisson B ne supporte qu'une température comprise entre 22 °C et 25 °C, bornes comprises.\n\n1. Traduis la condition du poisson A par un intervalle. Explique ce que signifie |T − 26| ≤ 2 en termes de distance.\n2. Écris l'intervalle des températures supportées par le poisson B.\n3. Détermine l'intervalle des températures qui conviennent **aux deux** poissons. Quelle opération sur les ensembles utilises-tu ?\n4. Détermine l'ensemble des températures qui conviennent **à au moins un** des deux poissons.\n5. Une température de 25,5 °C convient-elle aux deux poissons ? Justifie.","bareme":[{"critere":"Condition du poisson A traduite en [24 ; 28] avec l'idée de distance à 26 inférieure ou égale à 2","points":5},{"critere":"Intervalle du poisson B [22 ; 25] et intersection [24 ; 25] identifiée comme une intersection","points":6},{"critere":"Réunion [22 ; 28] correcte","points":5},{"critere":"Réponse justifiée pour 25,5 °C","points":4}],"dureeMin":10,"corrige":"1. |T − 26| est la distance entre T et 26. La condition dit que T est à une distance d'au plus 2 de 26 : c'est l'intervalle centré en 26 de rayon 2, **[24 ; 28]**.\n2. Poisson B : **[22 ; 25]**.\n3. Il faut que T appartienne aux deux intervalles : c'est l'**intersection** [24 ; 28] ∩ [22 ; 25] = **[24 ; 25]**.\n4. Il suffit que T appartienne à l'un ou à l'autre : c'est la **réunion** [22 ; 25] ∪ [24 ; 28] = **[22 ; 28]** (les deux intervalles se chevauchent, la réunion est d'un seul tenant).\n5. 25,5 n'appartient pas à [24 ; 25] (25,5 > 25) : cette température convient au poisson A mais **pas** au poisson B, donc pas aux deux."}$exo$::jsonb),
  ('fab3ca92-b4d6-53e0-b06b-eb3174505645'::uuid, 3, 'probleme', $exo${"titre":"Intervalles, valeur absolue et nature des nombres","consigne":"Réponds à chaque question en justifiant. Les réponses non justifiées ne rapportent pas de points.","enonce":"On considère les ensembles :\n- A, l'ensemble des réels x tels que x ≤ 3 **et** x ≥ −1 ;\n- B, l'ensemble des réels x tels que |x − 5| ≤ 3.\n\n1. Écris A sous forme d'un intervalle, en expliquant qu'il s'agit de l'intersection de ]−∞ ; 3] et de [−1 ; +∞[.\n2. Écris B sous forme d'un intervalle en utilisant la notion de distance.\n3. Détermine A ∩ B et A ∪ B.\n4. Parmi les nombres 5/2 ; 7/2 ; 3 ; π ; −1, lesquels appartiennent à A ∩ B ? Justifie chaque réponse.\n5. Vrai ou faux : « tous les nombres de A ∩ B sont des décimaux ». Justifie à l'aide d'un exemple tiré du cours.","bareme":[{"critere":"A = [−1 ; 3] obtenu comme intersection","points":4},{"critere":"B = [2 ; 8] justifié par la distance de x à 5","points":4},{"critere":"A ∩ B = [2 ; 3] et A ∪ B = [−1 ; 8]","points":5},{"critere":"Appartenance des cinq nombres à A ∩ B correctement justifiée (π ≈ 3,14 > 3)","points":4},{"critere":"Réponse « faux » avec un contre-exemple rationnel non décimal de [2 ; 3], comme 7/3","points":3}],"dureeMin":16,"corrige":"1. x ≤ 3 correspond à ]−∞ ; 3] et x ≥ −1 à [−1 ; +∞[. Les deux conditions en même temps : c'est l'intersection, **A = [−1 ; 3]**.\n2. |x − 5| est la distance de x à 5 ; elle doit être au plus 3 : intervalle centré en 5 de rayon 3, **B = [5 − 3 ; 5 + 3] = [2 ; 8]**.\n3. **A ∩ B = [2 ; 3]** (ce qui est commun) ; **A ∪ B = [−1 ; 8]** (les intervalles se chevauchent entre 2 et 3).\n4.\n- 5/2 = 2,5 : 2 ≤ 2,5 ≤ 3, **oui**.\n- 7/2 = 3,5 > 3 : **non**.\n- 3 : borne comprise, **oui**.\n- π ≈ 3,14 > 3 : **non**.\n- −1 < 2 : **non** (il est dans A mais pas dans B).\n5. **Faux.** 7/3 = 2,333… appartient à [2 ; 3], mais sa fraction irréductible a un dénominateur qui contient le facteur 3 : son écriture décimale n'est pas finie, 7/3 est rationnel mais **pas décimal**. (Tout autre contre-exemple juste est accepté, par exemple 8/3.)"}$exo$::jsonb),
  ('7aaec3ed-c892-51f4-9408-c6383039372a'::uuid, 1, 'probleme', $exo${"titre":"Décimal ou pas ? Calculs de fractions","consigne":"Justifie chaque réponse et donne les résultats sous forme de fraction irréductible.","enonce":"1. Parmi les fractions suivantes, lesquelles représentent un nombre **décimal** ? 7/20 ; 5/6 ; 13/25 ; 4/12. Justifie à l'aide des facteurs premiers du dénominateur, et donne l'écriture décimale des décimaux.\n2. Calcule et simplifie :\n   a. A = 3/4 + 5/6\n   b. B = 2/3 × 9/10\n   c. C = (5/8) ÷ (15/4)","bareme":[{"critere":"Les deux décimaux (7/20 et 13/25) reconnus avec leur écriture décimale","points":6},{"critere":"Justification par les facteurs premiers 2 et 5 du dénominateur de la fraction irréductible","points":5},{"critere":"Les trois calculs justes et simplifiés : 19/12, 3/5, 1/6","points":9}],"dureeMin":8,"corrige":"1.\n- 7/20 est irréductible et 20 = 2² × 5 : seuls 2 et 5, donc **décimal** : 7/20 = 35/100 = 0,35.\n- 5/6 est irréductible et 6 = 2 × 3 : le facteur 3 apparaît, **pas décimal**.\n- 13/25 est irréductible et 25 = 5² : **décimal** : 13/25 = 52/100 = 0,52.\n- 4/12 = 1/3 (il faut d'abord rendre la fraction irréductible) : dénominateur 3, **pas décimal**.\n2.\n   a. A = 9/12 + 10/12 = **19/12**.\n   b. B = (2 × 9)/(3 × 10) = 18/30 = **3/5**.\n   c. C = 5/8 × 4/15 = 20/120 = **1/6** (diviser, c'est multiplier par l'inverse)."}$exo$::jsonb),
  ('7aaec3ed-c892-51f4-9408-c6383039372a'::uuid, 2, 'probleme', $exo${"titre":"La pizza de Zoé","consigne":"Lis la situation, puis réponds en justifiant tes calculs.","enonce":"**Situation.** Zoé partage une pizza : elle en mange 1/3, son ami Malik en mange 1/4, et le reste est gardé pour le soir.\n\n1. Quelle fraction de la pizza a été mangée ? Quelle fraction reste-t-il ?\n2. La fraction restante est-elle un nombre décimal ? Est-elle un rationnel ? Justifie, en décrivant son écriture décimale.\n3. Malik refait le calcul avec des valeurs approchées : il remplace 1/3 par 0,33 et 1/4 par 0,25, puis calcule 1 − (0,33 + 0,25). Quel résultat obtient-il ? Compare avec la valeur exacte du reste et explique pourquoi il vaut mieux garder les valeurs exactes.","bareme":[{"critere":"Fraction mangée 7/12 et reste 5/12 obtenus par réduction au même dénominateur","points":6},{"critere":"5/12 non décimal (facteur 3 au dénominateur) mais rationnel, écriture décimale périodique 0,41666…","points":7},{"critere":"Calcul de Malik (0,42), écart avec 5/12 et explication sur l'accumulation des arrondis","points":7}],"dureeMin":10,"corrige":"1. Mangé : 1/3 + 1/4 = 4/12 + 3/12 = **7/12**. Reste : 1 − 7/12 = **5/12**.\n2. 5/12 est irréductible et 12 = 2² × 3 : le facteur 3 empêche l'écriture décimale d'être finie, donc 5/12 **n'est pas décimal**. C'est bien un **rationnel** (quotient de deux entiers) : son écriture décimale est 0,41666…, infinie mais **périodique** (le 6 se répète).\n3. Malik obtient 1 − 0,58 = **0,42**. La valeur exacte est 5/12 = 0,41666… : l'écart est d'environ 0,0033. Les deux arrondis (0,33 au lieu de 0,333… ; ici 0,25 est exact) introduisent une erreur qui se reporte sur le résultat. Avec plusieurs calculs successifs, les arrondis s'accumulent : garder **5/12**, valeur exacte, évite toute erreur."}$exo$::jsonb),
  ('7aaec3ed-c892-51f4-9408-c6383039372a'::uuid, 3, 'probleme', $exo${"titre":"Familles de nombres et raisonnement par l'absurde","consigne":"Réponds en rédigeant des justifications complètes.","enonce":"1. Classe chacun des nombres suivants dans sa famille la plus précise (décimal, rationnel non décimal, irrationnel), en justifiant : 0,125 ; 22/7 ; 4/33 ; π.\n2. Lina affirme : « π = 22/7, d'ailleurs les deux commencent par 3,14. » Explique pourquoi c'est impossible.\n3. Effectue la division de 4 par 33 jusqu'à obtenir quatre chiffres après la virgule. Que constates-tu ? Donne la période et sa longueur.\n4. Rédige la démonstration par l'absurde du fait que √2 est irrationnel, en indiquant clairement l'hypothèse, les étapes et la contradiction.","bareme":[{"critere":"Les quatre nombres correctement classés et justifiés","points":6},{"critere":"Impossibilité π = 22/7 : un irrationnel ne peut pas être un quotient d'entiers","points":4},{"critere":"Division 4/33 = 0,1212… avec la période 12 de longueur 2","points":3},{"critere":"Démonstration par l'absurde complète : hypothèse irréductible, parité de p puis de q, contradiction","points":7}],"dureeMin":18,"corrige":"1.\n- 0,125 = 125/1000 : écriture décimale finie, **décimal** (c'est 1/8).\n- 22/7 : quotient d'entiers irréductible, dénominateur 7 (ni 2 ni 5) : **rationnel non décimal**.\n- 4/33 : irréductible, 33 = 3 × 11 : **rationnel non décimal**.\n- π : **irrationnel** (écriture décimale infinie, non périodique).\n2. 22/7 est un quotient de deux entiers, donc un rationnel. π est irrationnel : il ne peut s'écrire comme quotient de deux entiers. Donc π ≠ 22/7 ; les deux nombres ont seulement les mêmes premières décimales (22/7 = 3,142857…, π = 3,14159…).\n3. 4 ÷ 33 = 0,1212… : les restes successifs sont 7, 4, 7, 4… donc les chiffres 1 et 2 se répètent. **Période : 12, de longueur 2.** C'est une écriture périodique, signe d'un rationnel.\n4. On suppose que √2 est rationnel : √2 = p/q avec p/q **irréductible**. En élevant au carré : 2 = p²/q², donc **2q² = p²**. p² est pair, donc **p est pair** : on pose p = 2k. Alors 2q² = 4k², soit q² = 2k² : q² est pair, donc **q est pair**. p et q sont tous deux pairs : la fraction p/q se simplifie par 2, ce qui **contredit** l'hypothèse d'irréductibilité. L'hypothèse est fausse : **√2 est irrationnel**."}$exo$::jsonb),
  ('b5b4c57e-81a5-5e7e-b94c-1da2647e723d'::uuid, 1, 'probleme', $exo${"titre":"Critères, nombres premiers, décomposition","consigne":"Justifie chaque réponse en citant le critère ou le calcul utilisé.","enonce":"1. Le nombre 4 515 est-il divisible par 2 ? par 3 ? par 4 ? par 5 ? par 9 ? par 10 ? Justifie chaque réponse avec un critère de divisibilité.\n2. Les nombres 91 et 97 sont-ils premiers ? Justifie.\n3. Décompose 84 en produit de facteurs premiers.","bareme":[{"critere":"Les six réponses justes, chacune justifiée par le bon critère","points":8},{"critere":"91 = 7 × 13 non premier ; 97 premier, testé avec les premiers jusqu'à √97","points":6},{"critere":"Décomposition 84 = 2² × 3 × 7","points":6}],"dureeMin":8,"corrige":"1.\n- Par 2 : chiffre des unités 5, impair → **non**.\n- Par 3 : 4 + 5 + 1 + 5 = 15, divisible par 3 → **oui**.\n- Par 4 : 15 n'est pas divisible par 4 → **non**.\n- Par 5 : se termine par 5 → **oui**.\n- Par 9 : 15 n'est pas divisible par 9 → **non**.\n- Par 10 : ne se termine pas par 0 → **non**.\n2. **91 = 7 × 13** : il a d'autres diviseurs que 1 et lui-même, il n'est **pas premier**. Pour 97 : √97 ≈ 9,8, on teste les premiers 2, 3, 5, 7. 97 est impair ; 9 + 7 = 16 non divisible par 3 ; il ne finit ni par 0 ni par 5 ; 97 = 7 × 13 + 6. Aucun ne divise 97 : **97 est premier**.\n3. 84 = 2 × 42 = 2 × 2 × 21 = 2 × 2 × 3 × 7, donc **84 = 2² × 3 × 7**."}$exo$::jsonb),
  ('b5b4c57e-81a5-5e7e-b94c-1da2647e723d'::uuid, 2, 'probleme', $exo${"titre":"Les bouquets du fleuriste","consigne":"Lis la situation, puis réponds en détaillant tes décompositions.","enonce":"**Situation.** Un fleuriste dispose de 84 roses et de 126 tulipes. Il veut composer des bouquets **tous identiques** (même nombre de roses et même nombre de tulipes dans chacun), en utilisant **toutes** les fleurs.\n\n1. Décompose 84 et 126 en produits de facteurs premiers.\n2. Quel est le plus grand nombre de bouquets qu'il peut réaliser ? Justifie à l'aide des décompositions.\n3. Combien chaque bouquet contient-il de roses et de tulipes ?\n4. Écris la fraction 84/126 sous forme irréductible.","bareme":[{"critere":"Décompositions 84 = 2² × 3 × 7 et 126 = 2 × 3² × 7","points":6},{"critere":"Nombre de bouquets = PGCD = 42, obtenu avec les facteurs communs au plus petit exposant","points":6},{"critere":"Composition d'un bouquet : 2 roses et 3 tulipes","points":5},{"critere":"Fraction irréductible 2/3","points":3}],"dureeMin":12,"corrige":"1. 84 = 2 × 2 × 3 × 7 = **2² × 3 × 7** ; 126 = 2 × 63 = 2 × 3 × 3 × 7 = **2 × 3² × 7**.\n2. Le nombre de bouquets doit diviser 84 et 126 : on cherche le **PGCD**. On prend les facteurs communs au plus petit exposant : 2¹, 3¹, 7¹. PGCD = 2 × 3 × 7 = **42 bouquets**.\n3. 84 ÷ 42 = **2 roses** et 126 ÷ 42 = **3 tulipes** par bouquet. Vérification : 42 × 2 = 84 et 42 × 3 = 126.\n4. On divise par le PGCD 42 : 84/126 = **2/3**."}$exo$::jsonb),
  ('b5b4c57e-81a5-5e7e-b94c-1da2647e723d'::uuid, 3, 'probleme', $exo${"titre":"Du nombre premier à la cryptographie","consigne":"Réponds à chaque question en justifiant soigneusement.","enonce":"1. Le nombre 221 est-il premier ? Indique jusqu'à quel nombre il suffit de tester les diviseurs, et pourquoi on ne teste que des nombres premiers.\n2. Décompose 1 050 et 1 540 en produits de facteurs premiers.\n3. Déduis-en le PGCD de 1 050 et 1 540, puis la forme irréductible de la fraction 1 050/1 540.\n4. La fraction obtenue représente-t-elle un nombre décimal ? Justifie.\n5. Calculer 13 × 17 est immédiat. Explique, à partir de la question 1, pourquoi le travail inverse est plus long, et pourquoi cette différence sert à protéger des données quand les nombres sont très grands.","bareme":[{"critere":"221 = 13 × 17 non premier, tests limités aux premiers jusqu'à √221 ≈ 14,9","points":5},{"critere":"Décompositions 1 050 = 2 × 3 × 5² × 7 et 1 540 = 2² × 5 × 7 × 11","points":5},{"critere":"PGCD = 70 et fraction irréductible 15/22","points":5},{"critere":"15/22 non décimal à cause du facteur 11","points":3},{"critere":"Explication de l'asymétrie multiplier / factoriser et de son usage en cryptographie","points":2}],"dureeMin":18,"corrige":"1. √221 ≈ 14,9 : il suffit de tester les premiers 2, 3, 5, 7, 11, 13 (si 221 avait un diviseur composé, il aurait aussi un diviseur premier plus petit). 221 est impair ; 2 + 2 + 1 = 5 non divisible par 3 ; il ne finit pas par 0 ou 5 ; 221 = 7 × 31 + 4 ; 221 = 11 × 20 + 1 ; **221 = 13 × 17**. Il n'est **pas premier**.\n2. 1 050 = 2 × 525 = 2 × 3 × 175 = 2 × 3 × 5 × 35 = **2 × 3 × 5² × 7**.\n1 540 = 2 × 770 = 2 × 2 × 385 = 2² × 5 × 77 = **2² × 5 × 7 × 11**.\n3. Facteurs communs au plus petit exposant : 2, 5, 7. **PGCD = 2 × 5 × 7 = 70**. 1 050 ÷ 70 = 15 et 1 540 ÷ 70 = 22 : **1 050/1 540 = 15/22**, irréductible (15 = 3 × 5 et 22 = 2 × 11 n'ont aucun facteur commun).\n4. Le dénominateur 22 = 2 × 11 contient le facteur 11 : **15/22 n'est pas décimal** (c'est un rationnel).\n5. Multiplier 13 × 17 = 221 se fait en une opération. Retrouver 13 et 17 à partir de 221 oblige à essayer les diviseurs un à un. Pour un produit de deux **très grands** nombres premiers, ces essais deviennent si nombreux qu'ils sont hors de portée : c'est sur cette difficulté de **factoriser** que repose la sécurité de nombreux systèmes de chiffrement."}$exo$::jsonb),
  ('7a85fcba-5f8b-5eb6-aabf-5bcc73b851ca'::uuid, 1, 'probleme', $exo${"titre":"Puissances et racines sans faute","consigne":"Donne chaque résultat sous la forme demandée en citant la règle utilisée.","enonce":"1. Écris sous la forme d'une seule puissance ou d'un nombre : A = a⁵ × a⁻² ; B = (x²)³ / x⁴ (x non nul) ; C = 2⁻³.\n2. Écris en notation scientifique : 0,000 45 et 3 200 000.\n3. Écris √50 sous la forme a√2 avec a entier, puis écris 1/√5 sans racine au dénominateur.","bareme":[{"critere":"A = a³, B = x², C = 1/8 avec les règles des puissances","points":8},{"critere":"Notations scientifiques 4,5 × 10⁻⁴ et 3,2 × 10⁶","points":5},{"critere":"√50 = 5√2 et 1/√5 = √5/5","points":7}],"dureeMin":8,"corrige":"1.\n- A = a⁵⁺⁽⁻²⁾ = **a³** (produit de même base).\n- B = x⁶ / x⁴ = x⁶⁻⁴ = **x²** (puissance de puissance, puis quotient).\n- C = 1/2³ = **1/8** (exposant négatif).\n2. 0,000 45 = **4,5 × 10⁻⁴** ; 3 200 000 = **3,2 × 10⁶** (dans les deux cas, 1 ≤ a < 10).\n3. √50 = √(25 × 2) = √25 × √2 = **5√2**. 1/√5 = (1 × √5)/(√5 × √5) = **√5/5**."}$exo$::jsonb),
  ('7a85fcba-5f8b-5eb6-aabf-5bcc73b851ca'::uuid, 2, 'probleme', $exo${"titre":"Simplifier un quotient sans barrer de termes","consigne":"Réponds à chaque question en justifiant.","enonce":"On considère l'expression F(x) = (3x + 6) / (x² + 2x).\n\n1. Factorise le dénominateur par un facteur commun, puis détermine les **valeurs interdites** de F.\n2. Factorise le numérateur, puis simplifie F(x) pour x différent des valeurs interdites.\n3. Nina a écrit : « (x + 6)/(x + 2) = 6/2 = 3 ». Explique son erreur, puis montre avec x = 1 que son égalité est fausse.\n4. Calcule F(4) avec l'expression de départ, puis avec l'expression simplifiée, et vérifie que tu trouves la même valeur.","bareme":[{"critere":"Dénominateur factorisé x(x + 2) et valeurs interdites 0 et −2","points":5},{"critere":"Simplification F(x) = 3/x obtenue en factorisant avant de simplifier","points":6},{"critere":"Erreur de Nina expliquée (termes barrés, pas des facteurs) et contre-exemple x = 1","points":5},{"critere":"F(4) = 3/4 trouvé par les deux calculs","points":4}],"dureeMin":12,"corrige":"1. x² + 2x = **x(x + 2)**. Il s'annule pour x = 0 ou x + 2 = 0, soit x = −2. **Valeurs interdites : 0 et −2.**\n2. 3x + 6 = **3(x + 2)**. Donc F(x) = 3(x + 2) / (x(x + 2)) : le facteur (x + 2) est commun, on peut le simplifier. Pour x ≠ 0 et x ≠ −2, **F(x) = 3/x**.\n3. Nina a « barré » des **termes** (x) et non des **facteurs** : c'est interdit, on ne simplifie que des facteurs. Avec x = 1 : (1 + 6)/(1 + 2) = 7/3 ≈ 2,33, qui n'est pas égal à 3.\n4. Expression de départ : (3 × 4 + 6)/(16 + 8) = 18/24 = **3/4**. Expression simplifiée : 3/4. Les deux résultats sont égaux."}$exo$::jsonb),
  ('7a85fcba-5f8b-5eb6-aabf-5bcc73b851ca'::uuid, 3, 'probleme', $exo${"titre":"Racines, notation scientifique et quotients","consigne":"Donne des résultats exacts et justifie chaque règle employée.","enonce":"1. Calcule √9 + √16 et √(9 + 16). Que montre ce calcul sur l'égalité √(a + b) = √a + √b ?\n2. Calcule sous forme exacte, sans calculatrice : A = √12 × √3 ; B = √18 / √2 ; C = (2√3)².\n3. Écris 6/√3 sans racine au dénominateur, puis simplifie.\n4. La distance Terre–Soleil vaut environ 1,5 × 10⁸ km et la lumière parcourt 3 × 10⁵ km par seconde. Calcule en notation scientifique le temps, en secondes, que met la lumière du Soleil pour nous parvenir.\n5. Pour x différent de 0 et de −1, écris 1/x + 2/(x + 1) sous la forme d'un seul quotient.","bareme":[{"critere":"Contre-exemple 7 ≠ 5 et calculs exacts A = 6, B = 3, C = 12","points":5},{"critere":"6/√3 = 2√3 en multipliant haut et bas par √3","points":3},{"critere":"Temps de 5 × 10² s obtenu avec les règles des puissances de 10","points":5},{"critere":"Somme réduite au même dénominateur (3x + 1)/(x(x + 1)) avec les valeurs interdites","points":7}],"dureeMin":18,"corrige":"1. √9 + √16 = 3 + 4 = **7** ; √(9 + 16) = √25 = **5**. 7 ≠ 5 : l'égalité √(a + b) = √a + √b est **fausse** en général.\n2. A = √(12 × 3) = √36 = **6** ; B = √(18/2) = √9 = **3** ; C = 2² × (√3)² = 4 × 3 = **12**.\n3. 6/√3 = (6 × √3)/(√3 × √3) = 6√3/3 = **2√3**.\n4. t = (1,5 × 10⁸) / (3 × 10⁵) = (1,5/3) × 10⁸⁻⁵ = 0,5 × 10³ = **5 × 10² s**, soit 500 s (environ 8 min 20 s).\n5. Même dénominateur x(x + 1) : 1/x + 2/(x + 1) = (x + 1)/(x(x + 1)) + 2x/(x(x + 1)) = **(3x + 1) / (x(x + 1))**, valable pour x ≠ 0 et x ≠ −1 (valeurs qui annulent le dénominateur)."}$exo$::jsonb),
  ('d513d5d5-e95d-5b04-b628-b4a1970f42bb'::uuid, 1, 'probleme', $exo${"titre":"Développer et factoriser","consigne":"Identifie a et b avant chaque calcul et cite l'identité utilisée.","enonce":"1. Développe et réduis :\n   a. (x + 4)²\n   b. (2x − 3)²\n   c. (5x + 1)(5x − 1)\n2. Factorise :\n   a. x² − 36\n   b. x² − 10x + 25","bareme":[{"critere":"Les trois développements justes, double produit compris","points":10},{"critere":"Les deux factorisations justes avec l'identité reconnue","points":10}],"dureeMin":7,"corrige":"1.\n   a. a = x, b = 4 : (x + 4)² = **x² + 8x + 16** (première identité).\n   b. a = 2x, b = 3 : (2x − 3)² = **4x² − 12x + 9** (deuxième identité).\n   c. a = 5x, b = 1 : (5x + 1)(5x − 1) = **25x² − 1** (troisième identité).\n2.\n   a. x² − 36 = x² − 6² = **(x − 6)(x + 6)** (troisième identité).\n   b. x² − 10x + 25 = x² − 2 × x × 5 + 5² = **(x − 5)²** (deuxième identité)."}$exo$::jsonb),
  ('d513d5d5-e95d-5b04-b628-b4a1970f42bb'::uuid, 2, 'probleme', $exo${"titre":"Calcul de tête et aire d'un cadre","consigne":"Utilise une identité remarquable à chaque question et écris-la.","enonce":"1. Calcule 103² sans poser la multiplication, à l'aide d'une identité remarquable.\n2. Calcule 98 × 102 de la même façon.\n3. **Situation.** Tom découpe, dans un carré de côté (x + 3) cm, un petit carré de côté 3 cm. On note A(x) l'aire restante, avec x > 0.\n   a. Exprime A(x), puis développe et réduis.\n   b. Factorise A(x).\n   c. Vérifie ton résultat avec x = 5 en calculant l'aire de deux façons.","bareme":[{"critere":"103² = 10 609 obtenu avec (100 + 3)²","points":5},{"critere":"98 × 102 = 9 996 obtenu avec (100 − 2)(100 + 2)","points":5},{"critere":"A(x) = (x + 3)² − 9 = x² + 6x puis factorisé en x(x + 6)","points":6},{"critere":"Vérification juste pour x = 5 (55 cm² par les deux calculs)","points":4}],"dureeMin":11,"corrige":"1. 103² = (100 + 3)² = 10 000 + 2 × 100 × 3 + 9 = 10 000 + 600 + 9 = **10 609**.\n2. 98 × 102 = (100 − 2)(100 + 2) = 100² − 2² = 10 000 − 4 = **9 996**.\n3.\n   a. A(x) = (x + 3)² − 3² = x² + 6x + 9 − 9 = **x² + 6x**.\n   b. Facteur commun x : **A(x) = x(x + 6)**. (On peut aussi voir la troisième identité : (x + 3 − 3)(x + 3 + 3) = x(x + 6).)\n   c. Pour x = 5 : grand carré 8² = 64, petit carré 9, aire 64 − 9 = **55 cm²** ; et x(x + 6) = 5 × 11 = **55**. Les deux calculs concordent."}$exo$::jsonb),
  ('d513d5d5-e95d-5b04-b628-b4a1970f42bb'::uuid, 3, 'probleme', $exo${"titre":"Choisir la bonne forme pour résoudre","consigne":"Justifie chaque étape et indique la forme de l'expression que tu utilises.","enonce":"On considère E = (2x + 1)² − 25.\n\n1. Développe et réduis E.\n2. Factorise E en reconnaissant une identité remarquable (précise a et b).\n3. Résous l'équation E = 0.\n4. Calcule E pour x = 0 en choisissant la forme la plus adaptée, puis vérifie avec l'autre forme.\n5. Résous l'équation E = −24 en choisissant la forme la plus adaptée.","bareme":[{"critere":"Forme développée 4x² + 4x − 24","points":4},{"critere":"Forme factorisée (2x − 4)(2x + 6) avec a = 2x + 1 et b = 5","points":5},{"critere":"E = 0 résolue par le produit nul : x = 2 ou x = −3","points":5},{"critere":"E(0) = −24 trouvé et vérifié par les deux formes","points":3},{"critere":"E = −24 résolue : x = 0 ou x = −1, en factorisant 4x² + 4x","points":3}],"dureeMin":18,"corrige":"1. (2x + 1)² = 4x² + 4x + 1, donc E = 4x² + 4x + 1 − 25 = **4x² + 4x − 24**.\n2. E = a² − b² avec a = 2x + 1 et b = 5 : E = (2x + 1 − 5)(2x + 1 + 5) = **(2x − 4)(2x + 6)**.\n3. Forme factorisée : un produit est nul si et seulement si l'un de ses facteurs est nul. 2x − 4 = 0 donne **x = 2** ; 2x + 6 = 0 donne **x = −3**. S = {−3 ; 2}.\n4. Forme développée : E = 0 + 0 − 24 = **−24**. Vérification avec la forme factorisée : (−4) × 6 = −24.\n5. Forme développée : 4x² + 4x − 24 = −24 équivaut à 4x² + 4x = 0, soit **4x(x + 1) = 0**. Produit nul : **x = 0 ou x = −1**. Vérification : pour x = −1, (−1)² − 25 = 1 − 25 = −24."}$exo$::jsonb),
  ('ae2a882f-7b8b-53bb-80bf-21b8b4812122'::uuid, 1, 'probleme', $exo${"titre":"Trois résolutions express","consigne":"Résous en détaillant les étapes, et donne l'ensemble des solutions.","enonce":"1. Résous l'équation 5x − 7 = 2x + 8.\n2. Résous l'équation (x + 3)(2x − 8) = 0.\n3. Résous l'inéquation −3x + 9 ≥ 0 et donne l'ensemble des solutions sous forme d'intervalle.","bareme":[{"critere":"Équation du premier degré résolue : x = 5","points":6},{"critere":"Produit nul : x = −3 ou x = 4","points":6},{"critere":"Inéquation résolue avec changement de sens en divisant par −3 : S = ]−∞ ; 3]","points":8}],"dureeMin":8,"corrige":"1. 5x − 2x = 8 + 7, soit 3x = 15, donc **x = 5**. Vérification : 25 − 7 = 18 et 10 + 8 = 18.\n2. Un produit est nul si et seulement si l'un de ses facteurs est nul : x + 3 = 0 donne **x = −3** ; 2x − 8 = 0 donne **x = 4**. S = {−3 ; 4}.\n3. −3x ≥ −9. On divise par −3, nombre **strictement négatif** : le sens de l'inégalité **s'inverse** : x ≤ 3. **S = ]−∞ ; 3]**."}$exo$::jsonb),
  ('ae2a882f-7b8b-53bb-80bf-21b8b4812122'::uuid, 2, 'probleme', $exo${"titre":"Quel tarif pour louer un vélo ?","consigne":"Lis la situation, puis réponds en mettant chaque question en équation ou en inéquation.","enonce":"**Situation.** Pour louer un vélo, Samir a le choix entre deux tarifs :\n- tarif A : 12 € de frais fixes, puis 1,50 € par heure ;\n- tarif B : 3 € par heure, sans frais fixes.\nOn note h le nombre d'heures de location (h ≥ 0).\n\n1. Exprime le prix payé avec chaque tarif en fonction de h.\n2. Pour quelle durée les deux tarifs coûtent-ils le même prix ? Quel est ce prix ?\n3. Résous une inéquation pour déterminer les durées pour lesquelles le tarif B est **strictement** moins cher.\n4. Samir prévoit une location de 10 heures. Quel tarif lui conseilles-tu ? Justifie par un calcul.","bareme":[{"critere":"Prix A = 12 + 1,5h et prix B = 3h","points":4},{"critere":"Égalité résolue : h = 8, prix commun 24 €","points":5},{"critere":"Inéquation 3h < 12 + 1,5h résolue : h < 8, soit [0 ; 8[","points":7},{"critere":"Conseil justifié pour 10 heures (A à 27 € contre B à 30 €)","points":4}],"dureeMin":11,"corrige":"1. Prix A = **12 + 1,5h** ; prix B = **3h**.\n2. 3h = 12 + 1,5h équivaut à 1,5h = 12, soit **h = 8**. Prix : 3 × 8 = **24 €** (et 12 + 1,5 × 8 = 24 €).\n3. B moins cher : 3h < 12 + 1,5h, soit 1,5h < 12. On divise par 1,5, positif : le sens est conservé, **h < 8**. Avec h ≥ 0 : le tarif B est moins cher pour une durée dans **[0 ; 8[**.\n4. Pour 10 heures : A coûte 12 + 1,5 × 10 = **27 €**, B coûte 3 × 10 = **30 €**. On conseille le **tarif A**, ce qui est cohérent avec la question 3 (10 > 8)."}$exo$::jsonb),
  ('ae2a882f-7b8b-53bb-80bf-21b8b4812122'::uuid, 3, 'probleme', $exo${"titre":"Tableaux de signes : produit et quotient","consigne":"Résous chaque inéquation à l'aide d'un tableau de signes complet, et donne les solutions sous forme d'intervalles.","enonce":"1. On considère l'inéquation (2x − 6)/(x + 1) ≤ 0.\n   a. Quelle est la valeur interdite ? Pourquoi faut-il la chercher avant toute résolution ?\n   b. Dresse le tableau de signes du quotient.\n   c. Déduis-en l'ensemble des solutions.\n2. Résous l'inéquation (x − 2)(−x + 5) > 0 à l'aide d'un tableau de signes.\n3. Vérifie ta réponse à la question 1 en testant x = 0 et x = 4.","bareme":[{"critere":"Valeur interdite −1 identifiée et justifiée","points":3},{"critere":"Tableau de signes du quotient juste, avec double barre en −1","points":6},{"critere":"Solution S = ]−1 ; 3] avec les bons crochets","points":4},{"critere":"Tableau du produit juste et solution ]2 ; 5[","points":5},{"critere":"Vérification par les deux valeurs tests","points":2}],"dureeMin":18,"corrige":"1.\n   a. Le dénominateur x + 1 s'annule pour **x = −1** : le quotient n'y est pas défini. Il faut l'exclure avant de résoudre, sinon on risque de l'inclure dans les solutions.\n   b. 2x − 6 s'annule en 3 (négatif avant, positif après) ; x + 1 s'annule en −1 (négatif avant, positif après).\n\n| x | −∞ … −1 | −1 … 3 | 3 … +∞ |\n| 2x − 6 | − | − | + |\n| x + 1 | − | + | + |\n| quotient | + (double barre en −1) | − (0 en 3) | + |\n\n   c. Le quotient est négatif ou nul sur ]−1 ; 3], −1 exclu (interdite) et 3 inclus (le quotient y vaut 0) : **S = ]−1 ; 3]**.\n2. x − 2 s'annule en 2 (négatif puis positif) ; −x + 5 s'annule en 5 (positif puis négatif, car le coefficient de x est négatif).\n\n| x | −∞ … 2 | 2 … 5 | 5 … +∞ |\n| x − 2 | − | + | + |\n| −x + 5 | + | + | − |\n| produit | − | + | − |\n\nProduit strictement positif : **S = ]2 ; 5[** (2 et 5 exclus car le produit y est nul).\n3. x = 0 : (−6)/1 = −6 ≤ 0, 0 est bien solution (0 ∈ ]−1 ; 3]). x = 4 : 2/5 > 0, 4 n'est pas solution (4 ∉ ]−1 ; 3])."}$exo$::jsonb),
  ('ebf88cac-fd60-5a8a-aa2d-6da9a219314a'::uuid, 1, 'probleme', $exo${"titre":"Le triangle 6-8-10","consigne":"Réponds en citant le théorème ou la définition utilisée.","enonce":"Le triangle ABC a pour côtés AB = 6 cm, AC = 8 cm et BC = 10 cm.\n\n1. Démontre que le triangle ABC est rectangle, et précise en quel sommet.\n2. Calcule cos(ABC), puis donne une valeur approchée au degré près de l'angle ABC.\n3. Comment s'appelle le point de concours des médiatrices d'un triangle ? Quelle propriété a-t-il par rapport aux sommets ?","bareme":[{"critere":"Réciproque de Pythagore appliquée : 36 + 64 = 100, triangle rectangle en A","points":8},{"critere":"cos(ABC) = 6/10 = 0,6 et angle d'environ 53°","points":7},{"critere":"Centre du cercle circonscrit, équidistant des trois sommets","points":5}],"dureeMin":8,"corrige":"1. Le plus grand côté est BC. BC² = 100 ; AB² + AC² = 36 + 64 = 100. Comme BC² = AB² + AC², d'après la **réciproque du théorème de Pythagore**, le triangle ABC est **rectangle en A**.\n2. Dans le triangle rectangle en A, pour l'angle en B : côté adjacent AB, hypoténuse BC. **cos(ABC) = 6/10 = 0,6**. À la calculatrice, ABC ≈ **53°**.\n3. Les médiatrices se coupent au **centre du cercle circonscrit**, qui est **équidistant des trois sommets**."}$exo$::jsonb),
  ('ebf88cac-fd60-5a8a-aa2d-6da9a219314a'::uuid, 2, 'probleme', $exo${"titre":"Le chemin le plus court vers la route","consigne":"Lis la situation, puis réponds en justifiant chaque calcul.","enonce":"**Situation.** La maison de Clara est au point M. Une route rectiligne est modélisée par une droite d. H est le **projeté orthogonal** de M sur d, et MH = 120 m. Un arrêt de bus se trouve au point P de la route, avec HP = 50 m.\n\n1. Rappelle la définition du projeté orthogonal H de M sur d.\n2. Calcule la distance MP.\n3. Clara prétend qu'aucun point de la route n'est à moins de 120 m de sa maison. A-t-elle raison ? Justifie avec une propriété du cours.\n4. Un autre arrêt Q, sur la route, est à 150 m de la maison. Calcule la distance HQ.","bareme":[{"critere":"Définition du projeté orthogonal : point H de d tel que (MH) soit perpendiculaire à d","points":5},{"critere":"MP = 130 m par Pythagore dans le triangle MHP rectangle en H","points":6},{"critere":"Minimalité : MH est la plus courte distance de M à un point de d","points":5},{"critere":"HQ = 90 m par Pythagore","points":4}],"dureeMin":12,"corrige":"1. H est le point de la droite d tel que la droite (MH) soit **perpendiculaire** à d.\n2. Le triangle MHP est rectangle en H. Par le théorème de Pythagore : MP² = MH² + HP² = 120² + 50² = 14 400 + 2 500 = 16 900, donc **MP = √16 900 = 130 m**.\n3. Oui : d'après la propriété de **minimalité** du projeté orthogonal, MH est la plus courte des distances de M à un point de d. Tout point de la route est donc à au moins 120 m de la maison (MH = 120 m est la distance de M à la droite d).\n4. Le triangle MHQ est rectangle en H : HQ² = MQ² − MH² = 150² − 120² = 22 500 − 14 400 = 8 100, donc **HQ = 90 m**."}$exo$::jsonb),
  ('ebf88cac-fd60-5a8a-aa2d-6da9a219314a'::uuid, 3, 'probleme', $exo${"titre":"Hauteur, aire et distance à une droite","consigne":"Rédige chaque réponse en citant l'outil utilisé et sa condition d'emploi.","enonce":"Dans le triangle ABC, BC = 14 cm. On note H le **projeté orthogonal** de A sur la droite (BC) ; H appartient au segment [BC], avec BH = 5 cm. On sait aussi que AB = 13 cm.\n\n1. Calcule AH.\n2. Calcule l'aire du triangle ABC.\n3. Calcule HC, puis AC.\n4. On note K le projeté orthogonal de B sur la droite (AC). En exprimant l'aire du triangle ABC d'une autre façon, calcule la distance BK du point B à la droite (AC).\n5. Le triangle ABC est-il rectangle ? Justifie.","bareme":[{"critere":"AH = 12 cm par Pythagore dans ABH rectangle en H","points":4},{"critere":"Aire = 14 × 12 / 2 = 84 cm²","points":3},{"critere":"HC = 9 cm et AC = 15 cm","points":4},{"critere":"BK = 2 × 84 / 15 = 11,2 cm, en prenant [AC] comme base et BK comme hauteur","points":5},{"critere":"Triangle non rectangle : l'égalité de Pythagore n'est pas vérifiée pour le plus grand côté AC","points":4}],"dureeMin":18,"corrige":"1. (AH) est perpendiculaire à (BC) : le triangle ABH est rectangle en H. AH² = AB² − BH² = 169 − 25 = 144, donc **AH = 12 cm**.\n2. AH est la hauteur relative à [BC] : aire = BC × AH / 2 = 14 × 12 / 2 = **84 cm²**.\n3. H est sur [BC] : HC = 14 − 5 = **9 cm**. Le triangle AHC est rectangle en H : AC² = AH² + HC² = 144 + 81 = 225, donc **AC = 15 cm**.\n4. BK est la hauteur relative à [AC] (distance de B à la droite (AC)). Aire = AC × BK / 2, donc 84 = 15 × BK / 2, soit **BK = 168 / 15 = 11,2 cm**.\n5. Le plus grand côté est AC = 15. AC² = 225 ; AB² + BC² = 169 + 196 = 365. Comme 225 ≠ 365, l'égalité de Pythagore n'est pas vérifiée : si le triangle était rectangle, ce serait en B et l'on aurait AC² = AB² + BC². Le triangle ABC **n'est pas rectangle**."}$exo$::jsonb),
  ('27b703e8-ce8e-5098-8991-6c9faf1c90cc'::uuid, 1, 'probleme', $exo${"titre":"Chasles et parallélogramme","consigne":"On note →AB le vecteur d'origine A et d'extrémité B. Justifie chaque réponse.","enonce":"1. Cite les trois caractéristiques du vecteur →AB.\n2. Simplifie à l'aide de la relation de Chasles :\n   a. →AB + →BC + →CD\n   b. →MA + →AM\n   c. →BC + →AB\n3. A, B, C et D sont quatre points tels que →AB = →DC. Quelle est la nature du quadrilatère ABCD ? Justifie.","bareme":[{"critere":"Direction (droite (AB)), sens (de A vers B), norme (longueur AB)","points":6},{"critere":"Les trois simplifications justes : →AD, vecteur nul, →AC","points":9},{"critere":"ABCD parallélogramme (éventuellement aplati) justifié par l'égalité de vecteurs","points":5}],"dureeMin":7,"corrige":"1. La **direction** : celle de la droite (AB) ; le **sens** : de A vers B ; la **norme** : la longueur AB.\n2.\n   a. →AB + →BC = →AC, puis →AC + →CD = **→AD**.\n   b. →MA + →AM = →MM = **le vecteur nul**.\n   c. →BC + →AB = →AB + →BC (commutativité) = **→AC**.\n3. D'après le cours, →AB = →CD équivaut à « ABDC est un parallélogramme ». Ici →AB = →DC : en remplaçant C par D et D par C, on obtient que **ABCD est un parallélogramme** (éventuellement aplati)."}$exo$::jsonb),
  ('27b703e8-ce8e-5098-8991-6c9faf1c90cc'::uuid, 2, 'probleme', $exo${"titre":"Déplacements dans un parallélogramme","consigne":"On note →AB le vecteur d'origine A et d'extrémité B. Justifie chaque égalité par une propriété du cours.","enonce":"ABCD est un parallélogramme.\n\n1. Justifie que →AB = →DC.\n2. Simplifie →AB + →AD en utilisant la règle du parallélogramme.\n3. Calcule →AB + →BC + →CA.\n4. On place le point E tel que →CE = →AB. Quelle est la nature du quadrilatère ABEC ? Justifie.\n5. Exprime →AE en fonction de →AB et →AD.","bareme":[{"critere":"→AB = →DC justifié par la définition de l'égalité de vecteurs dans ABCD","points":4},{"critere":"→AB + →AD = →AC et →AB + →BC + →CA = vecteur nul","points":5},{"critere":"ABEC parallélogramme justifié par →AB = →CE","points":5},{"critere":"→AE = 2→AB + →AD obtenu par la relation de Chasles","points":6}],"dureeMin":12,"corrige":"1. ABCD est un parallélogramme, donc (AB) et (DC) sont parallèles, AB = DC, et on va de A vers B dans le même sens que de D vers C : **→AB = →DC** (même direction, même sens, même norme).\n2. La somme de deux vecteurs de même origine est la diagonale issue du point commun : **→AB + →AD = →AC**.\n3. →AB + →BC = →AC, puis →AC + →CA = →AA = **vecteur nul**.\n4. →AB = →CE équivaut, d'après le cours, à « **ABEC est un parallélogramme** ».\n5. Chasles : →AE = →AC + →CE = (→AB + →AD) + →AB = **2→AB + →AD**."}$exo$::jsonb),
  ('27b703e8-ce8e-5098-8991-6c9faf1c90cc'::uuid, 3, 'probleme', $exo${"titre":"Démontrer un alignement avec des vecteurs","consigne":"On note →AB le vecteur d'origine A et d'extrémité B. Rédige chaque étape en citant la propriété utilisée.","enonce":"ABC est un triangle. On place le point D tel que →AD = 3→AB − 2→AC.\n\n1. À l'aide de la relation de Chasles, écris →BD en fonction de →BA et →AD, puis en fonction de →AB et →AC.\n2. Montre que →AB − →AC = →CB (on rappelle que −→AC = →CA), puis que →BD = 2→CB.\n3. Déduis-en que les points B, C et D sont alignés.\n4. Décris la position du point D sur la droite (BC) : sens de →BD par rapport à →CB, et longueur BD en fonction de BC.\n5. On place E tel que →AE = →AB + →AC. Quelle est la nature de ABEC ? Justifie.","bareme":[{"critere":"→BD = →BA + →AD = 2→AB − 2→AC, calcul juste","points":5},{"critere":"→AB − →AC = →CB justifié par Chasles et →BD = 2→CB","points":5},{"critere":"Alignement : vecteurs colinéaires ayant le point B en commun","points":4},{"critere":"Position de D : même sens que →CB et BD = 2BC","points":3},{"critere":"ABEC parallélogramme par la règle du parallélogramme","points":3}],"dureeMin":18,"corrige":"1. →BD = →BA + →AD = −→AB + 3→AB − 2→AC = **2→AB − 2→AC**.\n2. →AB − →AC = →AB + →CA = →CA + →AB = **→CB** (Chasles). Donc →BD = 2(→AB − →AC) = **2→CB**.\n3. →BD = 2→CB : les vecteurs →BD et →CB sont **colinéaires** (k = 2). Les droites (BD) et (CB) sont donc parallèles ; comme elles ont le point **B en commun**, elles sont confondues : **B, C et D sont alignés**.\n4. k = 2 > 0 : →BD a **le même sens** que →CB, c'est-à-dire qu'en partant de B on s'éloigne de C, dans la direction de C vers B. Sa norme vaut 2 fois celle de →CB : **BD = 2BC**. D est donc sur la droite (BC), au-delà de B par rapport à C, à une distance 2BC de B.\n5. →AE = →AB + →AC : d'après la règle du parallélogramme, E est l'extrémité de la diagonale issue de A du parallélogramme construit sur [AB] et [AC] : **ABEC est un parallélogramme** (on vérifie : →AE = →AB + →AC donne →BE = →BA + →AE = →AC, donc →AC = →BE, ce qui équivaut à ABEC parallélogramme)."}$exo$::jsonb),
  ('a6fc7a9d-dc23-5456-bb58-751dc2551f24'::uuid, 1, 'probleme', $exo${"titre":"Coordonnées, milieu, distance","consigne":"Le plan est muni d'un repère orthonormé. Détaille chaque calcul.","enonce":"On donne A(2 ; −1) et B(6 ; 2).\n\n1. Calcule les coordonnées du vecteur →AB.\n2. Calcule les coordonnées du milieu I de [AB].\n3. Calcule la distance AB.\n4. Les vecteurs u(4 ; 3) et v(−8 ; −6) sont-ils colinéaires ? Justifie avec le déterminant.","bareme":[{"critere":"→AB (4 ; 3) en soustrayant l'origine à l'extrémité","points":5},{"critere":"Milieu I (4 ; 0,5)","points":5},{"critere":"AB = 5 par la formule de distance en repère orthonormé","points":5},{"critere":"Déterminant nul, donc u et v colinéaires","points":5}],"dureeMin":8,"corrige":"1. →AB (6 − 2 ; 2 − (−1)) = **(4 ; 3)**.\n2. I ((2 + 6)/2 ; (−1 + 2)/2) = **(4 ; 0,5)**.\n3. Le repère est orthonormé : AB = √(4² + 3²) = √(16 + 9) = √25 = **5**.\n4. Déterminant : 4 × (−6) − 3 × (−8) = −24 + 24 = **0**. Le déterminant est nul : **u et v sont colinéaires** (en effet v = −2u)."}$exo$::jsonb),
  ('a6fc7a9d-dc23-5456-bb58-751dc2551f24'::uuid, 2, 'probleme', $exo${"titre":"Compléter un parallélogramme","consigne":"Le plan est muni d'un repère. Justifie chaque réponse par un calcul.","enonce":"On donne A(1 ; 2), B(5 ; 3) et C(6 ; 7).\n\n1. Calcule les coordonnées de →AB.\n2. Détermine les coordonnées du point D tel que ABCD soit un parallélogramme.\n3. Vérifie ton résultat en montrant que les diagonales [AC] et [BD] ont le même milieu.\n4. Le point E(9 ; 8) est-il aligné avec A et C ? Justifie.","bareme":[{"critere":"→AB (4 ; 1)","points":4},{"critere":"D (2 ; 6) obtenu à partir de →AB = →DC","points":6},{"critere":"Milieux de [AC] et [BD] tous deux égaux à (3,5 ; 4,5)","points":5},{"critere":"Non-alignement justifié par un déterminant non nul (−10)","points":5}],"dureeMin":12,"corrige":"1. →AB (5 − 1 ; 3 − 2) = **(4 ; 1)**.\n2. ABCD est un parallélogramme si et seulement si →AB = →DC. Avec D(x ; y) : →DC (6 − x ; 7 − y) = (4 ; 1), donc x = 2 et y = 6 : **D(2 ; 6)**.\n3. Milieu de [AC] : ((1 + 6)/2 ; (2 + 7)/2) = (3,5 ; 4,5). Milieu de [BD] : ((5 + 2)/2 ; (3 + 6)/2) = (3,5 ; 4,5). Les diagonales ont **le même milieu** : ABCD est bien un parallélogramme.\n4. →AC (5 ; 5) et →AE (8 ; 6). Déterminant : 5 × 6 − 5 × 8 = 30 − 40 = **−10 ≠ 0**. Les vecteurs ne sont pas colinéaires : **A, C et E ne sont pas alignés**."}$exo$::jsonb),
  ('a6fc7a9d-dc23-5456-bb58-751dc2551f24'::uuid, 3, 'probleme', $exo${"titre":"Un triangle étudié par le calcul","consigne":"Le plan est muni d'un repère orthonormé. Rédige chaque démonstration par le calcul.","enonce":"On donne A(−2 ; 1), B(2 ; 3) et C(4 ; −1).\n\n1. Calcule les longueurs AB, BC et AC (valeurs exactes).\n2. Démontre que le triangle ABC est rectangle et isocèle, en précisant le sommet.\n3. Détermine les coordonnées du point D tel que ABCD soit un parallélogramme.\n4. Calcule les coordonnées du centre K de ce parallélogramme, et vérifie que K est aussi le milieu de [BD].\n5. Le point M(8 ; 6) est-il aligné avec A et B ? Justifie.","bareme":[{"critere":"AB = √20, BC = √20, AC = √40","points":5},{"critere":"Rectangle en B par la réciproque de Pythagore et isocèle (AB = BC)","points":4},{"critere":"D (0 ; −3) par →AB = →DC","points":4},{"critere":"K (1 ; 0) milieu de [AC] et de [BD]","points":3},{"critere":"Alignement de A, B, M justifié par un déterminant nul","points":4}],"dureeMin":18,"corrige":"1. →AB (4 ; 2) : AB = √(16 + 4) = **√20**. →BC (2 ; −4) : BC = √(4 + 16) = **√20**. →AC (6 ; −2) : AC = √(36 + 4) = **√40**.\n2. AB² + BC² = 20 + 20 = 40 = AC². D'après la réciproque de Pythagore, ABC est **rectangle en B**. Comme AB = BC, il est aussi **isocèle en B**.\n3. →AB = →DC avec D(x ; y) : (4 − x ; −1 − y) = (4 ; 2), donc x = 0 et y = −3 : **D(0 ; −3)**.\n4. K milieu de [AC] : ((−2 + 4)/2 ; (1 − 1)/2) = **(1 ; 0)**. Milieu de [BD] : ((2 + 0)/2 ; (3 − 3)/2) = (1 ; 0) : c'est bien K.\n5. →AB (4 ; 2) et →AM (10 ; 5). Déterminant : 4 × 5 − 2 × 10 = 20 − 20 = **0**. Les vecteurs sont colinéaires et ont le point A en commun : **A, B et M sont alignés**."}$exo$::jsonb),
  ('e2803fe6-baa3-5cc6-b2e1-54da7febc1cd'::uuid, 1, 'probleme', $exo${"titre":"L'équation d'une droite par deux points","consigne":"Détaille chaque calcul.","enonce":"On donne A(1 ; 3) et B(4 ; 9).\n\n1. Calcule le coefficient directeur m de la droite (AB), puis son ordonnée à l'origine p. Écris l'équation réduite de (AB).\n2. Donne un vecteur directeur de (AB). La droite monte-t-elle ou descend-elle ?\n3. Le point C(−2 ; −3) appartient-il à (AB) ? Et le point E(3 ; 6) ?","bareme":[{"critere":"m = 2, p = 1 et équation réduite y = 2x + 1","points":10},{"critere":"Vecteur directeur (1 ; 2) et droite qui monte (m > 0)","points":4},{"critere":"C appartient à la droite, E non, par substitution des coordonnées","points":6}],"dureeMin":8,"corrige":"1. m = (9 − 3)/(4 − 1) = 6/3 = **2**. A appartient à la droite : 3 = 2 × 1 + p, donc **p = 1**. Équation réduite : **y = 2x + 1**.\n2. Un vecteur directeur est **(1 ; m) = (1 ; 2)**. m > 0 : la droite **monte**.\n3. Pour C : 2 × (−2) + 1 = −3, égal à l'ordonnée de C : **C ∈ (AB)**. Pour E : 2 × 3 + 1 = 7 ≠ 6 : **E ∉ (AB)**."}$exo$::jsonb),
  ('e2803fe6-baa3-5cc6-b2e1-54da7febc1cd'::uuid, 2, 'probleme', $exo${"titre":"Deux compagnies de taxi","consigne":"Lis la situation, puis réponds en justifiant chaque calcul.","enonce":"**Situation.** Le prix d'une course de taxi (en €) dépend de la distance x (en km).\n- La compagnie A facture selon la droite d'équation y = 1,5x + 4.\n- Pour la compagnie B, une course de 0 km coûte 7 € et une course de 10 km coûte 19 € ; son prix est aussi représenté par une droite.\n\n1. Détermine l'équation réduite de la droite de la compagnie B.\n2. Interprète le coefficient directeur et l'ordonnée à l'origine de chaque droite.\n3. Les deux droites sont-elles parallèles ? Calcule les coordonnées de leur point d'intersection.\n4. Pour une course de 20 km, quelle compagnie est la moins chère ? Justifie.","bareme":[{"critere":"Droite B : y = 1,2x + 7","points":5},{"critere":"Interprétation : prix par km (coefficient directeur) et prise en charge (ordonnée à l'origine)","points":4},{"critere":"Droites sécantes (1,5 ≠ 1,2) et intersection (10 ; 19) par résolution du système","points":7},{"critere":"Comparaison à 20 km : A 34 €, B 31 €, B moins chère","points":4}],"dureeMin":12,"corrige":"1. m = (19 − 7)/(10 − 0) = 12/10 = **1,2** ; p = 7 (prix pour 0 km). Droite B : **y = 1,2x + 7**.\n2. Le coefficient directeur est le prix par kilomètre (1,50 € pour A, 1,20 € pour B) ; l'ordonnée à l'origine est le prix fixe de prise en charge (4 € pour A, 7 € pour B).\n3. Les coefficients directeurs sont différents (1,5 ≠ 1,2) : les droites sont **sécantes**. On résout 1,5x + 4 = 1,2x + 7, soit 0,3x = 3, donc **x = 10**, puis y = 1,5 × 10 + 4 = **19**. Point d'intersection : **(10 ; 19)** : pour 10 km, les deux courses coûtent 19 €.\n4. À 20 km : A coûte 1,5 × 20 + 4 = **34 €**, B coûte 1,2 × 20 + 7 = **31 €**. La compagnie **B** est la moins chère (au-delà de 10 km, sa droite, moins pentue, est au-dessous)."}$exo$::jsonb),
  ('e2803fe6-baa3-5cc6-b2e1-54da7febc1cd'::uuid, 3, 'probleme', $exo${"titre":"Équations cartésiennes et positions relatives","consigne":"Justifie chaque réponse à l'aide des vecteurs directeurs ou des coefficients directeurs.","enonce":"On considère les droites :\n- d₁ d'équation 2x − y + 3 = 0 ;\n- d₂ passant par A(1 ; −1) et de vecteur directeur u(1 ; 2) ;\n- d₃ d'équation x + 2y − 4 = 0.\n\n1. Donne un vecteur directeur de d₁ et de d₃.\n2. Détermine l'équation réduite de d₂. Les droites d₁ et d₂ sont-elles parallèles ? Sont-elles confondues ?\n3. Montre que d₁ et d₃ sont sécantes, puis calcule les coordonnées de leur point d'intersection.\n4. Donne une équation de la droite parallèle à l'axe des ordonnées passant par A.","bareme":[{"critere":"Vecteurs directeurs (1 ; 2) pour d₁ et (−2 ; 1) pour d₃ avec la règle (−b ; a)","points":4},{"critere":"d₂ : y = 2x − 3, parallèle à d₁ mais non confondue","points":5},{"critere":"Sécantes justifiées (déterminant non nul ou coefficients différents)","points":3},{"critere":"Intersection (−0,4 ; 2,2) par résolution du système, vérifiée","points":5},{"critere":"Droite verticale x = 1","points":3}],"dureeMin":18,"corrige":"1. d₁ : a = 2, b = −1, vecteur directeur (−b ; a) = **(1 ; 2)**. d₃ : a = 1, b = 2, vecteur directeur **(−2 ; 1)**.\n2. u(1 ; 2) = (1 ; m) donc m = 2 ; A ∈ d₂ : −1 = 2 × 1 + p, p = −3. **d₂ : y = 2x − 3**. d₁ s'écrit y = 2x + 3 : même coefficient directeur 2, donc **d₁ et d₂ sont parallèles**. Leurs ordonnées à l'origine diffèrent (3 et −3) : elles ne sont **pas confondues** (strictement parallèles).\n3. Déterminant de (1 ; 2) et (−2 ; 1) : 1 × 1 − 2 × (−2) = 5 ≠ 0 : les vecteurs directeurs ne sont pas colinéaires, les droites sont **sécantes**. Système : y = 2x + 3 et x + 2y − 4 = 0. En substituant : x + 2(2x + 3) − 4 = 0, soit 5x + 2 = 0, **x = −0,4** ; y = 2 × (−0,4) + 3 = **2,2**. Point d'intersection **(−0,4 ; 2,2)**. Vérification dans d₃ : −0,4 + 4,4 − 4 = 0.\n4. Une droite parallèle à l'axe des ordonnées a une équation x = c ; elle passe par A : **x = 1**."}$exo$::jsonb),
  ('5731af00-4e7e-53c3-a955-cf8dc2e069c7'::uuid, 1, 'probleme', $exo${"titre":"Images, antécédents, ensemble de définition","consigne":"Réponds à chaque question en détaillant tes calculs.","enonce":"On considère la fonction f définie sur ℝ par f(x) = x² − 3x.\n\n1. Calcule l'image de 2 et l'image de −1 par f.\n2. Vérifie que 0 et 3 sont deux antécédents de 0 par f. Le nombre 0 a-t-il un seul antécédent ?\n3. Donne l'ensemble de définition de chacune des fonctions suivantes, en justifiant :\n   a. g(x) = 1/(x − 5)\n   b. h(x) = √(x − 2)","bareme":[{"critere":"Images justes : f(2) = −2 et f(−1) = 4","points":6},{"critere":"Vérification f(0) = 0 et f(3) = 0, et remarque qu'un nombre peut avoir plusieurs antécédents","points":6},{"critere":"Ensembles de définition : ℝ privé de 5 et [2 ; +∞[, justifiés","points":8}],"dureeMin":8,"corrige":"1. f(2) = 2² − 3 × 2 = 4 − 6 = **−2**. f(−1) = (−1)² − 3 × (−1) = 1 + 3 = **4**.\n2. f(0) = 0 − 0 = 0 et f(3) = 9 − 9 = 0 : **0 et 3 sont des antécédents de 0**. Le nombre 0 a donc **au moins deux** antécédents : rien n'interdit à un nombre d'avoir plusieurs antécédents (c'est l'image qui est unique).\n3.\n   a. Le dénominateur ne doit pas s'annuler : x − 5 ≠ 0, x ≠ 5. **Df = ℝ privé de 5**, soit ]−∞ ; 5[ ∪ ]5 ; +∞[.\n   b. L'intérieur de la racine doit être positif ou nul : x − 2 ≥ 0, x ≥ 2. **Dh = [2 ; +∞[**."}$exo$::jsonb),
  ('5731af00-4e7e-53c3-a955-cf8dc2e069c7'::uuid, 2, 'probleme', $exo${"titre":"Lire un tableau de variations","consigne":"Réponds en t'appuyant uniquement sur le tableau de variations, et justifie chaque réponse.","enonce":"Une fonction f est définie sur [−3 ; 5]. Son tableau de variations indique :\n- f(−3) = 2 ;\n- f est **décroissante** sur [−3 ; 1], jusqu'à f(1) = −4 ;\n- f est **croissante** sur [1 ; 5], jusqu'à f(5) = 3.\n\n1. Donne le minimum et le maximum de f sur [−3 ; 5], et les valeurs de x où ils sont atteints.\n2. Compare f(−2) et f(0), puis f(2) et f(4). Justifie par le sens de variation.\n3. Combien l'équation f(x) = 0 a-t-elle de solutions sur [−3 ; 5] ? Justifie.\n4. Peut-on comparer f(0) et f(4) à l'aide du tableau ? Explique.","bareme":[{"critere":"Minimum −4 en x = 1 et maximum 3 en x = 5","points":5},{"critere":"Comparaisons f(−2) ≥ f(0) et f(2) ≤ f(4) justifiées par la décroissance puis la croissance","points":7},{"critere":"Deux solutions à f(x) = 0, une sur chaque intervalle de monotonie","points":5},{"critere":"Explication : f(0) et f(4) ne sont pas sur un même intervalle de monotonie, comparaison impossible","points":3}],"dureeMin":12,"corrige":"1. Les valeurs extrêmes du tableau sont 2, −4 et 3. **Minimum : −4, atteint en x = 1. Maximum : 3, atteint en x = 5** (3 > 2).\n2. −2 et 0 sont dans [−3 ; 1] où f est décroissante : elle inverse l'ordre ; −2 ≤ 0 donc **f(−2) ≥ f(0)**. 2 et 4 sont dans [1 ; 5] où f est croissante : elle conserve l'ordre ; 2 ≤ 4 donc **f(2) ≤ f(4)**. (Les flèches indiquant ici une variation stricte, on accepte aussi les inégalités strictes.)\n3. Sur [−3 ; 1], f décroît de 2 à −4 : elle prend la valeur 0 **une fois**. Sur [1 ; 5], f croît de −4 à 3 : elle prend la valeur 0 **une fois**. L'équation f(x) = 0 a **deux solutions**, l'une entre −3 et 1, l'autre entre 1 et 5.\n4. **Non.** 0 est dans [−3 ; 1] et 4 dans [1 ; 5] : on sait seulement que f(0) est entre −4 et 2, et f(4) entre −4 et 3. Le tableau ne permet pas de trancher : il faudrait connaître les valeurs."}$exo$::jsonb),
  ('5731af00-4e7e-53c3-a955-cf8dc2e069c7'::uuid, 3, 'probleme', $exo${"titre":"Le rectangle d'aire maximale","consigne":"Lis la situation, puis réponds en justifiant chaque étape.","enonce":"**Situation.** Nour veut délimiter un enclos rectangulaire avec 20 m de grillage (le périmètre vaut 20 m). On note x la largeur en mètres, et A(x) l'aire de l'enclos en m².\n\n1. Montre que la longueur vaut 10 − x, puis que A(x) = x(10 − x). Explique pourquoi on étudie A sur l'intervalle [0 ; 10].\n2. Recopie et complète le tableau de valeurs :\n\n| x | 0 | 2 | 4 | 5 | 6 | 8 | 10 |\n| A(x) | | | | | | | |\n\n3. À l'aide du tableau, conjecture le sens de variation de A et son maximum.\n4. Développe (x − 5)², puis vérifie que 25 − A(x) = (x − 5)². Déduis-en que A(x) ≤ 25 pour tout x, et que 25 est bien le maximum.\n5. Quels sont les antécédents de 16 par A ? Vérifie par le calcul.","bareme":[{"critere":"Expression de la longueur et de A(x), intervalle [0 ; 10] justifié","points":3},{"critere":"Tableau de valeurs juste : 0, 16, 24, 25, 24, 16, 0","points":4},{"critere":"Conjecture : croissante sur [0 ; 5], décroissante sur [5 ; 10], maximum 25 en 5","points":4},{"critere":"Démonstration 25 − A(x) = (x − 5)² ≥ 0, donc maximum 25 atteint en x = 5","points":5},{"critere":"Antécédents de 16 : 2 et 8, vérifiés","points":4}],"dureeMin":18,"corrige":"1. Le périmètre vaut 2 × (largeur + longueur) = 20, donc largeur + longueur = 10 et la longueur vaut **10 − x**. A(x) = largeur × longueur = **x(10 − x)**. Une longueur est positive : x ≥ 0 et 10 − x ≥ 0, donc x ∈ **[0 ; 10]**.\n2. A(0) = 0 ; A(2) = 2 × 8 = 16 ; A(4) = 4 × 6 = 24 ; A(5) = 5 × 5 = 25 ; A(6) = 6 × 4 = 24 ; A(8) = 8 × 2 = 16 ; A(10) = 0.\n3. A semble **croissante sur [0 ; 5]** et **décroissante sur [5 ; 10]**, avec un **maximum de 25 m² en x = 5** (l'enclos carré de 5 m de côté).\n4. (x − 5)² = x² − 10x + 25. Et 25 − A(x) = 25 − 10x + x² = x² − 10x + 25. Donc **25 − A(x) = (x − 5)²**. Un carré est positif ou nul, donc 25 − A(x) ≥ 0, soit **A(x) ≤ 25** pour tout x. Comme A(5) = 25, **25 est le maximum**, atteint en x = 5.\n5. D'après le tableau, A(2) = 16 et A(8) = 16 : **les antécédents de 16 sont 2 et 8**. Vérification : 2 × (10 − 2) = 16 et 8 × (10 − 8) = 16."}$exo$::jsonb),
  ('4ed95570-6c2d-5152-b81e-57fdaaaa08c8'::uuid, 1, 'probleme', $exo${"titre":"Une fonction affine décroissante","consigne":"Réponds à chaque question en justifiant.","enonce":"On considère la fonction f définie sur ℝ par f(x) = −3x + 6.\n\n1. Donne les valeurs de a et de b. Quel est le sens de variation de f ? Justifie.\n2. Calcule f(0), f(2) et f(−1). Que représente f(0) pour la droite représentative ?\n3. Pour quelle valeur de x la fonction f s'annule-t-elle ? Dresse le tableau de signes de f.","bareme":[{"critere":"a = −3, b = 6 et f décroissante car a < 0","points":6},{"critere":"f(0) = 6 (ordonnée à l'origine), f(2) = 0, f(−1) = 9","points":6},{"critere":"f s'annule en 2 ; positive avant 2, négative après","points":8}],"dureeMin":7,"corrige":"1. **a = −3** et **b = 6**. Comme a < 0, f est **décroissante** sur ℝ.\n2. f(0) = **6** : c'est l'**ordonnée à l'origine**, l'ordonnée du point où la droite coupe l'axe des ordonnées. f(2) = −6 + 6 = **0** ; f(−1) = 3 + 6 = **9**.\n3. f(x) = 0 pour x = −b/a = −6/(−3) = **2**. Comme a < 0 :\n\n| x | −∞ … 2 | 2 … +∞ |\n| f(x) | + (0 en 2) | − |\n\nf est **positive** sur ]−∞ ; 2] et **négative** sur [2 ; +∞[."}$exo$::jsonb),
  ('4ed95570-6c2d-5152-b81e-57fdaaaa08c8'::uuid, 2, 'probleme', $exo${"titre":"Deux abonnements à la salle de sport","consigne":"Lis la situation, puis réponds en justifiant tes calculs.","enonce":"**Situation.** Une salle de sport propose deux formules pour l'année, x désignant le nombre de séances :\n- formule A : 20 € d'inscription puis 8 € par séance ;\n- formule B : son prix est donné par une fonction affine g ; on sait que 5 séances coûtent 65 € et que 15 séances coûtent 135 €.\n\n1. Exprime le prix f(x) de la formule A. Explique pourquoi f est affine et ce que représentent ses coefficients.\n2. Détermine l'expression de g(x) en calculant d'abord a par le taux d'accroissement.\n3. Pour combien de séances les deux formules coûtent-elles le même prix ? Au-delà, quelle formule est la moins chère ? Justifie.","bareme":[{"critere":"f(x) = 8x + 20 avec l'interprétation : 8 € par séance, 20 € fixes","points":5},{"critere":"g(x) = 7x + 30 : a = 70/10 = 7 puis b par réinjection d'un point","points":7},{"critere":"Égalité en x = 10 (100 €) et formule B moins chère au-delà, justifiée","points":8}],"dureeMin":11,"corrige":"1. **f(x) = 8x + 20**. C'est une fonction affine (forme ax + b) : a = 8 est le prix d'une séance (le coefficient directeur), b = 20 le forfait fixe d'inscription (l'ordonnée à l'origine).\n2. Taux d'accroissement : a = (135 − 65)/(15 − 5) = 70/10 = **7**. Avec le point (5 ; 65) : 65 = 7 × 5 + b, soit b = 65 − 35 = **30**. **g(x) = 7x + 30**. Vérification : 7 × 15 + 30 = 135.\n3. 8x + 20 = 7x + 30 donne **x = 10** : 10 séances coûtent **100 €** dans les deux formules. Au-delà, f(x) − g(x) = x − 10 > 0 pour x > 10 : la formule A est plus chère, donc la **formule B est la moins chère** (sa séance coûte 7 € au lieu de 8 €). Par exemple, pour 20 séances : A = 180 €, B = 170 €."}$exo$::jsonb),
  ('4ed95570-6c2d-5152-b81e-57fdaaaa08c8'::uuid, 3, 'probleme', $exo${"titre":"Retrouver une fonction affine et l'utiliser","consigne":"Justifie chaque étape ; les tableaux de signes doivent être complets.","enonce":"f est une fonction affine telle que f(−2) = 7 et f(4) = −5.\n\n1. Détermine l'expression de f(x).\n2. Sans calcul supplémentaire, quel est le taux d'accroissement de f entre 0 et 10 ? Justifie par une propriété du cours.\n3. Détermine le nombre qui annule f, puis dresse le tableau de signes de f.\n4. On pose g(x) = x + 2. Résous l'inéquation f(x) × g(x) ≥ 0 à l'aide d'un tableau de signes.\n5. La fonction f est-elle linéaire ? Justifie.","bareme":[{"critere":"f(x) = −2x + 3 : a = −12/6 = −2 puis b = 3","points":5},{"critere":"Taux d'accroissement égal à −2 quelle que soit la paire, propriété caractéristique citée","points":3},{"critere":"f s'annule en 1,5 ; positive avant, négative après (a < 0)","points":4},{"critere":"Tableau de signes du produit juste et solution [−2 ; 1,5]","points":6},{"critere":"f non linéaire car b ≠ 0","points":2}],"dureeMin":18,"corrige":"1. a = (f(4) − f(−2))/(4 − (−2)) = (−5 − 7)/6 = −12/6 = **−2**. Avec f(−2) = 7 : 7 = −2 × (−2) + b, soit b = **3**. **f(x) = −2x + 3**.\n2. Pour une fonction affine, le taux d'accroissement est **constant et égal à a**, quelle que soit la paire de valeurs choisie : entre 0 et 10, il vaut **−2**. (Vérification : (f(10) − f(0))/10 = (−17 − 3)/10 = −2.)\n3. f(x) = 0 pour x = −b/a = −3/(−2) = **1,5**. Comme a < 0, f est **positive** avant 1,5 et **négative** après.\n4. g(x) = x + 2 s'annule en −2 ; a = 1 > 0 : négative avant, positive après.\n\n| x | −∞ … −2 | −2 … 1,5 | 1,5 … +∞ |\n| f(x) | + | + | − |\n| g(x) | − | + | + |\n| produit | − | + | − |\n\nLe produit est nul en −2 et en 1,5. **S = [−2 ; 1,5]**.\n5. Une fonction linéaire a b = 0. Ici b = 3 ≠ 0 : f **n'est pas linéaire** (sa droite ne passe pas par l'origine)."}$exo$::jsonb),
  ('acc9b508-36d7-59bf-a1d2-79ea5d1bbdc3'::uuid, 1, 'probleme', $exo${"titre":"Équations x² = k et comparaisons","consigne":"Réponds en justifiant à l'aide des propriétés de la fonction carré.","enonce":"1. Résous dans ℝ les équations suivantes :\n   a. x² = 49\n   b. x² = −9\n   c. x² = 0\n2. Dresse le tableau de variations de la fonction carré et donne son minimum.\n3. Sans calculer les carrés, compare :\n   a. 2,3² et 2,5²\n   b. (−4)² et (−3)²","bareme":[{"critere":"Solutions : 7 et −7 ; aucune ; 0","points":8},{"critere":"Tableau de variations (décroissante puis croissante) et minimum 0 en 0","points":5},{"critere":"Comparaisons justifiées par le sens de variation sur le bon intervalle","points":7}],"dureeMin":8,"corrige":"1.\n   a. 49 > 0 : deux solutions, **x = 7 ou x = −7**.\n   b. −9 < 0 : un carré n'est jamais négatif, **aucune solution**.\n   c. **x = 0**, seule solution.\n2. La fonction carré est **décroissante sur ]−∞ ; 0]** et **croissante sur [0 ; +∞[**. Son **minimum est 0**, atteint en x = 0 (sommet de la parabole).\n3.\n   a. 2,3 et 2,5 sont dans [0 ; +∞[ où la fonction carré est croissante (elle conserve l'ordre) : 2,3 < 2,5 donc **2,3² < 2,5²**.\n   b. −4 et −3 sont dans ]−∞ ; 0] où elle est décroissante (elle inverse l'ordre) : −4 < −3 donc **(−4)² > (−3)²** (16 > 9)."}$exo$::jsonb),
  ('acc9b508-36d7-59bf-a1d2-79ea5d1bbdc3'::uuid, 2, 'probleme', $exo${"titre":"Le potager carré","consigne":"Réponds en justifiant, et écris les solutions sous forme d'intervalles.","enonce":"1. Résous dans ℝ les inéquations :\n   a. x² ≤ 16\n   b. x² > 4\n2. **Situation.** Rayan veut un potager carré de côté x mètres (x > 0) dont l'aire ne dépasse pas 81 m². Quelles sont les valeurs possibles de x ? Justifie.\n3. Hugo affirme : « Si a < b, alors a² < b². » Est-ce vrai ? Justifie par un contre-exemple ou une démonstration, et dis dans quel cas l'affirmation est vraie.","bareme":[{"critere":"x² ≤ 16 : [−4 ; 4]","points":6},{"critere":"x² > 4 : ]−∞ ; −2[ ∪ ]2 ; +∞[","points":6},{"critere":"Côté du potager dans ]0 ; 9] avec la contrainte x > 0","points":4},{"critere":"Affirmation fausse avec un contre-exemple, vraie pour a et b positifs","points":4}],"dureeMin":12,"corrige":"1.\n   a. x² ≤ 16 : les carrés inférieurs ou égaux à 16 sont ceux des nombres entre −4 et 4 (parabole sous la droite y = 16). **S = [−4 ; 4]**.\n   b. x² > 4 : **S = ]−∞ ; −2[ ∪ ]2 ; +∞[**.\n2. L'aire est x² ≤ 81, donc x ∈ [−9 ; 9] ; comme x > 0 (c'est une longueur), **x ∈ ]0 ; 9]** : le côté mesure au plus 9 m.\n3. **Faux** en général : −3 < 2 mais (−3)² = 9 > 2² = 4. Passer au carré ne conserve pas l'ordre. L'affirmation est **vraie lorsque a et b sont positifs ou nuls**, car la fonction carré est croissante sur [0 ; +∞[."}$exo$::jsonb),
  ('acc9b508-36d7-59bf-a1d2-79ea5d1bbdc3'::uuid, 3, 'probleme', $exo${"titre":"Encadrer un carré, résoudre avec la parabole","consigne":"Justifie chaque réponse par une propriété de la fonction carré.","enonce":"1. Résous l'équation (x − 3)² = 25.\n2. Résous l'inéquation x² ≤ 2. Donne les bornes en valeur exacte.\n3. Donne le meilleur encadrement possible de x² :\n   a. lorsque −3 ≤ x ≤ −1 ;\n   b. lorsque −1 ≤ x ≤ 2.\n4. Justifie par un calcul que la fonction carré est paire, et vérifie-le avec x = 2,5. Quelle conséquence graphique cela a-t-il ?","bareme":[{"critere":"(x − 3)² = 25 : x − 3 = 5 ou −5, donc x = 8 ou x = −2","points":5},{"critere":"x² ≤ 2 : [−√2 ; √2]","points":4},{"critere":"Encadrement 1 ≤ x² ≤ 9 par la décroissance sur les négatifs","points":4},{"critere":"Encadrement 0 ≤ x² ≤ 4 en tenant compte du minimum atteint en 0","points":5},{"critere":"Parité : (−x)² = x², vérification 6,25, symétrie par rapport à l'axe des ordonnées","points":2}],"dureeMin":18,"corrige":"1. On pose X = x − 3 : X² = 25 donne X = 5 ou X = −5 (ne pas oublier la solution négative). Donc x − 3 = 5, **x = 8**, ou x − 3 = −5, **x = −2**.\n2. x² ≤ 2 : **S = [−√2 ; √2]** (même raisonnement que x² ≤ 9 donne [−3 ; 3]).\n3.\n   a. Sur [−3 ; −1] ⊂ ]−∞ ; 0], la fonction carré est **décroissante** : elle inverse l'ordre. De −3 ≤ x ≤ −1 on tire (−1)² ≤ x² ≤ (−3)², soit **1 ≤ x² ≤ 9**.\n   b. L'intervalle [−1 ; 2] contient 0 : il faut couper. Sur [−1 ; 0], x² va de 1 à 0 ; sur [0 ; 2], x² va de 0 à 4. Le minimum est 0 (atteint en 0) et le maximum est le plus grand de 1 et 4 : **0 ≤ x² ≤ 4**. (Élever −1 ≤ x ≤ 2 au carré « terme à terme » donnerait 1 ≤ x² ≤ 4, ce qui est faux : pour x = 0, x² = 0.)\n4. Pour tout réel x, (−x)² = x² : la fonction carré est **paire**. Vérification : (−2,5)² = 6,25 = 2,5². Conséquence : sa courbe, la parabole, est **symétrique par rapport à l'axe des ordonnées**."}$exo$::jsonb),
  ('0336f88f-89aa-50c3-b8f0-9a437b1138d7'::uuid, 1, 'probleme', $exo${"titre":"Cubes et racines cubiques","consigne":"Réponds en justifiant par une propriété de la fonction cube.","enonce":"1. Résous dans ℝ les équations :\n   a. x³ = 64\n   b. x³ = −125\n   c. x³ = 0\n2. Sans calcul, donne le signe de (−2)³ et celui de 3³. Justifie.\n3. Compare (−3)³ et (−2)³ sans les calculer, puis vérifie par le calcul.","bareme":[{"critere":"Solutions uniques : 4, −5, 0","points":8},{"critere":"Signes justifiés : x³ a le signe de x","points":5},{"critere":"Comparaison (−3)³ < (−2)³ justifiée par la croissance sur ℝ et vérifiée (−27 < −8)","points":7}],"dureeMin":7,"corrige":"1. L'équation x³ = k a **toujours exactement une** solution.\n   a. 4³ = 64 : **x = 4**.\n   b. (−5)³ = −125 : **x = −5** (le cube garde le signe, une solution négative existe).\n   c. **x = 0**.\n2. x³ a **le signe de x** : (−2)³ est **négatif**, 3³ est **positif**.\n3. La fonction cube est **croissante sur ℝ** : elle conserve l'ordre quels que soient les signes. −3 < −2 donc **(−3)³ < (−2)³**. Vérification : −27 < −8."}$exo$::jsonb),
  ('0336f88f-89aa-50c3-b8f0-9a437b1138d7'::uuid, 2, 'probleme', $exo${"titre":"L'aquarium cubique","consigne":"Lis la situation, puis réponds en justifiant.","enonce":"**Situation.** Le volume d'un cube d'arête a (en cm) vaut a³ (en cm³).\n\n1. Un aquarium cubique a un volume de 27 000 cm³. Quelle est la longueur de son arête ? Justifie qu'il n'y a qu'une seule réponse possible.\n2. Un second aquarium cubique contient 8 litres, soit 8 000 cm³. Calcule son arête.\n3. Sami affirme : « Pour tout nombre positif x, x³ est plus grand que x². » Teste son affirmation avec x = 0,5 et x = 3, puis dis sur quel intervalle elle est vraie et sur lequel elle est fausse.","bareme":[{"critere":"Arête de 30 cm et unicité de la solution de x³ = k","points":6},{"critere":"Arête de 20 cm","points":4},{"critere":"Calculs 0,125 < 0,25 et 27 > 9","points":5},{"critere":"Conclusion : x³ ≤ x² sur [0 ; 1], x³ ≥ x² sur [1 ; +∞[, affirmation fausse","points":5}],"dureeMin":11,"corrige":"1. On résout a³ = 27 000. Or 30³ = 27 000 : **a = 30 cm**. L'équation x³ = k a toujours **exactement une** solution (la fonction cube est croissante sur ℝ) : c'est la seule réponse.\n2. a³ = 8 000 et 20³ = 8 000 : **a = 20 cm**.\n3. Pour x = 0,5 : x³ = 0,125 et x² = 0,25, donc **x³ < x²**. Pour x = 3 : x³ = 27 et x² = 9, donc **x³ > x²**. L'affirmation de Sami est **fausse** : sur [0 ; 1], x³ ≤ x² (élever à une puissance plus grande rapproche de 0) ; sur [1 ; +∞[, x³ ≥ x². Les deux sont égaux en 0 et en 1."}$exo$::jsonb),
  ('0336f88f-89aa-50c3-b8f0-9a437b1138d7'::uuid, 3, 'probleme', $exo${"titre":"Cube contre carré","consigne":"Justifie chaque réponse par une propriété du cours.","enonce":"1. Calcule f(−2) et f(2) pour f(x) = x³. Quelle propriété de la fonction cube illustres-tu ? Quelle en est la conséquence graphique ? Compare avec la fonction carré.\n2. Donne le meilleur encadrement de x³, puis de x², lorsque −2 ≤ x ≤ 3.\n3. Range dans l'ordre croissant x, x² et x³ pour x = 0,4, en donnant leurs valeurs. Aurais-tu pu prévoir cet ordre sans calcul ?\n4. Résous l'inéquation x³ ≤ −8.\n5. Combien l'équation x³ = −1 a-t-elle de solutions ? Et l'équation x² = −1 ? Explique la différence.","bareme":[{"critere":"f(−2) = −8, f(2) = 8 : fonction impaire, symétrie par rapport à l'origine, opposée à la parité du carré","points":3},{"critere":"Encadrements −8 ≤ x³ ≤ 27 et 0 ≤ x² ≤ 9","points":5},{"critere":"Rangement 0,064 < 0,16 < 0,4 prévu par la règle sur [0 ; 1]","points":4},{"critere":"x³ ≤ −8 équivaut à x ≤ −2, justifié par la conservation de l'ordre","points":4},{"critere":"Une solution (−1) pour le cube, aucune pour le carré, avec l'explication sur le signe","points":4}],"dureeMin":18,"corrige":"1. f(−2) = −8 et f(2) = 8 : f(−x) = −f(x), la fonction cube est **impaire** ; sa courbe est **symétrique par rapport à l'origine**. La fonction carré, elle, est paire (symétrie par rapport à l'axe des ordonnées).\n2. La fonction cube est croissante sur ℝ : de −2 ≤ x ≤ 3 on tire **−8 ≤ x³ ≤ 27**. Pour le carré, l'intervalle contient 0 : le minimum est 0 et le maximum le plus grand de 4 et 9 : **0 ≤ x² ≤ 9**.\n3. x = 0,4 ; x² = 0,16 ; x³ = 0,064. Ordre : **x³ < x² < x**. On pouvait le prévoir : sur [0 ; 1], **x³ ≤ x² ≤ x** (élever à une puissance plus grande rapproche de 0).\n4. −8 = (−2)³. La fonction cube conserve l'ordre, donc x³ ≤ (−2)³ équivaut à x ≤ −2 : **S = ]−∞ ; −2]**.\n5. x³ = −1 a **exactement une** solution : x = −1 (le cube garde le signe). x² = −1 n'en a **aucune** : un carré n'est jamais négatif. C'est la différence du cours : le cube garde le signe, le carré l'efface."}$exo$::jsonb),
  ('68f4b5d4-7e86-5ae9-b5b2-8243fed0fb0b'::uuid, 1, 'probleme', $exo${"titre":"Premiers pas avec la racine carrée","consigne":"Réponds en justifiant chaque réponse.","enonce":"1. Quel est l'ensemble de définition de la fonction racine carrée ? Pourquoi ? Calcule √49 et √0,25.\n2. Résous les équations :\n   a. √x = 6\n   b. √x = −2\n3. Compare 0,36 et √0,36. Le résultat est-il surprenant ? Explique à l'aide du cours.","bareme":[{"critere":"Ensemble [0 ; +∞[ justifié ; √49 = 7 et √0,25 = 0,5","points":6},{"critere":"√x = 6 donne x = 36 ; √x = −2 n'a pas de solution","points":8},{"critere":"√0,36 = 0,6 > 0,36, expliqué par x ≤ √x sur [0 ; 1]","points":6}],"dureeMin":7,"corrige":"1. La racine carrée n'est définie que sur **[0 ; +∞[** : la racine carrée d'un nombre négatif n'existe pas dans ℝ. √49 = **7** et √0,25 = **0,5** (0,5² = 0,25).\n2.\n   a. 6 ≥ 0 : x = 6² = **36**.\n   b. Une racine carrée est toujours positive ou nulle : **aucune solution**.\n3. √0,36 = 0,6 et **0,6 > 0,36**. Ce n'est pas surprenant : sur [0 ; 1], **x ≤ √x** — la racine d'un nombre compris entre 0 et 1 est plus grande que lui."}$exo$::jsonb),
  ('68f4b5d4-7e86-5ae9-b5b2-8243fed0fb0b'::uuid, 2, 'probleme', $exo${"titre":"Du côté du carré à la racine","consigne":"Lis chaque situation, puis réponds en justifiant.","enonce":"1. Paul écrit : « √((−4)²) = −4. » Trouve son erreur, donne la bonne valeur et la règle générale qui s'applique.\n2. **Situation.** Élise veut dessiner deux jardins carrés, l'un de 50 m², l'autre de 72 m².\n   a. Exprime le côté de chaque jardin à l'aide d'une racine carrée, puis donne une valeur approchée au centimètre près.\n   b. Sans calculatrice, comment savoir lequel a le plus grand côté ? Justifie par le sens de variation.\n3. Résous l'équation √(2x − 1) = 3, puis vérifie la solution trouvée dans l'équation de départ.","bareme":[{"critere":"√((−4)²) = 4 et règle √(x²) = |x|","points":5},{"critere":"Côtés √50 ≈ 7,07 m et √72 ≈ 8,49 m, comparaison par la croissance de la racine","points":7},{"critere":"Équation résolue en élevant au carré (x = 5) puis vérifiée","points":8}],"dureeMin":12,"corrige":"1. √((−4)²) = √16 = **4**, pas −4 : une racine carrée est toujours positive. La règle générale est **√(x²) = |x|** pour tout réel x ; l'égalité √(x²) = x n'est vraie que pour x ≥ 0.\n2.\n   a. Le côté c vérifie c² = aire, avec c > 0 : c = √50 ≈ **7,07 m** et c = √72 ≈ **8,49 m**.\n   b. La fonction racine carrée est **croissante** sur [0 ; +∞[ : 50 < 72 donc √50 < √72. Le jardin de 72 m² a le plus grand côté.\n3. On élève au carré : 2x − 1 = 9, donc 2x = 10, **x = 5**. Vérification (indispensable : élever au carré peut créer des solutions parasites) : √(2 × 5 − 1) = √9 = 3. **S = {5}**."}$exo$::jsonb),
  ('68f4b5d4-7e86-5ae9-b5b2-8243fed0fb0b'::uuid, 3, 'probleme', $exo${"titre":"La solution parasite","consigne":"Justifie chaque étape ; toute solution doit être vérifiée.","enonce":"On veut résoudre l'équation (E) : √(x + 6) = x.\n\n1. Pour quelles valeurs de x le membre de gauche est-il défini ?\n2. En élevant au carré, montre que toute solution de (E) vérifie x² − x − 6 = 0.\n3. Vérifie en développant que x² − x − 6 = (x − 3)(x + 2), puis résous x² − x − 6 = 0.\n4. Vérifie chaque valeur trouvée dans (E). Conclus, et explique le phénomène observé.\n5. Compare √x, x et x² pour x = 0,64, puis pour x = 4. Quelle règle du cours retrouves-tu ?\n6. Donne un encadrement de √x lorsque 4 ≤ x ≤ 9.","bareme":[{"critere":"Domaine x ≥ −6","points":2},{"critere":"Mise au carré, développement de (x − 3)(x + 2) et solutions 3 et −2","points":5},{"critere":"Vérification : 3 convient, −2 est une solution parasite (√4 = 2 ≠ −2), S = {3}","points":5},{"critere":"Comparaisons 0,4096 < 0,64 < 0,8 et 2 < 4 < 16, règle selon la position par rapport à 1","points":5},{"critere":"Encadrement 2 ≤ √x ≤ 3 par la croissance de la racine","points":3}],"dureeMin":18,"corrige":"1. Il faut x + 6 ≥ 0, soit **x ≥ −6**.\n2. Si √(x + 6) = x, en élevant au carré : x + 6 = x², soit **x² − x − 6 = 0**.\n3. (x − 3)(x + 2) = x² + 2x − 3x − 6 = x² − x − 6. Produit nul : **x = 3 ou x = −2**.\n4. Pour x = 3 : √9 = 3 = x, **3 est solution**. Pour x = −2 : √4 = 2 ≠ −2, **−2 n'est pas solution**. **S = {3}**. Élever au carré a créé une **solution parasite** : l'équation x + 6 = x² est aussi vérifiée quand √(x + 6) = −x. Une racine étant positive, la solution doit aussi vérifier x ≥ 0.\n5. Pour x = 0,64 : √x = 0,8 et x² = 0,4096, donc **x² < x < √x**. Pour x = 4 : √x = 2, x² = 16, donc **√x < x < x²**. On retrouve : sur [0 ; 1], x ≤ √x ; sur [1 ; +∞[, √x ≤ x (les points d'égalité sont 0 et 1).\n6. La fonction racine carrée est croissante : de 4 ≤ x ≤ 9 on tire √4 ≤ √x ≤ √9, soit **2 ≤ √x ≤ 3**."}$exo$::jsonb),
  ('edc04d10-a2b2-5bd7-8771-91d651f4a52b'::uuid, 1, 'probleme', $exo${"titre":"Calculer avec l'inverse","consigne":"Réponds en justifiant chaque réponse.","enonce":"1. Quel est l'ensemble de définition de la fonction inverse ? Pourquoi ?\n2. Calcule l'image par la fonction inverse de 4, de −0,5 et de 0,2.\n3. Résous les équations :\n   a. 1/x = 5\n   b. 1/x = −4\n   c. 1/x = 0","bareme":[{"critere":"Ensemble ℝ privé de 0, justifié par l'impossibilité de diviser par 0","points":4},{"critere":"Images 0,25 ; −2 ; 5","points":6},{"critere":"Solutions 0,2 ; −0,25 ; aucune pour 1/x = 0","points":10}],"dureeMin":7,"corrige":"1. **ℝ privé de 0**, soit ]−∞ ; 0[ ∪ ]0 ; +∞[ : diviser par zéro n'a pas de sens, 0 est une valeur interdite.\n2. 1/4 = **0,25** ; 1/(−0,5) = **−2** ; 1/0,2 = **5**.\n3.\n   a. k = 5 non nul : x = 1/5 = **0,2**.\n   b. x = 1/(−4) = **−0,25**.\n   c. Un quotient 1/x n'est jamais nul (son numérateur vaut 1) : **aucune solution**."}$exo$::jsonb),
  ('edc04d10-a2b2-5bd7-8771-91d651f4a52b'::uuid, 2, 'probleme', $exo${"titre":"Comparer des inverses sans se tromper","consigne":"Justifie chaque réponse par le sens de variation de la fonction inverse sur le bon intervalle.","enonce":"1. Compare 1/3 et 1/7 sans calcul.\n2. Compare 1/(−2) et 1/(−5) sans calcul, puis vérifie avec les valeurs décimales.\n3. Inès écrit : « La fonction inverse est décroissante et −1 < 2, donc 1/(−1) > 1/2. » Vérifie son résultat par le calcul, puis explique son erreur de raisonnement.\n4. On sait que 2 ≤ x ≤ 5. Donne un encadrement de 1/x.","bareme":[{"critere":"1/3 > 1/7 justifié par la décroissance sur ]0 ; +∞[","points":5},{"critere":"1/(−5) > 1/(−2) justifié par la décroissance sur ]−∞ ; 0[, vérifié (−0,2 > −0,5)","points":5},{"critere":"Conclusion d'Inès fausse (−1 < 0,5) : pas de décroissance sur la réunion des deux intervalles","points":5},{"critere":"Encadrement 0,2 ≤ 1/x ≤ 0,5 avec inversion de l'ordre","points":5}],"dureeMin":11,"corrige":"1. 3 et 7 sont dans ]0 ; +∞[ où la fonction inverse est **décroissante** (elle inverse l'ordre) : 3 < 7 donc **1/3 > 1/7**.\n2. −5 et −2 sont dans ]−∞ ; 0[ où elle est décroissante : −5 < −2 donc **1/(−5) > 1/(−2)**. Vérification : −0,2 > −0,5.\n3. 1/(−1) = −1 et 1/2 = 0,5 : −1 < 0,5, donc la conclusion d'Inès est **fausse**. Son erreur : −1 et 2 ne sont **pas dans le même intervalle**. La fonction inverse est décroissante sur ]−∞ ; 0[ et sur ]0 ; +∞[ séparément, mais **pas** sur leur réunion : on ne peut comparer par le sens de variation que deux nombres du même intervalle.\n4. 2 et 5 sont dans ]0 ; +∞[ où la fonction est décroissante : de 2 ≤ x ≤ 5 on tire 1/5 ≤ 1/x ≤ 1/2, soit **0,2 ≤ 1/x ≤ 0,5**."}$exo$::jsonb),
  ('edc04d10-a2b2-5bd7-8771-91d651f4a52b'::uuid, 3, 'probleme', $exo${"titre":"L'inéquation 1/x ≤ 2","consigne":"Rédige une résolution complète avec un tableau de signes, puis réponds aux questions d'analyse.","enonce":"On veut résoudre dans ℝ privé de 0 l'inéquation 1/x ≤ 2.\n\n1. Léa multiplie les deux membres par x et obtient 1 ≤ 2x, donc x ≥ 0,5. Teste x = −1 dans l'inéquation de départ : que constates-tu ? Explique l'erreur de Léa.\n2. Montre que l'inéquation équivaut à (1 − 2x)/x ≤ 0.\n3. Dresse le tableau de signes de (1 − 2x)/x, en indiquant la valeur interdite.\n4. Déduis-en l'ensemble des solutions.\n5. Vérifie ta réponse avec x = 0,25 et x = 1.","bareme":[{"critere":"x = −1 est solution et l'erreur de Léa expliquée (signe de x inconnu, sens de l'inégalité)","points":4},{"critere":"Réduction au même dénominateur : 1/x − 2 = (1 − 2x)/x","points":4},{"critere":"Tableau de signes juste avec double barre en 0 et zéro en 0,5","points":6},{"critere":"S = ]−∞ ; 0[ ∪ [0,5 ; +∞[","points":4},{"critere":"Vérifications justes avec 0,25 et 1","points":2}],"dureeMin":18,"corrige":"1. Pour x = −1 : 1/(−1) = −1 ≤ 2, donc **−1 est solution**, alors que Léa a trouvé x ≥ 0,5. Son erreur : elle a multiplié par x **sans connaître son signe**. Si x < 0, multiplier par x **inverse** le sens de l'inégalité ; elle a donc perdu toutes les solutions négatives.\n2. 1/x ≤ 2 équivaut à 1/x − 2 ≤ 0, et 1/x − 2 = 1/x − 2x/x = **(1 − 2x)/x**.\n3. 1 − 2x s'annule en 0,5 (positif avant, négatif après : coefficient −2) ; x s'annule en 0 (valeur interdite).\n\n| x | −∞ … 0 | 0 … 0,5 | 0,5 … +∞ |\n| 1 − 2x | + | + | − |\n| x | − | + | + |\n| quotient | − (double barre en 0) | + (0 en 0,5) | − |\n\n4. Le quotient est négatif ou nul sur ]−∞ ; 0[ et sur [0,5 ; +∞[ (0,5 inclus car le quotient y est nul, 0 exclu car interdit). **S = ]−∞ ; 0[ ∪ [0,5 ; +∞[**.\n5. x = 0,25 : 1/0,25 = 4 > 2, **non solution** (0,25 ∉ S). x = 1 : 1/1 = 1 ≤ 2, **solution** (1 ∈ S)."}$exo$::jsonb),
  ('4a031ed0-b4ad-598f-8555-fd3e7ddc6ae1'::uuid, 1, 'probleme', $exo${"titre":"Pourcentages et coefficients","consigne":"Détaille chaque calcul.","enonce":"1. Dans une classe de 30 élèves, 9 font du théâtre. Quelle est la proportion d'élèves qui font du théâtre ? Exprime-la en pourcentage.\n2. Calcule 35 % de 240.\n3. Donne le coefficient multiplicateur associé à une hausse de 12 %, puis à une baisse de 8 %.\n4. Un jeu vidéo coûte 45 €. Son prix augmente de 12 %. Calcule le nouveau prix.","bareme":[{"critere":"Proportion 0,3 soit 30 % et 35 % de 240 = 84","points":6},{"critere":"Coefficients 1,12 et 0,92","points":6},{"critere":"Nouveau prix 50,40 € obtenu avec le coefficient multiplicateur","points":8}],"dureeMin":7,"corrige":"1. Proportion = 9/30 = **0,3**, soit **30 %**.\n2. 240 × 35/100 = **84**.\n3. Hausse de 12 % : 1 + 12/100 = **1,12**. Baisse de 8 % : 1 − 8/100 = **0,92**.\n4. On multiplie le prix de départ par le coefficient de la hausse : 45 × 1,12 = **50,40 €** (la hausse vaut 45 × 0,12 = 5,40 €)."}$exo$::jsonb),
  ('4a031ed0-b4ad-598f-8555-fd3e7ddc6ae1'::uuid, 2, 'probleme', $exo${"titre":"Au lycée et en boutique","consigne":"Lis chaque situation, puis réponds en justifiant tes calculs.","enonce":"1. **Au lycée.** Un lycée compte 1 200 élèves. 30 % sont en seconde, et 45 % des élèves de seconde sont demi-pensionnaires.\n   a. Quelle proportion de l'ensemble des élèves du lycée est en seconde et demi-pensionnaire ? Donne-la en pourcentage.\n   b. Combien d'élèves cela représente-t-il ? Vérifie en passant par le nombre d'élèves de seconde.\n2. **En boutique.** Une veste coûte 80 €. Son prix augmente de 25 %, puis baisse de 20 %. Calcule le prix final et le coefficient global. Explique le résultat.\n3. **Au bac blanc.** Le taux de réussite passe de 80 % à 84 %. Donne l'évolution en points, puis en pourcentage.","bareme":[{"critere":"Proportion 0,3 × 0,45 = 0,135 soit 13,5 %, et 162 élèves vérifiés","points":6},{"critere":"Prix final 80 €, coefficient global 1,25 × 0,8 = 1, évolution réciproque expliquée","points":7},{"critere":"+4 points et +5 %, sans confondre les deux","points":7}],"dureeMin":12,"corrige":"1.\n   a. Proportion de proportion : 0,30 × 0,45 = **0,135**, soit **13,5 %**.\n   b. 1 200 × 0,135 = **162 élèves**. Vérification : 1 200 × 0,30 = 360 élèves de seconde, et 360 × 0,45 = 162.\n2. 80 × 1,25 = 100 €, puis 100 × 0,80 = **80 €**. Coefficient global : 1,25 × 0,80 = **1** : on revient au prix de départ. Ce n'est pas le cas en général (une hausse de 20 % puis une baisse de 20 % donne 0,96) ; ici, la baisse de 20 % est exactement l'**évolution réciproque** d'une hausse de 25 %, car 1/1,25 = 0,80.\n3. En **points** : 84 − 80 = **+4 points**. En **pourcentage** : 84/80 = 1,05, soit **+5 %**. Les deux ne doivent pas être confondus."}$exo$::jsonb),
  ('4a031ed0-b4ad-598f-8555-fd3e7ddc6ae1'::uuid, 3, 'probleme', $exo${"titre":"Démêler les chiffres d'un article","consigne":"Analyse chaque affirmation en justifiant par le calcul. Arrondis les pourcentages au centième.","enonce":"**Document.** Un journal local écrit :\n> « La population de notre ville, qui comptait 20 000 habitants, a augmenté de 10 % la première année, baissé de 5 % la deuxième, puis augmenté de 2 % la troisième. Au total, elle a donc augmenté de 7 %. Par ailleurs, le taux de chômage est passé de 7,5 % à 9 % : il a augmenté de 1,5 %. »\n\n1. Calcule le coefficient multiplicateur global sur les trois ans, puis le pourcentage d'évolution global.\n2. Calcule la population au bout des trois ans.\n3. Explique l'erreur de raisonnement du journal sur l'évolution de la population.\n4. Quelle évolution en pourcentage faudrait-il ensuite pour revenir à 20 000 habitants ? Justifie.\n5. Corrige la phrase sur le chômage en distinguant points et pourcentage.","bareme":[{"critere":"Coefficient global 1,1 × 0,95 × 1,02 = 1,0659, soit +6,59 %","points":5},{"critere":"Population finale 21 318 habitants","points":3},{"critere":"Erreur expliquée : on multiplie les coefficients, on n'additionne pas les pourcentages","points":4},{"critere":"Évolution réciproque : coefficient 1/1,0659 ≈ 0,9382, baisse d'environ 6,18 %","points":4},{"critere":"Chômage : +1,5 point mais +20 %","points":4}],"dureeMin":18,"corrige":"1. Coefficient global : 1,10 × 0,95 × 1,02 = 1,045 × 1,02 = **1,0659**. Évolution globale : **+6,59 %**.\n2. 20 000 × 1,0659 = **21 318 habitants**.\n3. Le journal a **additionné les pourcentages** (10 − 5 + 2 = 7). Or des évolutions successives se composent en **multipliant les coefficients** : chaque pourcentage s'applique à une population qui a déjà changé. Le vrai résultat est +6,59 %, pas +7 %.\n4. Évolution réciproque : coefficient **1/1,0659 ≈ 0,9382**, soit une **baisse d'environ 6,18 %** (et non de 6,59 %). Vérification : 21 318 × 0,9382 ≈ 20 000.\n5. Le taux passe de 7,5 % à 9 % : c'est une hausse de **1,5 point**. En pourcentage, 9/7,5 = 1,2, soit une hausse de **20 %**. Dire « 1,5 % » confond points et pourcentage."}$exo$::jsonb),
  ('d6f0ce64-ca85-5f51-9cd2-7fecd9d86b4b'::uuid, 1, 'probleme', $exo${"titre":"Les notes de Jade","consigne":"Détaille chaque calcul.","enonce":"Voici les notes de Jade au premier trimestre : 8 ; 12 ; 15 ; 9 ; 12 ; 14 ; 7.\n\n1. Calcule la moyenne de ces notes.\n2. Range les notes dans l'ordre croissant, puis détermine la médiane.\n3. Calcule l'étendue de la série. Que mesure-t-elle ?","bareme":[{"critere":"Moyenne 77/7 = 11","points":7},{"critere":"Série ordonnée et médiane 12 (4e valeur sur 7)","points":7},{"critere":"Étendue 15 − 7 = 8, interprétée comme l'écart entre extrêmes","points":6}],"dureeMin":8,"corrige":"1. Somme : 8 + 12 + 15 + 9 + 12 + 14 + 7 = 77. Moyenne : 77/7 = **11**.\n2. Série ordonnée : 7 ; 8 ; 9 ; 12 ; 12 ; 14 ; 15. Il y a 7 valeurs : la médiane est la 4e, **12** (3 notes en dessous, 3 au-dessus).\n3. Étendue : 15 − 7 = **8**. Elle mesure l'écart entre la plus grande et la plus petite note."}$exo$::jsonb),
  ('d6f0ce64-ca85-5f51-9cd2-7fecd9d86b4b'::uuid, 2, 'probleme', $exo${"titre":"Les salaires d'une petite entreprise","consigne":"Lis la situation, puis réponds en détaillant tes calculs.","enonce":"**Situation.** Les neuf salariés d'une entreprise touchent, en euros par mois :\n1 600 ; 1 700 ; 1 700 ; 1 800 ; 1 900 ; 2 000 ; 2 100 ; 2 200 ; 9 000 (le salaire du dirigeant).\n\nOn rappelle : Q1 est la plus petite valeur de la série ordonnée telle qu'au moins 25 % des valeurs lui soient inférieures ou égales ; Q3 est la plus petite valeur telle qu'au moins 75 % des valeurs lui soient inférieures ou égales.\n\n1. Calcule le salaire moyen (arrondi à l'euro) et le salaire médian.\n2. Détermine Q1, Q3 et l'écart interquartile.\n3. Le dirigeant annonce : « Chez nous, on gagne en moyenne plus de 2 600 € par mois. » Que penses-tu de cette présentation ? Quel indicateur de position est le plus représentatif ici, et pourquoi ?","bareme":[{"critere":"Moyenne ≈ 2 667 € (24 000 / 9) et médiane 1 900 €","points":5},{"critere":"Q1 = 1 700 €, Q3 = 2 100 €, écart interquartile 400 €","points":6},{"critere":"Critique : moyenne tirée vers le haut par une valeur extrême","points":5},{"critere":"Choix justifié de la médiane, insensible aux extrêmes","points":4}],"dureeMin":12,"corrige":"1. Somme : 1 600 + 1 700 + 1 700 + 1 800 + 1 900 + 2 000 + 2 100 + 2 200 = 15 000, plus 9 000 : 24 000. Moyenne : 24 000/9 ≈ **2 667 €**. La série est ordonnée, 9 valeurs : la médiane est la 5e, **1 900 €**.\n2. 25 % de 9 = 2,25 : Q1 est la 3e valeur, **1 700 €**. 75 % de 9 = 6,75 : Q3 est la 7e valeur, **2 100 €**. Écart interquartile : 2 100 − 1 700 = **400 €**.\n3. L'annonce est **exacte mais trompeuse** : huit salariés sur neuf gagnent 2 200 € ou moins. La moyenne est **tirée vers le haut** par le salaire du dirigeant (9 000 €), car elle est très sensible aux valeurs extrêmes. La **médiane** (1 900 €) est plus représentative : elle partage les salariés en deux moitiés et n'est pas influencée par la valeur extrême. C'est pour cela qu'on publie le salaire médian."}$exo$::jsonb),
  ('d6f0ce64-ca85-5f51-9cd2-7fecd9d86b4b'::uuid, 3, 'probleme', $exo${"titre":"Combien de livres par an ?","consigne":"Détaille chaque calcul et justifie tes interprétations.","enonce":"On a demandé aux 25 élèves d'une classe A combien de livres ils avaient lus pendant l'été.\n\n| Nombre de livres | 0 | 1 | 2 | 3 | 4 | 5 |\n| Effectif | 3 | 5 | 7 | 5 | 3 | 2 |\n\nOn rappelle : Q1 est la plus petite valeur de la série ordonnée telle qu'au moins 25 % des valeurs lui soient inférieures ou égales ; Q3, la plus petite telle qu'au moins 75 % des valeurs lui soient inférieures ou égales.\n\n1. Calcule la moyenne pondérée de la classe A.\n2. Détermine la médiane, Q1, Q3 et l'écart interquartile.\n3. Dans une classe B de 35 élèves, on trouve : moyenne 3,2 ; médiane 2 ; Q1 = 0 ; Q3 = 5. Compare la dispersion des deux classes.\n4. Hugo calcule la moyenne des 60 élèves des deux classes ainsi : (2,24 + 3,2)/2. Donne son résultat, explique pourquoi il est faux et calcule la vraie moyenne.","bareme":[{"critere":"Moyenne pondérée 56/25 = 2,24","points":4},{"critere":"Médiane 2, Q1 = 1, Q3 = 3 et écart interquartile 2 à l'aide des effectifs cumulés","points":6},{"critere":"Comparaison : écart interquartile 5 en B contre 2 en A, B plus dispersée","points":4},{"critere":"Moyenne de moyennes 2,72 fausse (effectifs différents) et vraie moyenne 168/60 = 2,8","points":6}],"dureeMin":18,"corrige":"1. Somme pondérée : 0 × 3 + 1 × 5 + 2 × 7 + 3 × 5 + 4 × 3 + 5 × 2 = 0 + 5 + 14 + 15 + 12 + 10 = 56. Moyenne : 56/25 = **2,24 livres**.\n2. Effectifs cumulés croissants : 3 ; 8 ; 15 ; 20 ; 23 ; 25.\n- Médiane : 25 valeurs, la 13e. 8 < 13 ≤ 15 : **médiane = 2**.\n- Q1 : 25 % de 25 = 6,25, donc la 7e valeur. 3 < 7 ≤ 8 : **Q1 = 1**.\n- Q3 : 75 % de 25 = 18,75, donc la 19e valeur. 15 < 19 ≤ 20 : **Q3 = 3**.\n- Écart interquartile : 3 − 1 = **2**.\n3. Les deux classes ont la même médiane (2), mais l'écart interquartile de B vaut 5 − 0 = **5**, contre **2** pour A : le cœur de la série B est beaucoup plus **dispersé** (des élèves qui ne lisent rien et d'autres qui lisent beaucoup). La moyenne ne suffit pas à décrire une série.\n4. Hugo obtient (2,24 + 3,2)/2 = **2,72**. C'est faux : une **moyenne de moyennes** ne tient pas compte des effectifs (25 et 35 élèves). Vraie moyenne : nombre total de livres (56 + 3,2 × 35 = 56 + 112 = 168) divisé par 60 élèves : 168/60 = **2,8 livres**."}$exo$::jsonb),
  ('32e56704-95df-5107-b4a8-0293761dfcbc'::uuid, 1, 'probleme', $exo${"titre":"Un lancer de dé","consigne":"Justifie chaque probabilité.","enonce":"On lance un dé équilibré à six faces numérotées de 1 à 6.\n\n1. Décris l'univers Ω de cette expérience. Pourquoi est-on en situation d'équiprobabilité ?\n2. On note A l'événement « obtenir un multiple de 3 ». Écris A comme une partie de Ω et calcule P(A).\n3. On note B l'événement « obtenir au moins 2 ». Décris l'événement contraire de B, puis calcule P(B) en l'utilisant.","bareme":[{"critere":"Ω = {1 ; 2 ; 3 ; 4 ; 5 ; 6} et équiprobabilité justifiée par le dé équilibré","points":5},{"critere":"A = {3 ; 6} et P(A) = 2/6 = 1/3","points":7},{"critere":"Contraire de B = {1} et P(B) = 1 − 1/6 = 5/6","points":8}],"dureeMin":7,"corrige":"1. **Ω = {1 ; 2 ; 3 ; 4 ; 5 ; 6}**. Le dé est équilibré : chaque face a la même probabilité, 1/6 : c'est une situation d'**équiprobabilité**.\n2. **A = {3 ; 6}**. P(A) = issues favorables / issues possibles = 2/6 = **1/3**.\n3. Le contraire de B est « obtenir moins de 2 », soit **{1}**, de probabilité 1/6. Donc P(B) = 1 − 1/6 = **5/6**."}$exo$::jsonb),
  ('32e56704-95df-5107-b4a8-0293761dfcbc'::uuid, 2, 'probleme', $exo${"titre":"Sport et lycéens","consigne":"Lis la situation, puis réponds en justifiant chaque probabilité.","enonce":"**Situation.** On a interrogé 200 lycéens. 110 sont des filles. Parmi les filles, 66 pratiquent un sport en club ; parmi les garçons, 60 pratiquent un sport en club.\n\n1. Recopie et complète le tableau à double entrée :\n\n| | Sport | Pas de sport | Total |\n| Filles | | | |\n| Garçons | | | |\n| Total | | | 200 |\n\n2. On choisit un lycéen au hasard. On note F « c'est une fille » et S « il pratique un sport en club ». Calcule P(F), P(S) et P(F ∩ S).\n3. Calcule P(F ∪ S) à l'aide de la formule du cours, puis vérifie avec le tableau.","bareme":[{"critere":"Tableau complet et juste (44, 90, 30, 126, 74)","points":4},{"critere":"P(F) = 0,55 et P(S) = 0,63","points":4},{"critere":"P(F ∩ S) = 0,33 identifiée comme l'intersection","points":6},{"critere":"P(F ∪ S) = 0,85 par la formule, vérifiée par le tableau (170 / 200)","points":6}],"dureeMin":12,"corrige":"1.\n\n| | Sport | Pas de sport | Total |\n| Filles | 66 | 44 | 110 |\n| Garçons | 60 | 30 | 90 |\n| Total | 126 | 74 | 200 |\n\n2. Situation d'équiprobabilité (choix au hasard) : P(F) = 110/200 = **0,55** ; P(S) = 126/200 = **0,63** ; F ∩ S = « fille qui pratique un sport » : P(F ∩ S) = 66/200 = **0,33**.\n3. P(F ∪ S) = P(F) + P(S) − P(F ∩ S) = 0,55 + 0,63 − 0,33 = **0,85**. Vérification : F ∪ S regroupe les 110 filles et les 60 garçons sportifs, soit 170 lycéens, et 170/200 = 0,85. La soustraction évite de compter deux fois les 66 filles sportives."}$exo$::jsonb),
  ('32e56704-95df-5107-b4a8-0293761dfcbc'::uuid, 3, 'probleme', $exo${"titre":"Deux tirages dans une urne","consigne":"Construis un arbre de probabilités et justifie chaque calcul.","enonce":"**Situation.** Une urne contient 3 boules rouges (R) et 2 boules bleues (B), indiscernables au toucher. On tire une boule, on note sa couleur, on la **remet** dans l'urne, puis on tire une seconde boule.\n\n1. Construis l'arbre de probabilités de cette expérience.\n2. Calcule la probabilité d'obtenir deux boules rouges, puis celle d'obtenir deux boules de la même couleur.\n3. Calcule la probabilité d'obtenir au moins une boule bleue, en utilisant l'événement contraire.\n4. Calcule la probabilité d'obtenir exactement une boule rouge. Vérifie la cohérence de tes résultats en additionnant les probabilités d'événements qui couvrent tous les cas.","bareme":[{"critere":"Arbre complet avec les probabilités 3/5 et 2/5 à chaque tirage","points":4},{"critere":"P(RR) = 9/25 et P(même couleur) = 13/25","points":6},{"critere":"P(au moins une bleue) = 1 − 9/25 = 16/25 par l'événement contraire","points":5},{"critere":"P(exactement une rouge) = 12/25 et vérification 13/25 + 12/25 = 1","points":5}],"dureeMin":18,"corrige":"1. Premier tirage : R avec probabilité 3/5, B avec probabilité 2/5. La boule est remise : au second tirage, depuis chaque branche, R avec 3/5 et B avec 2/5. Quatre chemins : RR, RB, BR, BB.\n2. On multiplie le long d'un chemin : P(RR) = 3/5 × 3/5 = **9/25**. P(BB) = 2/5 × 2/5 = 4/25. Même couleur = RR ou BB (chemins incompatibles, on additionne) : 9/25 + 4/25 = **13/25**.\n3. Le contraire de « au moins une bleue » est « aucune bleue », c'est-à-dire RR. P = 1 − 9/25 = **16/25**.\n4. Exactement une rouge : RB ou BR. P(RB) = 3/5 × 2/5 = 6/25, P(BR) = 2/5 × 3/5 = 6/25 ; total **12/25**. Vérification : « même couleur » et « exactement une rouge » couvrent tous les cas sans se chevaucher : 13/25 + 12/25 = 25/25 = 1. De même, P(au moins une bleue) = P(RB) + P(BR) + P(BB) = 6/25 + 6/25 + 4/25 = 16/25, ce qui confirme la question 3."}$exo$::jsonb),
  ('9a7eedff-74a9-5095-87f1-a7ecb7ce6d4b'::uuid, 1, 'probleme', $exo${"titre":"L'intervalle de fluctuation","consigne":"Réponds en justifiant chaque calcul.","enonce":"1. Qu'appelle-t-on fluctuation d'échantillonnage ? Est-ce une erreur de mesure ?\n2. Dans une grande population, la proportion d'un caractère vaut p = 0,3. On prélève des échantillons de taille n = 400. Calcule l'intervalle de fluctuation au seuil de 95 %.\n3. Un échantillon de 400 personnes donne une fréquence observée f = 0,28. Ce résultat est-il compatible avec p = 0,3 ? Justifie.","bareme":[{"critere":"Définition : variation de la fréquence observée d'un échantillon à l'autre, inhérente au tirage","points":6},{"critere":"Intervalle [0,25 ; 0,35] avec 1/√400 = 0,05","points":8},{"critere":"0,28 dans l'intervalle : résultat compatible, pas de rejet","points":6}],"dureeMin":7,"corrige":"1. La **fluctuation d'échantillonnage** est la variation de la fréquence observée d'un échantillon à l'autre, pour des échantillons de même taille. Ce n'est **pas une erreur de mesure** : elle est inhérente au tirage au hasard.\n2. 1/√400 = 1/20 = 0,05. Intervalle : [0,3 − 0,05 ; 0,3 + 0,05] = **[0,25 ; 0,35]**.\n3. 0,28 appartient à [0,25 ; 0,35] : le résultat est **compatible** avec p = 0,3, on ne rejette pas cette valeur au seuil de 95 %."}$exo$::jsonb),
  ('9a7eedff-74a9-5095-87f1-a7ecb7ce6d4b'::uuid, 2, 'probleme', $exo${"titre":"La pièce est-elle truquée ?","consigne":"Lis la situation, puis réponds en justifiant chaque conclusion.","enonce":"**Situation.** Yanis veut savoir si sa pièce est équilibrée, c'est-à-dire si la probabilité d'obtenir « pile » vaut p = 0,5.\n\n1. Il lance la pièce 100 fois et obtient 62 fois « pile ». Calcule la fréquence observée et l'intervalle de fluctuation au seuil de 95 %. Que peut-il conclure ?\n2. Son amie Salomé lance une autre pièce 2 500 fois et obtient 1 290 fois « pile ». Même question.\n3. Salomé en déduit : « Ma pièce est donc parfaitement équilibrée. » Qu'en penses-tu ?\n4. Par combien a été divisée la demi-largeur de l'intervalle en passant de 100 à 2 500 lancers ? Relie ce résultat à la racine de n.","bareme":[{"critere":"f = 0,62 hors de [0,4 ; 0,6] : hypothèse rejetée au seuil de 95 %","points":5},{"critere":"f = 0,516 dans [0,48 ; 0,52] : hypothèse non rejetée","points":5},{"critere":"Ne pas rejeter n'est pas démontrer","points":5},{"critere":"Demi-largeur divisée par 5 (0,1 à 0,02) car n est multiplié par 25 et √25 = 5","points":5}],"dureeMin":12,"corrige":"1. f = 62/100 = **0,62**. 1/√100 = 0,1 : intervalle [0,5 − 0,1 ; 0,5 + 0,1] = **[0,4 ; 0,6]**. 0,62 est **hors** de l'intervalle : on **rejette** l'hypothèse « la pièce est équilibrée », au seuil de 95 %.\n2. f = 1 290/2 500 = **0,516**. 1/√2 500 = 1/50 = 0,02 : intervalle **[0,48 ; 0,52]**. 0,516 est **dans** l'intervalle : on **ne rejette pas** l'hypothèse.\n3. Salomé va trop loin : ne pas rejeter l'hypothèse **n'est pas la démontrer**. Le résultat est seulement compatible avec p = 0,5 ; une pièce très légèrement déséquilibrée pourrait donner le même résultat.\n4. La demi-largeur passe de 0,1 à 0,02 : elle est **divisée par 5**. n a été multiplié par 25, et la précision dépend de la **racine** de n : √25 = 5."}$exo$::jsonb),
  ('9a7eedff-74a9-5095-87f1-a7ecb7ce6d4b'::uuid, 3, 'probleme', $exo${"titre":"Clients satisfaits : vérifier une affirmation","consigne":"Analyse la situation en justifiant chaque conclusion par le cours.","enonce":"**Situation.** Une entreprise de livraison affirme sur son site : « 80 % de nos clients sont satisfaits. » Une association de consommateurs interroge au hasard 400 clients : 296 se déclarent satisfaits.\n\n1. Calcule l'intervalle de fluctuation au seuil de 95 % associé à p = 0,8 et n = 400.\n2. Calcule la fréquence observée. Que peut conclure l'association ? Justifie.\n3. Si 312 clients s'étaient déclarés satisfaits, qu'aurait-on pu conclure ? L'affirmation de l'entreprise serait-elle alors démontrée ?\n4. L'association veut un intervalle de demi-largeur 0,025. Quelle taille d'échantillon doit-elle choisir ? Justifie.\n5. L'entreprise répond : « Sur notre page, 10 000 clients ont cliqué sur “satisfait” ou “pas satisfait”, et 85 % ont cliqué sur “satisfait”. Notre échantillon est 25 fois plus grand, il est donc plus fiable. » Critique cet argument.","bareme":[{"critere":"Intervalle [0,75 ; 0,85] avec 1/√400 = 0,05","points":4},{"critere":"f = 0,74 hors de l'intervalle : affirmation rejetée au seuil de 95 %","points":5},{"critere":"f = 0,78 dans l'intervalle : pas de rejet, mais pas de démonstration","points":3},{"critere":"n = 1 600 (1/√n = 0,025, soit n multiplié par 4)","points":4},{"critere":"Biais de recrutement (réponses volontaires) que la taille ne corrige pas","points":4}],"dureeMin":18,"corrige":"1. 1/√400 = 0,05 : intervalle [0,8 − 0,05 ; 0,8 + 0,05] = **[0,75 ; 0,85]**.\n2. f = 296/400 = **0,74**. 0,74 est **hors** de l'intervalle (0,74 < 0,75) : l'association peut **rejeter** l'affirmation « 80 % de clients satisfaits », au seuil de 95 %.\n3. f = 312/400 = 0,78, qui est **dans** l'intervalle : on n'aurait **pas rejeté** l'affirmation. Mais ne pas rejeter **n'est pas démontrer** : le résultat serait seulement compatible avec 80 %.\n4. Il faut 1/√n = 0,025, soit √n = 40, donc **n = 1 600**. On retrouve la règle : pour diviser l'incertitude par deux (de 0,05 à 0,025), il faut multiplier la taille par quatre (400 × 4).\n5. L'argument ne tient pas. Un échantillon est le résultat de tirages **indépendants au hasard** ; ici, ce sont des clients qui ont **choisi** de répondre sur la page de l'entreprise : l'échantillon est **mal recruté** (biais de recrutement). Un tel biais **ne se corrige pas par la taille** : 10 000 réponses volontaires restent biaisées, alors que 400 clients tirés au hasard donnent une information fiable, à la fluctuation près."}$exo$::jsonb),
  ('32257dd2-f18f-51b8-b4da-e741eace3198'::uuid, 1, 'redaction', $exo${"titre":"Les mots de l'analyse","consigne":"Réponds à chaque question par une ou deux phrases complètes, en employant le vocabulaire du cours.","enonce":"1. Qu'est-ce que la **tonique** dans le système tonal ?\n2. Donne la définition d'un **accord**.\n3. Nomme les trois cadences du cours et, pour chacune, indique le mouvement harmonique et l'effet produit.\n4. Associe chaque texture à sa définition : **monodie**, **homophonie**, **polyphonie**, **hétérophonie**.","bareme":[{"critere":"Tonique définie comme la note centrale autour de laquelle s'organise la tonalité","points":4},{"critere":"Accord défini comme la superposition d'au moins trois sons","points":3},{"critere":"Trois cadences nommées avec mouvement et effet exacts","points":7},{"critere":"Quatre textures correctement définies","points":6}],"dureeMin":7,"corrige":"1. La **tonique** est la note centrale du système tonal : tous les autres sons s'entendent par rapport à elle.\n2. Un **accord** superpose **au moins trois sons** joués ensemble.\n3. - **Cadence parfaite** : dominante → tonique ; effet d'**achèvement**, la phrase se ferme.\n   - **Cadence suspensive** : on s'arrête sur la dominante ; effet d'**attente**, la phrase reste ouverte.\n   - **Cadence rompue** : dominante → un autre degré que la tonique ; effet de **surprise**, l'attente est déjouée.\n4. **Monodie** : une seule ligne (chant grégorien). **Homophonie** : une mélodie accompagnée (chanson, choral). **Polyphonie** : plusieurs lignes indépendantes (fugue, motet). **Hétérophonie** : une seule ligne jouée en variantes simultanées (musiques traditionnelles)."}$exo$::jsonb),
  ('32257dd2-f18f-51b8-b4da-e741eace3198'::uuid, 2, 'redaction', $exo${"titre":"Le carnet d'écoute de Maëlle","consigne":"Lis la description d'écoute, puis réponds aux questions en utilisant le vocabulaire d'analyse du cours.","enonce":"**Document – Notes prises par Maëlle en écoutant une pièce pour chœur**\n\n> Début : une seule voix d'homme chante, sans accompagnement, sur une échelle qui ne sonne ni vraiment majeure ni vraiment mineure.\n> Milieu : quatre voix entrent l'une après l'autre ; chacune chante sa propre mélodie, et elles se croisent.\n> Fin : les quatre voix chantent ensemble les mêmes rythmes, en accords ; la dernière phrase s'arrête sur la dominante et on reste « en l'air ».\n\n1. Nomme la **texture** de chacune des trois parties. Justifie.\n2. Quel **mode** semble utilisé au début ? Donne un répertoire du cours où on le rencontre.\n3. Quelle **cadence** termine la pièce ? Quel effet produit-elle ?\n4. D'après le cours, quel est le moment le plus révélateur de l'intention du compositeur ? Explique.","bareme":[{"critere":"Monodie, polyphonie, homophonie identifiées et justifiées par le nombre et la nature des lignes","points":7},{"critere":"Mode modal identifié, avec un exemple (grégorien, musiques traditionnelles, jazz modal)","points":4},{"critere":"Cadence suspensive nommée, effet d'attente expliqué","points":4},{"critere":"Idée que le changement (rupture de texture ou de mode) révèle l'intention","points":5}],"dureeMin":10,"corrige":"1. **Début : monodie** (une seule ligne, une seule voix sans accompagnement). **Milieu : polyphonie** (plusieurs lignes mélodiques indépendantes qui se croisent). **Fin : homophonie**, ou plus exactement une écriture en accords où toutes les voix suivent les mêmes rythmes : la mélodie est portée par les accords, ce n'est plus un jeu de lignes indépendantes.\n2. Une échelle « ni majeure ni mineure » correspond au **mode modal** : une autre échelle que celles du système tonal. On la rencontre dans le **chant grégorien**, les musiques traditionnelles ou le jazz modal.\n3. La pièce finit par une **cadence suspensive** : la phrase s'arrête sur la dominante, elle ne se referme pas. Effet d'**attente**, d'inachèvement : on reste « en l'air ».\n4. Selon le cours, le moment le plus révélateur est **celui où quelque chose change** : un changement de texture ou de mode est toujours un geste du compositeur, jamais un hasard. Ici, les passages de la monodie à la polyphonie puis à l'écriture en accords, et la fin suspendue, sont les moments à interroger."}$exo$::jsonb),
  ('32257dd2-f18f-51b8-b4da-e741eace3198'::uuid, 3, 'redaction', $exo${"titre":"Analyser une rupture","consigne":"Rédige une analyse organisée (une quinzaine de lignes) à partir du document, en mobilisant les quatre outils du cours.","enonce":"**Document – Description d'une chanson écoutée en classe**\n\n> Couplets : une voix chante la mélodie, accompagnée par une guitare qui joue des accords ; mode majeur, tempo modéré. Chaque couplet se termine par une cadence parfaite.\n> Pont : la guitare se tait ; trois voix se superposent, chacune avec sa propre mélodie. Le mode devient mineur.\n> Dernier refrain : retour de la guitare et du mode majeur ; la toute dernière phrase passe de la dominante à un autre accord que la tonique, puis la chanson s'arrête.\n\n**Question.** Analyse cette chanson : décris sa texture, son mode et ses cadences partie par partie, puis montre ce que les changements révèlent de l'intention du compositeur. Tu discuteras aussi l'idée qu'un passage en mineur « exprime forcément la tristesse ».","bareme":[{"critere":"Textures justes : homophonie aux couplets, polyphonie au pont","points":4},{"critere":"Modes et cadences identifiés (parfaite aux couplets, rompue à la fin) avec leurs effets","points":5},{"critere":"Ruptures du pont et de la fin repérées et interprétées comme des gestes du compositeur","points":5},{"critere":"Discussion nuancée du lien mineur / tristesse comme perception culturelle","points":4},{"critere":"Analyse organisée, vocabulaire précis, pas de simple jugement de goût","points":2}],"dureeMin":16,"corrige":"**Couplets** : **homophonie** (une mélodie accompagnée d'accords de guitare), **mode majeur**, perçu comme lumineux. Chaque couplet se ferme par une **cadence parfaite** (dominante → tonique) : effet d'achèvement, la phrase se referme, l'auditeur est installé dans un cadre stable.\n\n**Pont** : double **rupture**. La texture passe à la **polyphonie** (trois lignes indépendantes, sans accompagnement) et le mode devient **mineur**. Selon le cours, c'est à ce moment que l'intention se lit le mieux : ce changement est un geste voulu, qui crée un contraste fort, un moment de tension ou d'intériorité au centre de la chanson.\n\n**Fin** : retour du majeur et de l'accompagnement, mais la dernière phrase se termine par une **cadence rompue** (dominante → autre degré) : l'attente d'une conclusion est **déjouée**, effet de **surprise**. Le compositeur refuse la fermeture attendue, que les couplets avaient pourtant installée par des cadences parfaites.\n\n**Mineur = triste ?** Le cours rappelle que l'association majeur/joyeux, mineur/triste est une **perception culturelle**, pas naturelle : une berceuse mineure n'est pas triste partout. On peut dire que le mineur apporte ici un contraste plus sombre ou plus tendu, mais pas qu'il « exprime forcément » la tristesse.\n\n**Conclusion attendue** : analyser, c'est nommer ce qui produit l'effet (tonalité, accord, cadence, texture) et repérer ce qui change, sans se contenter d'un jugement de goût."}$exo$::jsonb),
  ('759acb4f-463d-50c8-8e6c-5dd7294c7c2d'::uuid, 1, 'redaction', $exo${"titre":"Un siècle de machines","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Remets dans l'ordre chronologique et date : la norme **MIDI**, la **musique concrète**, le **multipiste**, le **microphone et le disque**.\n2. Qui est à l'origine de la musique concrète, et en quoi consiste-t-elle ?\n3. Vrai ou faux : « le MIDI transporte du son ». Justifie.\n4. Cite les trois grandes voies de fabrication du son par un synthétiseur.","bareme":[{"critere":"Ordre et dates justes : années 1900, 1948, années 1950, 1983","points":6},{"critere":"Pierre Schaeffer et définition de la musique concrète (sons enregistrés du réel)","points":5},{"critere":"Faux justifié : le MIDI transporte des instructions, pas du son","points":5},{"critere":"Synthèses additive, soustractive et FM citées","points":4}],"dureeMin":7,"corrige":"1. **Microphone et disque** (années 1900) → **musique concrète** (1948) → **multipiste** (années 1950) → **norme MIDI** (1983).\n2. **Pierre Schaeffer**, en 1948 : il compose à partir de **sons enregistrés du réel** (une porte, un train), qui deviennent un matériau musical.\n3. **Faux.** Le MIDI transporte des **instructions** (quelle note, quelle intensité, quelle durée), pas du son. C'est pourquoi un même fichier MIDI sonne autrement d'une machine à l'autre : chaque machine fabrique son propre son à partir des mêmes instructions.\n4. Synthèse **additive** (on empile des harmoniques), **soustractive** (on filtre un son riche en harmoniques), **FM** (on module une fréquence par une autre)."}$exo$::jsonb),
  ('759acb4f-463d-50c8-8e6c-5dd7294c7c2d'::uuid, 2, 'redaction', $exo${"titre":"Le fichier de Nathan","consigne":"Lis la situation, puis réponds aux questions en t'appuyant sur le cours.","enonce":"**Situation.** Nathan compose un morceau sur son ordinateur avec un séquenceur. Il envoie le fichier MIDI à son amie Inès. Chez elle, le morceau « ne sonne pas pareil » : le piano ressemble à un orgue. Nathan pense que le fichier a été abîmé.\n\nPour son refrain, Nathan veut aussi utiliser trois secondes d'une vieille chanson enregistrée, et le bruit d'une porte qu'il a lui-même enregistré.\n\n1. Explique à Nathan pourquoi le morceau sonne différemment chez Inès. Le fichier est-il abîmé ?\n2. Comment s'appelle le procédé qui consiste à réutiliser un extrait de chanson enregistrée ?\n3. Utiliser le bruit d'une porte comme matériau : à quel courant et à quel compositeur cela se rattache-t-il ? Date-le.\n4. Selon le cours, quelle question ces outils (échantillonnage, IA générative) rouvrent-ils ?","bareme":[{"critere":"Explication juste : le MIDI transmet des instructions, chaque machine fabrique le son","points":7},{"critere":"Échantillonnage (sampling) nommé","points":3},{"critere":"Musique concrète, Pierre Schaeffer, 1948","points":5},{"critere":"Question de l'auteur identifiée et expliquée","points":5}],"dureeMin":10,"corrige":"1. Le fichier **n'est pas abîmé**. Un fichier MIDI **ne transporte pas de son** : il transporte des **instructions** (quelle note, quelle intensité, quelle durée). C'est la machine qui lit le fichier qui fabrique le son. Le synthétiseur ou la banque de sons d'Inès n'est pas celle de Nathan : les mêmes instructions produisent donc un timbre différent (un « orgue » au lieu d'un piano).\n2. Réutiliser un extrait sonore enregistré, c'est l'**échantillonnage** (*sampling*).\n3. Composer à partir de sons enregistrés du réel, c'est le principe de la **musique concrète**, inventée par **Pierre Schaeffer** en **1948**.\n4. Ces outils déplacent la frontière entre interpréter et fabriquer et rouvrent la question de ce qu'est un **auteur** : qui est l'auteur d'un refrain fait d'un extrait d'une autre chanson, ou d'un morceau produit par une IA générative ?"}$exo$::jsonb),
  ('759acb4f-463d-50c8-8e6c-5dd7294c7c2d'::uuid, 3, 'redaction', $exo${"titre":"Jouer ou fabriquer ?","consigne":"Rédige un paragraphe argumenté d'une quinzaine de lignes, appuyé sur des exemples datés du cours.","enonce":"**Document**\n\n> « Depuis un siècle, la technologie n'accompagne plus la musique : elle la compose. Chaque outil déplace la frontière entre jouer et fabriquer. »\n\n**Question.** En t'appuyant sur au moins **quatre étapes** de l'histoire présentée dans le cours, explique cette affirmation. Montre en particulier :\n- comment le statut de l'œuvre a changé avec l'enregistrement ;\n- en quoi le studio est devenu un instrument ;\n- ce que la musique concrète et le synthétiseur ont changé au matériau sonore ;\n- pourquoi la question de l'auteur se pose aujourd'hui.","bareme":[{"critere":"Au moins quatre étapes justes et datées (1900, 1948, années 1950, 1983, aujourd'hui)","points":5},{"critere":"Changement de statut de l'œuvre : la version enregistrée devient la référence","points":4},{"critere":"Studio-instrument et nouveau matériau (sons du réel, son fabriqué, MIDI) expliqués","points":5},{"critere":"Question de l'auteur reliée à l'échantillonnage et à l'IA générative","points":4},{"critere":"Paragraphe organisé qui répond à l'affirmation","points":2}],"dureeMin":16,"corrige":"Éléments attendus, dans un ordre logique :\n\n- **Années 1900, microphone et disque** : l'œuvre devient un **objet qu'on possède**. Avec le multipiste, la **version enregistrée devient la référence**, alors qu'elle n'était au départ que la trace d'une exécution parmi d'autres.\n- **1948, musique concrète** : **Pierre Schaeffer** compose avec des **sons enregistrés du réel** (porte, train) : le matériau n'est plus seulement la note jouée. L'**électroacoustique** élargit ensuite le matériau à tout son possible, même entièrement synthétique.\n- **Années 1950, multipiste** : on enregistre piste par piste, on superpose, on retravaille : le **studio devient un instrument**. On ne capte plus un jeu, on fabrique un résultat.\n- **Synthétiseur** : il **fabrique** le son (additif, soustractif, FM). **1983, norme MIDI** : les machines dialoguent par des **instructions** (note, intensité, durée) et non par du son.\n- **Aujourd'hui** : séquenceurs, **échantillonnage**, auto-tune, **IA générative** : la frontière entre interpréter et fabriquer se déplace encore, et la question de **ce qu'est un auteur** se rouvre (celui qui échantillonne ? celui qui programme ? la machine ?).\n\n**Conclusion attendue** : chaque outil a fait passer une part de la musique du geste de l'interprète à la fabrication, jusqu'à interroger la notion même d'auteur ; la technologie ne se contente donc pas d'accompagner la musique, elle participe à sa composition."}$exo$::jsonb),
  ('082a5ebd-0e18-5ff8-a38b-8588b0e869ba'::uuid, 1, 'redaction', $exo${"titre":"Ce que décide l'interprète","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Pourquoi dit-on que l'interprète ne « restitue » pas la partition mais qu'il **choisit** ?\n2. Cite les quatre choix de l'interprète présentés dans le cours et ce que chacun change à l'écoute.\n3. Quelles sont les trois étapes d'une **écoute active** ?\n4. Qu'apporte le concert en direct qu'aucun enregistrement ne reproduit ?","bareme":[{"critere":"Idée que la partition laisse des décisions à l'interprète","points":3},{"critere":"Tempo, nuances, phrasé, instrument avec leur effet","points":8},{"critere":"Avant, pendant, après, avec le contenu de chaque étape","points":6},{"critere":"Incertitude, corps, acoustique du lieu, public","points":3}],"dureeMin":7,"corrige":"1. Une même partition donne des résultats très différents : l'interprète **prend des décisions** que la partition ne fixe pas entièrement. Il ne se contente pas de restituer, il **choisit**.\n2. - **Tempo** : l'énergie, la respiration de la phrase.\n   - **Nuances** : le relief, ce qui passe au premier plan.\n   - **Phrasé** : le sens, où la phrase respire et où elle s'enchaîne (la manière de relier et de respirer les notes).\n   - **Instrument** : la couleur, l'équilibre, la puissance.\n3. **Avant** : se demander ce qu'on va chercher (un instrument, une forme, un retour de thème). **Pendant** : repérer les **retours** et les **ruptures**. **Après** : dire ce qu'on a entendu avec des mots d'analyse, pas seulement de goût.\n4. Le direct ajoute l'**incertitude**, le **corps** des musiciens, l'**acoustique du lieu** et le **public** : le silence d'une salle attentive fait partie de l'œuvre entendue."}$exo$::jsonb),
  ('082a5ebd-0e18-5ff8-a38b-8588b0e869ba'::uuid, 2, 'redaction', $exo${"titre":"Deux versions du même Bach","consigne":"Lis le document, puis réponds aux questions en utilisant le vocabulaire du cours.","enonce":"**Document – Comparaison de deux enregistrements d'un même mouvement de Bach**\n\n| | Version A (1955) | Version B (1998) |\n| Instruments | Grand orchestre moderne, cordes en métal | Petit ensemble, cordes en boyau |\n| Diapason | Moderne | Plus bas |\n| Tempo | Lent, solennel | Vif, dansant |\n| Articulation | Notes longues et liées | Plus légère, détachée |\n\n1. Laquelle des deux versions relève de la musique **historiquement informée** ? Justifie avec trois indices du tableau.\n2. Que cherche ce mouvement et à partir de quand se développe-t-il ?\n3. Pour deux choix de l'interprète (tempo, instrument), dis ce que la différence change à l'écoute.\n4. Pourquoi le cours dit-il que comparer deux interprétations est « le raccourci le plus efficace » ?","bareme":[{"critere":"Version B identifiée avec trois indices justes (boyau, diapason bas, effectif réduit, articulation légère)","points":6},{"critere":"But du mouvement (rejouer avec les moyens de l'époque) et années 1960","points":4},{"critere":"Effets du tempo et de l'instrument à l'écoute expliqués","points":5},{"critere":"Ce qui diffère entre deux versions = ce que l'interprète décide","points":5}],"dureeMin":11,"corrige":"1. La **version B** relève de la musique historiquement informée : **cordes en boyau**, **diapason plus bas**, **effectif réduit** (petit ensemble), **articulation plus légère**. Trois de ces indices suffisent.\n2. Ce mouvement, développé **à partir des années 1960**, rejoue le répertoire ancien **avec les moyens de son temps** (instruments et techniques de l'époque). Son but est aussi de montrer que « la » version fidèle n'existe pas : le même Bach peut devenir méconnaissable.\n3. **Tempo** : il agit sur l'énergie et la respiration de la phrase ; la version A, lente, paraît solennelle, la version B, vive, retrouve un caractère dansant. **Instrument** : il agit sur la couleur, l'équilibre et la puissance ; le grand orchestre moderne sonne plus massif, le petit ensemble à cordes en boyau plus léger et plus transparent.\n4. Parce que, la partition étant la même, **ce qui diffère entre les deux versions est exactement ce que l'interprète décide** : la comparaison fait apparaître ses choix."}$exo$::jsonb),
  ('082a5ebd-0e18-5ff8-a38b-8588b0e869ba'::uuid, 3, 'redaction', $exo${"titre":"Écouter n'est pas subir","consigne":"Rédige un paragraphe argumenté d'une quinzaine de lignes.","enonce":"**Document**\n\n> Jules, en sortant du concert : « À quoi bon aller au concert ? J'ai la même symphonie en streaming, jouée par un orchestre célèbre, avec un meilleur son. Et puis écouter, c'est juste se laisser porter. »\n\n**Question.** Réponds à Jules en t'appuyant sur le cours. Tu montreras :\n- que ni l'interprète ni l'auditeur ne sont passifs ;\n- ce que l'interprète décide, et pourquoi il n'existe pas une seule version fidèle (appuie-toi sur les pratiques d'époque) ;\n- ce qu'est une écoute active, étape par étape ;\n- ce que le direct apporte que l'enregistrement ne donne pas.","bareme":[{"critere":"Rôle actif de l'interprète : choix de tempo, nuances, phrasé, instrument","points":4},{"critere":"Pratiques d'époque mobilisées : pas de version fidèle unique","points":4},{"critere":"Écoute active décrite en trois temps (avant, pendant, après)","points":5},{"critere":"Apport du direct : incertitude, corps, acoustique, public","points":4},{"critere":"Réponse argumentée et adressée à l'objection de Jules","points":3}],"dureeMin":16,"corrige":"Réponse attendue, argumentée :\n\n- **L'interprète n'est pas passif** : une même partition donne des résultats très différents. Il **choisit** le **tempo** (énergie, respiration), les **nuances** (relief), le **phrasé** (où la phrase respire et s'enchaîne), l'**instrument** (couleur, puissance). La version en streaming n'est donc qu'**une** version parmi d'autres, pas « la » symphonie.\n- **Pas de version fidèle unique** : le mouvement de la musique **historiquement informée** (à partir des années 1960) rejoue le répertoire ancien avec diapason plus bas, cordes en boyau, effectifs réduits, articulation plus légère ; le même Bach y devient méconnaissable, et c'est le but : montrer que « la » version fidèle n'existe pas.\n- **L'auditeur n'est pas passif** : écouter, ce n'est pas subir mais anticiper, comparer, repérer. **Avant** : savoir ce qu'on va chercher (un instrument, une forme, un retour de thème). **Pendant** : repérer les **retours** et les **ruptures**. **Après** : raconter ce qu'on a entendu avec des mots d'analyse. Comparer deux interprétations est le raccourci le plus efficace.\n- **Le direct** : il ajoute l'**incertitude**, le **corps** des musiciens, l'**acoustique du lieu** et le **public**. Aucun enregistrement ne reproduit une salle qui écoute ensemble ; le silence d'un public attentif fait partie de l'œuvre entendue. Un « meilleur son » n'est donc pas la même expérience.\n\n**Conclusion** : Jules confond fidélité sonore et expérience musicale ; entre la partition et lui, il y a un interprète qui décide et une écoute qui se construit."}$exo$::jsonb),
  ('0f4c7b7f-4cd7-5f83-a328-7ed3dfa8af40'::uuid, 1, 'application', $exo${"titre":"Corps pur ou mélange ?","consigne":"Réponds à chaque question par une phrase complète en utilisant le vocabulaire du cours.","enonce":"Voici six échantillons : **eau distillée**, **eau salée**, **eau et huile**, **air**, **fer**, **jus d'orange avec pulpe**.\n\n1. Donne la définition d'un **corps pur** et celle d'un **mélange homogène**.\n2. Classe les six échantillons dans un tableau à trois colonnes : corps pur, mélange homogène, mélange hétérogène.\n3. Quelle technique permet de retenir la pulpe du jus d'orange ? Quelle technique permet de récupérer le sel dissous dans l'eau salée ?","bareme":[{"critere":"Définitions exactes du corps pur (une seule espèce) et du mélange homogène (une seule phase)","points":6},{"critere":"Les six échantillons correctement classés","points":9},{"critere":"Filtration pour la pulpe, évaporation pour le sel","points":5}],"dureeMin":7,"corrige":"1. Un **corps pur** est constitué d'une **seule espèce chimique**. Un **mélange homogène** contient plusieurs espèces mais ne présente qu'**une seule phase** visible.\n2. Classement :\n- **corps purs** : eau distillée, fer ;\n- **mélanges homogènes** : eau salée, air ;\n- **mélanges hétérogènes** : eau et huile, jus d'orange avec pulpe.\n3. La **filtration** retient les particules solides : elle sépare la pulpe du jus. L'**évaporation** de l'eau permet de récupérer le sel, solide dissous."}$exo$::jsonb),
  ('0f4c7b7f-4cd7-5f83-a328-7ed3dfa8af40'::uuid, 2, 'application', $exo${"titre":"Le flacon sans étiquette","consigne":"Réponds en détaillant tes calculs, avec les unités, puis conclus par une phrase.","enonce":"**Situation.** Au laboratoire, Malik trouve un flacon de liquide incolore sans étiquette. Il prélève **20,0 mL** de ce liquide et mesure leur masse : **15,8 g**.\n\n> **Données** (masses volumiques à 20 °C) : eau 1,00 g·cm⁻³ ; éthanol 0,79 g·cm⁻³ ; glycérol 1,26 g·cm⁻³. On rappelle que 1 mL = 1 cm³.\n\n1. Calcule la masse volumique ρ du liquide en g·cm⁻³.\n2. Déduis-en sa densité. Pourquoi la densité n'a-t-elle pas d'unité ?\n3. Quel liquide des données peut-il s'agir ?\n4. Malik prélève ensuite 40,0 mL du même liquide. La masse volumique change-t-elle ? Justifie.","bareme":[{"critere":"Calcul de ρ = m / V = 0,790 g·cm⁻³ avec unité","points":7},{"critere":"Densité 0,790 et justification de l'absence d'unité","points":5},{"critere":"Identification de l'éthanol par comparaison aux données","points":4},{"critere":"La masse volumique ne dépend pas de la quantité prélevée","points":4}],"dureeMin":10,"corrige":"1. ρ = m / V = 15,8 / 20,0 = **0,790 g·cm⁻³**.\n2. La densité est la masse volumique du liquide rapportée à celle de l'eau : d = 0,790 / 1,00 = **0,790**. C'est le quotient de deux grandeurs de même unité : elle est **sans unité**.\n3. La valeur 0,79 g·cm⁻³ correspond à l'**éthanol**.\n4. Non : la masse volumique est une grandeur caractéristique de l'espèce, elle **ne dépend pas de la quantité prélevée**. Avec 40,0 mL, la masse doublerait (31,6 g) mais ρ resterait 0,790 g·cm⁻³."}$exo$::jsonb),
  ('0f4c7b7f-4cd7-5f83-a328-7ed3dfa8af40'::uuid, 3, 'application', $exo${"titre":"Identifier et séparer un liquide inconnu","consigne":"Exploite les mesures et les données pour répondre. Justifie chaque conclusion par un argument du cours.","enonce":"**Situation.** Inès étudie un liquide incolore X.\n\n- Mesure 1 : 50,0 mL de X ont une masse de 39,5 g.\n- Mesure 2 : elle chauffe X sous 1 013 hPa ; la température monte, puis reste **constante à 78 °C** pendant toute l'ébullition.\n\n> **Données** :\n\n| Espèce | Masse volumique (g·cm⁻³) | Température d'ébullition sous 1 013 hPa |\n| Acétone | 0,79 | 56 °C |\n| Éthanol | 0,79 | 78 °C |\n| Eau | 1,00 | 100 °C |\n\n1. Calcule la masse volumique de X.\n2. La mesure 1 suffit-elle à identifier X ? Explique.\n3. Que montre la mesure 2 sur la nature de X (corps pur ou mélange) ? Identifie X.\n4. Inès a par ailleurs un mélange homogène d'eau et d'éthanol. Quelle technique de séparation choisir ? Sur quelle propriété repose-t-elle, et quelle espèce est récupérée en premier ?","bareme":[{"critere":"ρ = 39,5 / 50,0 = 0,790 g·cm⁻³","points":4},{"critere":"Une seule grandeur ne suffit pas : acétone et éthanol ont la même masse volumique","points":4},{"critere":"Palier de température constant donc corps pur ; X identifié à l'éthanol en croisant deux grandeurs","points":6},{"critere":"Distillation, fondée sur la différence de températures d'ébullition ; l'éthanol (78 °C) sort en premier","points":6}],"dureeMin":15,"corrige":"1. ρ = m / V = 39,5 / 50,0 = **0,790 g·cm⁻³**.\n2. **Non** : l'acétone et l'éthanol ont tous deux une masse volumique de 0,79 g·cm⁻³. Une seule grandeur caractéristique ne permet pas de trancher.\n3. Pendant l'ébullition, la température reste **constante** : c'est le comportement d'un **corps pur** (un mélange ne présente pas de palier net). La température d'ébullition, 78 °C, est celle de l'éthanol et non celle de l'acétone (56 °C). En croisant la masse volumique et la température d'ébullition, qui sont propres à l'espèce, X est l'**éthanol**.\n4. On choisit la **distillation**, qui repose sur la **différence de température d'ébullition** des constituants. L'éthanol bout à 78 °C, l'eau à 100 °C : c'est l'**éthanol** qui se vaporise et est recueilli en premier."}$exo$::jsonb),
  ('eacc2aa2-858e-5f5f-ae21-4006a908f025'::uuid, 1, 'application', $exo${"titre":"Le sirop de Chloé","consigne":"Réponds en utilisant le vocabulaire du cours et en détaillant ton calcul.","enonce":"**Situation.** Chloé dissout **5,0 g de sucre** dans de l'eau et obtient, après avoir complété au trait de jauge, **250,0 mL** de solution.\n\n1. Dans cette solution, quel est le **solvant** ? Quel est le **soluté** ? Comment qualifie-t-on la solution ?\n2. Calcule la concentration en masse t de la solution en g·L⁻¹.\n3. Pourquoi utilise-t-on le volume de la solution obtenue, et non celui de l'eau ajoutée ?","bareme":[{"critere":"Solvant eau, soluté sucre, solution aqueuse","points":6},{"critere":"t = m / V = 5,0 / 0,2500 = 20 g·L⁻¹, volume converti en litres","points":9},{"critere":"Explication : dissoudre un solide modifie le volume, on complète au trait de jauge","points":5}],"dureeMin":6,"corrige":"1. Le **solvant** est l'eau (espèce majoritaire) ; le **soluté** est le sucre (espèce dissoute). Le solvant étant l'eau, la solution est **aqueuse**.\n2. V = 250,0 mL = 0,2500 L. t = m / V = 5,0 / 0,2500 = **20 g·L⁻¹**.\n3. La concentration se rapporte au volume de la **solution obtenue** : ajouter un soluté à un volume d'eau ne donne pas exactement ce volume de solution. C'est pour cela qu'on complète jusqu'au **trait de jauge** de la fiole."}$exo$::jsonb),
  ('eacc2aa2-858e-5f5f-ae21-4006a908f025'::uuid, 2, 'application', $exo${"titre":"Diluer une solution de colorant","consigne":"Détaille tes calculs puis rédige le protocole étape par étape en nommant la verrerie.","enonce":"**Situation.** Yanis dispose d'une solution mère de colorant de concentration en masse **t₁ = 20 g·L⁻¹**. Il doit préparer **100,0 mL** d'une solution fille de concentration **t₂ = 2,0 g·L⁻¹**.\n\n1. Quelle grandeur se conserve lors d'une dilution ? Écris la relation correspondante.\n2. Calcule le facteur de dilution F.\n3. Calcule le volume V₁ de solution mère à prélever.\n4. Rédige le protocole de la dilution en nommant la verrerie utilisée.","bareme":[{"critere":"Conservation de la quantité de soluté : t₁ × V₁ = t₂ × V₂","points":4},{"critere":"F = t₁ / t₂ = 10","points":4},{"critere":"V₁ = V₂ / F = 10,0 mL","points":5},{"critere":"Protocole complet : pipette jaugée de 10,0 mL, fiole jaugée de 100,0 mL, compléter au trait, homogénéiser","points":7}],"dureeMin":10,"corrige":"1. La dilution **conserve la quantité de soluté** : t₁ × V₁ = t₂ × V₂.\n2. F = t₁ / t₂ = 20 / 2,0 = **10**.\n3. F = V₂ / V₁ donc V₁ = V₂ / F = 100,0 / 10 = **10,0 mL**. (Vérification : 20 × 10,0 = 2,0 × 100,0.)\n4. Protocole :\n- verser un peu de solution mère dans un bécher ;\n- prélever **10,0 mL** de solution mère à la **pipette jaugée** ;\n- les introduire dans une **fiole jaugée de 100,0 mL** ;\n- compléter avec de l'eau distillée jusqu'au **trait de jauge** ;\n- boucher et **homogénéiser** en retournant la fiole."}$exo$::jsonb),
  ('eacc2aa2-858e-5f5f-ae21-4006a908f025'::uuid, 3, 'application', $exo${"titre":"Doser le sulfate de cuivre d'une bouillie","consigne":"Réponds aux questions dans l'ordre en justifiant chaque étape par le cours et en détaillant les calculs.","enonce":"**Situation.** Un jardinier veut connaître la concentration en masse d'une solution bleue de sulfate de cuivre S. Léna réalise un dosage par étalonnage.\n\n**Étape 1.** Elle prépare 50,0 mL d'une solution étalon de concentration 4,0 g·L⁻¹ par dissolution.\n\n**Étape 2.** Elle prépare des étalons et mesure leur absorbance A au spectrophotomètre :\n\n| t (g·L⁻¹) | 1,0 | 2,0 | 3,0 | 4,0 |\n| A | 0,15 | 0,30 | 0,45 | 0,60 |\n\n**Étape 3.** La solution S étant trop concentrée, elle la **dilue 5 fois** : la solution diluée a une absorbance A = 0,39.\n\n1. Calcule la masse de sulfate de cuivre à peser à l'étape 1 et cite la verrerie utilisée.\n2. Décris l'allure de la courbe d'étalonnage A en fonction de t.\n3. Détermine la concentration en masse de la solution diluée.\n4. Déduis-en la concentration en masse de la solution S.","bareme":[{"critere":"m = t × V = 4,0 × 0,0500 = 0,20 g ; fiole jaugée de 50,0 mL","points":5},{"critere":"Courbe : droite passant par l'origine (A proportionnelle à t, A = 0,15 × t)","points":4},{"critere":"Lecture ou calcul : t = 0,39 / 0,15 = 2,6 g·L⁻¹","points":6},{"critere":"Facteur de dilution appliqué : t(S) = 5 × 2,6 = 13 g·L⁻¹","points":5}],"dureeMin":18,"corrige":"1. t = m / V donc m = t × V = 4,0 × 0,0500 = **0,20 g**. On pèse 0,20 g, on les introduit dans une **fiole jaugée de 50,0 mL**, on dissout, on complète au trait de jauge et on homogénéise.\n2. Quand t double, A double : A est **proportionnelle** à t. La courbe d'étalonnage est une **droite passant par l'origine**, d'équation A = 0,15 × t (t en g·L⁻¹).\n3. On reporte A = 0,39 sur la courbe : t = 0,39 / 0,15 = **2,6 g·L⁻¹** pour la solution diluée.\n4. La solution a été diluée 5 fois : F = t(S) / t(diluée) = 5, donc t(S) = 5 × 2,6 = **13 g·L⁻¹**.\n\nRemarque : on dilue parce qu'une absorbance mesurée hors de la gamme d'étalons ne pourrait pas être lue sur la courbe."}$exo$::jsonb),
  ('37a47f84-0811-5f2c-a63c-f61467d9c29f'::uuid, 1, 'application', $exo${"titre":"Quatre tests à connaître","consigne":"Pour chaque espèce, indique le test et le résultat attendu, en une phrase.","enonce":"Au cours de plusieurs expériences, Samuel veut vérifier la présence de quatre espèces chimiques.\n\n1. Comment met-il en évidence le **dioxygène** ? Quel résultat observe-t-il ?\n2. Comment met-il en évidence le **dioxyde de carbone** ?\n3. Comment met-il en évidence le **dihydrogène** ?\n4. Comment prouve-t-il qu'un liquide contient de l'**eau** ?","bareme":[{"critere":"Dioxygène : bûchette incandescente qui se rallume","points":5},{"critere":"Dioxyde de carbone : eau de chaux qui se trouble","points":5},{"critere":"Dihydrogène : détonation à l'approche d'une flamme","points":5},{"critere":"Eau : sulfate de cuivre anhydre qui passe du blanc au bleu","points":5}],"dureeMin":6,"corrige":"1. On approche une **bûchette incandescente** : elle se **rallume** en présence de dioxygène.\n2. On fait barboter le gaz dans l'**eau de chaux** : elle se **trouble** en présence de dioxyde de carbone.\n3. On approche une **flamme** : une **détonation** se produit en présence de dihydrogène.\n4. On dépose quelques gouttes sur du **sulfate de cuivre anhydre** : il passe du **blanc au bleu** en présence d'eau."}$exo$::jsonb),
  ('37a47f84-0811-5f2c-a63c-f61467d9c29f'::uuid, 2, 'application', $exo${"titre":"Que contient l'eau du bassin ?","consigne":"Décris chaque observation, puis conclus sur les ions présents en citant le réactif et le précipité.","enonce":"**Situation.** Nora analyse un échantillon d'eau bleutée prélevé près d'un ancien atelier. Elle le répartit dans trois tubes.\n\n- **Tube 1** : elle ajoute quelques gouttes de soude. Un précipité **bleu** apparaît.\n- **Tube 2** : elle ajoute quelques gouttes de nitrate d'argent. Un précipité **blanc** apparaît, qui **noircit à la lumière**.\n- **Tube 3** : elle ajoute de la soude à un second échantillon, prélevé plus loin : un précipité **rouille** apparaît.\n\n1. Quel ion le tube 1 met-il en évidence ?\n2. Quel ion le tube 2 met-il en évidence ?\n3. Quel ion contient le second échantillon (tube 3) ?\n4. Quel précipité Nora aurait-elle obtenu avec la soude si l'eau avait contenu des ions fer II ?","bareme":[{"critere":"Tube 1 : ions cuivre II (précipité bleu avec la soude)","points":5},{"critere":"Tube 2 : ions chlorure (précipité blanc noircissant avec le nitrate d'argent)","points":6},{"critere":"Tube 3 : ions fer III (précipité rouille)","points":5},{"critere":"Fer II : précipité vert","points":4}],"dureeMin":9,"corrige":"1. Avec la soude, un précipité **bleu** caractérise les ions **cuivre II**.\n2. Avec le nitrate d'argent, un précipité **blanc qui noircit à la lumière** caractérise les ions **chlorure**. L'échantillon contient donc des ions cuivre II et des ions chlorure.\n3. Avec la soude, un précipité **rouille** caractérise les ions **fer III**.\n4. Avec des ions **fer II**, la soude aurait donné un précipité **vert**."}$exo$::jsonb),
  ('37a47f84-0811-5f2c-a63c-f61467d9c29f'::uuid, 3, 'application', $exo${"titre":"L'arôme de vanille est-il authentique ?","consigne":"Exploite le chromatogramme et la mesure, calcule les rapports frontaux, puis rédige une conclusion argumentée.","enonce":"**Situation.** Hugo veut savoir si un arôme contient de la vanilline. Il réalise une chromatographie sur couche mince avec trois dépôts : E (l'arôme), R₁ (vanilline pure), R₂ (une autre espèce de référence). Après élution et révélation :\n\n| Dépôt | Distance parcourue par la ou les taches |\n| E | 2,4 cm et 5,6 cm |\n| R₁ | 5,6 cm |\n| R₂ | 4,0 cm |\n\nLe front de l'éluant a parcouru **8,0 cm**.\n\nIl isole ensuite l'espèce de la tache haute de E et mesure sa température de fusion au banc Kofler : **82 °C**.\n\n> **Donnée** : température de fusion de la vanilline : 82 °C.\n\n1. Rappelle les étapes d'une chromatographie sur couche mince.\n2. Combien d'espèces l'arôme contient-il au moins ?\n3. Calcule le Rf de chaque tache.\n4. L'arôme contient-il de la vanilline ? Contient-il l'espèce R₂ ? Argumente en croisant les deux mesures et en évoquant l'incertitude.","bareme":[{"critere":"Étapes : dépôt, élution par capillarité, révélation, comparaison des hauteurs","points":4},{"critere":"Au moins deux espèces dans l'arôme (deux taches)","points":3},{"critere":"Rf calculés : 0,30 et 0,70 pour E, 0,70 pour R₁, 0,50 pour R₂","points":6},{"critere":"Conclusion : présence probable de vanilline par deux indices concordants, absence de R₂","points":5},{"critere":"Nuance : une mesure porte une incertitude, les indices rendent l'identité probable","points":2}],"dureeMin":16,"corrige":"1. On **dépose** l'échantillon et les références sur la plaque, on laisse **migrer l'éluant** par capillarité, on **révèle** les taches, puis on **compare les hauteurs**.\n2. Le dépôt E donne **deux taches** : l'arôme contient **au moins deux espèces**.\n3. Rf = distance de la tache / distance du front :\n- E : 2,4 / 8,0 = **0,30** et 5,6 / 8,0 = **0,70** ;\n- R₁ : 5,6 / 8,0 = **0,70** ;\n- R₂ : 4,0 / 8,0 = **0,50**.\n4. La tache haute de E a le même Rf (0,70) que la vanilline, dans le même couple support-éluant : c'est probablement de la vanilline. La température de fusion mesurée (82 °C) est celle de la vanilline : deux indices **concordants**, on conclut que l'arôme **contient très probablement de la vanilline**. Aucune tache de E n'est à 4,0 cm : l'arôme **ne contient pas R₂**. Chaque mesure portant une **incertitude**, on ne parle pas de certitude absolue, mais le croisement des deux indices rend l'identification solide."}$exo$::jsonb),
  ('dde4e188-ec24-51d2-b85b-0cd0e4bee7ae'::uuid, 1, 'application', $exo${"titre":"Dans le noyau du sodium","consigne":"Réponds à chaque question en justifiant ton calcul.","enonce":"Le noyau de l'atome de sodium est noté ²³₁₁Na : A = 23 et Z = 11.\n\n1. Que représentent A et Z ?\n2. Donne le nombre de protons, de neutrons et d'électrons de l'atome de sodium.\n3. Calcule la charge électrique du noyau, sachant que e = 1,6 × 10⁻¹⁹ C.\n4. Pourquoi l'atome de sodium est-il électriquement neutre ?","bareme":[{"critere":"A = nombre de nucléons, Z = nombre de protons","points":4},{"critere":"11 protons, 12 neutrons (A − Z), 11 électrons","points":7},{"critere":"Charge du noyau : 11 × 1,6 × 10⁻¹⁹ = 1,8 × 10⁻¹⁸ C","points":5},{"critere":"Neutralité : autant d'électrons que de protons","points":4}],"dureeMin":7,"corrige":"1. **A** est le nombre de masse : le nombre total de **nucléons**. **Z** est le numéro atomique : le nombre de **protons**.\n2. Protons : Z = **11**. Neutrons : A − Z = 23 − 11 = **12**. L'atome est neutre, il a autant d'électrons que de protons : **11 électrons**.\n3. Seuls les protons sont chargés dans le noyau : Q = Z × e = 11 × 1,6 × 10⁻¹⁹ ≈ **1,8 × 10⁻¹⁸ C**.\n4. L'atome contient **autant d'électrons (charge −e) que de protons (charge +e)** : les charges se compensent, la charge totale est nulle."}$exo$::jsonb),
  ('dde4e188-ec24-51d2-b85b-0cd0e4bee7ae'::uuid, 2, 'application', $exo${"titre":"Un atome presque vide","consigne":"Réponds en détaillant tes calculs et en utilisant les puissances de dix.","enonce":"**Données** : diamètre d'un noyau ≈ 10⁻¹⁵ m ; diamètre d'un atome ≈ 10⁻¹⁰ m ; masse d'un nucléon ≈ 1,67 × 10⁻²⁷ kg.\n\n1. Calcule le rapport entre le diamètre de l'atome et celui du noyau.\n2. Lors d'une maquette, Jade représente le noyau par une bille de 1 cm de diamètre. Quel devrait être le diamètre de l'atome à la même échelle ? Exprime-le en kilomètres.\n3. Pourquoi dit-on que l'atome a une structure **lacunaire** ?\n4. Estime la masse d'un atome de carbone 12 (A = 12). Pourquoi peut-on négliger la masse des électrons ?","bareme":[{"critere":"Rapport 10⁻¹⁰ / 10⁻¹⁵ = 10⁵ = 100 000","points":5},{"critere":"Diamètre de l'atome à l'échelle : 10⁵ cm = 1 km","points":5},{"critere":"Structure lacunaire : l'atome est essentiellement vide","points":4},{"critere":"m ≈ 12 × 1,67 × 10⁻²⁷ = 2,0 × 10⁻²⁶ kg ; nucléon environ 1 800 fois plus massif que l'électron","points":6}],"dureeMin":10,"corrige":"1. Rapport = 10⁻¹⁰ / 10⁻¹⁵ = 10⁵ = **100 000** : l'atome est cent mille fois plus grand que son noyau.\n2. Diamètre de l'atome = 100 000 × 1 cm = 100 000 cm = 1 000 m = **1 km**.\n3. Entre le noyau, minuscule, et les électrons, il n'y a **rien** : l'atome est essentiellement **vide**, c'est une structure lacunaire.\n4. m ≈ A × masse d'un nucléon = 12 × 1,67 × 10⁻²⁷ ≈ **2,0 × 10⁻²⁶ kg**. Un nucléon est environ **1 800 fois plus massif** qu'un électron : l'apport des électrons est négligeable, presque toute la masse est dans le noyau."}$exo$::jsonb),
  ('dde4e188-ec24-51d2-b85b-0cd0e4bee7ae'::uuid, 3, 'application', $exo${"titre":"Deux chlores et un ion","consigne":"Réponds en justifiant chaque réponse par une définition du cours.","enonce":"Le chlore naturel est formé de deux sortes d'atomes : ³⁵₁₇Cl et ³⁷₁₇Cl. Dans l'eau de mer, le chlore se trouve sous forme d'ion **chlorure Cl⁻**. On trouve aussi l'ion magnésium **Mg²⁺**, dont le noyau est ²⁴₁₂Mg.\n\n> Donnée : masse d'un nucléon ≈ 1,67 × 10⁻²⁷ kg.\n\n1. Donne la composition (protons, neutrons) des noyaux ³⁵Cl et ³⁷Cl. Comment appelle-t-on ces deux noyaux ? Justifie.\n2. Ces deux atomes appartiennent-ils au même élément chimique ? Ont-ils les mêmes propriétés chimiques ? Justifie.\n3. Donne le nombre d'électrons de l'ion Cl⁻ (issu de ³⁵Cl) et de l'ion Mg²⁺. Précise pour chacun s'il s'agit d'un cation ou d'un anion.\n4. Lors de la formation de l'ion Mg²⁺, le noyau est-il modifié ? Estime la masse de l'ion Mg²⁺.","bareme":[{"critere":"³⁵Cl : 17 p, 18 n ; ³⁷Cl : 17 p, 20 n ; isotopes car même Z, A différents","points":5},{"critere":"Même élément (même Z) et mêmes propriétés chimiques, qui dépendent des électrons","points":4},{"critere":"Cl⁻ : 18 électrons, anion ; Mg²⁺ : 10 électrons, cation","points":6},{"critere":"Noyau inchangé ; m ≈ 24 × 1,67 × 10⁻²⁷ = 4,0 × 10⁻²⁶ kg","points":5}],"dureeMin":15,"corrige":"1. ³⁵Cl : 17 protons, 35 − 17 = **18 neutrons**. ³⁷Cl : 17 protons, 37 − 17 = **20 neutrons**. Ils ont le **même Z** mais des **A différents** : ce sont des **isotopes**.\n2. Un élément chimique est défini par son seul Z : ils appartiennent au **même élément**, le chlore. Ils ont les **mêmes propriétés chimiques**, car celles-ci dépendent des **électrons**, en même nombre (17) dans les deux atomes.\n3. Cl⁻ : l'atome (17 électrons) a **gagné** un électron : **18 électrons** ; charge négative, c'est un **anion**. Mg²⁺ : l'atome (12 électrons) a **perdu** deux électrons : **10 électrons** ; charge positive, c'est un **cation**.\n4. Non : seuls les électrons changent, le **noyau n'est pas modifié**, c'est toujours du magnésium. La masse des électrons étant négligeable : m ≈ 24 × 1,67 × 10⁻²⁷ ≈ **4,0 × 10⁻²⁶ kg**."}$exo$::jsonb),
  ('1d5d7962-fbfd-5abb-a035-fcdcdd0eaed2'::uuid, 1, 'application', $exo${"titre":"Écrire deux configurations","consigne":"Écris les configurations électroniques en respectant l'ordre de remplissage, puis réponds par une phrase.","enonce":"1. Rappelle le nombre maximal d'électrons d'une sous-couche s et d'une sous-couche p, et l'ordre de remplissage des sous-couches.\n2. Écris la configuration électronique de l'azote (Z = 7) et celle du magnésium (Z = 12).\n3. Pour chacun, indique le numéro de la couche externe et le nombre d'électrons de valence.","bareme":[{"critere":"s : 2 électrons, p : 6 ; ordre 1s, 2s, 2p, 3s, 3p","points":5},{"critere":"Azote 1s² 2s² 2p³ et magnésium 1s² 2s² 2p⁶ 3s²","points":9},{"critere":"Azote : couche 2, 5 électrons de valence ; magnésium : couche 3, 2 électrons de valence","points":6}],"dureeMin":7,"corrige":"1. Une sous-couche **s** contient au plus **2** électrons, une sous-couche **p** au plus **6**. Ordre de remplissage : **1s, 2s, 2p, 3s, 3p**.\n2. Azote (7 électrons) : **1s² 2s² 2p³**. Magnésium (12 électrons) : **1s² 2s² 2p⁶ 3s²**.\n3. Azote : couche externe n° **2** (2s² 2p³), soit **5 électrons de valence**. Magnésium : couche externe n° **3** (3s²), soit **2 électrons de valence**."}$exo$::jsonb),
  ('1d5d7962-fbfd-5abb-a035-fcdcdd0eaed2'::uuid, 2, 'application', $exo${"titre":"Ranger six éléments en familles","consigne":"Écris les configurations, puis regroupe les éléments en justifiant par les électrons de valence.","enonce":"On étudie six éléments : lithium (Z = 3), fluor (Z = 9), néon (Z = 10), sodium (Z = 11), chlore (Z = 17), argon (Z = 18).\n\n1. Écris la configuration électronique de chacun.\n2. Indique pour chacun le nombre d'électrons de valence.\n3. Regroupe-les en trois familles, nomme chaque famille et précise sa réactivité.\n4. Le lithium et le sodium sont-ils sur la même ligne du tableau périodique ? Justifie.","bareme":[{"critere":"Six configurations exactes","points":6},{"critere":"Électrons de valence : Li 1, Na 1, F 7, Cl 7, Ne 8, Ar 8","points":4},{"critere":"Alcalins (Li, Na) perdent un électron ; halogènes (F, Cl) en gagnent un ; gaz nobles (Ne, Ar) inertes","points":6},{"critere":"Lignes différentes : couche externe n° 2 pour Li, n° 3 pour Na","points":4}],"dureeMin":11,"corrige":"1. Li : 1s² 2s¹ ; F : 1s² 2s² 2p⁵ ; Ne : 1s² 2s² 2p⁶ ; Na : 1s² 2s² 2p⁶ 3s¹ ; Cl : 1s² 2s² 2p⁶ 3s² 3p⁵ ; Ar : 1s² 2s² 2p⁶ 3s² 3p⁶.\n2. Li : **1** ; Na : **1** ; F : **7** ; Cl : **7** ; Ne : **8** ; Ar : **8**.\n3. Les éléments de même nombre d'électrons de valence sont dans la même colonne et ont des propriétés voisines :\n- Li et Na : les **alcalins**, très réactifs, ils **perdent** facilement un électron ;\n- F et Cl : les **halogènes**, ils **gagnent** facilement un électron ;\n- Ne et Ar : les **gaz nobles**, couche externe saturée, chimiquement **inertes**.\n4. **Non** : une ligne rassemble les éléments dont la couche externe porte le même numéro. Celle du lithium est la couche **2**, celle du sodium la couche **3** : ils sont sur deux lignes différentes (mais dans la même colonne)."}$exo$::jsonb),
  ('1d5d7962-fbfd-5abb-a035-fcdcdd0eaed2'::uuid, 3, 'application', $exo${"titre":"L'élément mystère","consigne":"Mène un raisonnement argumenté à partir de la configuration, en citant les règles du cours.","enonce":"**Situation.** Un élément X a pour couche externe **3s² 3p⁵**.\n\n> Aide : fluor Z = 9, sodium Z = 11, chlore Z = 17, argon Z = 18.\n\n1. Écris la configuration électronique complète de X et déduis-en son numéro atomique. Identifie X.\n2. Sur quelle ligne du tableau périodique se trouve X ? Combien a-t-il d'électrons de valence ?\n3. À quelle famille appartient X ? Avec quel élément de l'aide partage-t-il des propriétés chimiques voisines ? Justifie.\n4. Mendeleïev classait les éléments par masse croissante ; on les classe aujourd'hui par numéro atomique croissant. Explique pourquoi le classement actuel rend compte directement des familles.\n5. Pourquoi l'argon, voisin de X, ne réagit-il presque avec rien ?","bareme":[{"critere":"1s² 2s² 2p⁶ 3s² 3p⁵, Z = 17, X est le chlore","points":5},{"critere":"Ligne 3 (couche externe n° 3), 7 électrons de valence","points":3},{"critere":"Halogène, propriétés voisines du fluor car même nombre d'électrons de valence","points":4},{"critere":"Le numéro atomique fixe le nombre d'électrons donc la couche externe, qui détermine les propriétés","points":4},{"critere":"Argon : couche externe saturée, gaz noble inerte","points":4}],"dureeMin":15,"corrige":"1. En remplissant dans l'ordre jusqu'à 3p⁵ : **1s² 2s² 2p⁶ 3s² 3p⁵**, soit 2 + 2 + 6 + 2 + 5 = **17 électrons**. L'atome est neutre : **Z = 17**, X est le **chlore**.\n2. Couche externe n° 3 : X est sur la **3e ligne**. Électrons de valence : 3s² 3p⁵, soit **7**.\n3. X appartient à l'avant-dernière colonne, celle des **halogènes** : il **gagne** facilement un électron. Le fluor (1s² 2s² 2p⁵) a aussi **7 électrons de valence** : même colonne, propriétés chimiques voisines.\n4. Le numéro atomique donne le nombre d'électrons, donc la configuration et la **couche externe**. Or ce sont les électrons de valence qui fixent la chimie d'un élément : en ordonnant par Z, les éléments de même nombre d'électrons de valence tombent naturellement dans la même colonne.\n5. L'argon (1s² 2s² 2p⁶ 3s² 3p⁶) a une couche externe **saturée** : c'est un **gaz noble**, chimiquement **inerte**."}$exo$::jsonb),
  ('2210c063-acb9-58e3-84e3-21849315d457'::uuid, 1, 'application', $exo${"titre":"Quels ions se forment ?","consigne":"Pour chaque atome, justifie l'ion formé en citant la règle du cours.","enonce":"> Configurations : sodium (Z = 11) 1s² 2s² 2p⁶ 3s¹ ; magnésium (Z = 12) 1s² 2s² 2p⁶ 3s² ; oxygène (Z = 8) 1s² 2s² 2p⁴ ; chlore (Z = 17) 1s² 2s² 2p⁶ 3s² 3p⁵.\n\n1. Énonce la règle de l'**octet** et la règle du **duet**.\n2. Pour chacun des quatre atomes, indique s'il gagne ou perd des électrons, combien, et écris l'ion formé.\n3. Quel gaz noble chaque ion imite-t-il ?","bareme":[{"critere":"Octet : 8 électrons externes ; duet : 2, comme l'hélium ; configuration du gaz noble le plus proche","points":5},{"critere":"Na⁺, Mg²⁺, O²⁻, Cl⁻ avec le nombre d'électrons perdus ou gagnés","points":10},{"critere":"Na⁺, Mg²⁺ et O²⁻ : néon ; Cl⁻ : argon","points":5}],"dureeMin":7,"corrige":"1. **Octet** : un atome tend à avoir **8 électrons** sur sa couche externe. **Duet** : pour les plus petits atomes, 2 électrons, comme l'hélium. Un atome tend à acquérir la configuration du **gaz noble le plus proche**.\n2. Le chemin le plus court vers l'octet :\n- sodium : il **perd 1** électron → **Na⁺** ;\n- magnésium : il **perd 2** électrons → **Mg²⁺** ;\n- oxygène : il **gagne 2** électrons → **O²⁻** ;\n- chlore : il **gagne 1** électron → **Cl⁻**.\n3. Na⁺, Mg²⁺ et O²⁻ ont la configuration du **néon** (1s² 2s² 2p⁶) ; Cl⁻ a celle de l'**argon** (… 3s² 3p⁶)."}$exo$::jsonb),
  ('2210c063-acb9-58e3-84e3-21849315d457'::uuid, 2, 'application', $exo${"titre":"Les schémas de Lewis de trois molécules","consigne":"Justifie le nombre de liaisons de chaque atome, puis décris les schémas de Lewis.","enonce":"On étudie trois molécules : l'eau **H₂O**, l'ammoniac **NH₃** et le méthane **CH₄**.\n\n> Électrons de valence : H 1 ; C 4 ; N 5 ; O 6.\n\n1. Combien de liaisons covalentes forment l'hydrogène, le carbone, l'azote et l'oxygène ? Justifie avec la règle de l'octet ou du duet.\n2. Pour chaque molécule, indique le nombre de doublets liants et de doublets non liants, puis décris son schéma de Lewis.\n3. Qu'est-ce qu'une liaison covalente ? Une molécule porte-t-elle une charge électrique ?","bareme":[{"critere":"H : 1, C : 4, N : 3, O : 2 liaisons, justifiés par les électrons manquants","points":6},{"critere":"H₂O : 2 liants, 2 non liants ; NH₃ : 3 liants, 1 non liant ; CH₄ : 4 liants, 0 non liant","points":9},{"critere":"Liaison covalente : partage d'un doublet ; molécule électriquement neutre","points":5}],"dureeMin":11,"corrige":"1. Le nombre de liaisons est le nombre d'électrons qui **manquent** : H (1 électron, duet) : **1** ; C (4, il en manque 4) : **4** ; N (5, il en manque 3) : **3** ; O (6, il en manque 2) : **2**.\n2. \n- **H₂O** : deux liaisons O–H (**2 doublets liants**) ; il reste 6 − 2 = 4 électrons sur l'oxygène, soit **2 doublets non liants** sur O.\n- **NH₃** : trois liaisons N–H (**3 doublets liants**) ; il reste 5 − 3 = 2 électrons, soit **1 doublet non liant** sur N.\n- **CH₄** : quatre liaisons C–H (**4 doublets liants**) ; **aucun** doublet non liant.\nDans chaque schéma, un tiret entre deux atomes représente une liaison, un tiret sur un atome un doublet non liant.\n3. Une liaison covalente est le **partage d'un doublet d'électrons** entre deux atomes, chacun apportant un électron. Une molécule est **électriquement neutre**."}$exo$::jsonb),
  ('2210c063-acb9-58e3-84e3-21849315d457'::uuid, 3, 'application', $exo${"titre":"Aluminium, soufre et dioxyde de carbone","consigne":"Raisonne à partir des configurations électroniques et justifie chaque réponse par les règles du duet et de l'octet.","enonce":"> Données : aluminium Z = 13 ; soufre Z = 16 ; carbone Z = 6 ; oxygène Z = 8.\n\n1. Écris la configuration électronique de l'aluminium et celle du soufre.\n2. Quel ion chacun forme-t-il ? Justifie par le chemin le plus court vers l'octet et indique le gaz noble dont l'ion prend la configuration.\n3. Le dioxyde de carbone a pour formule brute CO₂. Sachant que le carbone est l'atome central, propose sa formule développée. Vérifie que chaque atome forme bien le nombre de liaisons attendu.\n4. Combien de doublets non liants porte chaque atome d'oxygène dans CO₂ ? Vérifie que l'octet est respecté pour tous les atomes.","bareme":[{"critere":"Al : 1s² 2s² 2p⁶ 3s² 3p¹ ; S : 1s² 2s² 2p⁶ 3s² 3p⁴","points":4},{"critere":"Al³⁺ (néon, perte de 3 électrons) et S²⁻ (argon, gain de 2)","points":6},{"critere":"O=C=O : C forme 4 liaisons, chaque O en forme 2 (deux doubles liaisons)","points":5},{"critere":"2 doublets non liants par oxygène ; décompte de l'octet pour C et O","points":5}],"dureeMin":16,"corrige":"1. Aluminium (13 électrons) : **1s² 2s² 2p⁶ 3s² 3p¹**. Soufre (16 électrons) : **1s² 2s² 2p⁶ 3s² 3p⁴**.\n2. \n- L'aluminium a 3 électrons de valence : il est plus court d'en **perdre 3** que d'en gagner 5. Il forme **Al³⁺**, de configuration 1s² 2s² 2p⁶, celle du **néon**.\n- Le soufre a 6 électrons de valence : il lui en manque 2, il en **gagne 2** et forme **S²⁻**, de configuration … 3s² 3p⁶, celle de l'**argon**.\n3. Le carbone forme **4** liaisons, l'oxygène **2**. La seule façon de les satisfaire avec C au centre est deux **doubles liaisons** : **O=C=O**. Le carbone a bien 2 + 2 = 4 liaisons, chaque oxygène 2.\n4. Chaque oxygène a 6 électrons de valence, dont 2 engagés dans la double liaison : il en reste 4, soit **2 doublets non liants**. Octet : chaque O compte 2 doublets liants + 2 non liants = 8 électrons ; le carbone compte 4 doublets liants = 8 électrons. L'octet est respecté pour tous les atomes, et la molécule est neutre."}$exo$::jsonb),
  ('9600e331-947d-5d5b-aa3e-a933c899663a'::uuid, 1, 'application', $exo${"titre":"Une pincée de dioxyde de carbone","consigne":"Détaille chaque calcul avec les unités et le bon nombre de chiffres significatifs.","enonce":"Un échantillon contient **11,0 g** de dioxyde de carbone CO₂.\n\n> Données : M(C) = 12,0 g·mol⁻¹ ; M(O) = 16,0 g·mol⁻¹ ; N_A = 6,02 × 10²³ mol⁻¹.\n\n1. Calcule la masse molaire moléculaire du dioxyde de carbone.\n2. Calcule la quantité de matière n contenue dans l'échantillon.\n3. Calcule le nombre N de molécules de CO₂.","bareme":[{"critere":"M(CO₂) = 12,0 + 2 × 16,0 = 44,0 g·mol⁻¹","points":6},{"critere":"n = m / M = 11,0 / 44,0 = 0,250 mol","points":7},{"critere":"N = n × N_A = 1,51 × 10²³ molécules","points":7}],"dureeMin":7,"corrige":"1. M(CO₂) = M(C) + 2 × M(O) = 12,0 + 2 × 16,0 = **44,0 g·mol⁻¹**.\n2. n = m / M = 11,0 / 44,0 = **0,250 mol**.\n3. n = N / N_A donc N = n × N_A = 0,250 × 6,02 × 10²³ ≈ **1,51 × 10²³ molécules**.\n\nOn garde trois chiffres significatifs, comme les données (11,0 g ; 44,0 g·mol⁻¹), et l'on vérifie les unités : g / (g·mol⁻¹) donne bien des mol."}$exo$::jsonb),
  ('9600e331-947d-5d5b-aa3e-a933c899663a'::uuid, 2, 'application', $exo${"titre":"Un liquide et un gaz","consigne":"Choisis la bonne relation pour chaque cas et détaille les calculs avec leurs unités.","enonce":"**Situation.** Pour un atelier, Aya dispose de :\n- **50,0 mL d'éthanol** liquide C₂H₆O, de masse volumique ρ = 0,790 g·mL⁻¹ ;\n- **1,20 L de dioxyde de carbone** gazeux, à 20 °C sous 1 013 hPa.\n\n> Données : M(H) = 1,0 g·mol⁻¹ ; M(C) = 12,0 g·mol⁻¹ ; M(O) = 16,0 g·mol⁻¹ ; V_m = 24,0 L·mol⁻¹ à 20 °C sous 1 013 hPa ; N_A = 6,02 × 10²³ mol⁻¹.\n\n1. Calcule la masse de l'éthanol prélevé.\n2. Calcule la masse molaire de l'éthanol, puis la quantité de matière d'éthanol.\n3. Calcule la quantité de matière de dioxyde de carbone.\n4. Lequel des deux échantillons contient le plus de molécules ? Justifie.","bareme":[{"critere":"m = ρ × V = 39,5 g","points":4},{"critere":"M(C₂H₆O) = 46,0 g·mol⁻¹ et n = 0,859 mol","points":6},{"critere":"n(CO₂) = V / V_m = 0,0500 mol","points":5},{"critere":"Comparaison justifiée par n (proportionnel au nombre de molécules) : l'éthanol","points":5}],"dureeMin":11,"corrige":"1. m = ρ × V = 0,790 × 50,0 = **39,5 g**.\n2. M(C₂H₆O) = 2 × 12,0 + 6 × 1,0 + 16,0 = **46,0 g·mol⁻¹**. n = m / M = 39,5 / 46,0 ≈ **0,859 mol**.\n3. Pour un gaz : n = V / V_m = 1,20 / 24,0 = **0,0500 mol**.\n4. Le nombre de molécules vaut N = n × N_A : il est proportionnel à n. L'éthanol (0,859 mol, soit environ 5,17 × 10²³ molécules) en contient bien plus que le gaz (0,0500 mol, soit environ 3,01 × 10²² molécules), environ 17 fois plus."}$exo$::jsonb),
  ('9600e331-947d-5d5b-aa3e-a933c899663a'::uuid, 3, 'application', $exo${"titre":"L'eau sucrée de la sportive","consigne":"Enchaîne les calculs en justifiant chaque relation utilisée, puis réponds à la question sur la précision.","enonce":"**Situation.** Pour une boisson d'effort, Salomé dissout **3,42 g** de saccharose C₁₂H₂₂O₁₁ dans de l'eau, et obtient **250,0 mL** de solution.\n\n> Données : M(H) = 1,0 g·mol⁻¹ ; M(C) = 12,0 g·mol⁻¹ ; M(O) = 16,0 g·mol⁻¹ ; N_A = 6,02 × 10²³ mol⁻¹.\n\n1. Calcule la masse molaire du saccharose.\n2. Calcule la quantité de matière de saccharose dissous, puis le nombre de molécules correspondant.\n3. Calcule la concentration en quantité de matière c de la solution.\n4. Calcule la concentration en masse t de deux façons : à partir de m et V, puis à partir de c et M. Vérifie la cohérence.\n5. Salomé affiche son résultat « 13,68000 g·L⁻¹ ». Qu'en penses-tu ?","bareme":[{"critere":"M = 12 × 12,0 + 22 × 1,0 + 11 × 16,0 = 342 g·mol⁻¹","points":4},{"critere":"n = 1,00 × 10⁻² mol et N = 6,02 × 10²¹ molécules","points":5},{"critere":"c = n / V = 4,00 × 10⁻² mol·L⁻¹, volume en litres","points":4},{"critere":"t = 13,7 g·L⁻¹ par les deux méthodes, relation t = c × M","points":4},{"critere":"Critique des chiffres significatifs : trois chiffres, pas plus précis que les données","points":3}],"dureeMin":18,"corrige":"1. M = 12 × 12,0 + 22 × 1,0 + 11 × 16,0 = 144 + 22 + 176 = **342 g·mol⁻¹**.\n2. n = m / M = 3,42 / 342 = **1,00 × 10⁻² mol**. N = n × N_A = 1,00 × 10⁻² × 6,02 × 10²³ = **6,02 × 10²¹ molécules**.\n3. V = 250,0 mL = 0,2500 L. c = n / V = 1,00 × 10⁻² / 0,2500 = **4,00 × 10⁻² mol·L⁻¹**.\n4. t = m / V = 3,42 / 0,2500 ≈ **13,7 g·L⁻¹**. Par t = c × M = 4,00 × 10⁻² × 342 ≈ **13,7 g·L⁻¹**. Les deux résultats concordent.\n5. Un résultat ne peut pas être plus précis que la donnée la moins précise : les données ont **trois chiffres significatifs** (3,42 g). On écrit donc **13,7 g·L⁻¹** ; « 13,68000 » affiche une précision que la mesure n'a pas."}$exo$::jsonb),
  ('8cdb4008-bfd7-581e-9ffd-ada6b7b564df'::uuid, 1, 'application', $exo${"titre":"Six changements d'état au quotidien","consigne":"Nomme chaque changement d'état et précise s'il absorbe ou libère de l'énergie.","enonce":"Nomme le changement d'état dans chaque situation, puis indique s'il est **endothermique** ou **exothermique**.\n\n1. Un glaçon fond dans un verre.\n2. De la buée se forme sur une vitre froide.\n3. Du givre apparaît directement sur une voiture par une nuit glaciale, à partir de la vapeur d'eau de l'air.\n4. La neige carbonique (dioxyde de carbone solide) disparaît en fumée sans devenir liquide.\n5. Une flaque sèche au soleil.\n6. L'eau d'un bac se transforme en glace au congélateur.","bareme":[{"critere":"Les six noms exacts : fusion, liquéfaction, condensation, sublimation, vaporisation, solidification","points":12},{"critere":"Bilan énergétique correct pour chacun (fusion, vaporisation, sublimation endothermiques ; les trois autres exothermiques)","points":8}],"dureeMin":7,"corrige":"1. Solide → liquide : **fusion**, **endothermique**.\n2. Gaz → liquide : **liquéfaction**, **exothermique**.\n3. Gaz → solide : **condensation**, **exothermique**.\n4. Solide → gaz : **sublimation**, **endothermique**.\n5. Liquide → gaz : **vaporisation**, **endothermique**.\n6. Liquide → solide : **solidification**, **exothermique**."}$exo$::jsonb),
  ('8cdb4008-bfd7-581e-9ffd-ada6b7b564df'::uuid, 2, 'application', $exo${"titre":"La courbe de chauffage de la glace","consigne":"Exploite le tableau de mesures et justifie chaque réponse par le cours.","enonce":"**Situation.** Théo chauffe régulièrement des glaçons d'eau pure, sous 1 013 hPa, et relève la température chaque minute.\n\n| t (min) | 0 | 1 | 2 | 3 | 4 | 5 | 6 | 7 |\n| θ (°C) | −10 | −5 | 0 | 0 | 0 | 0 | 6 | 12 |\n\n1. Décris l'évolution de la température. Entre quelles dates observe-t-on un palier ?\n2. Quel changement d'état a lieu pendant le palier ? Dans quel état est l'eau à t = 1 min et à t = 7 min ?\n3. L'eau est-elle un corps pur ? Justifie à partir de la courbe.\n4. Pendant le palier, Théo continue de chauffer, mais la température ne monte pas. À quoi sert l'énergie apportée ?","bareme":[{"critere":"Hausse, puis palier à 0 °C entre 2 et 5 min, puis nouvelle hausse","points":5},{"critere":"Fusion ; solide à 1 min, liquide à 7 min","points":5},{"critere":"Palier de température constante donc corps pur","points":4},{"critere":"L'énergie sert à défaire les interactions entre molécules ; fusion endothermique","points":6}],"dureeMin":10,"corrige":"1. La température monte de −10 °C à 0 °C, reste **constante à 0 °C entre t = 2 min et t = 5 min** (palier), puis remonte.\n2. Pendant le palier a lieu la **fusion** (solide → liquide) à 0 °C. À t = 1 min, l'eau est **solide** (−5 °C) ; à t = 7 min, elle est **liquide** (12 °C).\n3. Oui : pendant le changement d'état, la température reste **constante** ; ce **palier** est caractéristique d'un **corps pur** (un mélange n'en présente pas de net).\n4. Pendant le palier, l'énergie apportée ne sert pas à agiter davantage les molécules : elle sert à **défaire les interactions** entre elles, qui passent d'une organisation ordonnée et fixe à une organisation désordonnée. La fusion est **endothermique** : elle absorbe de l'énergie."}$exo$::jsonb),
  ('8cdb4008-bfd7-581e-9ffd-ada6b7b564df'::uuid, 3, 'application', $exo${"titre":"Eau pure, eau salée et Everest","consigne":"Analyse chaque situation et rédige des réponses argumentées qui s'appuient sur le cours.","enonce":"**Document 1.** Refroidissement de deux liquides sous 1 013 hPa :\n\n| t (min) | 0 | 2 | 4 | 6 | 8 | 10 |\n| Liquide A (°C) | 8 | 3 | 0 | 0 | 0 | −4 |\n| Liquide B (°C) | 8 | 2 | −2 | −4 | −6 | −9 |\n\nL'un est de l'eau pure, l'autre de l'eau salée ; tous deux finissent solides.\n\n**Document 2.** Une alpiniste campe au sommet de l'Everest. Elle constate que son eau bout vers 70 °C et que ses pâtes cuisent très mal.\n\n1. Identifie l'eau pure et l'eau salée. Justifie.\n2. Nomme le changement d'état observé. Est-il endothermique ou exothermique ?\n3. Décris l'organisation des molécules d'eau avant et après ce changement d'état. Les molécules sont-elles modifiées ?\n4. Explique pourquoi l'eau bout à 70 °C au sommet de l'Everest et pourquoi les pâtes cuisent mal.\n5. Après l'effort, l'alpiniste transpire et se sent refroidie. Explique ce phénomène.","bareme":[{"critere":"A eau pure (palier à 0 °C), B eau salée (pas de palier net)","points":4},{"critere":"Solidification, exothermique","points":4},{"critere":"Liquide désordonné puis solide ordonné et fixe ; molécules inchangées (transformation physique)","points":4},{"critere":"Pression plus faible donc ébullition à plus basse température ; eau à 70 °C seulement pour cuire","points":4},{"critere":"Vaporisation endothermique qui prélève de l'énergie sur la peau","points":4}],"dureeMin":17,"corrige":"1. Le liquide **A** présente un **palier à 0 °C** : c'est un corps pur, l'**eau pure**. Le liquide **B** ne présente **pas de palier net** : c'est un mélange, l'**eau salée**.\n2. Liquide → solide : **solidification**, **exothermique** (elle libère de l'énergie).\n3. Dans le liquide, les molécules sont **désordonnées mais liées et en contact** ; dans le solide, elles sont **ordonnées et fixes**. Un changement d'état est une transformation **physique** : les molécules restent des molécules d'eau, seule leur organisation change.\n4. La température d'ébullition dépend de la **pression**. Au sommet de l'Everest, la pression est bien plus faible qu'au niveau de la mer (1 013 hPa) : l'eau bout vers **70 °C**. L'eau ne peut pas dépasser cette température tant qu'elle bout : les pâtes cuisent dans une eau à 70 °C au lieu de 100 °C, d'où une cuisson très lente.\n5. La sueur se **vaporise** : ce changement d'état est **endothermique**, l'énergie nécessaire est **prélevée sur la peau**, qui se refroidit."}$exo$::jsonb),
  ('0fb60a4c-0d09-5810-b219-f61e01b8ad25'::uuid, 1, 'application', $exo${"titre":"Équilibrer trois équations","consigne":"Ajuste les nombres stœchiométriques, puis vérifie la conservation des éléments et des charges.","enonce":"Équilibre les équations suivantes (le mot « donne » remplace la flèche) :\n\n1. H₂ + O₂ donne H₂O\n2. Fe + O₂ donne Fe₃O₄\n3. Cu²⁺ + Fe donne Cu + Fe²⁺\n\n4. Que doit-on conserver lorsqu'on équilibre une équation de réaction ? Vérifie la conservation des charges dans l'équation 3.","bareme":[{"critere":"2 H₂ + O₂ donne 2 H₂O","points":5},{"critere":"3 Fe + 2 O₂ donne Fe₃O₄","points":5},{"critere":"Équation 3 déjà équilibrée (1 Cu, 1 Fe, charge +2 de chaque côté)","points":5},{"critere":"Conservation des éléments et de la charge électrique, vérifiée pour l'équation 3","points":5}],"dureeMin":7,"corrige":"1. **2 H₂ + O₂ donne 2 H₂O** : 4 H et 2 O de chaque côté.\n2. **3 Fe + 2 O₂ donne Fe₃O₄** : 3 Fe et 4 O de chaque côté.\n3. **Cu²⁺ + Fe donne Cu + Fe²⁺** : elle est déjà équilibrée, avec 1 Cu et 1 Fe de chaque côté.\n4. On conserve les **éléments** (autant d'atomes de chaque élément de part et d'autre) et la **charge électrique**. Dans l'équation 3 : à gauche, charge +2 (Cu²⁺) ; à droite, charge +2 (Fe²⁺). La charge est conservée."}$exo$::jsonb),
  ('0fb60a4c-0d09-5810-b219-f61e01b8ad25'::uuid, 2, 'application', $exo${"titre":"Le tableau d'avancement de l'eau","consigne":"Construis le tableau d'avancement et détaille la recherche du réactif limitant.","enonce":"**Situation.** Dans une pile à combustible, le dihydrogène réagit avec le dioxygène selon :\n\n2 H₂ + O₂ donne 2 H₂O\n\nÀ l'état initial, on dispose de **3,0 mol de H₂** et **2,0 mol de O₂**, sans eau.\n\n1. Construis le tableau d'avancement (état initial, état intermédiaire, état final).\n2. Détermine l'avancement maximal x_max et le réactif limitant.\n3. Donne la composition du système à l'état final.\n4. Le mélange initial est-il stœchiométrique ? Justifie.","bareme":[{"critere":"Tableau correct : 3,0 − 2x ; 2,0 − x ; 2x","points":6},{"critere":"x_max = 1,5 mol, H₂ limitant, avec les deux valeurs comparées","points":6},{"critere":"État final : 0 mol H₂, 0,5 mol O₂, 3,0 mol H₂O","points":5},{"critere":"Non stœchiométrique : il reste du dioxygène","points":3}],"dureeMin":11,"corrige":"1. Tableau d'avancement :\n\n| État | H₂ | O₂ | H₂O |\n| Initial (x = 0) | 3,0 | 2,0 | 0 |\n| Intermédiaire (x) | 3,0 − 2x | 2,0 − x | 2x |\n| Final (x_max) | 3,0 − 2x_max | 2,0 − x_max | 2x_max |\n\n2. H₂ s'annule pour 3,0 − 2x = 0, soit x = **1,5 mol** ; O₂ s'annule pour x = **2,0 mol**. x_max est la plus petite valeur : **x_max = 1,5 mol**, le réactif limitant est le **dihydrogène**.\n3. État final : n(H₂) = **0 mol** ; n(O₂) = 2,0 − 1,5 = **0,5 mol** ; n(H₂O) = 2 × 1,5 = **3,0 mol**.\n4. **Non** : dans un mélange stœchiométrique, tous les réactifs disparaissent en même temps. Ici il reste 0,5 mol de dioxygène."}$exo$::jsonb),
  ('0fb60a4c-0d09-5810-b219-f61e01b8ad25'::uuid, 3, 'application', $exo${"titre":"La combustion du propane","consigne":"Équilibre l'équation, calcule les quantités initiales, puis mène l'étude complète de l'avancement.","enonce":"**Situation.** Un réchaud de camping brûle du propane C₃H₈. La combustion complète produit du dioxyde de carbone et de l'eau :\n\nC₃H₈ + … O₂ donne … CO₂ + … H₂O\n\nOn fait réagir **4,4 g** de propane avec **0,40 mol** de dioxygène.\n\n> Données : M(H) = 1,0 g·mol⁻¹ ; M(C) = 12,0 g·mol⁻¹.\n\n1. Équilibre l'équation de réaction.\n2. Calcule la quantité de matière initiale de propane.\n3. Détermine le réactif limitant et l'avancement maximal.\n4. Donne la composition du système à l'état final.\n5. Quelle quantité de dioxygène aurait-il fallu pour un mélange stœchiométrique ?\n6. Cette réaction est-elle endothermique ou exothermique ? Justifie.","bareme":[{"critere":"C₃H₈ + 5 O₂ donne 3 CO₂ + 4 H₂O","points":4},{"critere":"M = 44,0 g·mol⁻¹ et n = 0,10 mol","points":3},{"critere":"x = 0,10 (propane) et x = 0,080 (O₂) : O₂ limitant, x_max = 0,080 mol","points":5},{"critere":"État final : 0,02 mol C₃H₈, 0 mol O₂, 0,24 mol CO₂, 0,32 mol H₂O","points":4},{"critere":"0,50 mol de O₂ pour le mélange stœchiométrique ; combustion exothermique","points":4}],"dureeMin":18,"corrige":"1. **C₃H₈ + 5 O₂ donne 3 CO₂ + 4 H₂O** : 3 C, 8 H et 10 O de chaque côté.\n2. M(C₃H₈) = 3 × 12,0 + 8 × 1,0 = 44,0 g·mol⁻¹ ; n = 4,4 / 44,0 = **0,10 mol**.\n3. Propane : 0,10 − x = 0 pour x = 0,10 mol. Dioxygène : 0,40 − 5x = 0 pour x = 0,080 mol. La plus petite valeur l'emporte : **x_max = 0,080 mol**, le **dioxygène est limitant**.\n4. État final : n(C₃H₈) = 0,10 − 0,080 = **0,02 mol** ; n(O₂) = **0 mol** ; n(CO₂) = 3 × 0,080 = **0,24 mol** ; n(H₂O) = 4 × 0,080 = **0,32 mol**.\n5. Pour consommer 0,10 mol de propane en même temps que le dioxygène : n(O₂) = 5 × 0,10 = **0,50 mol**.\n6. C'est une **combustion** : elle **libère** de l'énergie thermique (le réchaud chauffe), elle est **exothermique**."}$exo$::jsonb),
  ('f321f7cc-0a13-5e10-b7a2-3b609edb195c'::uuid, 1, 'application', $exo${"titre":"Vanille de gousse ou de laboratoire","consigne":"Réponds par des phrases complètes en t'appuyant sur le cours.","enonce":"**Situation.** La vanilline donne son goût à la vanille. Elle est extraite des gousses de vanillier, mais la plus grande partie de la vanilline consommée dans le monde est synthétisée en laboratoire.\n\n1. Donne deux raisons pour lesquelles on synthétise la vanilline plutôt que de l'extraire.\n2. Un ami affirme : « La vanilline de synthèse, c'est forcément moins bon pour la santé. » Que lui réponds-tu ?\n3. Cite dans l'ordre les trois grandes étapes d'un protocole de synthèse.","bareme":[{"critere":"Deux raisons parmi quantité, coût, saisonnalité, impact sur le milieu","points":6},{"critere":"Molécule identique si même structure ; naturel n'est pas synonyme d'inoffensif, dose et usage comptent","points":8},{"critere":"Transformation, séparation, identification","points":6}],"dureeMin":6,"corrige":"1. Deux raisons parmi : la **quantité** (l'extraction ne suffit pas à la demande), le **coût** (l'extraction est bien plus chère), la **saisonnalité** (la ressource n'est pas toujours disponible), l'**impact** sur les milieux naturels.\n2. Une molécule de synthèse est **identique** à la molécule naturelle si sa **structure** est la même : le corps ne fait aucune différence. « Naturel » ne veut pas dire « inoffensif » et « de synthèse » ne veut pas dire « dangereux » : ce qui compte, c'est la **molécule, sa dose et son usage**.\n3. **Transformation** (réaction), **séparation** (isoler le produit), **identification** (vérifier ce qu'on a obtenu)."}$exo$::jsonb),
  ('f321f7cc-0a13-5e10-b7a2-3b609edb195c'::uuid, 2, 'application', $exo${"titre":"Le rendement de l'arôme de banane","consigne":"Calcule le rendement en détaillant la relation, puis explique le montage et les pertes.","enonce":"**Situation.** En TP, Amine synthétise l'acétate d'isoamyle, une espèce à odeur de banane présente dans le fruit. Il chauffe le mélange de réactifs **à reflux** pendant 30 minutes.\n\nD'après l'équation de réaction et les quantités introduites, il pouvait obtenir au maximum **0,150 mol** d'acétate d'isoamyle. Il en obtient **0,105 mol**.\n\n1. À quoi sert le chauffage à reflux ? Quel est le rôle du réfrigérant ?\n2. Calcule le rendement de la synthèse et exprime-le en pourcentage.\n3. Donne trois causes qui expliquent que le rendement soit inférieur à 1.\n4. Quelles précautions de sécurité Amine doit-il prendre pendant ce TP ?","bareme":[{"critere":"Reflux : chauffer sans perte, le réfrigérant condense les vapeurs et les renvoie","points":5},{"critere":"Rendement = 0,105 / 0,150 = 0,70 soit 70 %","points":6},{"critere":"Trois causes : transferts, réaction incomplète, réactions secondaires","points":6},{"critere":"Sécurité : pictogrammes, blouse, gants, lunettes, hotte, tri des déchets","points":3}],"dureeMin":10,"corrige":"1. Le chauffage accélère la transformation. Le **réfrigérant** **condense les vapeurs** et les **renvoie** dans le ballon : on chauffe longtemps **sans perdre de matière**.\n2. Rendement = quantité obtenue / quantité maximale attendue = 0,105 / 0,150 = **0,70**, soit **70 %**.\n3. \n- les **transferts** : il reste toujours du produit dans la verrerie ;\n- une réaction **incomplète** : tout le réactif n'a pas réagi ;\n- des réactions **secondaires** : une partie des réactifs forme d'autres produits.\n4. Lire les **pictogrammes de danger** et les mentions H et P des flacons, porter blouse, **lunettes** et gants, travailler sous la **hotte aspirante**, et **trier les déchets**."}$exo$::jsonb),
  ('f321f7cc-0a13-5e10-b7a2-3b609edb195c'::uuid, 3, 'application', $exo${"titre":"Du ballon au flacon : une synthèse complète","consigne":"Analyse chaque étape du protocole et justifie tes choix à l'aide des données.","enonce":"**Situation.** Un laboratoire synthétise une espèce P, présente dans l'huile essentielle d'une plante, selon ce protocole :\n\n> **Étape 1.** Chauffer à reflux les réactifs pendant 1 h.\n> **Étape 2.** Verser le mélange refroidi dans une ampoule à décanter, ajouter un solvant, agiter, laisser décanter, récupérer la phase contenant P.\n> **Étape 3.** Réaliser une chromatographie sur couche mince et mesurer la température de fusion du produit.\n\n**Données** :\n\n| | Eau | Cyclohexane | Éthanol |\n| Solubilité de P | Très faible | Très grande | Très grande |\n| Miscibilité avec l'eau | — | Non miscible | Miscible |\n\nLe mélange réactionnel est aqueux. La quantité maximale attendue de P est 0,080 mol ; on en obtient 0,052 mol.\n\n1. Associe chaque étape à l'une des trois grandes étapes d'une synthèse.\n2. Sur quel principe repose l'étape 2 ? Quel solvant choisir ? Justifie en éliminant les deux autres.\n3. Comment l'étape 3 permet-elle de vérifier que le produit est bien P ? Pourquoi croiser deux méthodes ?\n4. Calcule le rendement.\n5. Le produit de synthèse P aura-t-il les mêmes propriétés que l'espèce P extraite de la plante ? Justifie.","bareme":[{"critere":"Étape 1 transformation, 2 séparation, 3 identification","points":3},{"critere":"Différence de solubilité dans deux liquides non miscibles ; cyclohexane (P très soluble, non miscible à l'eau)","points":6},{"critere":"Comparaison à une référence de P (même hauteur sur la plaque, même température de fusion) ; indices concordants","points":4},{"critere":"Rendement = 0,052 / 0,080 = 0,65 soit 65 %","points":4},{"critere":"Même structure donc même molécule, mêmes propriétés","points":3}],"dureeMin":18,"corrige":"1. Étape 1 : **transformation** ; étape 2 : **séparation** ; étape 3 : **identification**.\n2. L'étape 2 est une **extraction par solvant** : elle repose sur la **différence de solubilité** de P dans **deux liquides non miscibles**. Le solvant doit dissoudre P et ne pas se mélanger à l'eau :\n- l'**eau** ne convient pas, P y est très peu soluble ;\n- l'**éthanol** dissout P mais il est **miscible** à l'eau : pas de deux phases à séparer ;\n- le **cyclohexane** dissout très bien P et n'est pas miscible à l'eau : c'est le bon choix.\n3. On dépose le produit à côté d'une **référence** de P : s'ils migrent à la même hauteur, c'est probablement P. On compare aussi la **température de fusion** mesurée à celle de P. Une seule mesure suffit rarement : deux indices **concordants** rendent l'identification solide.\n4. Rendement = 0,052 / 0,080 = **0,65**, soit **65 %**.\n5. Oui : si sa **structure est identique**, la molécule de synthèse est la **même** que la molécule naturelle ; elle a les mêmes propriétés."}$exo$::jsonb),
  ('4ac624e9-b754-5dfd-a02f-d91fe2b9af1d'::uuid, 1, 'application', $exo${"titre":"L'uranium qui devient thorium","consigne":"Applique les lois de conservation et justifie chaque réponse.","enonce":"L'uranium 238 (²³⁸₉₂U) est radioactif α : il émet un noyau d'hélium ⁴₂He et se transforme en un noyau X.\n\n1. Quelle différence fondamentale y a-t-il entre une réaction chimique et une réaction nucléaire ?\n2. Énonce les lois de Soddy.\n3. Détermine le nombre de masse A et le numéro atomique Z du noyau X.\n4. Sachant que le thorium a pour numéro atomique 90, identifie X et écris l'équation de la désintégration.","bareme":[{"critere":"Chimique : électrons et liaisons, éléments conservés ; nucléaire : noyau modifié, un élément en devient un autre","points":5},{"critere":"Conservation du nombre de nucléons A et du nombre de charge Z","points":5},{"critere":"A = 234 et Z = 90 calculés","points":6},{"critere":"X = thorium 234 ; équation ²³⁸₉₂U donne ²³⁴₉₀Th + ⁴₂He","points":4}],"dureeMin":7,"corrige":"1. Une réaction **chimique** ne concerne que les électrons et les liaisons : les **éléments se conservent**. Une réaction **nucléaire** modifie le **noyau** : un élément se transforme en un autre.\n2. Lois de Soddy : conservation du nombre de **nucléons A** et du nombre de **charge Z**.\n3. Conservation de A : 238 = A + 4, donc **A = 234**. Conservation de Z : 92 = Z + 2, donc **Z = 90**.\n4. Z = 90 : X est le **thorium 234**. Équation : **²³⁸₉₂U donne ²³⁴₉₀Th + ⁴₂He**."}$exo$::jsonb),
  ('4ac624e9-b754-5dfd-a02f-d91fe2b9af1d'::uuid, 2, 'application', $exo${"titre":"Carbone 14 et fluor 18","consigne":"Complète les équations avec les lois de Soddy, puis réponds en justifiant.","enonce":"**Document 1.** Le carbone 14 (¹⁴₆C), utilisé en archéologie, est radioactif **β⁻** : il se transforme en azote (Z = 7).\n\n**Document 2.** Le fluor 18 (¹⁸₉F), utilisé en imagerie médicale, est radioactif **β⁺** : il se transforme en oxygène (Z = 8).\n\n1. Qu'est-ce qui est émis lors d'une désintégration β⁻ ? Que se passe-t-il dans le noyau ?\n2. Écris l'équation de la désintégration du carbone 14 (l'électron est noté ⁰₋₁e).\n3. Écris l'équation de la désintégration du fluor 18 (le positon est noté ⁰₊₁e).\n4. Ces désintégrations s'accompagnent souvent d'un rayonnement γ. Qu'est-ce que c'est, et modifie-t-il A ou Z ?\n5. Peut-on savoir à quel moment un noyau de carbone 14 donné va se désintégrer ?","bareme":[{"critere":"β⁻ : émission d'un électron, un neutron devient proton","points":4},{"critere":"¹⁴₆C donne ¹⁴₇N + ⁰₋₁e, conservation de A et Z vérifiée","points":5},{"critere":"¹⁸₉F donne ¹⁸₈O + ⁰₊₁e","points":5},{"critere":"γ : rayonnement électromagnétique d'un noyau qui se désexcite, A et Z inchangés","points":3},{"critere":"Désintégration imprévisible pour un noyau, loi statistique sur un grand nombre","points":3}],"dureeMin":11,"corrige":"1. Lors d'une désintégration β⁻, le noyau émet un **électron** : un **neutron devient un proton**. A est inchangé, Z augmente de 1.\n2. **¹⁴₆C donne ¹⁴₇N + ⁰₋₁e**. Vérification : A : 14 = 14 + 0 ; Z : 6 = 7 − 1.\n3. **¹⁸₉F donne ¹⁸₈O + ⁰₊₁e**. Vérification : A : 18 = 18 + 0 ; Z : 9 = 8 + 1.\n4. Le rayonnement γ est un **rayonnement électromagnétique très énergétique**, émis par un noyau qui se **désexcite**. Il ne modifie **ni A ni Z**.\n5. **Non** : la désintégration d'un noyau donné est **imprévisible**. Seule une loi **statistique** apparaît sur un très grand nombre de noyaux."}$exo$::jsonb),
  ('4ac624e9-b754-5dfd-a02f-d91fe2b9af1d'::uuid, 3, 'application', $exo${"titre":"Fission dans la centrale, fusion dans le Soleil","consigne":"Complète et analyse les deux réactions, puis rédige un paragraphe argumenté sur les enjeux.","enonce":"**Réaction 1** (dans un réacteur) : ²³⁵₉₂U + ¹₀n donne ¹⁴¹₅₆Ba + ᴬ_Z Kr + 3 ¹₀n\n\n**Réaction 2** (au cœur du Soleil) : ²₁H + ³₁H donne ⁴₂He + ᴬ'_Z' X\n\n1. Détermine A et Z pour le krypton de la réaction 1.\n2. Détermine A' et Z' dans la réaction 2 et identifie la particule X.\n3. Laquelle de ces réactions est une fission, laquelle une fusion ? Justifie à l'aide de la taille des noyaux.\n4. Compare l'ordre de grandeur de l'énergie mise en jeu par une réaction nucléaire et par une réaction chimique.\n5. En quelques lignes, présente un avantage et deux risques de la production d'électricité par fission, ainsi que la façon dont chaque risque est géré.","bareme":[{"critere":"Krypton : A = 92, Z = 36 (conservation de A et Z détaillée)","points":4},{"critere":"A' = 1, Z' = 0 : X est un neutron","points":4},{"critere":"Réaction 1 fission (noyau lourd cassé par un neutron) ; réaction 2 fusion (noyaux légers unis)","points":4},{"critere":"Million d'électronvolts contre électronvolt","points":3},{"critere":"Avantage (production d'électricité) et risques gérés : déchets (stockage longue durée), exposition (radioprotection), accident (sûreté)","points":5}],"dureeMin":18,"corrige":"1. Conservation de A : 235 + 1 = 141 + A + 3 × 1, donc **A = 92**. Conservation de Z : 92 + 0 = 56 + Z + 0, donc **Z = 36**. Le noyau est ⁹²₃₆Kr.\n2. A : 2 + 3 = 4 + A', donc **A' = 1**. Z : 1 + 1 = 2 + Z', donc **Z' = 0**. X est un **neutron** ¹₀n.\n3. Réaction 1 : un noyau **lourd** (uranium 235), frappé par un neutron, se **casse** en deux noyaux plus légers : c'est une **fission**. Réaction 2 : deux noyaux **légers** (isotopes de l'hydrogène) s'**unissent** : c'est une **fusion**, source d'énergie des étoiles.\n4. Une réaction chimique met en jeu des énergies de l'ordre de l'**électronvolt** par entité ; une réaction nucléaire, de l'ordre du **million d'électronvolts** : environ un million de fois plus.\n5. La fission permet de **produire de l'électricité** en grande quantité dans les centrales. Mais elle produit des **déchets radioactifs**, gérés par un **stockage de très longue durée** ; elle expose à des rayonnements, d'où la **radioprotection** ; et un accident reste possible, d'où les règles de **sûreté et de confinement**. Ces choix énergétiques mêlent physique, économie et politique."}$exo$::jsonb),
  ('dacee4e2-6a4b-5397-84c9-944047efeb73'::uuid, 1, 'application', $exo${"titre":"Immobile ou en mouvement ?","consigne":"Réponds par des phrases complètes en précisant toujours le référentiel.","enonce":"**Situation.** Zoé est assise dans un TGV qui roule en ligne droite. Son frère Adam la regarde passer depuis le quai.\n\n1. Qu'est-ce qu'un référentiel ?\n2. Zoé est-elle immobile ou en mouvement ? Réponds dans le référentiel du train, puis dans celui du quai.\n3. Laquelle des deux réponses est juste ? Comment s'appelle cette idée ?\n4. Quel référentiel choisit-on pour étudier un satellite autour de la Terre ? Et pour étudier le mouvement de Mars autour du Soleil ?","bareme":[{"critere":"Référentiel : objet de référence muni d'un repère d'espace et d'une horloge","points":5},{"critere":"Immobile dans le référentiel du train, en mouvement dans celui du quai","points":6},{"critere":"Les deux sont justes : relativité du mouvement","points":4},{"critere":"Géocentrique pour le satellite, héliocentrique pour Mars","points":5}],"dureeMin":6,"corrige":"1. Un **référentiel** est un objet de référence auquel on associe un **repère d'espace** et une **horloge**.\n2. Dans le référentiel du **train**, Zoé est **immobile**. Dans le référentiel du **quai** (terrestre), elle est **en mouvement**.\n3. Les **deux** descriptions sont justes : un mouvement n'a de sens que par rapport à un référentiel. C'est la **relativité du mouvement**.\n4. Satellite : référentiel **géocentrique** (centre de la Terre). Mars : référentiel **héliocentrique** (centre du Soleil)."}$exo$::jsonb),
  ('dacee4e2-6a4b-5397-84c9-944047efeb73'::uuid, 2, 'application', $exo${"titre":"La balade à vélo de Karim","consigne":"Détaille tes calculs avec les unités, et précise le référentiel dans les descriptions.","enonce":"**Situation.** Karim parcourt **18 km** à vélo en **45 min** sur une route droite, à vitesse constante. Sa petite sœur l'attend au bord de la route.\n\n1. Calcule la vitesse moyenne de Karim en km·h⁻¹, puis en m·s⁻¹.\n2. Décris le mouvement de Karim dans le référentiel terrestre en deux mots (trajectoire et vitesse).\n3. Quelle est la trajectoire de la valve de sa roue avant pour Karim ? Et pour sa sœur au bord de la route ?\n4. Pourquoi la trajectoire de la valve n'est-elle pas la même pour les deux observateurs ?","bareme":[{"critere":"v = 18 / 0,75 = 24 km·h⁻¹ puis 24 / 3,6 ≈ 6,7 m·s⁻¹","points":7},{"critere":"Mouvement rectiligne uniforme dans le référentiel terrestre","points":4},{"critere":"Cercle pour Karim, cycloïde (arches) pour sa sœur","points":5},{"critere":"La trajectoire dépend du référentiel choisi","points":4}],"dureeMin":10,"corrige":"1. Δt = 45 min = 0,75 h. v = d / Δt = 18 / 0,75 = **24 km·h⁻¹**. Avec 1 m·s⁻¹ = 3,6 km·h⁻¹ : v = 24 / 3,6 ≈ **6,7 m·s⁻¹**.\n2. Dans le référentiel terrestre, la trajectoire est une droite et la vitesse constante : le mouvement est **rectiligne uniforme**.\n3. Pour Karim (référentiel du vélo), la valve décrit un **cercle**. Pour sa sœur (référentiel terrestre), elle décrit une **cycloïde**, une courbe en arches.\n4. La trajectoire est l'ensemble des positions successives d'un point **dans un référentiel donné** : en changeant de référentiel, on change la trajectoire."}$exo$::jsonb),
  ('dacee4e2-6a4b-5397-84c9-944047efeb73'::uuid, 3, 'application', $exo${"titre":"Le tapis roulant de l'aéroport","consigne":"Analyse chaque situation en précisant le référentiel, et justifie tes calculs.","enonce":"**Situation.** Dans un aéroport, Léa se tient immobile sur un tapis roulant rectiligne de **60 m**, qui avance à **0,75 m·s⁻¹** par rapport au sol.\n\n1. Léa est-elle en mouvement ? Réponds dans le référentiel du tapis, puis dans le référentiel terrestre.\n2. Combien de temps met-elle à parcourir le tapis ? Exprime sa vitesse par rapport au sol en km·h⁻¹.\n3. Pour Léa, un panneau publicitaire fixé au mur semble défiler. Explique.\n4. Plus tard, Léa fait rouler une balle sur le sol du hall. Un enregistrement donne sa position toutes les 0,50 s, avec les distances parcourues entre deux positions successives :\n\n| Intervalle | 1 | 2 | 3 | 4 | 5 |\n| Distance (cm) | 60 | 60 | 60 | 45 | 30 |\n\nCalcule la vitesse instantanée approchée de la balle sur l'intervalle 2 puis sur l'intervalle 5, et décris son mouvement en deux phases (la trajectoire est rectiligne).","bareme":[{"critere":"Immobile dans le référentiel du tapis, en mouvement rectiligne uniforme dans le référentiel terrestre","points":4},{"critere":"Δt = 60 / 0,75 = 80 s ; v = 0,75 × 3,6 = 2,7 km·h⁻¹","points":5},{"critere":"Dans le référentiel de Léa, c'est le panneau qui se déplace : relativité du mouvement","points":4},{"critere":"v ≈ 1,2 m·s⁻¹ puis 0,60 m·s⁻¹ ; rectiligne uniforme puis rectiligne ralenti","points":7}],"dureeMin":16,"corrige":"1. Dans le référentiel du **tapis**, Léa est **immobile**. Dans le référentiel **terrestre**, elle est **en mouvement rectiligne uniforme** à 0,75 m·s⁻¹.\n2. Δt = d / v = 60 / 0,75 = **80 s**. v = 0,75 × 3,6 = **2,7 km·h⁻¹**.\n3. Dans le référentiel lié à Léa, c'est le **panneau** qui est en mouvement (en sens inverse) : les deux descriptions sont justes, c'est la **relativité du mouvement**.\n4. La vitesse instantanée s'estime sur un intervalle très court, entre deux positions successives :\n- intervalle 2 : v ≈ 0,60 / 0,50 = **1,2 m·s⁻¹** ;\n- intervalle 5 : v ≈ 0,30 / 0,50 = **0,60 m·s⁻¹**.\nSur les trois premiers intervalles, les distances sont égales : mouvement **rectiligne uniforme**. Ensuite, les distances diminuent : mouvement **rectiligne ralenti**."}$exo$::jsonb),
  ('1d74eec5-d615-5c6e-a540-bf3b0314550d'::uuid, 1, 'application', $exo${"titre":"La flèche de la voiture","consigne":"Réponds par des phrases complètes et justifie la longueur de la flèche.","enonce":"**Situation.** Une voiture roule sur une route rectiligne orientée d'ouest en est, à la vitesse de **20 m·s⁻¹**. On veut représenter son vecteur vitesse avec l'échelle **1 cm pour 5 m·s⁻¹**.\n\n1. Cite les quatre caractéristiques d'un vecteur vitesse.\n2. Donne chacune de ces caractéristiques pour la voiture.\n3. Quelle doit être la longueur de la flèche ?\n4. En général, quelle est la direction du vecteur vitesse par rapport à la trajectoire ?","bareme":[{"critere":"Point d'application, direction, sens, valeur","points":5},{"critere":"Caractéristiques de la voiture : sa position, direction ouest-est, sens vers l'est, 20 m·s⁻¹","points":6},{"critere":"Longueur : 20 / 5 = 4 cm","points":5},{"critere":"Direction tangente à la trajectoire","points":4}],"dureeMin":6,"corrige":"1. Un vecteur vitesse a un **point d'application**, une **direction**, un **sens** et une **valeur**.\n2. Pour la voiture : point d'application = la **position de la voiture** ; direction = celle de la **route** (ouest-est) ; sens = **vers l'est**, celui du mouvement ; valeur = **20 m·s⁻¹**.\n3. Longueur = 20 / 5 = **4 cm**.\n4. Le vecteur vitesse est toujours **tangent à la trajectoire** (sur une route droite, il suit la droite)."}$exo$::jsonb),
  ('1d74eec5-d615-5c6e-a540-bf3b0314550d'::uuid, 2, 'application', $exo${"titre":"Le chariot qui accélère","consigne":"Détaille tes calculs avec les unités SI, puis interprète la variation du vecteur vitesse.","enonce":"**Situation.** Un chariot se déplace en ligne droite sur un banc. Une caméra enregistre ses positions M₀, M₁, M₂… à intervalles réguliers **τ = 40 ms**. On mesure (en vraie grandeur) :\n\n- M₂M₄ = **3,2 cm** ;\n- M₄M₆ = **4,8 cm**.\n\n1. Calcule la valeur approchée de la vitesse v₃ au point M₃, puis v₅ au point M₅.\n2. Avec l'échelle 1 cm pour 0,10 m·s⁻¹, quelles longueurs donner aux flèches v₃ et v₅ ?\n3. Décris la construction du vecteur variation de vitesse entre M₃ et M₅. Quelle est sa valeur et son sens ?\n4. Que peut-on en déduire sur la somme des forces qui s'exercent sur le chariot ?","bareme":[{"critere":"v₃ = 0,032 / 0,080 = 0,40 m·s⁻¹ et v₅ = 0,048 / 0,080 = 0,60 m·s⁻¹","points":7},{"critere":"Longueurs 4,0 cm et 6,0 cm","points":3},{"critere":"Construction depuis un même point ; variation 0,20 m·s⁻¹ dans le sens du mouvement","points":6},{"critere":"Somme des forces dans le sens du mouvement","points":4}],"dureeMin":11,"corrige":"1. v(i) ≈ M(i−1)M(i+1) / 2τ, avec 2τ = 80 ms = 0,080 s.\n- v₃ ≈ 0,032 / 0,080 = **0,40 m·s⁻¹** ;\n- v₅ ≈ 0,048 / 0,080 = **0,60 m·s⁻¹**.\n2. v₃ : 0,40 / 0,10 = **4,0 cm** ; v₅ : 0,60 / 0,10 = **6,0 cm**. Les deux flèches sont tangentes à la trajectoire, donc sur la droite du mouvement.\n3. On **reporte les deux vecteurs à partir d'un même point**, puis on trace le vecteur qui joint l'extrémité de v₃ à celle de v₅. Les vecteurs étant de même direction et de même sens, la variation vaut 0,60 − 0,40 = **0,20 m·s⁻¹**, **dans le sens du mouvement** : le mouvement est rectiligne accéléré.\n4. Le vecteur variation de vitesse a le même sens que la somme des forces : la **somme des forces n'est pas nulle** et elle est **dirigée dans le sens du mouvement**."}$exo$::jsonb),
  ('1d74eec5-d615-5c6e-a540-bf3b0314550d'::uuid, 3, 'application', $exo${"titre":"Un tour de manège","consigne":"Raisonne à l'aide de constructions décrites et de calculs, puis argumente en reliant variation de vitesse et forces.","enonce":"**Situation.** Sur un manège, Mathis décrit un cercle de centre O à vitesse de valeur constante **3,0 m·s⁻¹**. On repère deux positions : A, puis B, un quart de tour plus loin.\n\n1. Le mouvement de Mathis est-il uniforme ? Son vecteur vitesse est-il constant ? Justifie.\n2. Décris les vecteurs vitesse en A et en B : direction par rapport au rayon OA (ou OB), sens, valeur. Quel angle font-ils entre eux ?\n3. Décris la construction du vecteur variation de vitesse entre A et B. Calcule sa valeur (utilise le théorème de Pythagore). Vers où pointe-t-il ?\n4. Un camarade affirme : « Mathis tourne à vitesse constante, donc les forces qui s'exercent sur lui se compensent. » Réfute cette affirmation.","bareme":[{"critere":"Uniforme (valeur constante) mais vecteur vitesse non constant car la direction change","points":4},{"critere":"Vecteurs tangents, perpendiculaires aux rayons, 3,0 m·s⁻¹, perpendiculaires entre eux","points":4},{"critere":"Construction depuis un même point ; valeur √(3,0² + 3,0²) ≈ 4,2 m·s⁻¹","points":5},{"critere":"Variation dirigée vers l'intérieur du cercle, vers le centre","points":3},{"critere":"Variation non nulle donc somme des forces non nulle, dirigée vers le centre","points":4}],"dureeMin":17,"corrige":"1. La valeur de la vitesse est constante : le mouvement est **circulaire uniforme**. Mais la **direction** du vecteur vitesse change en permanence : le vecteur vitesse **n'est pas constant**.\n2. En A comme en B, le vecteur vitesse est **tangent** au cercle, donc **perpendiculaire au rayon** ; son sens est celui du mouvement ; sa valeur est **3,0 m·s⁻¹**. Entre A et B, le rayon a tourné d'un quart de tour (90°) : les deux vecteurs sont **perpendiculaires** entre eux.\n3. On reporte v(A) et v(B) à partir d'un **même point**, puis on trace le vecteur qui va de l'extrémité de v(A) à celle de v(B). Les deux vecteurs formant un angle droit, la variation est l'hypoténuse d'un triangle rectangle : Δv = √(3,0² + 3,0²) = √18 ≈ **4,2 m·s⁻¹**. Il pointe **vers l'intérieur du cercle, en direction du centre** O.\n4. L'affirmation est fausse : le vecteur vitesse **varie** (sa direction change), donc sa variation n'est **pas nulle**. Or le vecteur variation de vitesse a le même sens que la somme des forces : la somme des forces est **non nulle**, dirigée **vers le centre** du manège. Les forces ne se compensent pas."}$exo$::jsonb),
  ('25e61fb2-54c0-5300-9f1d-92e9e9cf73ab'::uuid, 1, 'application', $exo${"titre":"Le poids d'une astronaute","consigne":"Détaille tes calculs avec les unités, puis réponds par des phrases complètes.","enonce":"**Situation.** Une astronaute a une masse de **60 kg** (équipement compris).\n\n> Données : g(Terre) ≈ 9,8 N·kg⁻¹ ; g(Lune) ≈ 1,6 N·kg⁻¹.\n\n1. Calcule son poids sur Terre.\n2. Quelle est sa masse sur la Lune ? Calcule son poids sur la Lune.\n3. Donne les caractéristiques du poids (direction, sens, point d'application).\n4. Explique la différence entre masse et poids.","bareme":[{"critere":"P = m × g = 60 × 9,8 = 588 N (≈ 5,9 × 10² N)","points":5},{"critere":"Masse 60 kg inchangée ; poids 60 × 1,6 = 96 N","points":6},{"critere":"Vertical, vers le bas, appliqué au centre de gravité","points":4},{"critere":"Masse (kg) identique partout ; poids (N), force qui dépend du lieu","points":5}],"dureeMin":7,"corrige":"1. P = m × g = 60 × 9,8 = **588 N**, soit environ 5,9 × 10² N.\n2. La masse ne dépend que de l'objet : elle vaut toujours **60 kg**. P(Lune) = 60 × 1,6 = **96 N**, environ six fois moins que sur Terre.\n3. Le poids est **vertical**, dirigé **vers le bas**, appliqué au **centre de gravité**.\n4. La **masse** (en kg) caractérise l'objet et est **identique partout**. Le **poids** est une **force** (en newtons) qui **dépend du lieu** par la valeur de g."}$exo$::jsonb),
  ('25e61fb2-54c0-5300-9f1d-92e9e9cf73ab'::uuid, 2, 'application', $exo${"titre":"La suspension du salon","consigne":"Réalise l'inventaire des actions puis réponds en justifiant chaque réponse par le cours.","enonce":"**Situation.** Une lampe de masse **1,5 kg** est suspendue au plafond par un fil. Le système étudié est la **lampe**. On néglige l'action de l'air.\n\n> Donnée : g ≈ 9,8 N·kg⁻¹.\n\n1. Fais l'inventaire des actions qui s'exercent sur la lampe. Décris le diagramme objet-interaction correspondant.\n2. Pour chaque action, indique s'il s'agit d'une action de contact ou à distance.\n3. Calcule la valeur du poids de la lampe et donne ses caractéristiques.\n4. La lampe exerce-t-elle, elle aussi, une force sur le fil ? Énonce le principe utilisé et donne les caractéristiques de cette force par rapport à celle du fil sur la lampe.","bareme":[{"critere":"Deux actions : la Terre (poids) et le fil","points":4},{"critere":"Diagramme : lampe au centre, Terre et fil autour, une double flèche par interaction ; poids à distance, fil de contact","points":5},{"critere":"P = 1,5 × 9,8 = 14,7 N, vertical, vers le bas, au centre de gravité","points":5},{"critere":"Actions réciproques : même direction, même valeur, sens opposé, appliquées à des objets différents","points":6}],"dureeMin":10,"corrige":"1. Deux acteurs agissent sur la lampe : la **Terre** et le **fil**. Diagramme objet-interaction : la lampe au centre, la Terre et le fil autour, reliés chacun à la lampe par une **double flèche** (le plafond n'agit pas directement sur la lampe).\n2. L'action de la Terre (le **poids**) est une action **à distance** ; l'action du **fil** est une action **de contact**.\n3. P = m × g = 1,5 × 9,8 = **14,7 N** ; vertical, vers le bas, appliqué au centre de gravité de la lampe.\n4. **Oui** : d'après le **principe des actions réciproques**, si le fil exerce une force sur la lampe, la lampe exerce sur le fil une force de **même direction**, de **même valeur** et de **sens opposé**. Ces deux forces s'appliquent à des objets différents (l'une sur la lampe, l'autre sur le fil) : elles ne se compensent pas entre elles."}$exo$::jsonb),
  ('25e61fb2-54c0-5300-9f1d-92e9e9cf73ab'::uuid, 3, 'application', $exo${"titre":"La Terre et la Lune s'attirent","consigne":"Détaille les calculs en notation scientifique puis argumente chaque réponse.","enonce":"> **Données** : G ≈ 6,67 × 10⁻¹¹ N·m²·kg⁻² ; masse de la Terre m(T) = 5,97 × 10²⁴ kg ; masse de la Lune m(L) = 7,35 × 10²² kg ; distance entre leurs centres d = 3,84 × 10⁸ m.\n\n1. Écris l'expression de la force d'interaction gravitationnelle exercée par la Terre sur la Lune, puis calcule sa valeur.\n2. Quelle est la valeur de la force exercée par la Lune sur la Terre ? Précise sa direction et son sens. Justifie.\n3. Ces deux forces se compensent-elles ? Explique.\n4. Si la Lune était deux fois plus loin, que deviendrait cette force ? Donne sa nouvelle valeur.\n5. Un élève affirme : « La Terre, bien plus massive, attire la Lune plus fort que la Lune n'attire la Terre. » Réponds-lui.","bareme":[{"critere":"F = G × m(T) × m(L) / d² ≈ 2,0 × 10²⁰ N, calcul détaillé","points":6},{"critere":"Même valeur, même direction (droite des centres), sens opposé : force attractive et réciproque","points":4},{"critere":"Pas de compensation : les deux forces s'appliquent à deux objets différents","points":3},{"critere":"Distance doublée : force divisée par 4, soit ≈ 5,0 × 10¹⁹ N","points":4},{"critere":"Réfutation : l'interaction a la même valeur pour les deux corps","points":3}],"dureeMin":16,"corrige":"1. F = G × m(T) × m(L) / d².\nF = 6,67 × 10⁻¹¹ × 5,97 × 10²⁴ × 7,35 × 10²² / (3,84 × 10⁸)² ≈ 2,93 × 10³⁷ / 1,47 × 10¹⁷ ≈ **2,0 × 10²⁰ N**.\n2. La force gravitationnelle est **réciproque** : la Lune attire la Terre avec une force de **même valeur** (2,0 × 10²⁰ N), de même direction (la droite qui joint les centres), mais de **sens opposé** : dirigée de la Terre vers la Lune. Elle est **attractive**.\n3. **Non** : ces deux forces ne s'appliquent **pas au même objet** (l'une à la Lune, l'autre à la Terre). Elles ne se compensent jamais entre elles.\n4. La force décroît en 1/d² : doubler la distance la **divise par quatre**. F' = 2,0 × 10²⁰ / 4 = **5,0 × 10¹⁹ N**.\n5. C'est faux : d'après la formule, F dépend du **produit** des deux masses, identique pour les deux corps, et le principe des actions réciproques impose la **même valeur**. C'est la même interaction vue des deux côtés."}$exo$::jsonb),
  ('10278a4d-480a-5704-863f-74e8302f6310'::uuid, 1, 'application', $exo${"titre":"Le palet qui glisse","consigne":"Réponds par des phrases complètes en citant le principe d'inertie.","enonce":"**Situation.** Sur une table à coussin d'air, Rayan lance un palet qui glisse presque sans frottement.\n\n1. Énonce le principe d'inertie.\n2. Après le lancer, comment le palet se déplace-t-il ? Justifie.\n3. Rayan pense qu'« il faut une force pour que le palet continue d'avancer ». Que lui réponds-tu ?\n4. Dans quel type de référentiel le principe d'inertie s'applique-t-il ? Quel référentiel peut-on utiliser ici ?","bareme":[{"critere":"Énoncé : forces qui se compensent ⇔ vecteur vitesse constant (immobile ou rectiligne uniforme)","points":6},{"critere":"Palet en mouvement rectiligne uniforme car les forces se compensent presque","points":5},{"critere":"Une force sert à changer le mouvement, pas à l'entretenir","points":5},{"critere":"Référentiel galiléen ; terrestre, bonne approximation pour une expérience courte","points":4}],"dureeMin":6,"corrige":"1. Dans un **référentiel galiléen**, si les forces qui s'exercent sur un système **se compensent**, son **vecteur vitesse ne varie pas** : il est immobile ou en mouvement **rectiligne uniforme** (et réciproquement).\n2. Sur coussin d'air, il n'y a presque pas de frottement : le poids est compensé par l'action de l'air soufflé. Les forces se compensent, le palet **conserve sa vitesse et sa direction** : mouvement **rectiligne uniforme**.\n3. C'est l'erreur la plus tenace de la mécanique : il ne faut **pas** de force pour **entretenir** un mouvement, il en faut une pour le **changer**.\n4. Dans un **référentiel galiléen** ; le **référentiel terrestre** en est une bonne approximation pour une expérience de courte durée."}$exo$::jsonb),
  ('10278a4d-480a-5704-863f-74e8302f6310'::uuid, 2, 'application', $exo${"titre":"Trois situations à expliquer","consigne":"Pour chaque situation, fais le lien entre le mouvement et les forces en appliquant le principe d'inertie ou sa contraposée.","enonce":"1. **Le parachutiste.** Parachute ouvert, Nathan (masse totale **80 kg**) descend à vitesse constante, à la verticale. Que peut-on dire des forces qui s'exercent sur lui ? Calcule son poids (g ≈ 9,8 N·kg⁻¹) et déduis-en la valeur de la force exercée par l'air.\n2. **La skieuse.** Clara descend une piste droite et sa vitesse augmente. Les forces qui s'exercent sur elle se compensent-elles ? Dans quel sens est dirigée leur somme ?\n3. **La voiture.** Une voiture roule à vitesse constante sur une route droite, moteur en marche. Pourquoi le moteur doit-il continuer à fonctionner si les forces se compensent ?","bareme":[{"critere":"Parachutiste : mouvement rectiligne uniforme donc forces qui se compensent","points":4},{"critere":"P = 784 N ; force de l'air de 784 N, verticale vers le haut","points":5},{"critere":"Skieuse : vitesse qui varie donc forces qui ne se compensent pas ; somme dans le sens du mouvement","points":6},{"critere":"Voiture : la force motrice compense exactement les frottements","points":5}],"dureeMin":11,"corrige":"1. Nathan a un mouvement **rectiligne uniforme** : d'après la réciproque du principe d'inertie, les forces **se compensent**. P = m × g = 80 × 9,8 = **784 N**. La force exercée par l'air compense le poids : elle vaut **784 N**, verticale, dirigée **vers le haut**.\n2. La vitesse de Clara **augmente** : son vecteur vitesse varie. D'après la contraposée, les forces **ne se compensent pas**. Leur somme a le sens de la variation de vitesse : **dans le sens du mouvement**, vers le bas de la piste.\n3. Les forces se compensent parce que le moteur fournit une force motrice qui **compense exactement les frottements**. Si le moteur s'arrête, les frottements ne sont plus compensés : la voiture ralentit."}$exo$::jsonb),
  ('10278a4d-480a-5704-863f-74e8302f6310'::uuid, 3, 'application', $exo${"titre":"Analyse d'un enregistrement et chute libre","consigne":"Exploite l'enregistrement, puis rédige une argumentation qui s'appuie sur le principe d'inertie.","enonce":"**Document 1.** Un palet glisse sur une table horizontale : sur coussin d'air d'abord, puis il passe sur une partie en moquette. Positions relevées toutes les 50 ms ; distances entre positions successives :\n\n| Intervalle | 1 | 2 | 3 | 4 | 5 | 6 |\n| Distance (cm) | 2,0 | 2,0 | 2,0 | 1,6 | 1,2 | 0,8 |\n\n**Document 2.** Dans un tube où l'on a fait le vide, on lâche en même temps une plume et une bille. Dans l'air, la bille arrive bien avant la plume.\n\n1. Décris le mouvement du palet dans chacune des deux phases (la trajectoire est rectiligne).\n2. Que peut-on dire des forces dans la première phase ? Dans la seconde ? Précise le sens de leur somme dans la seconde phase.\n3. Qu'est-ce qu'un corps en chute libre ? Dans le tube vidé, la plume et la bille sont-elles en chute libre ?\n4. Explique le document 2 : pourquoi tombent-elles ensemble dans le vide, et pas dans l'air ?\n5. Aristote pensait qu'un corps lourd tombe plus vite qu'un corps léger. Que montre le document 2 ?","bareme":[{"critere":"Phase 1 rectiligne uniforme (distances égales), phase 2 rectiligne ralentie","points":4},{"critere":"Phase 1 : forces qui se compensent ; phase 2 : ne se compensent pas, somme opposée au mouvement","points":5},{"critere":"Chute libre : soumis à son seul poids ; oui dans le vide","points":3},{"critere":"Même variation de vitesse sans air ; dans l'air, la résistance de l'air les sépare","points":5},{"critere":"La masse n'intervient pas dans la chute libre : Aristote se trompait","points":3}],"dureeMin":18,"corrige":"1. Intervalles 1 à 3 : distances **égales** pendant des durées égales : mouvement **rectiligne uniforme**. Intervalles 4 à 6 : distances qui **diminuent** : mouvement **rectiligne ralenti**.\n2. Première phase : le vecteur vitesse ne varie pas, donc les forces **se compensent** (principe d'inertie). Seconde phase : le vecteur vitesse varie, donc les forces **ne se compensent pas** (contraposée). La variation de vitesse est opposée au mouvement : la somme des forces est **dirigée en sens inverse du mouvement** (frottements de la moquette).\n3. Un corps en **chute libre** n'est soumis qu'à **son poids**. Dans le tube vidé, il n'y a pas d'air : la plume et la bille sont **en chute libre**.\n4. Tous les corps en chute libre subissent la **même variation de vitesse**, quelle que soit leur masse : dans le vide, ils tombent **ensemble**. Dans l'air, la **résistance de l'air** freine beaucoup plus la plume : c'est elle qui les sépare, et non la masse.\n5. Le document montre que la **masse n'intervient pas** dans la chute libre : l'idée d'Aristote vient de l'effet de l'air, pas de la masse."}$exo$::jsonb),
  ('832cbafb-fb8a-5c07-90ff-6933a2096979'::uuid, 1, 'application', $exo${"titre":"Le son de la guitare","consigne":"Réponds par des phrases complètes en utilisant le vocabulaire du cours.","enonce":"**Situation.** Élise joue de la guitare dans sa chambre ; son frère l'entend depuis le couloir.\n\n1. Décris les trois étapes de la chaîne du son dans cette situation (émission, propagation, réception).\n2. Le son transporte-t-il de l'air de la guitare jusqu'à l'oreille ? Explique comment il se propage.\n3. Un film montre une explosion bruyante dans l'espace. Est-ce physiquement possible ? Justifie.\n4. Donne l'ordre de grandeur de la célérité du son dans l'air à 20 °C.","bareme":[{"critere":"Émission : corde qui vibre ; propagation dans l'air ; réception par l'oreille","points":6},{"critere":"Pas de transport de matière : compressions et dilatations transmises de proche en proche","points":5},{"critere":"Impossible : le son ne se propage pas dans le vide, il lui faut un milieu matériel","points":5},{"critere":"Environ 340 m·s⁻¹","points":4}],"dureeMin":6,"corrige":"1. **Émission** : la corde de la guitare **vibre**. **Propagation** : la vibration se transmet de proche en proche dans l'**air**, milieu matériel. **Réception** : l'**oreille** du frère convertit la vibration.\n2. **Non** : le son est une onde mécanique, faite de **compressions et dilatations** successives du milieu. Chaque molécule oscille autour de sa position d'équilibre et transmet la perturbation à sa voisine : il n'y a **pas de transport de matière**, seulement d'énergie.\n3. **Non** : le son a besoin d'un **milieu matériel** pour se propager ; dans le **vide** de l'espace, il n'y a aucune matière à faire vibrer.\n4. Dans l'air à 20 °C, v ≈ **340 m·s⁻¹**."}$exo$::jsonb),
  ('832cbafb-fb8a-5c07-90ff-6933a2096979'::uuid, 2, 'application', $exo${"titre":"Sonar et orage","consigne":"Choisis la bonne relation pour chaque situation et détaille tes calculs.","enonce":"> Données : célérité du son dans l'air ≈ 340 m·s⁻¹ ; dans l'eau de mer ≈ 1 500 m·s⁻¹.\n\n**Situation 1.** Le sonar d'un bateau émet un signal vers le fond. L'écho revient **0,40 s** après l'émission.\n\n**Situation 2.** Pendant un orage, Lucie compte **6 s** entre l'éclair et le tonnerre.\n\n1. Explique le principe de la méthode de l'écho et écris la relation qui donne la distance.\n2. Calcule la profondeur de l'eau sous le bateau.\n3. Calcule la distance qui sépare Lucie de l'orage.\n4. Pourquoi Lucie voit-elle l'éclair avant d'entendre le tonnerre ? Pourquoi peut-on négliger la durée de trajet de la lumière ?","bareme":[{"critere":"Aller-retour : d = v × Δt / 2","points":5},{"critere":"d = 1 500 × 0,40 / 2 = 300 m","points":5},{"critere":"d = 340 × 6 ≈ 2,0 × 10³ m (environ 2 km)","points":5},{"critere":"La lumière va beaucoup plus vite que le son, elle arrive presque instantanément","points":5}],"dureeMin":10,"corrige":"1. Le signal fait un **aller-retour** entre l'émetteur et l'obstacle : la durée mesurée correspond à deux fois la distance. **d = v × Δt / 2**.\n2. d = 1 500 × 0,40 / 2 = **300 m**.\n3. Le son parcourt l'aller simple : d = v × Δt = 340 × 6 ≈ **2 000 m**, soit environ **2 km**.\n4. La **lumière** se propage beaucoup plus vite que le son : elle arrive **presque instantanément**, tandis que le son met environ 3 s par kilomètre. On peut donc mesurer le retard du tonnerre comme la durée de trajet du son."}$exo$::jsonb),
  ('832cbafb-fb8a-5c07-90ff-6933a2096979'::uuid, 3, 'application', $exo${"titre":"Le coup de marteau sur le rail","consigne":"Exploite les données pour calculer les durées de propagation, puis explique les résultats avec le cours.","enonce":"**Situation.** Sur une voie ferrée désaffectée, Ilyes frappe un rail en acier avec un marteau. Son amie Mia, à **510 m** de là, a l'oreille posée contre le rail. Elle entend **deux coups** successifs.\n\n> Données : célérité du son dans l'air ≈ 340 m·s⁻¹ ; dans l'acier ≈ 5 100 m·s⁻¹.\n\n1. Explique pourquoi Mia entend deux coups.\n2. Calcule la durée de propagation du son dans le rail, puis dans l'air.\n3. Calcule le retard entre les deux coups. Quelle relation du cours retrouve-t-on ?\n4. Pourquoi le son se propage-t-il plus vite dans l'acier que dans l'air ?\n5. Mia ne connaît pas la distance et mesure seulement un retard de 1,4 s entre les deux coups. Montre que cette mesure permettrait de retrouver la distance (on utilisera le fait qu'une durée de trajet vaut d / v).","bareme":[{"critere":"Deux chemins de propagation : le rail et l'air, à des célérités différentes","points":3},{"critere":"Δt(acier) = 510 / 5 100 = 0,10 s ; Δt(air) = 510 / 340 = 1,5 s","points":5},{"critere":"Retard 1,4 s ; relation du retard entre deux trajets","points":4},{"critere":"Célérité plus grande dans un milieu dense et rigide","points":3},{"critere":"d / 340 − d / 5 100 = 1,4 conduit à d ≈ 510 m","points":5}],"dureeMin":18,"corrige":"1. Le son se propage par **deux chemins** : dans le **rail** (acier) et dans l'**air**. Les célérités étant différentes, il n'arrive pas en même temps par les deux : Mia entend deux coups.\n2. Dans l'acier : Δt₁ = d / v = 510 / 5 100 = **0,10 s**. Dans l'air : Δt₂ = 510 / 340 = **1,5 s**.\n3. Retard = 1,5 − 0,10 = **1,4 s**. C'est l'idée de la relation du **retard** : la différence de durée de trajet permet de **localiser** une source sonore.\n4. La célérité du son est d'autant plus grande que le milieu est **dense et rigide** : l'acier transmet la vibration bien plus vite que l'air.\n5. Retard = d / 340 − d / 5 100 = 1,4. Or 1/340 − 1/5 100 ≈ 0,002 94 − 0,000 20 = 0,002 75 s·m⁻¹. Donc d ≈ 1,4 / 0,002 75 ≈ **510 m** : la mesure du retard suffit à retrouver la distance."}$exo$::jsonb),
  ('5cc746c4-a49e-5347-b16a-7c67b478b260'::uuid, 1, 'application', $exo${"titre":"Audible ou non ?","consigne":"Détaille chaque calcul avec les unités, puis conclus par une phrase.","enonce":"1. Donne la relation entre la période T et la fréquence f d'un son, avec leurs unités.\n2. Un diapason émet un son de période **T = 4,0 ms**. Calcule sa fréquence. Ce son est-il audible par l'être humain ?\n3. Un sifflet pour chien émet un son de période **T = 25 µs**. Calcule sa fréquence. L'oreille humaine l'entend-elle ? Comment appelle-t-on ce type de son ?\n4. De ces deux sons, lequel est le plus aigu ? Justifie.","bareme":[{"critere":"f = 1 / T, f en hertz, T en secondes","points":4},{"critere":"f = 1 / 0,0040 = 250 Hz, audible (20 Hz à 20 000 Hz)","points":6},{"critere":"f = 1 / (25 × 10⁻⁶) = 40 000 Hz, ultrason inaudible","points":6},{"critere":"Plus aigu : la plus grande fréquence, le sifflet","points":4}],"dureeMin":7,"corrige":"1. **f = 1 / T**, avec f en **hertz** (Hz) et T en **secondes**.\n2. T = 4,0 ms = 4,0 × 10⁻³ s. f = 1 / (4,0 × 10⁻³) = **250 Hz**. Elle est comprise entre 20 Hz et 20 000 Hz : le son est **audible**.\n3. T = 25 µs = 25 × 10⁻⁶ s. f = 1 / (25 × 10⁻⁶) = **40 000 Hz**. C'est plus que 20 000 Hz : l'oreille humaine ne l'entend pas, c'est un **ultrason**.\n4. Plus la fréquence est grande, plus le son est aigu : le son du **sifflet** est le plus aigu (même s'il est inaudible pour nous)."}$exo$::jsonb),
  ('5cc746c4-a49e-5347-b16a-7c67b478b260'::uuid, 2, 'application', $exo${"titre":"Violon et flûte jouent la même note","consigne":"Exploite les mesures, détaille les calculs, puis explique avec le vocabulaire du cours.","enonce":"**Situation.** Nina enregistre avec un micro un violon puis une flûte qui jouent la même note. Sur l'écran, les deux signaux sont périodiques mais de formes différentes. Pour chacun, on compte **5 motifs** sur une durée de **11,4 ms**.\n\n1. Calcule la période du signal, puis sa fréquence (arrondie à l'unité).\n2. Quelle est la sensation associée à la fréquence ? Pourquoi dit-on que les deux instruments jouent la même note ?\n3. On reconnaît pourtant chaque instrument. Quelle qualité du son les distingue ? À quoi est-elle liée ?\n4. Le son du violon contient des harmoniques. Calcule les fréquences des deux premiers harmoniques après le fondamental.","bareme":[{"critere":"T = 11,4 / 5 = 2,28 ms ; f = 1 / T ≈ 439 Hz (proche de 440 Hz)","points":6},{"critere":"Fréquence liée à la hauteur ; même fréquence donc même note","points":4},{"critere":"Timbre, lié à la forme du signal et aux harmoniques","points":5},{"critere":"Harmoniques multiples du fondamental : ≈ 878 Hz et ≈ 1 317 Hz","points":5}],"dureeMin":11,"corrige":"1. T = 11,4 / 5 = **2,28 ms** = 2,28 × 10⁻³ s. f = 1 / T = 1 / (2,28 × 10⁻³) ≈ **439 Hz** (c'est pratiquement le la à 440 Hz).\n2. La fréquence est liée à la **hauteur** du son (grave ou aigu). Les deux signaux ont la **même fréquence** : les instruments jouent la **même note**.\n3. Ils se distinguent par leur **timbre**, lié à la **forme du signal** et à la présence d'**harmoniques**.\n4. Les harmoniques ont des fréquences **multiples** du fondamental : 2 × 439 ≈ **878 Hz** et 3 × 439 ≈ **1 317 Hz**."}$exo$::jsonb),
  ('5cc746c4-a49e-5347-b16a-7c67b478b260'::uuid, 3, 'application', $exo${"titre":"Scooters, concert et audition","consigne":"Raisonne avec l'échelle des décibels, justifie chaque réponse, puis rédige un conseil argumenté.","enonce":"**Données.** Conversation : 60 dB ; rue passante : 80 dB ; concert : 100 dB ; seuil de douleur : vers 120 dB.\n\n1. Qu'est-ce que le niveau d'intensité sonore ? Dans quelle unité s'exprime-t-il ? Pourquoi dit-on que son échelle est logarithmique ?\n2. Un scooter produit un niveau de 80 dB au bord de la route. Un second scooter identique passe à côté du premier. Quel est le niveau total ? Un camarade répond 160 dB : explique son erreur.\n3. Par combien l'intensité sonore est-elle multipliée entre une conversation et un concert ?\n4. Pour un auditeur, un son de 90 dB paraît-il deux fois plus fort, ou dix fois plus fort, qu'un son de 80 dB ? Justifie.\n5. Rédige un court conseil à un ami qui passe ses soirées collé aux enceintes : explique ce que risque son oreille et comment s'en protéger.","bareme":[{"critere":"Niveau L en décibels ; +10 dB multiplie l'intensité par 10","points":4},{"critere":"Deux sources identiques : +3 dB, soit 83 dB ; les décibels ne s'additionnent pas","points":4},{"critere":"40 dB d'écart : intensité multipliée par 10⁴ = 10 000","points":5},{"critere":"Son perçu deux fois plus fort (intensité ×10)","points":3},{"critere":"Cellules ciliées détruites définitivement, lésions irréversibles ; protections, pauses, distance","points":4}],"dureeMin":16,"corrige":"1. Le **niveau d'intensité sonore** L se mesure en **décibels** (dB). Son échelle est **logarithmique** : chaque **+10 dB** multiplie l'**intensité** sonore (en W·m⁻²) par **10**.\n2. Deux sources identiques côte à côte n'ajoutent que **+3 dB** : le niveau total est **83 dB**. Le camarade a additionné les décibels comme des nombres ordinaires, ce qui est faux : 160 dB dépasserait largement le seuil de douleur.\n3. De 60 à 100 dB, l'écart est de 40 dB, soit quatre fois +10 dB : l'intensité est multipliée par 10 × 10 × 10 × 10 = **10 000**.\n4. +10 dB multiplie l'intensité par 10, mais le son **paraît seulement deux fois plus fort**.\n5. Conseil : une exposition prolongée à des niveaux élevés **détruit définitivement les cellules ciliées** de l'oreille interne, qui **ne se régénèrent pas** : acouphènes et perte d'audition sont **irréversibles**. Il faut porter des **protections auditives**, faire des **pauses** et se tenir **à distance des enceintes**."}$exo$::jsonb),
  ('18184ff1-a5ec-54f4-852e-eeb91f921bba'::uuid, 1, 'application', $exo${"titre":"Deux lampes en série","consigne":"Justifie chaque réponse en citant la loi utilisée.","enonce":"**Situation.** Un générateur de **12 V** alimente deux lampes L₁ et L₂ montées **en série**. Un voltmètre indique **4,5 V** aux bornes de L₁, et l'ampèremètre placé près du générateur indique **0,30 A**.\n\n1. Comment branche-t-on un ampèremètre ? Un voltmètre ? Donne l'unité de chaque grandeur mesurée.\n2. Quelle est l'intensité du courant qui traverse L₂ ? Justifie.\n3. Calcule la tension aux bornes de L₂. Quelle loi utilises-tu ?","bareme":[{"critere":"Ampèremètre en série (ampère), voltmètre en dérivation (volt)","points":6},{"critere":"0,30 A dans L₂ : intensité identique partout en série (loi des nœuds)","points":6},{"critere":"U₂ = 12 − 4,5 = 7,5 V par la loi des mailles","points":8}],"dureeMin":7,"corrige":"1. L'**ampèremètre** se branche **en série** et mesure l'intensité, en **ampères** (A). Le **voltmètre** se branche **en dérivation** et mesure la tension, en **volts** (V).\n2. Dans un circuit série, l'intensité est la **même partout** (conséquence de la loi des nœuds) : L₂ est traversée par **0,30 A**.\n3. D'après la **loi des mailles**, en série la tension du générateur est la somme des tensions aux bornes des récepteurs : U = U₁ + U₂, donc U₂ = 12 − 4,5 = **7,5 V**."}$exo$::jsonb),
  ('18184ff1-a5ec-54f4-852e-eeb91f921bba'::uuid, 2, 'application', $exo${"titre":"Trois appareils en dérivation","consigne":"Applique les lois des nœuds et des mailles en détaillant tes calculs.","enonce":"**Situation.** Un générateur de **6,0 V** alimente trois dipôles D₁, D₂ et D₃ montés **en dérivation**. On mesure : I₁ = **0,15 A** dans D₁, I₂ = **0,25 A** dans D₂, et le générateur débite **0,60 A**.\n\n1. Quelle est la tension aux bornes de chaque dipôle ? Justifie.\n2. Énonce la loi des nœuds, puis calcule l'intensité I₃ dans D₃.\n3. On retire D₂. Que devient la tension aux bornes de D₁ ? D₁ continue-t-il de fonctionner ?\n4. Pourquoi l'éclairage d'une maison est-il câblé en dérivation ?","bareme":[{"critere":"6,0 V aux bornes de chaque dipôle (branches entre les mêmes nœuds)","points":5},{"critere":"Loi des nœuds énoncée ; I₃ = 0,60 − 0,15 − 0,25 = 0,20 A","points":7},{"critere":"Tension de D₁ inchangée (6,0 V), il fonctionne toujours","points":4},{"critere":"Chaque appareil reçoit la même tension et fonctionne indépendamment","points":4}],"dureeMin":10,"corrige":"1. Les branches en dérivation entre deux mêmes nœuds ont la **même tension** (loi des mailles) : chaque dipôle est soumis à **6,0 V**.\n2. **Loi des nœuds** : la somme des intensités qui arrivent à un nœud est égale à la somme de celles qui en repartent. I = I₁ + I₂ + I₃, donc I₃ = 0,60 − 0,15 − 0,25 = **0,20 A**.\n3. Retirer une branche ne modifie pas la tension des autres : D₁ reste sous **6,0 V** et **continue de fonctionner**.\n4. En dérivation, chaque appareil reçoit la **même tension** et fonctionne **indépendamment** : éteindre ou retirer une lampe n'éteint pas les autres."}$exo$::jsonb),
  ('18184ff1-a5ec-54f4-852e-eeb91f921bba'::uuid, 3, 'application', $exo${"titre":"Un circuit mixte","consigne":"Identifie les nœuds et les mailles, puis applique les deux lois en justifiant chaque étape.","enonce":"**Situation.** Un générateur de tension **9,0 V** est relié à une lampe L₁. En sortie de L₁, le circuit se divise en deux branches en dérivation : l'une contient la lampe L₂, l'autre la lampe L₃ ; les deux branches se rejoignent avant de revenir au générateur.\n\nMesures : tension aux bornes de L₁ : **U₁ = 3,0 V** ; intensité débitée par le générateur : **I = 0,40 A** ; intensité dans L₂ : **I₂ = 0,15 A**.\n\n1. Combien ce circuit compte-t-il de nœuds ? Quels dipôles sont en série, lesquels en dérivation ?\n2. Quelle est l'intensité I₁ dans L₁ ? Justifie.\n3. Calcule l'intensité I₃ dans L₃.\n4. Calcule les tensions U₂ et U₃ aux bornes de L₂ et L₃. Justifie avec la loi des mailles.\n5. Où et comment faut-il brancher l'ampèremètre pour mesurer I₃, et le voltmètre pour mesurer U₃ ? Que risquerait-on en branchant l'ampèremètre en dérivation aux bornes de L₃ ?","bareme":[{"critere":"Deux nœuds ; L₁ en série avec l'ensemble (L₂ // L₃)","points":3},{"critere":"I₁ = I = 0,40 A (même intensité dans la partie série)","points":3},{"critere":"I₃ = 0,40 − 0,15 = 0,25 A par la loi des nœuds","points":4},{"critere":"U₂ = U₃ = 9,0 − 3,0 = 6,0 V par la loi des mailles","points":5},{"critere":"Ampèremètre en série dans la branche de L₃, voltmètre en dérivation ; risque de court-circuit et de destruction","points":5}],"dureeMin":17,"corrige":"1. Le circuit compte **deux nœuds** (où les branches se séparent et se rejoignent). **L₁** est **en série** avec le générateur et avec l'ensemble formé par **L₂ et L₃**, qui sont **en dérivation** entre eux.\n2. L₁ est sur la partie série, traversée par tout le courant du générateur : **I₁ = I = 0,40 A**.\n3. Loi des nœuds : I₁ = I₂ + I₃, donc I₃ = 0,40 − 0,15 = **0,25 A**.\n4. Dans la maille générateur – L₁ – L₂ : U = U₁ + U₂, donc U₂ = 9,0 − 3,0 = **6,0 V**. L₂ et L₃ sont branchées entre les deux mêmes nœuds : **U₃ = U₂ = 6,0 V**.\n5. Pour I₃ : l'ampèremètre se branche **en série** dans la branche de L₃, pour être traversé par son courant. Pour U₃ : le voltmètre se branche **en dérivation** aux bornes de L₃. Un ampèremètre en dérivation **court-circuiterait** la lampe et pourrait être **détruit**."}$exo$::jsonb),
  ('bf193743-4add-5715-9623-983d7003215b'::uuid, 1, 'application', $exo${"titre":"Appliquer la loi d'Ohm","consigne":"Écris la relation utilisée, convertis si besoin, puis donne le résultat avec son unité.","enonce":"1. Énonce la loi d'Ohm et donne l'unité de chaque grandeur.\n2. Un résistor de **220 Ω** est traversé par un courant de **50 mA**. Calcule la tension à ses bornes.\n3. Un résistor de **150 Ω** est soumis à une tension de **4,5 V**. Calcule l'intensité qui le traverse, en ampères puis en milliampères.\n4. Pourquoi une lampe à filament n'est-elle pas un conducteur ohmique ?","bareme":[{"critere":"U = R × I ; U en V, R en Ω, I en A","points":5},{"critere":"U = 220 × 0,050 = 11 V (conversion des mA)","points":5},{"critere":"I = 4,5 / 150 = 0,030 A = 30 mA","points":5},{"critere":"Résistance de la lampe qui augmente avec la température : U et I non proportionnelles","points":5}],"dureeMin":7,"corrige":"1. **U = R × I** : U en **volts** (V), R en **ohms** (Ω), I en **ampères** (A). La tension et l'intensité sont proportionnelles.\n2. I = 50 mA = 0,050 A. U = 220 × 0,050 = **11 V**.\n3. I = U / R = 4,5 / 150 = **0,030 A**, soit **30 mA**.\n4. La résistance d'une lampe **augmente avec la température** de son filament : U n'est pas proportionnelle à I, sa caractéristique est une **courbe** et non une droite passant par l'origine."}$exo$::jsonb),
  ('bf193743-4add-5715-9623-983d7003215b'::uuid, 2, 'application', $exo${"titre":"Tracer une caractéristique","consigne":"Exploite les mesures, justifie tes conclusions et détaille les calculs.","enonce":"**Situation.** Sofia relève la tension U aux bornes de deux dipôles en fonction de l'intensité I.\n\n**Dipôle A**\n\n| I (A) | 0 | 0,010 | 0,020 | 0,030 | 0,040 |\n| U (V) | 0 | 1,0 | 2,0 | 3,0 | 4,0 |\n\n**Dipôle B**\n\n| I (A) | 0 | 0,050 | 0,10 | 0,15 |\n| U (V) | 0 | 0,5 | 2,0 | 5,0 |\n\n1. Décris l'allure de la caractéristique U = f(I) de chaque dipôle. Lequel est un conducteur ohmique ? Justifie.\n2. Détermine la résistance du dipôle ohmique.\n3. Calcule la puissance reçue par le dipôle A quand I = 0,040 A.\n4. Le dipôle B pourrait-il être une lampe ? Justifie.","bareme":[{"critere":"A : droite par l'origine, U proportionnelle à I, donc ohmique ; B : courbe, non ohmique","points":6},{"critere":"R = U / I = 100 Ω (coefficient directeur)","points":5},{"critere":"P = U × I = 4,0 × 0,040 = 0,16 W","points":5},{"critere":"B : rapport U / I qui augmente (résistance croissante) comme une lampe qui chauffe","points":4}],"dureeMin":11,"corrige":"1. Dipôle A : U / I vaut toujours 100 V·A⁻¹ ; U est **proportionnelle** à I, la caractéristique est une **droite passant par l'origine** : A est un **conducteur ohmique**. Dipôle B : U / I vaut 10, puis 20, puis 33 : pas de proportionnalité, la caractéristique est une **courbe** : B n'est **pas ohmique**.\n2. R est le coefficient directeur de la droite : R = U / I = 4,0 / 0,040 = **100 Ω**.\n3. P = U × I = 4,0 × 0,040 = **0,16 W** (ou P = R × I² = 100 × 0,040² = 0,16 W).\n4. Oui, c'est plausible : le rapport U / I, c'est-à-dire la **résistance**, **augmente** avec l'intensité. C'est le comportement d'une **lampe**, dont la résistance augmente quand son filament chauffe."}$exo$::jsonb),
  ('bf193743-4add-5715-9623-983d7003215b'::uuid, 3, 'application', $exo${"titre":"La bouilloire et les mains mouillées","consigne":"Mène les calculs avec les unités, puis rédige une explication argumentée pour la question de sécurité.","enonce":"**Situation.** Une bouilloire porte l'indication **230 V – 2 000 W**. Sa résistance chauffante se comporte comme un conducteur ohmique. Elle chauffe l'eau du thé pendant **3,0 min**.\n\n1. Calcule l'intensité du courant qui traverse la bouilloire.\n2. Déduis-en la valeur de sa résistance.\n3. Calcule l'énergie consommée, en joules puis en kilowattheures.\n4. Comment s'appelle l'effet utilisé par la bouilloire ? Est-il ici recherché ou subi ? Donne un exemple où il est subi.\n5. Dans un modèle très simplifié, on admet que la résistance du corps humain entre les deux mains vaut **5 000 Ω** peau sèche et **1 000 Ω** peau mouillée. Calcule l'intensité qui traverserait le corps sous 230 V dans chaque cas, et explique pourquoi on ne doit jamais toucher un appareil électrique les mains mouillées.","bareme":[{"critere":"I = P / U = 2 000 / 230 ≈ 8,7 A","points":4},{"critere":"R = U / I ≈ 26 Ω","points":3},{"critere":"E = P × Δt = 2 000 × 180 = 3,6 × 10⁵ J = 0,10 kWh","points":5},{"critere":"Effet Joule recherché ; exemple subi : composants électroniques à refroidir","points":3},{"critere":"I = 0,046 A puis 0,23 A : la résistance diminue avec l'humidité, l'intensité est cinq fois plus grande","points":5}],"dureeMin":18,"corrige":"1. P = U × I donc I = P / U = 2 000 / 230 ≈ **8,7 A**.\n2. U = R × I donc R = U / I = 230 / 8,7 ≈ **26 Ω**.\n3. Δt = 3,0 min = 180 s. E = P × Δt = 2 000 × 180 = **3,6 × 10⁵ J**. Avec 1 kWh = 3,6 × 10⁶ J : E = **0,10 kWh** (ou 2,0 kW × 0,050 h).\n4. C'est l'**effet Joule** : un conducteur parcouru par un courant s'échauffe. Ici il est **recherché**. Il est **subi** dans les **composants électroniques** (ordinateur, téléphone), qu'il faut refroidir.\n5. I = U / R :\n- peau sèche : 230 / 5 000 ≈ **0,046 A** ;\n- peau mouillée : 230 / 1 000 = **0,23 A**.\nÀ tension donnée, l'intensité qui traverse le corps dépend de sa **résistance**, très **diminuée par l'humidité** : ici l'intensité est **cinq fois plus grande** les mains mouillées. D'où l'interdiction absolue de manipuler un appareil électrique les mains mouillées."}$exo$::jsonb),
  ('5a1924c3-a54f-5202-b576-c0977f2c92bf'::uuid, 1, 'application', $exo${"titre":"Voir les objets","consigne":"Réponds par des phrases complètes en utilisant le vocabulaire du cours.","enonce":"1. Dans quel type de milieu la lumière se propage-t-elle en ligne droite ? Comment modélise-t-on son trajet ?\n2. Cite deux phénomènes expliqués par la propagation rectiligne de la lumière.\n3. Classe les objets suivants en **sources primaires** et **objets diffusants** : le Soleil, la Lune, une page de livre, l'écran d'un téléphone allumé, une flamme de bougie, un mur blanc.\n4. Pourquoi ne voit-on pas un mur dans une pièce totalement obscure ?","bareme":[{"critere":"Milieu transparent et homogène ; modèle du rayon lumineux","points":5},{"critere":"Deux phénomènes parmi ombres, chambre noire, éclipses, viseur","points":4},{"critere":"Classement correct des six objets","points":6},{"critere":"Un objet diffusant renvoie la lumière reçue : sans éclairage, il est invisible","points":5}],"dureeMin":6,"corrige":"1. La lumière se propage en ligne droite dans un milieu **transparent et homogène**. On modélise son trajet par des **rayons lumineux**.\n2. Par exemple : les **ombres** nettes (un objet opaque intercepte les rayons) et les **éclipses** (un astre entre dans l'ombre d'un autre) ; aussi la chambre noire, le viseur.\n3. **Sources primaires** : le Soleil, l'écran allumé, la flamme de bougie. **Objets diffusants** : la Lune, la page de livre, le mur blanc.\n4. Le mur est un **objet diffusant** : il ne produit pas de lumière, il **renvoie** celle qu'il reçoit. Sans éclairage, il n'a rien à renvoyer : il est **invisible**."}$exo$::jsonb),
  ('5a1924c3-a54f-5202-b576-c0977f2c92bf'::uuid, 2, 'application', $exo${"titre":"Voir loin, c'est voir tôt","consigne":"Détaille tes calculs en notation scientifique, avec les unités.","enonce":"> Données : c = 3,00 × 10⁸ m·s⁻¹ ; distance Terre-Soleil : 1,50 × 10¹¹ m ; une année vaut environ 3,16 × 10⁷ s.\n\n1. Calcule la durée que met la lumière du Soleil pour atteindre la Terre. Exprime-la en minutes et secondes.\n2. Qu'est-ce qu'une année-lumière ? Calcule sa valeur en mètres.\n3. L'étoile Proxima du Centaure est à **4,2 années-lumière**. Calcule cette distance en mètres.\n4. Explique la phrase : « voir loin, c'est voir tôt ».","bareme":[{"critere":"Δt = 1,50 × 10¹¹ / 3,00 × 10⁸ = 500 s = 8 min 20 s","points":5},{"critere":"Définition (distance parcourue par la lumière en un an) et 9,5 × 10¹⁵ m","points":6},{"critere":"4,2 × 9,5 × 10¹⁵ ≈ 4,0 × 10¹⁶ m","points":4},{"critere":"La lumière met du temps : on voit l'astre tel qu'il était au départ de la lumière","points":5}],"dureeMin":10,"corrige":"1. Δt = d / c = 1,50 × 10¹¹ / 3,00 × 10⁸ = **500 s**, soit **8 min 20 s**.\n2. Une **année-lumière** est la **distance parcourue par la lumière dans le vide en un an**. d = c × Δt = 3,00 × 10⁸ × 3,16 × 10⁷ ≈ **9,5 × 10¹⁵ m**.\n3. d = 4,2 × 9,5 × 10¹⁵ ≈ **4,0 × 10¹⁶ m**.\n4. La lumière met un certain temps à nous parvenir : nous voyons un astre **tel qu'il était quand la lumière l'a quitté**. Le Soleil observé est celui d'il y a environ huit minutes, Proxima du Centaure celle d'il y a 4,2 ans : plus un astre est loin, plus on voit son passé."}$exo$::jsonb),
  ('5a1924c3-a54f-5202-b576-c0977f2c92bf'::uuid, 3, 'application', $exo${"titre":"Lire les spectres d'une nébuleuse","consigne":"Exploite les documents, classe les spectres et rédige une conclusion argumentée.","enonce":"**Document 1.** Trois sources :\n- **S₁** : une lampe à filament très chaud ;\n- **S₂** : un pointeur laser qui émet une seule radiation, de longueur d'onde 650 nm ;\n- **S₃** : un gaz chaud sous basse pression, qui émet des raies.\n\n**Document 2.** Raies d'émission de deux éléments (en nm) :\n\n| Hydrogène | 410 | 434 | 486 | 656 |\n| Hélium | 447 | 502 | 588 | 668 |\n\n**Document 3.** La lumière d'une nébuleuse (nuage de gaz chaud et peu dense) présente des raies d'émission à 434 nm, 486 nm et 656 nm.\n\n1. Décris le spectre de chaque source S₁, S₂ et S₃. Laquelle émet une lumière monochromatique ?\n2. À quel domaine (UV, visible, IR) appartiennent les radiations de 350 nm, 650 nm et 950 nm ?\n3. Comment Newton a-t-il montré que la lumière blanche est composite ?\n4. Quel élément la nébuleuse contient-elle ? Contient-elle de l'hélium ? Argumente à partir des documents.\n5. Pourquoi cette méthode est-elle précieuse pour les astronomes ?","bareme":[{"critere":"S₁ spectre continu, S₂ une seule radiation (monochromatique), S₃ raies d'émission","points":4},{"critere":"350 nm UV, 650 nm visible (rouge), 950 nm IR","points":4},{"critere":"Dispersion par un prisme puis recombinaison du spectre en blanc","points":3},{"critere":"Raies de l'hydrogène présentes ; aucune raie de l'hélium : pas d'hélium détecté","points":6},{"critere":"Raies propres à chaque élément : identifier la composition sans y aller","points":3}],"dureeMin":16,"corrige":"1. **S₁** (solide chaud) : **spectre continu**, dont l'aspect dépend de la température. **S₂** (laser) : une **seule radiation**, c'est une lumière **monochromatique**. **S₃** (gaz chaud à basse pression) : un **spectre de raies d'émission**.\n2. 350 nm < 400 nm : **ultraviolet** ; 650 nm, entre 400 et 800 nm : **visible** (rouge) ; 950 nm > 800 nm : **infrarouge**.\n3. Il a **dispersé** la lumière blanche avec un prisme, obtenant un spectre continu, puis l'a **recombiné** pour retrouver du blanc : le blanc est une **superposition** de radiations.\n4. Les raies de la nébuleuse (434, 486 et 656 nm) coïncident avec des raies de l'**hydrogène** : elle contient de l'**hydrogène**. Aucune raie de l'hélium (447, 502, 588, 668 nm) n'apparaît : ces mesures ne permettent pas de détecter d'hélium.\n5. Chaque élément possède ses **raies propres** : on identifie la composition d'un astre **sans y aller**, seulement en analysant sa lumière."}$exo$::jsonb),
  ('c1b89b34-d967-591e-857b-13b0f4a1ebd3'::uuid, 1, 'application', $exo${"titre":"Le rayon sur le miroir","consigne":"Justifie chaque réponse en précisant par rapport à quoi les angles sont mesurés.","enonce":"**Situation.** Un rayon lumineux arrive sur un miroir plan. Victor mesure un angle de **50°** entre le rayon incident et la **surface** du miroir.\n\n1. Qu'est-ce que la normale ? Par rapport à quoi mesure-t-on les angles en optique ?\n2. Quel est l'angle d'incidence ?\n3. Énonce les lois de la réflexion et donne l'angle de réflexion.\n4. Quelle différence y a-t-il entre la réflexion sur un miroir et la réflexion sur une feuille de papier ?","bareme":[{"critere":"Normale : perpendiculaire à la surface au point d'incidence ; angles mesurés par rapport à elle","points":5},{"critere":"i = 90° − 50° = 40°","points":5},{"critere":"Angle de réflexion égal à l'angle d'incidence (40°), rayon réfléchi dans le plan d'incidence","points":5},{"critere":"Miroir poli : réflexion spéculaire ; papier rugueux : réflexion diffuse","points":5}],"dureeMin":7,"corrige":"1. La **normale** est la **perpendiculaire à la surface** au point d'incidence. Tous les angles se mesurent **par rapport à la normale**, jamais par rapport à la surface.\n2. La normale fait 90° avec la surface : i = 90° − 50° = **40°**.\n3. L'angle de réflexion est **égal** à l'angle d'incidence : **r = 40°** ; le rayon réfléchi appartient au **plan d'incidence**.\n4. Le miroir est une surface **polie** : la réflexion est **spéculaire**, dans une seule direction. Le papier est **rugueux** : la réflexion est **diffuse**, dans toutes les directions, ce qui le rend visible de partout."}$exo$::jsonb),
  ('c1b89b34-d967-591e-857b-13b0f4a1ebd3'::uuid, 2, 'application', $exo${"titre":"Le rayon qui plonge dans l'eau","consigne":"Écris la loi utilisée, détaille le calcul et conclus par une phrase.","enonce":"**Situation.** Un rayon laser passe de l'air dans l'eau d'un aquarium. L'angle d'incidence vaut **i₁ = 45°**.\n\n> Données : n(air) = 1,00 ; n(eau) = 1,33 ; sin 45° ≈ 0,707.\n\n1. Écris la loi de Snell-Descartes pour la réfraction.\n2. Calcule le sinus de l'angle de réfraction i₂, puis i₂ (à la calculatrice).\n3. Le rayon s'est-il rapproché ou écarté de la normale ? Était-ce prévisible ? Justifie.\n4. Explique pourquoi un bâton plongé dans l'eau semble brisé.","bareme":[{"critere":"n₁ × sin i₁ = n₂ × sin i₂","points":4},{"critere":"sin i₂ = 0,707 / 1,33 ≈ 0,532 et i₂ ≈ 32°","points":7},{"critere":"Rapproché de la normale, car l'eau est plus réfringente que l'air","points":5},{"critere":"Bâton brisé : la lumière qui sort de l'eau est déviée par réfraction","points":4}],"dureeMin":10,"corrige":"1. **n₁ × sin i₁ = n₂ × sin i₂**, les angles étant mesurés par rapport à la normale.\n2. sin i₂ = n₁ × sin i₁ / n₂ = 1,00 × 0,707 / 1,33 ≈ **0,532**, d'où **i₂ ≈ 32°**.\n3. i₂ (32°) < i₁ (45°) : le rayon s'est **rapproché de la normale**. C'était prévisible : en passant dans un milieu **plus réfringent** (n plus grand), le rayon se rapproche de la normale.\n4. La lumière qui vient de la partie immergée **change de direction** en sortant de l'eau (réfraction) : l'œil la reçoit comme si elle venait d'un autre endroit, et la partie immergée paraît décalée : le bâton semble brisé."}$exo$::jsonb),
  ('c1b89b34-d967-591e-857b-13b0f4a1ebd3'::uuid, 3, 'application', $exo${"titre":"Sortir de l'eau, ou rester prisonnier","consigne":"Mène les calculs avec la loi de Snell-Descartes et justifie chaque conclusion.","enonce":"**Situation.** Au fond d'une piscine, un projecteur envoie des rayons vers la surface de l'eau, qui débouchent dans l'air.\n\n> Données : n(eau) = 1,33 ; n(air) = 1,00.\n\n1. Un rayon arrive sur la surface avec un angle d'incidence de **30°**. Calcule l'angle de réfraction dans l'air. Le rayon se rapproche-t-il ou s'écarte-t-il de la normale ?\n2. On augmente l'angle d'incidence. L'angle limite est l'angle d'incidence pour lequel le rayon réfracté fait **90°** avec la normale. Calcule cet angle limite.\n3. Que se passe-t-il pour un rayon qui arrive sous **60°** ? Nomme le phénomène.\n4. Explique comment ce phénomène permet à une fibre optique de guider la lumière.\n5. Si le projecteur émettait de la lumière blanche à travers un prisme de verre, quelle radiation serait la plus déviée ? Pourquoi ?","bareme":[{"critere":"sin i₂ = 1,33 × 0,5 = 0,665, i₂ ≈ 42° ; le rayon s'écarte de la normale","points":5},{"critere":"sin i(lim) = 1,00 / 1,33 ≈ 0,752, i(lim) ≈ 49°","points":5},{"critere":"60° > angle limite : réflexion totale, aucun rayon réfracté","points":4},{"critere":"Fibre : réflexions totales successives qui guident la lumière","points":3},{"critere":"Violet le plus dévié : l'indice dépend de la longueur d'onde (dispersion)","points":3}],"dureeMin":18,"corrige":"1. n(eau) × sin 30° = n(air) × sin i₂ : sin i₂ = 1,33 × 0,500 = **0,665**, d'où **i₂ ≈ 42°**. Le rayon passe dans un milieu **moins réfringent** : il **s'écarte** de la normale (42° > 30°).\n2. Pour i₂ = 90° : 1,33 × sin i(lim) = 1,00 × sin 90° = 1,00, donc sin i(lim) = 1,00 / 1,33 ≈ 0,752 et **i(lim) ≈ 49°**.\n3. 60° dépasse l'angle limite : il n'y a **plus de rayon réfracté**, toute la lumière est **réfléchie** dans l'eau. C'est la **réflexion totale**.\n4. Dans une fibre optique, la lumière se propage dans un cœur plus réfringent que ce qui l'entoure et frappe la paroi au-delà de l'angle limite : elle subit des **réflexions totales successives** et reste guidée sur des kilomètres.\n5. L'indice de réfraction **dépend de la longueur d'onde** : le **violet** est plus dévié que le rouge. C'est la **dispersion**, qui sépare les radiations de la lumière blanche (comme dans l'arc-en-ciel)."}$exo$::jsonb),
  ('2599252f-5986-55e6-8f92-f5761239c652'::uuid, 1, 'application', $exo${"titre":"Vergence et distance focale","consigne":"Détaille tes calculs en convertissant les longueurs en mètres.","enonce":"1. Comment reconnaît-on une lentille convergente au toucher ?\n2. Écris la relation entre la vergence C et la distance focale f′, avec leurs unités.\n3. Calcule la vergence d'une lentille de distance focale **25 cm**.\n4. Des lunettes de lecture portent l'indication **+2**. Que signifie ce nombre ? Calcule la distance focale correspondante.\n5. Que devient un rayon qui passe par le centre optique ? Un rayon qui arrive parallèlement à l'axe optique ?","bareme":[{"critere":"Plus épaisse au centre qu'aux bords","points":3},{"critere":"C = 1 / f′, C en dioptries, f′ en mètres","points":4},{"critere":"C = 1 / 0,25 = 4 δ","points":4},{"critere":"+2 est une vergence de 2 δ ; f′ = 0,50 m","points":5},{"critere":"Non dévié par O ; parallèle à l'axe : repart par F′","points":4}],"dureeMin":8,"corrige":"1. Une lentille convergente est **plus épaisse au centre qu'aux bords**.\n2. **C = 1 / f′**, avec C en **dioptries** (δ) et f′ en **mètres**.\n3. f′ = 25 cm = 0,25 m. C = 1 / 0,25 = **4 δ**.\n4. « +2 » est une **vergence** : C = +2 δ (lentille convergente). f′ = 1 / C = 1 / 2 = **0,50 m**.\n5. Un rayon passant par le **centre optique O** n'est **pas dévié**. Un rayon arrivant **parallèlement à l'axe** repart en passant par le **foyer image F′**."}$exo$::jsonb),
  ('2599252f-5986-55e6-8f92-f5761239c652'::uuid, 2, 'application', $exo${"titre":"La lentille qui brûle le papier","consigne":"Exploite l'expérience et réponds en justifiant chaque étape par le cours.","enonce":"**Situation.** Lors d'une sortie, Noé tient une lentille face au Soleil. Les rayons du Soleil arrivent parallèlement à l'axe optique. En éloignant une feuille, il obtient un petit point très lumineux quand la feuille est à **12,5 cm** de la lentille.\n\n1. Comment appelle-t-on le point lumineux obtenu ? Justifie.\n2. Déduis-en la distance focale, puis la vergence de la lentille.\n3. Où se trouve le foyer objet F de cette lentille ?\n4. Une deuxième lentille, plus bombée, a une vergence de 20 δ. Laquelle des deux est la plus convergente ? À quelle distance de cette deuxième lentille faudrait-il placer la feuille ?","bareme":[{"critere":"Foyer image F′ : point de convergence des rayons parallèles à l'axe","points":5},{"critere":"f′ = 0,125 m ; C = 1 / 0,125 = 8 δ","points":6},{"critere":"F symétrique de F′ par rapport à O, à 12,5 cm de l'autre côté","points":4},{"critere":"La lentille de 20 δ est la plus convergente ; f′ = 0,050 m = 5,0 cm","points":5}],"dureeMin":10,"corrige":"1. Les rayons du Soleil arrivent **parallèlement à l'axe** : ils convergent au **foyer image F′**.\n2. f′ = OF′ = 12,5 cm = **0,125 m**. C = 1 / f′ = 1 / 0,125 = **8 δ**.\n3. Le foyer objet F est le **symétrique de F′ par rapport au centre optique O** : à **12,5 cm** de la lentille, **de l'autre côté**.\n4. La vergence la plus grande correspond à la lentille la **plus convergente** : celle de **20 δ** (plus bombée). Sa distance focale : f′ = 1 / 20 = **0,050 m = 5,0 cm** ; c'est là qu'il faudrait placer la feuille."}$exo$::jsonb),
  ('2599252f-5986-55e6-8f92-f5761239c652'::uuid, 3, 'application', $exo${"titre":"L'œil de Margot","consigne":"Utilise le modèle de l'œil réduit et argumente chaque réponse à l'aide du cours.","enonce":"**Situation.** On modélise l'œil de Margot par une lentille convergente (le cristallin), un diaphragme et un écran. Quand Margot regarde un objet très lointain, les rayons arrivent parallèlement à l'axe, et son cristallin a une distance focale de **17 mm**.\n\n1. Associe chaque élément de l'œil (cristallin, iris et pupille, rétine) à son équivalent dans le modèle.\n2. Calcule la vergence du cristallin quand Margot regarde au loin.\n3. Pour que l'image d'un objet lointain soit nette, où doit se trouver la rétine ? Justifie avec un rayon particulier.\n4. Margot lit maintenant un livre proche. Comment son œil garde-t-il une image nette ? Comment s'appelle ce phénomène ?\n5. Le frère de Margot est myope : chez lui, l'image d'un objet lointain se forme en avant de la rétine. Quel type de lentille corrige ce défaut ? Quel signe a sa vergence ? Et pour leur grand-père, dont le cristallin a perdu sa souplesse, comment s'appelle le défaut ?","bareme":[{"critere":"Cristallin = lentille convergente ; iris et pupille = diaphragme ; rétine = écran","points":3},{"critere":"C = 1 / 0,017 ≈ 59 δ","points":4},{"critere":"Rétine au foyer image F′, à 17 mm : rayons parallèles à l'axe repartent par F′","points":4},{"critere":"Accommodation : déformation du cristallin qui garde l'image nette","points":4},{"critere":"Myopie corrigée par une lentille divergente (vergence négative) ; presbytie","points":5}],"dureeMin":16,"corrige":"1. **Cristallin** → lentille convergente ; **iris et pupille** → diaphragme ; **rétine** → écran.\n2. f′ = 17 mm = 0,017 m. C = 1 / 0,017 ≈ **59 δ**.\n3. Les rayons venant d'un objet lointain arrivent **parallèlement à l'axe** : ils repartent en passant par le **foyer image F′**. L'image se forme donc en F′ : pour qu'elle soit nette, la **rétine** doit se trouver **au foyer image**, à 17 mm du cristallin.\n4. Quand l'objet se rapproche, le **cristallin se déforme** (il devient plus bombé, donc plus convergent) pour garder l'image nette sur la rétine : c'est l'**accommodation**.\n5. La **myopie** (image en avant de la rétine) se corrige par une lentille **divergente**, de vergence **négative**. Le défaut du grand-père, dû à la perte de souplesse du cristallin avec l'âge, est la **presbytie**, corrigée pour la vision de près."}$exo$::jsonb),
  ('997b009c-d4b0-5c4e-a327-61445a21fadd'::uuid, 1, 'application', $exo${"titre":"Construire une image","consigne":"Décris les étapes de la construction avec précision, puis caractérise l'image.","enonce":"**Situation.** Un objet AB est placé perpendiculairement à l'axe optique d'une lentille convergente, avec A sur l'axe, **au-delà du foyer objet F**.\n\n1. Décris, étape par étape, la construction de l'image A′B′ à l'aide de deux rayons particuliers issus de B.\n2. L'image obtenue est-elle réelle ou virtuelle ? Droite ou renversée ? Peut-on l'observer sur un écran ?\n3. Si l'on place maintenant l'objet entre F et la lentille, quelle image obtient-on ? Quel instrument fonctionne ainsi ?","bareme":[{"critere":"Rayon par O non dévié, rayon parallèle à l'axe qui repart par F′, B′ à l'intersection, A′ sur l'axe","points":9},{"critere":"Image réelle, renversée, observable sur un écran","points":6},{"critere":"Objet entre F et O : image virtuelle, droite, agrandie ; la loupe","points":5}],"dureeMin":8,"corrige":"1. Construction :\n- depuis B, tracer le rayon qui passe par le **centre optique O** : il n'est **pas dévié** ;\n- depuis B, tracer le rayon **parallèle à l'axe** : il repart en passant par **F′** ;\n- leur **intersection** donne **B′** ;\n- **A′** est sur l'axe, à la verticale de B′.\n2. Objet au-delà de F : l'image est **réelle** et **renversée** ; elle se forme de l'autre côté de la lentille et peut être **projetée sur un écran**.\n3. Objet entre F et la lentille : l'image est **virtuelle**, **droite** et **agrandie** ; on la regarde à travers la lentille. C'est le fonctionnement de la **loupe**."}$exo$::jsonb),
  ('997b009c-d4b0-5c4e-a327-61445a21fadd'::uuid, 2, 'application', $exo${"titre":"Calculer la position de l'image","consigne":"Utilise les relations de conjugaison avec les mesures algébriques, en détaillant les calculs.","enonce":"**Situation.** Une lentille convergente a une distance focale **OF′ = +5,0 cm**. Un objet AB de hauteur **2,0 cm** est placé à **15 cm** avant la lentille : **OA = −15 cm**.\n\n1. Écris la relation de conjugaison et calcule OA′.\n2. Écris la relation du grandissement et calcule γ.\n3. Calcule la hauteur algébrique A′B′ de l'image.\n4. Décris l'image : réelle ou virtuelle, droite ou renversée, agrandie ou réduite. Justifie avec les signes et les valeurs obtenus.","bareme":[{"critere":"1/OA′ − 1/OA = 1/OF′ ; OA′ = +7,5 cm","points":7},{"critere":"γ = OA′ / OA = −0,50","points":5},{"critere":"A′B′ = γ × AB = −1,0 cm","points":3},{"critere":"Réelle (OA′ > 0), renversée (γ < 0), réduite (|γ| < 1)","points":5}],"dureeMin":11,"corrige":"1. **1/OA′ − 1/OA = 1/OF′**, donc 1/OA′ = 1/OF′ + 1/OA = 1/5,0 + 1/(−15) = 3/15 − 1/15 = 2/15. D'où **OA′ = +7,5 cm**.\n2. **γ = A′B′/AB = OA′/OA** = 7,5 / (−15) = **−0,50**.\n3. A′B′ = γ × AB = −0,50 × 2,0 = **−1,0 cm**.\n4. OA′ > 0 : l'image est de l'autre côté de la lentille, elle est **réelle**. γ < 0 : elle est **renversée**. |γ| = 0,50 < 1 : elle est **réduite**, deux fois plus petite que l'objet."}$exo$::jsonb),
  ('997b009c-d4b0-5c4e-a327-61445a21fadd'::uuid, 3, 'application', $exo${"titre":"Vidéoprojecteur et loupe","consigne":"Applique les relations de conjugaison dans les deux situations, puis argumente sur la nature des images.","enonce":"**Situation 1.** Dans un vidéoprojecteur simplifié, une lentille convergente de distance focale **OF′ = +10 cm** forme sur un écran, placé à **3,0 m** de la lentille, l'image d'une petite plaque lumineuse de hauteur **2,4 cm**.\n\n**Situation 2.** Adèle observe un timbre à travers une loupe de distance focale **OF′ = +5,0 cm**, le timbre étant placé à **3,0 cm** de la lentille : **OA = −3,0 cm**.\n\n1. Situation 1 : quelle est la valeur de OA′ ? Calcule OA (arrondi au millimètre) : à quelle distance de la lentille faut-il placer la plaque ?\n2. Calcule le grandissement et la hauteur de l'image sur l'écran.\n3. Dans quel sens faut-il placer la plaque pour que l'image apparaisse à l'endroit ? Justifie.\n4. Situation 2 : calcule OA′ et γ. Caractérise l'image obtenue.\n5. Explique pourquoi l'image du vidéoprojecteur se « projette » alors que celle de la loupe se « regarde ».","bareme":[{"critere":"OA′ = +300 cm ; 1/OA = 1/300 − 1/10 d'où OA ≈ −10,3 cm","points":5},{"critere":"γ ≈ −29 ; image d'environ 70 cm","points":4},{"critere":"γ < 0 : image renversée, donc plaque placée à l'envers","points":3},{"critere":"OA′ = −7,5 cm ; γ = +2,5 : image virtuelle, droite, agrandie","points":5},{"critere":"Image réelle projetable sur un écran ; image virtuelle visible seulement à travers la lentille","points":3}],"dureeMin":20,"corrige":"1. L'écran est de l'autre côté de la lentille : **OA′ = +300 cm**. Relation de conjugaison : 1/OA = 1/OA′ − 1/OF′ = 1/300 − 1/10 = (1 − 30)/300 = −29/300, donc **OA ≈ −10,3 cm** : la plaque est à environ **10,3 cm** avant la lentille, juste au-delà du foyer objet F.\n2. γ = OA′/OA = 300 / (−10,34) ≈ **−29**. A′B′ = γ × AB ≈ −29 × 2,4 ≈ **−70 cm** : l'image mesure environ **70 cm**.\n3. γ < 0 : l'image est **renversée**. Pour qu'elle apparaisse à l'endroit sur l'écran, il faut placer la plaque **à l'envers**.\n4. 1/OA′ = 1/OF′ + 1/OA = 1/5,0 + 1/(−3,0) = 3/15 − 5/15 = −2/15, donc **OA′ = −7,5 cm**. γ = OA′/OA = (−7,5) / (−3,0) = **+2,5**. OA′ < 0 : l'image est du même côté que l'objet, **virtuelle** ; γ > 0 : **droite** ; |γ| > 1 : **agrandie** 2,5 fois. C'est le fonctionnement de la loupe (objet entre F et la lentille).\n5. L'image du vidéoprojecteur est **réelle** : les rayons se croisent vraiment en A′B′, on peut la **projeter** sur un écran. L'image de la loupe est **virtuelle** : les rayons ne s'y croisent pas, on ne peut que la **regarder** à travers la lentille."}$exo$::jsonb),
  ('94c8df39-d7f9-5d49-a14f-2309759f8404'::uuid, 1, 'redaction', $exo${"titre":"Rareté, choix et coût d'opportunité","consigne":"Réponds à chaque question par des phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Définis la **rareté** en économie et explique pourquoi on dit que toute l'économie découle de ce constat.\n2. Définis le **coût d'opportunité**.\n3. Mathis hésite entre passer son mercredi après-midi à réviser son contrôle ou à travailler comme serveur. Quel est le coût d'opportunité de chacun des deux choix ?\n4. Cite les **trois grandes questions** auxquelles toute économie doit répondre.","bareme":[{"critere":"Définition juste de la rareté (ressources limitées, besoins illimités) et lien avec la nécessité de choisir","points":7},{"critere":"Définition du coût d'opportunité appliquée correctement aux deux choix de Mathis","points":8},{"critere":"Les trois questions : que produire, comment produire, pour qui produire","points":5}],"dureeMin":6,"corrige":"1. La **rareté** est le fait que les **ressources** disponibles (temps, argent, matières, travail) sont **limitées** alors que les **besoins** sont **illimités**. Comme on ne peut pas tout avoir, il faut **choisir** : c'est pourquoi toute l'économie, science des choix, découle de la rareté.\n2. Le **coût d'opportunité** est ce à quoi on **renonce** en faisant un choix (la meilleure option abandonnée).\n3. S'il révise, le coût d'opportunité de Mathis est le **salaire** qu'il aurait gagné comme serveur. S'il travaille, son coût d'opportunité est le **temps de révision** perdu (et la meilleure note qu'il aurait pu obtenir). Choisir, c'est renoncer.\n4. **Que** produire ? **Comment** produire ? **Pour qui** produire ? Le marché, l'État ou les deux y répondent."}$exo$::jsonb),
  ('94c8df39-d7f9-5d49-a14f-2309759f8404'::uuid, 2, 'redaction', $exo${"titre":"Le circuit d'une petite ville","consigne":"Lis la situation, puis réponds aux questions en t'appuyant sur les notions du cours.","enonce":"**Situation.**\n\n> Awa travaille comme préparatrice dans une entreprise de meubles de sa ville. Elle reçoit un salaire chaque mois. Avec ce salaire, elle achète des produits dans une supérette. Elle paie aussi des impôts, qui financent l'école de son fils. Pour acheter une voiture, elle a emprunté auprès de sa banque.\n\n1. Identifie dans le texte les **agents économiques** qui apparaissent et donne le rôle de chacun selon le cours.\n2. Pour la relation entre Awa et l'entreprise de meubles, décris le **flux réel** et le **flux monétaire**. Dans quel sens circule chacun ?\n3. Explique la phrase : « la dépense de l'un est le revenu de l'autre », à partir d'un exemple tiré de la situation.","bareme":[{"critere":"Agents identifiés (ménage, entreprises, administrations publiques, banque) avec leur rôle exact","points":7},{"critere":"Flux réel (travail d'Awa) et flux monétaire (salaire) décrits, sens inverse précisé","points":7},{"critere":"Exemple pertinent montrant qu'une dépense est un revenu pour un autre agent, idée de système","points":6}],"dureeMin":10,"corrige":"1. **Awa** et sa famille forment un **ménage** : ils consomment et fournissent du travail. L'**entreprise de meubles** et la **supérette** sont des **entreprises** : elles produisent. L'**école**, financée par l'impôt, relève des **administrations publiques**, qui produisent des services non marchands et redistribuent. La **banque** finance (le prêt pour la voiture).\n2. Le **flux réel** : Awa fournit son **travail** à l'entreprise (du ménage vers l'entreprise). Le **flux monétaire** : l'entreprise lui verse un **salaire** (de l'entreprise vers le ménage). Les flux monétaires circulent **en sens inverse** des flux réels : c'est le **circuit économique**.\n3. Quand Awa **dépense** son salaire à la supérette, cette dépense devient le **chiffre d'affaires**, donc le revenu, de la supérette, qui pourra à son tour payer ses salariés. De même, le salaire d'Awa est une dépense pour l'entreprise de meubles. L'économie n'est donc pas une addition de décisions isolées : c'est un **système** où les agents sont reliés entre eux."}$exo$::jsonb),
  ('94c8df39-d7f9-5d49-a14f-2309759f8404'::uuid, 3, 'redaction', $exo${"titre":"Comment raisonne l'économiste","consigne":"Analyse le document puis réponds de façon argumentée. La dernière question attend un paragraphe structuré.","enonce":"**Document.**\n\n> Pour étudier la consommation des ménages, un économiste construit un modèle très simple : il suppose que chaque ménage dépense toujours la même part de son revenu, et que les prix ne changent pas. Il compare ensuite les prévisions de son modèle aux statistiques de consommation de plusieurs pays européens, sur vingt ans.\n\n1. Qu'est-ce qu'un **modèle** en économie ? Relève dans le document les **hypothèses** de ce modèle.\n2. Pourquoi l'économiste compare-t-il plusieurs pays et plusieurs périodes plutôt que de réaliser une **expérience en laboratoire** ?\n3. Un modèle est une représentation simplifiée : est-ce un défaut ? Justifie.\n4. En un paragraphe argumenté, explique pourquoi toutes les économies réelles sont **mixtes**, en t'appuyant sur les trois grandes questions de l'économie et sur la notion de rareté.","bareme":[{"critere":"Définition du modèle et relevé des deux hypothèses du document","points":5},{"critere":"Impossibilité d'expérimenter sur des sociétés entières, rôle de la comparaison et de la confrontation aux données","points":4},{"critere":"Discussion de la simplification : utile pour comprendre, à confronter aux données","points":4},{"critere":"Paragraphe structuré : rareté, trois questions, réponses du marché et de l'État, économie mixte","points":7}],"dureeMin":16,"corrige":"1. Un **modèle** est une **représentation simplifiée de la réalité**, fondée sur des hypothèses. Hypothèses du document : chaque ménage dépense **toujours la même part** de son revenu ; les **prix ne changent pas**.\n2. L'économiste étudie des **sociétés entières** : on ne peut pas les mettre en laboratoire ni les faire vivre deux fois dans des conditions différentes. Il **compare** donc des pays et des périodes, et **confronte** son modèle aux **données** (statistiques) pour voir s'il explique bien la réalité.\n3. Ce n'est pas un défaut en soi : simplifier permet d'isoler un mécanisme et de le comprendre. Mais un modèle n'est pas une vérité : ses hypothèses peuvent être fausses (les prix changent en réalité), d'où la nécessité de le confronter aux données.\n4. Paragraphe attendu : les ressources étant **rares** face à des besoins illimités, toute société doit répondre à trois questions : **que** produire, **comment** produire, **pour qui** produire. Le **marché** peut y répondre par les prix (les entreprises produisent ce qui se vend), l'**État** peut y répondre par la décision publique (écoles, santé financées par l'impôt, redistribution). Dans la réalité, aucune économie ne s'en remet à un seul des deux : elles **combinent** marché et intervention publique. Elles sont donc toutes **mixtes**, seule la place respective du marché et de l'État varie."}$exo$::jsonb),
  ('4a6b214e-c645-5983-bf6d-9100ad3f1121'::uuid, 1, 'redaction', $exo${"titre":"Le fait social selon Durkheim","consigne":"Réponds à chaque question en une à trois phrases complètes.","enonce":"1. Donne la définition d'un **fait social** selon Émile Durkheim.\n2. Pourquoi le suicide, acte en apparence très intime, est-il un fait social ?\n3. Présente les deux grands types de **méthodes** du sociologue : leurs outils et ce qu'elles permettent.\n4. Que signifie **rompre avec les prénotions** ?","bareme":[{"critere":"Définition du fait social (extérieur à l'individu, pouvoir de contrainte) et exemple du suicide expliqué","points":8},{"critere":"Méthodes quantitative et qualitative avec outils et objectifs (mesurer / comprendre)","points":8},{"critere":"Sens de la rupture avec les prénotions","points":4}],"dureeMin":7,"corrige":"1. Un **fait social** est une manière d'agir, de penser et de sentir **extérieure** à l'individu et dotée d'un **pouvoir de contrainte**.\n2. Le taux de suicide **varie régulièrement** selon la religion, le statut familial ou la période : ce qui semble un choix personnel dépend donc de la société, de l'**intégration** des individus. C'est bien un fait social.\n3. La méthode **quantitative** utilise questionnaires, statistiques publiques, enquêtes de l'Insee : elle permet de **mesurer** et de comparer. La méthode **qualitative** utilise entretiens et observation (parfois participante) : elle permet de **comprendre** les logiques d'action.\n4. C'est se défaire des **idées reçues** avant d'analyser : refuser d'expliquer un fait social par « les gens sont comme ça »."}$exo$::jsonb),
  ('4a6b214e-c645-5983-bf6d-9100ad3f1121'::uuid, 2, 'redaction', $exo${"titre":"Enquêter sur le choix des spécialités","consigne":"Lis la situation et réponds en justifiant chaque choix à l'aide du cours.","enonce":"**Situation.**\n\n> Lina, élève de seconde, veut savoir pourquoi les élèves de son lycée choisissent telle ou telle spécialité pour la première. Sa première idée : « Ceux qui prennent maths, c'est qu'ils aiment les maths, c'est tout. »\n\n1. En quoi la première idée de Lina est-elle une **prénotion** ? Que doit faire le sociologue face à elle ?\n2. Lina hésite entre distribuer un questionnaire à 300 élèves et mener des entretiens avec 10 élèves. Explique ce que chaque méthode lui apporterait.\n3. Propose une question qu'elle pourrait poser dans son questionnaire et une question qu'elle pourrait poser en entretien.","bareme":[{"critere":"Idée identifiée comme prénotion, nécessité de s'en défaire et de chercher des causes sociales","points":6},{"critere":"Questionnaire : mesurer, comparer ; entretiens : comprendre les logiques d'action","points":8},{"critere":"Deux questions pertinentes, l'une fermée et chiffrable, l'autre ouverte","points":6}],"dureeMin":10,"corrige":"1. C'est une **prénotion** : une explication spontanée, une idée reçue qui ramène le choix au seul goût individuel (« les gens sont comme ça »). Le sociologue doit **rompre** avec elle : il cherche si le choix dépend de la **position sociale** (métier des parents, genre, conseils reçus), car nos choix apparemment libres sont largement influencés par la société.\n2. Le **questionnaire** (méthode **quantitative**) permet de **mesurer** : par exemple la part d'élèves choisissant maths selon le métier des parents, et de **comparer** des groupes. Les **entretiens** (méthode **qualitative**) permettent de **comprendre** les logiques d'action : comment l'élève a décidé, qui l'a conseillé, ce qu'il juge possible pour lui.\n3. Exemples. Questionnaire : « Quelle est la profession de tes parents ? » ou « Quelle spécialité as-tu choisie ? (cocher) ». Entretien : « Raconte-moi comment tu as choisi tes spécialités, avec qui tu en as parlé. »"}$exo$::jsonb),
  ('4a6b214e-c645-5983-bf6d-9100ad3f1121'::uuid, 3, 'redaction', $exo${"titre":"Mêmes notes, orientations différentes","consigne":"Analyse le document, puis rédige les réponses. La dernière question attend un paragraphe argumenté.","enonce":"**Document (données fictives d'une enquête de lycée).** Part des élèves ayant entre 12 et 14 de moyenne qui demandent une classe préparatoire, selon la profession des parents.\n\n| Profession des parents | Part demandant une prépa |\n| Cadres | 45 % |\n| Professions intermédiaires | 28 % |\n| Ouvriers | 12 % |\n\n1. Fais une phrase donnant la signification du chiffre 12 %.\n2. Pourquoi l'enquête compare-t-elle des élèves aux **résultats identiques** ?\n3. Un camarade conclut : « Être enfant d'ouvrier cause directement un moindre désir de prépa. » Discute cette conclusion à l'aide de la distinction **corrélation / causalité**.\n4. En un paragraphe argumenté, propose les **mécanismes** qui peuvent expliquer ces écarts, et montre comment Durkheim, Weber et Bourdieu éclaireraient chacun ce fait.","bareme":[{"critere":"Lecture exacte du chiffre (élèves de 12 à 14, enfants d'ouvriers, 12 % demandent une prépa)","points":3},{"critere":"Rôle de la comparaison à résultats égaux : neutraliser l'effet du niveau scolaire","points":4},{"critere":"Distinction corrélation / causalité, nécessité d'identifier un mécanisme","points":5},{"critere":"Mécanismes du cours (information, coût perçu, autocensure, conseils) et regards de Durkheim, Weber, Bourdieu","points":8}],"dureeMin":18,"corrige":"1. Selon cette enquête, parmi les élèves ayant entre 12 et 14 de moyenne, **12 %** des enfants d'**ouvriers** demandent une classe préparatoire.\n2. Comparer des élèves aux **notes identiques** permet de neutraliser l'effet du niveau scolaire : si les demandes diffèrent quand même, c'est que d'autres facteurs, **sociaux**, interviennent.\n3. Le tableau montre une **corrélation** (un lien statistique) entre profession des parents et demande de prépa. Mais **corrélation n'est pas causalité** : l'origine sociale n'agit pas « directement » ; il faut identifier les **mécanismes** qui relient les deux variables.\n4. Mécanismes attendus : l'**information disponible** (les familles de cadres connaissent mieux les filières), le **coût perçu** des études (plus longues, plus chères), l'**autocensure** (« ce n'est pas pour moi »), les **conseils reçus** (famille, entourage, enseignants). Durkheim y verrait un **fait social** : une régularité extérieure aux individus et contraignante. Weber chercherait le **sens** que chaque élève donne à son choix (entretiens). **Bourdieu** insisterait sur les **héritages culturels** qui **reproduisent** les positions sociales. On peut aussi opposer le **holisme** (expliquer par le tout, la structure sociale) à l'**individualisme méthodologique** (le résultat global comme agrégation de choix individuels raisonnés)."}$exo$::jsonb),
  ('4cf3155e-62df-5540-8a69-c46561bc49ae'::uuid, 1, 'redaction', $exo${"titre":"Pouvoir et État","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Définis le **pouvoir** en science politique.\n2. Donne la définition de l'**État** selon Max Weber.\n3. Cite les **quatre éléments constitutifs** de l'État et ce que chacun apporte.\n4. Cite deux **objets** d'étude du politiste.","bareme":[{"critere":"Définition du pouvoir (obtenir d'autrui un comportement qu'il n'aurait pas eu spontanément)","points":5},{"critere":"Définition wébérienne : monopole de la violence physique légitime sur un territoire","points":6},{"critere":"Territoire, population, administration, souveraineté avec leur apport","points":6},{"critere":"Deux objets du politiste corrects","points":3}],"dureeMin":6,"corrige":"1. Le **pouvoir** est la capacité d'obtenir d'autrui un **comportement qu'il n'aurait pas eu spontanément**.\n2. Pour Weber, l'État est la communauté humaine qui revendique avec succès le **monopole de la violence physique légitime** sur un **territoire** donné.\n3. Un **territoire** (une aire d'exercice), une **population** (des sujets ou des citoyens), une **administration** (la continuité de l'action), la **souveraineté** (aucune autorité supérieure).\n4. Deux parmi : les institutions et la Constitution ; les partis et les élections (sociologie électorale) ; l'opinion publique et les sondages ; les mobilisations ; les politiques publiques."}$exo$::jsonb),
  ('4cf3155e-62df-5540-8a69-c46561bc49ae'::uuid, 2, 'redaction', $exo${"titre":"Trois façons d'obéir","consigne":"Lis les trois situations, puis réponds en utilisant la typologie de Max Weber.","enonce":"**Situations (inventées).**\n\n- **A.** Dans un royaume ancien, les habitants obéissent au jeune roi parce que son père et son grand-père régnaient avant lui.\n- **B.** Lors d'une révolte, des milliers de personnes suivent une oratrice dont on dit qu'elle a « un don » pour entraîner les foules.\n- **C.** Une inspectrice des impôts, recrutée sur concours, applique un texte de loi ; le contribuable s'y soumet.\n\n1. Rappelle ce qu'est une **domination légitime** et nomme les trois types distingués par Weber.\n2. Associe chaque situation à un type de domination en justifiant.\n3. Quel type domine dans les États modernes ? Explique pourquoi la situation C en est typique.","bareme":[{"critere":"Les trois types nommés (traditionnelle, charismatique, légale-rationnelle) et idée d'un pouvoir accepté","points":5},{"critere":"A traditionnelle, B charismatique, C légale-rationnelle, chacune justifiée par son fondement","points":10},{"critere":"Domination légale-rationnelle dominante dans l'État moderne, fondée sur la règle écrite et la compétence","points":5}],"dureeMin":10,"corrige":"1. Une **domination légitime** est un pouvoir auquel on obéit parce qu'on le juge fondé, acceptable. Weber distingue la domination **traditionnelle**, **charismatique** et **légale-rationnelle**.\n2. **A** : domination **traditionnelle**, fondée sur la **coutume** et l'**hérédité** (on obéit au chef parce qu'il est né chef). **B** : domination **charismatique**, fondée sur les **qualités exceptionnelles** prêtées à une personne (elle fascine). **C** : domination **légale-rationnelle**, fondée sur la **règle écrite** (la loi) et la **compétence** (le concours).\n3. La domination **légale-rationnelle** est la forme dominante dans les États modernes. En C, on obéit non à une personne mais à une **règle** impersonnelle, appliquée par une agente recrutée pour sa compétence : c'est le fonctionnement de l'administration d'un État moderne."}$exo$::jsonb),
  ('4cf3155e-62df-5540-8a69-c46561bc49ae'::uuid, 3, 'redaction', $exo${"titre":"Un sondage n'est pas une prédiction","consigne":"Analyse le document, puis réponds de façon argumentée. La dernière question attend un paragraphe structuré.","enonce":"**Document (fictif).**\n\n> À dix jours du second tour d'une élection municipale, un sondage réalisé auprès de 800 personnes donne la candidate Morel à 51 % et le candidat Garnier à 49 %, avec une marge d'erreur de plus ou moins 3 points. Un site local titre : « Morel a déjà gagné ! »\n\n1. Qu'est-ce qu'un **sondage** pour le politiste ? Explique ce que signifie la marge d'erreur de 3 points dans ce cas.\n2. Le titre du site est-il justifié ? Argumente.\n3. Le politiste veut expliquer les votes de cette élection. Cite des **variables lourdes** qu'il pourrait étudier et explique pourquoi il doit aussi tenir compte de la **conjoncture**.\n4. En un paragraphe, montre comment le politiste combinerait méthodes **quantitatives** et **qualitatives** pour étudier cette campagne, y compris l'**abstention**.","bareme":[{"critere":"Sondage défini comme estimation ; marge interprétée (Morel entre 48 et 54 %, Garnier entre 46 et 52 %)","points":5},{"critere":"Titre critiqué : écart inférieur à la marge, sondage non prédictif, dix jours avant le vote","points":4},{"critere":"Variables lourdes (âge, diplôme, profession, territoire, religion) et rôle de la conjoncture","points":5},{"critere":"Paragraphe combinant méthodes quantitatives et qualitatives, abstention traitée comme comportement politique","points":6}],"dureeMin":16,"corrige":"1. Un sondage est une **estimation** de l'opinion à un moment donné, à partir d'un échantillon, et non une prédiction. Avec une marge de 3 points, Morel se situe probablement **entre 48 et 54 %** et Garnier **entre 46 et 52 %**.\n2. Non : l'écart (2 points) est **inférieur à la marge d'erreur**, les intervalles se chevauchent, donc Garnier pourrait être en tête. De plus, le sondage mesure l'opinion dix jours avant : des électeurs peuvent changer d'avis ou s'abstenir. Le politiste se méfie des sondages lus comme des prédictions.\n3. **Variables lourdes** : âge, diplôme, profession, territoire (quartier), religion. Mais un même vote s'explique aussi par la **conjoncture** : événements de la campagne, thèmes du moment, personnalité des candidats.\n4. Paragraphe attendu : **quantitatif** : résultats électoraux par bureau de vote, sondages, panels, comparaison des quartiers selon leur composition sociale, taux d'**abstention** par bureau. **Qualitatif** : entretiens avec les candidats et des électeurs, **observation** des réunions et du porte-à-porte, archives de la campagne. L'**abstention** est étudiée comme un comportement politique à part entière (pourquoi certains ne votent pas), les deux méthodes se complétant : mesurer puis comprendre."}$exo$::jsonb),
  ('0f2e9102-9bc2-5499-8a32-d3e4ff705a3a'::uuid, 1, 'redaction', $exo${"titre":"Qui produit, et pourquoi","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Qu'est-ce que **produire** en économie ?\n2. Présente les **trois types de producteurs** vus en cours, en précisant ce qu'ils produisent et leur but.\n3. Selon quel critère la comptabilité nationale dit-elle qu'un service est **non marchand** ?\n4. La production d'un professeur de lycée public est-elle comptée dans le PIB ? Justifie.","bareme":[{"critere":"Produire : combiner des ressources pour créer des biens ou des services","points":3},{"critere":"Entreprises privées, administrations publiques, associations avec production et but","points":9},{"critere":"Critère du non marchand (gratuit ou prix inférieur à la moitié du coût) et prise en compte dans le PIB","points":8}],"dureeMin":7,"corrige":"1. **Produire**, c'est **combiner des ressources** pour créer des **biens** ou des **services** ; ce n'est pas seulement fabriquer des objets.\n2. Les **entreprises privées** produisent des biens et services **marchands** dans le but de réaliser un **profit**. Les **administrations publiques** produisent des services **non marchands**, financés par l'impôt, dans un but de **service** (école, justice, police, santé). Les **associations** produisent des biens et services **sans redistribuer de bénéfices**, au service d'un **projet**.\n3. Un service est non marchand s'il est fourni **gratuitement** ou à un prix **inférieur à la moitié de son coût de production**.\n4. Oui : l'heure de cours n'a pas de prix de marché, mais c'est une **production** (non marchande) ; elle est **comptée dans le PIB**, évaluée à son coût de production."}$exo$::jsonb),
  ('0f2e9102-9bc2-5499-8a32-d3e4ff705a3a'::uuid, 2, 'redaction', $exo${"titre":"Marchand ou non marchand ?","consigne":"Pour chaque cas, fais le calcul nécessaire et justifie ta réponse avec le critère du cours.","enonce":"**Cas (inventés).**\n\n| Service | Coût de production | Prix payé par l'usager |\n| A. Repas de la cantine municipale | 8 € | 3 € |\n| B. Séance d'un cinéma associatif | 7 € | 6 € |\n| C. Consultation d'un kinésithérapeute libéral | 40 € | 40 € |\n| D. Visite d'un musée public | 12 € | 0 € |\n\n1. Pour chaque service, indique s'il est **marchand** ou **non marchand**, en justifiant par un calcul.\n2. Classe les producteurs A, C et D selon leur **secteur** d'activité (primaire, secondaire ou tertiaire).\n3. Le cinéma associatif (B) est-il une entreprise privée ? Explique ce qui distingue une association.","bareme":[{"critere":"Quatre classements justes avec comparaison à la moitié du coût (4 € ; 3,5 € ; 20 € ; 6 €)","points":10},{"critere":"Les trois services classés dans le secteur tertiaire, avec justification","points":4},{"critere":"Association : ne redistribue pas de bénéfices, sert un projet, peut vendre des services marchands","points":6}],"dureeMin":11,"corrige":"1. Critère : non marchand si gratuit ou prix **< moitié du coût**.\n- **A** : moitié du coût = 4 € ; 3 € < 4 € → **non marchand**.\n- **B** : moitié = 3,5 € ; 6 € ≥ 3,5 € → **marchand** (même vendu un peu à perte).\n- **C** : moitié = 20 € ; 40 € ≥ 20 € → **marchand**.\n- **D** : gratuit → **non marchand**.\n2. A, C et D produisent des **services** : ils relèvent du **secteur tertiaire**.\n3. Non. Le cinéma est une **association** : il produit des services (ici marchands, puisque le prix dépasse la moitié du coût) mais **ne redistribue pas de bénéfices** ; son but est un **projet** (culturel), non le profit. Une entreprise privée, elle, cherche le **profit**. L'association fait partie de l'**économie sociale et solidaire**."}$exo$::jsonb),
  ('0f2e9102-9bc2-5499-8a32-d3e4ff705a3a'::uuid, 3, 'redaction', $exo${"titre":"Coopérative et grande société","consigne":"Analyse le document, puis rédige des réponses argumentées. La dernière question attend un paragraphe.","enonce":"**Document (entreprises imaginaires).**\n\n> **Laiterie du Val** est une coopérative : 120 éleveurs en sont associés ; chacun a une voix à l'assemblée, quel que soit le capital qu'il a apporté. Une grande part des bénéfices est mise en réserve. Elle emploie 45 salariés.\n>\n> **Lactis SA** est une société : ses actionnaires votent en proportion des actions qu'ils détiennent. Elle emploie 6 000 salariés et verse chaque année des dividendes.\n\n1. Classe chacune des deux entreprises selon les trois critères du cours : **taille**, **secteur**, **statut juridique**.\n2. Compare leur **gouvernance** et leur façon d'utiliser les bénéfices.\n3. Quelle entreprise relève de l'**économie sociale et solidaire** ? Cite les autres formes de l'ESS et son poids en France.\n4. En un paragraphe, explique pourquoi les très petites entreprises sont les plus **nombreuses** alors que les grandes concentrent l'essentiel du **chiffre d'affaires**, et ce que cela montre de la diversité des organisations productives.","bareme":[{"critere":"Classement exact : PME / grande entreprise, secteur secondaire (industrie agroalimentaire), coopérative / société","points":5},{"critere":"Gouvernance comparée (une personne une voix / une action une voix) et partage des bénéfices limité ou non","points":5},{"critere":"Laiterie du Val dans l'ESS, formes (coopératives, mutuelles, associations, fondations), environ un salarié privé sur dix","points":4},{"critere":"Paragraphe : nombre vs chiffre d'affaires, diversité de taille, de statut et de but","points":6}],"dureeMin":17,"corrige":"1. **Laiterie du Val** : 45 salariés → **PME** ; transformation du lait → secteur **secondaire** (industrie) ; statut : **coopérative**. **Lactis SA** : 6 000 salariés → **grande entreprise** ; secteur **secondaire** ; statut : **société**.\n2. Dans la coopérative, la gouvernance suit le principe **une personne, une voix** et le **partage des bénéfices est limité** (mise en réserve). Dans la société, le pouvoir est proportionnel au **capital** détenu, et les bénéfices sont en partie distribués aux actionnaires sous forme de **dividendes**.\n3. La **Laiterie du Val** relève de l'**ESS**. Ses autres formes : **mutuelles**, **associations**, **fondations**. L'ESS emploie environ **un salarié privé sur dix** en France.\n4. Paragraphe attendu : les **microentreprises** et très petites entreprises sont les plus **nombreuses** (artisans, commerces, indépendants), mais chacune vend peu ; les **grandes entreprises**, peu nombreuses, réalisent des ventes énormes et concentrent l'essentiel du **chiffre d'affaires**. Les organisations productives diffèrent donc par leur **taille**, leur **secteur**, leur **statut**, et même leur **but** (profit, service public, projet) : produire n'est pas l'affaire d'un seul type d'acteur."}$exo$::jsonb),
  ('a1b336f2-5ba8-59e9-8fd8-3e2b77ecb04a'::uuid, 1, 'redaction', $exo${"titre":"Travail et capital","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Quels sont les deux **facteurs de production** ? Définis chacun.\n2. Qu'est-ce que le **capital humain** ?\n3. Classe les éléments suivants en **capital fixe** ou **capital circulant**, en rappelant le critère : un four de boulangerie, de la farine, un logiciel de caisse, l'électricité, une camionnette de livraison.","bareme":[{"critere":"Travail et capital définis correctement","points":6},{"critere":"Capital humain : formation, expérience, santé qui font la qualité du travail","points":4},{"critere":"Critère de durée rappelé et cinq éléments classés sans erreur","points":10}],"dureeMin":6,"corrige":"1. Le **travail** est l'activité humaine, physique et intellectuelle, mise en œuvre pour produire (mesuré en actifs occupés ou en heures travaillées). Le **capital** regroupe les moyens matériels et immatériels utilisés pour produire.\n2. Le **capital humain** est ce qui fait la qualité du travail : la **formation**, l'**expérience** et la **santé**.\n3. Critère : le capital **fixe** sert **plus d'un an** et s'use (amortissement) ; le capital **circulant** est **détruit ou transformé** au cours de la production.\n- Four : **fixe** ; logiciel de caisse : **fixe** (immatériel) ; camionnette : **fixe**.\n- Farine : **circulant** ; électricité : **circulant** (consommations intermédiaires)."}$exo$::jsonb),
  ('a1b336f2-5ba8-59e9-8fd8-3e2b77ecb04a'::uuid, 2, 'redaction', $exo${"titre":"Une machine dans l'atelier","consigne":"Fais les calculs en détaillant chaque étape, puis justifie tes réponses avec le cours.","enonce":"**Situation (entreprise imaginaire).**\n\n> L'atelier Bois&Co fabrique des chaises. Avant : 6 salariés travaillent 35 heures par semaine et fabriquent 4 200 pièces par semaine. Après l'achat d'une machine à commande numérique : 5 salariés travaillent 35 heures et fabriquent 5 250 pièces par semaine.\n\n1. Calcule la **productivité horaire du travail** avant et après l'achat de la machine.\n2. Calcule le taux de variation de cette productivité.\n3. Le remplacement d'un salarié par une machine illustre-t-il la **substituabilité** ou la **complémentarité** des facteurs ? Justifie.\n4. Cite deux usages possibles de ces **gains de productivité**.","bareme":[{"critere":"Productivités justes : 4 200 / 210 = 20 pièces/h et 5 250 / 175 = 30 pièces/h","points":7},{"critere":"Taux de variation : (30 − 20) / 20 × 100 = + 50 %","points":4},{"critere":"Substituabilité identifiée et justifiée, nuance sur la complémentarité avec les salariés restants","points":5},{"critere":"Deux usages parmi baisse des prix, hausse des salaires, hausse des profits, réduction du temps de travail","points":4}],"dureeMin":11,"corrige":"1. La productivité horaire rapporte la production aux **heures travaillées**.\n- Avant : 6 × 35 = 210 h ; 4 200 / 210 = **20 pièces par heure**.\n- Après : 5 × 35 = 175 h ; 5 250 / 175 = **30 pièces par heure**.\n2. (30 − 20) / 20 × 100 = **+ 50 %**.\n3. Remplacer un salarié par une machine illustre la **substituabilité** : on remplace du travail par du capital pour produire. On peut nuancer : la machine doit être pilotée par les salariés restants, travail et capital sont aussi **complémentaires**.\n4. Deux usages parmi : **baisser les prix** des chaises, **augmenter les salaires**, **augmenter les profits**, **réduire le temps de travail**."}$exo$::jsonb),
  ('a1b336f2-5ba8-59e9-8fd8-3e2b77ecb04a'::uuid, 3, 'redaction', $exo${"titre":"Caisses automatiques ou vendeurs ?","consigne":"Analyse la situation et réponds de manière argumentée. La dernière question attend un paragraphe structuré.","enonce":"**Situation (inventée).**\n\n> Le gérant d'une chaîne de supérettes doit choisir pour ses nouveaux magasins : embaucher quatre caissiers par magasin, ou installer six caisses automatiques surveillées par un seul employé. Dans la région, le coût du travail vient d'augmenter, tandis que le prix des caisses automatiques a baissé.\n\n1. Caractérise les deux **combinaisons productives** possibles.\n2. Montre, à l'aide des trois critères du cours, ce qui peut pousser le gérant vers les caisses automatiques.\n3. Pourquoi l'employé qui surveille les caisses doit-il être formé ? Utilise la notion de **capital humain**.\n4. En un paragraphe argumenté, explique d'où viennent les **gains de productivité** et discute de la façon dont ils peuvent être répartis entre clients, salariés et propriétaires.","bareme":[{"critere":"Combinaison intensive en travail (caissiers) / intensive en capital (caisses automatiques)","points":4},{"critere":"Coût relatif des facteurs, technologie disponible, nature du produit appliqués à la situation","points":5},{"critere":"Capital humain : formation, compétences qui rendent le travail productif, complémentarité avec le capital","points":4},{"critere":"Paragraphe : sources des gains (progrès technique, formation, organisation, division des tâches) et quatre usages discutés","points":7}],"dureeMin":17,"corrige":"1. Quatre caissiers : combinaison **intensive en travail** (beaucoup de main-d'œuvre, peu de machines). Six caisses et un employé : combinaison **intensive en capital**.\n2. Le choix dépend : du **coût relatif des facteurs** (le travail devient plus cher, le capital moins cher : la machine est relativement plus avantageuse) ; de la **technologie disponible** (les caisses automatiques existent et sont fiables) ; de la **nature du produit** (un encaissement simple peut être automatisé, un conseil personnalisé moins). Remplacer du travail par du capital est une décision économique : les facteurs sont ici **substituables**.\n3. Le capital humain (formation, expérience) rend le travail plus productif : l'employé doit savoir dépanner les caisses, aider les clients, surveiller. Le capital et ce travail qualifié sont **complémentaires**.\n4. Paragraphe attendu : les gains de productivité viennent du **progrès technique** (nouvelles machines), de la **formation**, de l'**organisation du travail** et de la **division des tâches**. Ils peuvent servir à **baisser les prix** (profit des clients), **augmenter les salaires** (salariés), **augmenter les profits** (propriétaires) ou **réduire le temps de travail**. Leur répartition n'est pas automatique : elle résulte de choix et peut opposer les intérêts de ces groupes."}$exo$::jsonb),
  ('358b5d19-a910-52e9-92e0-6996bba8965b'::uuid, 1, 'redaction', $exo${"titre":"Calculer une valeur ajoutée","consigne":"Donne les définitions demandées, puis fais le calcul en détaillant.","enonce":"1. Définis le **chiffre d'affaires**, les **consommations intermédiaires** et la **valeur ajoutée**.\n2. Une pâtisserie imaginaire a vendu pour **500 000 €** de gâteaux dans l'année. Elle a acheté pour **180 000 €** de farine, beurre, sucre, énergie et emballages. Calcule sa valeur ajoutée.\n3. Que représente concrètement cette valeur ajoutée ?","bareme":[{"critere":"Trois définitions exactes","points":8},{"critere":"Calcul juste : 500 000 − 180 000 = 320 000 €","points":7},{"critere":"Interprétation : richesse ajoutée par le travail et les machines de l'entreprise","points":5}],"dureeMin":6,"corrige":"1. Le **chiffre d'affaires** est le total des ventes. Les **consommations intermédiaires** sont les biens et services achetés à d'autres et détruits ou transformés dans la production (matières premières, énergie, transport, entretien). La **valeur ajoutée** = chiffre d'affaires − consommations intermédiaires.\n2. VA = 500 000 − 180 000 = **320 000 €**.\n3. C'est la **richesse réellement créée** par la pâtisserie : ce que son travail et ses machines ont **ajouté** à ce qu'elle a acheté à d'autres entreprises."}$exo$::jsonb),
  ('358b5d19-a910-52e9-92e0-6996bba8965b'::uuid, 2, 'redaction', $exo${"titre":"Du blé au pain","consigne":"Fais les calculs demandés en détaillant, puis explique ce qu'ils montrent.","enonce":"**Situation (simplifiée et imaginaire).** On suppose que l'agriculteur n'achète rien à d'autres entreprises.\n\n| Entreprise | Ventes | Achats à d'autres entreprises |\n| Agriculteur | 20 000 € de blé au meunier | 0 € |\n| Meunier | 50 000 € de farine au boulanger | 20 000 € de blé |\n| Boulanger | 120 000 € de pain aux clients | 50 000 € de farine |\n\n1. Calcule la **valeur ajoutée** de chacune des trois entreprises.\n2. Calcule la somme des **chiffres d'affaires** et la somme des **valeurs ajoutées**.\n3. Laquelle de ces deux sommes mesure la richesse créée par la filière ? Explique pourquoi l'autre est trompeuse.","bareme":[{"critere":"Trois valeurs ajoutées justes : 20 000 €, 30 000 €, 70 000 €","points":8},{"critere":"Sommes justes : 190 000 € de chiffres d'affaires, 120 000 € de valeurs ajoutées","points":5},{"critere":"Double compte expliqué (blé et farine comptés plusieurs fois), la somme des VA égale la valeur du pain","points":7}],"dureeMin":10,"corrige":"1. VA = chiffre d'affaires − consommations intermédiaires.\n- Agriculteur : 20 000 − 0 = **20 000 €**.\n- Meunier : 50 000 − 20 000 = **30 000 €**.\n- Boulanger : 120 000 − 50 000 = **70 000 €**.\n2. Somme des chiffres d'affaires : 20 000 + 50 000 + 120 000 = **190 000 €**. Somme des VA : 20 000 + 30 000 + 70 000 = **120 000 €**.\n3. C'est la **somme des valeurs ajoutées** qui mesure la richesse créée : 120 000 €, soit exactement la valeur du pain vendu aux clients. La somme des chiffres d'affaires compte **plusieurs fois** les mêmes biens : le blé est compté dans les ventes de l'agriculteur, puis dans celles du meunier (dans la farine), puis dans celles du boulanger (dans le pain). C'est un **double compte**. C'est pourquoi on calcule le **PIB** en additionnant les valeurs ajoutées."}$exo$::jsonb),
  ('358b5d19-a910-52e9-92e0-6996bba8965b'::uuid, 3, 'redaction', $exo${"titre":"Le partage de la valeur ajoutée","consigne":"Analyse le document, fais les calculs, puis rédige. La dernière question attend un paragraphe argumenté.","enonce":"**Document (entreprise imaginaire).** Répartition de la valeur ajoutée de l'entreprise Vélonova en 2025.\n\n| Bénéficiaire | Montant |\n| Salaires et cotisations | 620 000 € |\n| Impôts liés à la production | 50 000 € |\n| Intérêts versés aux prêteurs | 30 000 € |\n| Dividendes | 120 000 € |\n| Autofinancement | ? |\n| **Valeur ajoutée totale** | **1 000 000 €** |\n\n1. Calcule le montant de l'**autofinancement**, puis la part des salaires et celle de l'autofinancement dans la valeur ajoutée (en %).\n2. À quoi sert l'autofinancement ?\n3. Les salariés demandent une hausse de 50 000 € de la masse salariale. Si les autres postes ne changent pas, que devient l'autofinancement ? Quelle conséquence pour l'entreprise ?\n4. En un paragraphe argumenté, explique pourquoi le partage de la valeur ajoutée est un **enjeu de conflit**, et pourquoi la valeur ajoutée est un indicateur utile (au moins deux usages).","bareme":[{"critere":"Autofinancement 180 000 € ; salaires 62 % ; autofinancement 18 %","points":5},{"critere":"Autofinancement : ce qui reste pour investir","points":3},{"critere":"Nouvel autofinancement 130 000 € et conséquence sur l'investissement","points":4},{"critere":"Paragraphe : intérêts opposés (salaires, profits, investissement, État) et usages (contribution sans double compte, PIB, TVA)","points":8}],"dureeMin":17,"corrige":"1. Autofinancement = 1 000 000 − (620 000 + 50 000 + 30 000 + 120 000) = 1 000 000 − 820 000 = **180 000 €**. Part des salaires : 620 000 / 1 000 000 × 100 = **62 %**. Part de l'autofinancement : **18 %**.\n2. L'autofinancement est ce qui **reste à l'entreprise pour investir** (acheter des machines, se développer) sans emprunter.\n3. Salaires : 670 000 € ; autofinancement = 1 000 000 − 870 000 = **130 000 €**. L'entreprise aurait moins de ressources propres pour **investir** ; elle devrait emprunter (et payer plus d'intérêts) ou investir moins, à moins de réduire les dividendes.\n4. Paragraphe attendu : la valeur ajoutée est une richesse **limitée** qui se partage entre **salariés** (salaires et cotisations), **État** (impôts), **prêteurs** (intérêts), **propriétaires** (dividendes) et l'**entreprise** (autofinancement). Ce que l'un reçoit en plus, un autre le reçoit en moins : d'où un **conflit permanent** (négociations salariales, arbitrage entre dividendes et investissement). L'indicateur est utile car il mesure la **contribution réelle** de chaque entreprise **sans double compte**, permet de calculer le **PIB** en sommant les valeurs ajoutées, et sert d'assiette à la **TVA**."}$exo$::jsonb),
  ('0fff4b70-b221-596d-bc30-947f3532f2db'::uuid, 1, 'redaction', $exo${"titre":"Définir le PIB","consigne":"Réponds à chaque question par des phrases complètes, avec le vocabulaire du cours.","enonce":"1. Donne la définition du **PIB**.\n2. Que signifie le mot **intérieur** ? Une usine japonaise installée en France entre-t-elle dans le PIB français ?\n3. Distingue le PIB **en valeur**, **en volume** et **par habitant** : que mesure chacun et à quoi sert-il ?","bareme":[{"critere":"Définition : somme des valeurs ajoutées des unités résidentes sur un an, plus TVA et droits de douane","points":6},{"critere":"Sens d'intérieur et application juste à l'usine japonaise","points":5},{"critere":"Trois PIB distingués avec leur usage (croissance = volume ; comparaison = par habitant)","points":9}],"dureeMin":7,"corrige":"1. Le PIB est la **somme des valeurs ajoutées** produites par toutes les **unités résidentes** d'un territoire pendant **un an**, plus la TVA et les droits de douane.\n2. **Intérieur** : ce qui est produit **sur le territoire**, quelle que soit la **nationalité** du producteur. L'usine japonaise installée en France produit sur le territoire français : sa valeur ajoutée **entre dans le PIB français**.\n3. Le PIB **en valeur** est mesuré aux **prix courants** : il augmente quand les prix augmentent. Le PIB **en volume** neutralise l'**inflation** : c'est lui qui mesure la **croissance**. Le PIB **par habitant** rapporte le PIB à la population : il permet de **comparer** les pays, sans rien dire de la répartition des richesses."}$exo$::jsonb),
  ('0fff4b70-b221-596d-bc30-947f3532f2db'::uuid, 2, 'redaction', $exo${"titre":"Ce que le PIB compte et oublie","consigne":"Pour chaque situation, dis si le PIB augmente, et justifie avec le cours.","enonce":"**Situations (inventées).**\n\n- **A.** Un père reste au foyer pour s'occuper de ses deux enfants et de la maison.\n- **B.** Après une marée noire, une entreprise est payée pour nettoyer les plages pendant trois mois.\n- **C.** Une bénévole anime gratuitement l'aide aux devoirs dans une association.\n- **D.** Une forêt est entièrement abattue et le bois est vendu.\n\n1. Pour chaque situation, indique l'effet sur le PIB et justifie.\n2. Que révèlent ces exemples sur les **limites** du PIB comme mesure du bien-être ?\n3. Cite deux **indicateurs complémentaires** et ce que chacun ajoute.","bareme":[{"critere":"Quatre effets justes et justifiés (A et C non comptés, B et D augmentent le PIB)","points":10},{"critere":"Limites : production non rémunérée oubliée, dégâts et épuisement des ressources non déduits","points":5},{"critere":"Deux indicateurs complémentaires justes avec leur apport","points":5}],"dureeMin":10,"corrige":"1. **A** : pas de hausse du PIB : le **travail domestique** n'est ni rémunéré ni échangé, il n'est pas compté, bien qu'il soit une production réelle. **B** : le PIB **augmente** : les dépenses de dépollution sont une production marchande ; la dégradation de l'environnement, elle, n'est pas déduite. **C** : pas de hausse : le **bénévolat** n'est pas compté. **D** : le PIB **augmente** (vente du bois), alors que l'**épuisement des ressources**, le capital naturel consommé, n'est pas déduit.\n2. Le PIB mesure l'activité, pas le **bien-être** : il oublie des productions utiles non rémunérées et compte positivement des activités liées à des dégâts ; il ne dit rien des inégalités, de la santé, du temps libre.\n3. Deux parmi : l'**IDH** (ajoute santé et éducation) ; l'**empreinte écologique** (pression sur la biosphère) ; l'indice de **Gini** (inégalités) ; l'**espérance de vie en bonne santé** (qualité des années vécues)."}$exo$::jsonb),
  ('0fff4b70-b221-596d-bc30-947f3532f2db'::uuid, 3, 'redaction', $exo${"titre":"Deux pays, un classement ?","consigne":"Analyse le document, puis rédige. La dernière question attend un paragraphe argumenté.","enonce":"**Document (pays imaginaires).**\n\n| Indicateur | Pays Alba | Pays Borée |\n| PIB en valeur (variation sur un an) | + 6 % | + 3 % |\n| Hausse des prix sur un an | + 5 % | + 1 % |\n| PIB par habitant | 42 000 $ | 36 000 $ |\n| IDH | 0,86 | 0,92 |\n| Indice de Gini | 0,45 | 0,28 |\n\n1. Explique pourquoi on ne peut pas dire qu'Alba a connu la plus forte **croissance** à partir de la seule variation du PIB en valeur. Quel PIB faut-il utiliser ? Donne l'ordre de grandeur de la croissance de chaque pays.\n2. Alba a un PIB par habitant plus élevé : ses habitants sont-ils tous plus riches ? Justifie à l'aide du document.\n3. En un paragraphe argumenté, réponds à la question : **le PIB suffit-il à mesurer la richesse d'un pays ?** Appuie-toi sur le document et sur ce que le PIB ne compte pas.","bareme":[{"critere":"Distinction valeur / volume ; croissance en volume d'environ 1 % pour Alba et 2 % pour Borée","points":6},{"critere":"PIB par habitant = moyenne, Gini plus élevé à Alba donc répartition plus inégale","points":5},{"critere":"Paragraphe : utilité du PIB, oublis (domestique, informel, environnement, ressources, inégalités), indicateurs à lire ensemble","points":9}],"dureeMin":18,"corrige":"1. Le PIB **en valeur** augmente aussi quand les **prix** augmentent. Pour mesurer la **croissance**, il faut le PIB **en volume**, qui neutralise l'inflation. Alba : environ 6 − 5 ≈ **1 %** de croissance ; Borée : environ 3 − 1 ≈ **2 %**. C'est donc Borée qui a la plus forte croissance.\n2. Non : le PIB par habitant est une **moyenne**, il ne dit rien de la **répartition**. L'indice de **Gini** d'Alba (0,45) est plus élevé que celui de Borée (0,28) : les richesses y sont plus **inégalement** réparties ; une partie des habitants peut être moins riche qu'à Borée.\n3. Paragraphe attendu : le PIB est l'indicateur le plus utilisé : il mesure l'activité, permet de calculer la croissance (en volume) et de comparer les pays (par habitant). Mais il **oublie** le travail domestique et le bénévolat, l'économie informelle, il ne déduit ni la dégradation de l'**environnement** ni l'épuisement des **ressources**, et ignore les **inégalités**, la santé, le temps libre ; une marée noire l'augmente. Le document le montre : Alba a un PIB par habitant supérieur mais un **IDH** plus faible (santé, éducation) et plus d'inégalités. Aucun indicateur ne remplace le PIB : ils se lisent **ensemble** (IDH, Gini, empreinte écologique, espérance de vie en bonne santé)."}$exo$::jsonb),
  ('466c1452-b017-5929-8f9b-3efc5e95fb28'::uuid, 1, 'redaction', $exo${"titre":"Croissance, expansion, développement","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Définis la **croissance économique** et précise comment on la mesure.\n2. Distingue la croissance de l'**expansion** et du **développement**.\n3. Définis une **récession** et une **dépression**, en donnant un exemple historique de dépression.\n4. Quand commence la croissance économique moderne, et où ?","bareme":[{"critere":"Croissance : hausse durable de la production, mesurée par le PIB en volume","points":5},{"critere":"Expansion (courte durée) et développement (transformations sociales, conditions de vie) distingués","points":6},{"critere":"Récession (deux trimestres de recul) et dépression (après 1929)","points":5},{"critere":"Révolution industrielle, fin du XVIIIe siècle, en Angleterre","points":4}],"dureeMin":6,"corrige":"1. La **croissance** est l'augmentation **durable** de la production, mesurée par la variation du **PIB en volume**.\n2. L'**expansion** est une hausse de la production de **courte durée**. Le **développement** va au-delà de la croissance : il inclut les **transformations sociales** et l'amélioration des **conditions de vie**.\n3. Une **récession** est un recul du PIB pendant **deux trimestres consécutifs**. Une **dépression** est un recul **durable et profond**, comme après la crise de **1929**.\n4. Avec la **révolution industrielle**, dès la **fin du XVIIIe siècle**, en **Angleterre**."}$exo$::jsonb),
  ('466c1452-b017-5929-8f9b-3efc5e95fb28'::uuid, 2, 'redaction', $exo${"titre":"Lire une conjoncture","consigne":"Analyse le document, puis réponds en justifiant avec le cours.","enonce":"**Document (pays imaginaire).** Variation du PIB en volume d'un trimestre à l'autre.\n\n| Trimestre | T1 | T2 | T3 | T4 |\n| Variation | + 0,4 % | − 0,2 % | − 0,5 % | + 0,1 % |\n\n1. Ce pays a-t-il connu une **récession** cette année ? Justifie à l'aide de la définition.\n2. Comment appelle-t-on l'alternance de phases d'expansion et de ralentissement ? En quoi ce document illustre-t-il l'**irrégularité** de la croissance ?\n3. Un pays connaît une croissance de 2 % par an. En combien de temps environ sa production double-t-elle ? Pourquoi dit-on que la croissance est une affaire d'**intérêts composés** ?","bareme":[{"critere":"Récession identifiée : deux trimestres consécutifs de recul (T2 et T3)","points":7},{"critere":"Fluctuations nommées, irrégularité expliquée à partir des données","points":6},{"critere":"Doublement en trente-cinq ans environ, chaque hausse s'appliquant à une production déjà augmentée","points":7}],"dureeMin":9,"corrige":"1. Oui : le PIB en volume recule en **T2** (− 0,2 %) et en **T3** (− 0,5 %), soit **deux trimestres consécutifs** de recul : c'est la définition d'une **récession**.\n2. On parle de **fluctuations** : l'alternance d'expansion et de ralentissement. Le document le montre : hausse en T1, recul en T2 et T3, reprise en T4. La croissance n'est donc pas **régulière**.\n3. Avec 2 % par an, la production **double en trente-cinq ans environ**. Chaque année, les 2 % s'appliquent à une production **déjà augmentée** les années précédentes : les hausses se cumulent comme des **intérêts composés**, ce qui fait qu'un petit taux, tenu longtemps, transforme profondément une économie."}$exo$::jsonb),
  ('466c1452-b017-5929-8f9b-3efc5e95fb28'::uuid, 3, 'redaction', $exo${"titre":"Récente, inégale, irrégulière","consigne":"Rédige un développement argumenté et organisé en trois parties, en t'appuyant sur le document et sur le cours.","enonce":"**Sujet.** Montrez que la croissance économique est un phénomène **récent**, **inégal** et **irrégulier**.\n\n**Document (repères).**\n\n> Avant le XIXe siècle, la production progresse très lentement. En France, pendant les Trente Glorieuses (1945-1975), la croissance atteint environ 5 % par an. Depuis 1975, elle est nettement plus faible dans les pays anciennement industrialisés. Le Japon décolle à la fin du XIXe siècle, puis après 1945 ; la Chine, l'Inde ou le Brésil au cours des dernières décennies ; une partie de l'Afrique subsaharienne reste encore à l'écart. Des chocs frappent l'économie mondiale en 1973, 1979, 2008 et 2020.\n\nTa réponse doit comporter une courte introduction qui définit la croissance, trois paragraphes et une phrase de conclusion.","bareme":[{"critere":"Introduction : croissance définie (hausse durable du PIB en volume), distinguée du développement","points":3},{"critere":"Phénomène récent : stagnation avant le XIXe, révolution industrielle fin XVIIIe en Angleterre, Trente Glorieuses","points":5},{"critere":"Phénomène inégal : décollages décalés selon les régions, exemples justes","points":5},{"critere":"Phénomène irrégulier : fluctuations, récession, dépression, chocs datés (1973, 1979, 2008, 2020)","points":5},{"critere":"Organisation et conclusion cohérente","points":2}],"dureeMin":20,"corrige":"**Introduction.** La croissance est l'augmentation **durable** de la production, mesurée par le **PIB en volume** ; elle ne se confond pas avec le développement (transformations sociales, conditions de vie).\n\n**1. Récente.** Pendant des millénaires, jusqu'au XIXe siècle, la production est **quasi stagnante**. La croissance moderne démarre avec la **révolution industrielle**, dès la **fin du XVIIIe siècle en Angleterre**. Elle culmine en France pendant les **Trente Glorieuses** (1945-1975, environ **5 %** par an) ; depuis 1975, elle est nettement plus faible dans les pays anciennement industrialisés. À l'échelle de l'histoire humaine, c'est une nouveauté de deux siècles.\n\n**2. Inégale.** Toutes les régions n'ont pas décollé en même temps : **Europe et Amérique du Nord** au XIXe siècle, le **Japon** à la fin du XIXe puis après 1945, les pays **émergents** (Chine, Inde, Brésil, Asie du Sud-Est) au cours des dernières décennies, tandis qu'une partie de l'**Afrique subsaharienne** reste encore à l'écart.\n\n**3. Irrégulière.** La croissance connaît des **fluctuations** : expansion et ralentissement alternent. Elle subit des **récessions** (deux trimestres consécutifs de recul du PIB) et parfois des **dépressions** (après 1929). Des chocs l'interrompent : **chocs pétroliers de 1973 et 1979**, **crise financière de 2008**, **crise sanitaire de 2020**.\n\n**Conclusion.** La croissance n'est donc ni ancienne, ni universelle, ni continue : c'est un phénomène historique, situé et heurté."}$exo$::jsonb),
  ('1e67895e-ac53-50df-bed3-8949b08ce213'::uuid, 1, 'redaction', $exo${"titre":"Externalités et biens communs","consigne":"Réponds à chaque question par des phrases complètes, avec un exemple quand c'est demandé.","enonce":"1. Définis une **externalité négative** et donne un exemple.\n2. Qu'est-ce qu'un **bien commun** ? Pourquoi l'atmosphère est-elle difficile à protéger ?\n3. Cite trois **problèmes écologiques** liés à la croissance, en distinguant ressources **non renouvelables** et **renouvelables**.\n4. Quel rapport alerte dès 1972 sur les limites de la croissance ?","bareme":[{"critere":"Externalité négative définie (effet non payé imposé à autrui) avec exemple juste","points":6},{"critere":"Bien commun défini et appliqué à l'atmosphère","points":6},{"critere":"Trois problèmes écologiques, distinction renouvelables / non renouvelables avec exemples","points":5},{"critere":"Rapport Meadows, 1972","points":3}],"dureeMin":7,"corrige":"1. Une **externalité négative** est un **effet non payé** qu'une activité impose à autrui. Exemple : une usine qui **pollue une rivière** sans en supporter le coût, au détriment des pêcheurs et des riverains.\n2. Un **bien commun** est une ressource que chacun a intérêt à **surexploiter** et que personne n'a intérêt à **préserver seul**. L'atmosphère en est un : chacun peut y rejeter des gaz sans payer le coût du réchauffement, et celui qui ferait seul des efforts supporterait leur coût sans en garder le bénéfice.\n3. Trois parmi : l'**épuisement** des ressources **non renouvelables** (pétrole, gaz, métaux) ; la **surexploitation** des **renouvelables** (poissons, forêts, eau) ; les **pollutions** ; l'effondrement de la **biodiversité** ; le **réchauffement climatique**.\n4. Le **rapport Meadows** (1972)."}$exo$::jsonb),
  ('1e67895e-ac53-50df-bed3-8949b08ce213'::uuid, 2, 'redaction', $exo${"titre":"La papeterie et les pêcheurs","consigne":"Lis la situation et réponds en mobilisant les notions et les instruments du cours.","enonce":"**Situation (inventée).**\n\n> Une papeterie rejette ses eaux usées dans la rivière. Ses coûts sont bas et son papier se vend bon marché. En aval, les pêcheurs attrapent de moins en moins de poissons et un camping perd des clients.\n\n1. Identifie l'**externalité** en jeu : qui la provoque, qui la subit ?\n2. Explique la phrase du cours : « Un prix qui ne compte pas la pollution est un prix qui ment sur ce que coûte le produit. »\n3. Propose **deux instruments** différents pour réduire cette pollution et explique le principe de chacun.","bareme":[{"critere":"Externalité négative identifiée avec émetteur (papeterie) et victimes (pêcheurs, camping)","points":5},{"critere":"Explication : coût de la pollution non intégré au prix, papier trop bon marché, marché seul insuffisant","points":7},{"critere":"Deux instruments du cours adaptés à la situation avec leur principe","points":8}],"dureeMin":10,"corrige":"1. C'est une **externalité négative** : la **papeterie** impose un effet non payé (la pollution de la rivière) aux **pêcheurs** et au **camping**, qui en supportent le coût.\n2. Le prix du papier ne reflète que les coûts supportés par la papeterie, pas ceux de la pollution supportés par les autres : il est **trop bas**, il « ment » sur le vrai coût du produit pour la société. On achète donc plus de ce papier qu'on ne le ferait si son prix comptait la pollution : la seule loi du **marché ne suffit pas**.\n3. Deux parmi : **réglementer** (norme limitant les rejets, interdiction de certains produits) ; **taxer** selon le principe **pollueur-payeur** (taxe par tonne de rejet, qui renchérit la pollution) ; créer un **marché de quotas** (plafond de rejets, droits échangeables) ; **subventionner** un procédé d'épuration ; **informer**, labelliser (label du papier propre pour éclairer le consommateur)."}$exo$::jsonb),
  ('1e67895e-ac53-50df-bed3-8949b08ce213'::uuid, 3, 'redaction', $exo${"titre":"Croître sur une planète finie","consigne":"Analyse le document, puis rédige un paragraphe argumenté pour la dernière question.","enonce":"**Document (propos imaginaires, recueillis lors d'un débat au lycée).**\n\n> **Hugo** : « Grâce aux voitures électriques et aux énergies renouvelables, on pourra produire plus tout en polluant moins. »\n>\n> **Salomé** : « Il faut répondre à nos besoins sans empêcher les générations futures de répondre aux leurs. »\n>\n> **Yasmine** : « Les progrès techniques ne suffiront jamais à compenser la hausse de la production : il faut produire moins. »\n\n1. Associe chaque propos à l'une des trois **positions** du débat vues en cours, en justifiant.\n2. Définis le **découplage**. Sur quel pari repose la croissance verte ?\n3. En un paragraphe argumenté, explique pourquoi la croissance se heurte à des **limites écologiques**, en mobilisant les notions d'**externalité négative** et de **bien commun**, puis présente les réponses possibles des pouvoirs publics.","bareme":[{"critere":"Hugo : croissance verte ; Salomé : développement durable (1987) ; Yasmine : décroissance, justifiés","points":6},{"critere":"Découplage défini, pari du progrès technique","points":4},{"critere":"Limites : ressources, pollutions, biodiversité, climat ; externalité et bien commun expliqués","points":6},{"critere":"Instruments publics présentés (réglementer, taxer, quotas, subventionner, informer)","points":4}],"dureeMin":18,"corrige":"1. **Hugo** défend la **croissance verte** : produire plus en polluant moins grâce au progrès technique. **Salomé** reprend la définition du **développement durable** (1987) : répondre aux besoins présents sans compromettre ceux des générations futures. **Yasmine** défend la **décroissance** : elle conteste la possibilité d'un découplage suffisant.\n2. Le **découplage** consiste à faire croître la production tout en réduisant la **pression environnementale**. La croissance verte parie que le **progrès technique** le rendra possible.\n3. Paragraphe attendu : la croissance mobilise des ressources et rejette des déchets, or la planète est **finie** : épuisement des ressources non renouvelables (pétrole, gaz, métaux), surexploitation des renouvelables (poissons, forêts, eau), pollutions, effondrement de la biodiversité, réchauffement climatique. Le marché ne corrige pas seul ces dégâts : la pollution est une **externalité négative** (effet non payé imposé à autrui), et l'atmosphère ou les océans sont des **biens communs** que chacun a intérêt à surexploiter. Les pouvoirs publics peuvent **réglementer** (normes, interdictions, quotas), **taxer** (pollueur-payeur), créer un **marché de quotas**, **subventionner** les alternatives, **informer** et labelliser."}$exo$::jsonb),
  ('c34c6023-5016-52d1-90a5-bef26ea06279'::uuid, 1, 'redaction', $exo${"titre":"Qu'est-ce qu'un marché ?","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Définis un **marché** en économie. Est-ce forcément un lieu physique ?\n2. Cite les **trois conditions** de l'échange marchand et ce que chacune assure.\n3. Cite trois **types de marchés** et ce qui s'y échange.","bareme":[{"critere":"Marché : rencontre d'une offre et d'une demande aboutissant à un échange et un prix ; physique ou dématérialisé","points":6},{"critere":"Droits de propriété, monnaie, institutions avec leur rôle","points":8},{"critere":"Trois types de marchés corrects avec leur objet","points":6}],"dureeMin":6,"corrige":"1. Un **marché** est la **rencontre d'une offre et d'une demande** qui aboutit à un **échange** et à un **prix**. Ce n'est pas forcément un lieu : il peut être **physique** (une halle) ou **dématérialisé** (une plateforme en ligne).\n2. Des **droits de propriété** définis et protégés (on sait qui vend quoi) ; une **monnaie** (unité de compte et moyen de paiement) ; des **institutions** : contrats, tribunaux, normes (la parole donnée sera tenue). Sans confiance, pas d'échange.\n3. Trois parmi : marché des **biens et services** (produits, prestations) ; du **travail** (force de travail contre salaire) ; **financier** (actions, obligations) ; des **changes** (monnaies) ; des **matières premières** (pétrole, blé, métaux)."}$exo$::jsonb),
  ('c34c6023-5016-52d1-90a5-bef26ea06279'::uuid, 2, 'redaction', $exo${"titre":"Quelle structure de marché ?","consigne":"Pour chaque situation, identifie la structure de marché et justifie avec les critères du cours.","enonce":"**Situations (inventées).**\n\n- **A.** Sur une petite île, une seule entreprise distribue l'eau potable.\n- **B.** Dans un pays, trois opérateurs se partagent le marché de la téléphonie mobile.\n- **C.** Dans une grande ville, des centaines de restaurants proposent chacun leur cuisine, leur décor, leur carte.\n- **D.** Sur un marché mondial, des milliers de producteurs vendent un blé de même qualité à des milliers d'acheteurs bien informés des prix.\n\n1. Nomme la structure de marché de chaque situation en justifiant par le **nombre d'offreurs** et la nature du **produit**.\n2. Pourquoi dit-on que la **concurrence parfaite** est un modèle **théorique** ? Rappelle ses conditions.","bareme":[{"critere":"A monopole, B oligopole, C concurrence monopolistique, D proche de la concurrence parfaite, chacun justifié","points":12},{"critere":"Conditions de la concurrence parfaite (nombreux agents, produit homogène, information parfaite, libre entrée et sortie) et caractère théorique","points":8}],"dureeMin":9,"corrige":"1. **A** : **monopole** : un **seul** offreur. **B** : **oligopole** : **quelques** offreurs dominent le marché. **C** : **concurrence monopolistique** : offreurs **nombreux**, mais produit **différencié** (chaque restaurant a sa cuisine, son décor, sa « marque »). **D** : situation proche de la **concurrence parfaite** : offreurs et acheteurs très nombreux, produit **homogène**, information sur les prix.\n2. La concurrence parfaite suppose des offreurs et demandeurs **très nombreux**, un produit **homogène**, une **information parfaite** et la **libre entrée et sortie** du marché. Ces conditions sont rarement toutes réunies dans la réalité (marques, informations incomplètes, barrières) : c'est un **modèle théorique**, une référence pour raisonner plus qu'une description."}$exo$::jsonb),
  ('c34c6023-5016-52d1-90a5-bef26ea06279'::uuid, 3, 'redaction', $exo${"titre":"Encadrer les marchés","consigne":"Analyse le document et rédige des réponses argumentées. La dernière question attend un paragraphe structuré.","enonce":"**Document (affaire imaginaire).**\n\n> Trois fabricants de lessive, qui vendent à eux seuls 80 % des lessives du pays, se sont réunis en secret pendant cinq ans pour fixer ensemble leurs prix de vente. L'autorité de la concurrence les a lourdement sanctionnés. Au même moment, le plus gros d'entre eux annonçait vouloir racheter le quatrième fabricant.\n\n1. Quelle est la **structure** de ce marché ? Justifie.\n2. Quelle pratique l'autorité de la concurrence a-t-elle sanctionnée ? Pourquoi est-elle nuisible aux consommateurs ?\n3. Que pourrait faire l'autorité face au projet de **rachat** ? Nomme la pratique surveillée.\n4. En un paragraphe argumenté, montre qu'un marché ne fonctionne pas tout seul : il repose sur des **institutions** et il est **encadré**, et certaines activités en sont même **soustraites**.","bareme":[{"critere":"Oligopole justifié (quelques offreurs, 80 % du marché)","points":3},{"critere":"Entente sur les prix identifiée, prix plus élevés et concurrence supprimée","points":5},{"critere":"Contrôle des concentrations : interdire ou conditionner un rachat qui réduit trop la concurrence","points":4},{"critere":"Paragraphe : conditions de l'échange (propriété, monnaie, institutions), sanctions (ententes, concentrations, abus de position dominante), activités hors marché","points":8}],"dureeMin":17,"corrige":"1. C'est un **oligopole** : **quelques** offreurs (trois, puis quatre) dominent le marché, avec 80 % des ventes.\n2. C'est une **entente** sur les prix : un accord entre concurrents. Elle supprime la concurrence : les fabricants n'ont plus intérêt à baisser leurs prix, les consommateurs paient **plus cher** que si les entreprises se faisaient concurrence.\n3. L'autorité surveille les **concentrations** : elle peut **interdire** le rachat, ou l'autoriser sous conditions, s'il **réduit trop la concurrence** (le groupe deviendrait dominant).\n4. Paragraphe attendu : un marché suppose des **droits de propriété** protégés, une **monnaie** et des **institutions** (contrats, tribunaux, normes) qui garantissent la confiance. Il est aussi **encadré** par les États et l'Union européenne, qui sanctionnent les **ententes**, contrôlent les **concentrations** et punissent les **abus de position dominante** (utiliser son pouvoir de marché pour évincer des concurrents). Enfin, certaines activités sont **soustraites** au marché : on ne vend légalement ni **organes** ni **voix électorales**. Le marché est donc une construction sociale et juridique, pas un mécanisme naturel."}$exo$::jsonb),
  ('40def777-4077-596e-9439-4e9a0c5a3ff1'::uuid, 1, 'redaction', $exo${"titre":"Offre, demande et équilibre","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Comment évolue la **demande** quand le prix augmente ? Et l'**offre** ? Explique pourquoi.\n2. Définis le **prix d'équilibre**.\n3. Que se passe-t-il si le prix est **au-dessus** du prix d'équilibre ? Et **au-dessous** ?\n4. Pourquoi dit-on que le prix est une **information** ?","bareme":[{"critere":"Demande décroissante et offre croissante, avec explication","points":6},{"critere":"Prix d'équilibre : quantité offerte = quantité demandée","points":4},{"critere":"Excédent d'offre (invendus, baisse) et pénurie (hausse) décrits","points":6},{"critere":"Prix comme information pour producteurs et consommateurs","points":4}],"dureeMin":6,"corrige":"1. Quand le prix augmente, la **demande diminue** (courbe **décroissante**) : les acheteurs renoncent ou se reportent sur autre chose. L'**offre augmente** (courbe **croissante**) : produire devient plus rentable.\n2. Le **prix d'équilibre** est le prix pour lequel la **quantité offerte est égale à la quantité demandée**.\n3. **Au-dessus** : l'offre excède la demande, il y a des **invendus**, le prix **baisse**. **Au-dessous** : la demande excède l'offre, il y a **pénurie**, le prix **monte**. Le marché est dit **autorégulateur**.\n4. Le prix dit aux **producteurs** où produire et aux **consommateurs** à quoi renoncer : il transmet une information sur la rareté."}$exo$::jsonb),
  ('40def777-4077-596e-9439-4e9a0c5a3ff1'::uuid, 2, 'redaction', $exo${"titre":"Le marché des fraises","consigne":"Analyse le tableau, puis réponds en justifiant par des calculs.","enonce":"**Document (marché imaginaire de la barquette de fraises, sur une semaine).**\n\n| Prix (€) | 1 | 2 | 3 | 4 | 5 |\n| Quantité demandée | 500 | 400 | 300 | 200 | 100 |\n| Quantité offerte | 100 | 200 | 300 | 400 | 500 |\n\n1. Détermine le **prix** et la **quantité d'équilibre**. Justifie.\n2. Si le prix était de 4 €, quelle serait la situation du marché ? Chiffre-la et indique comment le prix évoluerait.\n3. Même question pour un prix de 2 €.\n4. Ces quantités sont-elles des quantités **échangées** ? Explique.","bareme":[{"critere":"Équilibre : 3 € et 300 barquettes, justification par l'égalité offre = demande","points":5},{"critere":"À 4 € : excédent d'offre de 200 barquettes, invendus, baisse du prix","points":5},{"critere":"À 2 € : excès de demande de 200 barquettes, pénurie, hausse du prix","points":5},{"critere":"Quantités souhaitées à chaque prix, et non échangées","points":5}],"dureeMin":10,"corrige":"1. À **3 €**, la quantité demandée (300) est égale à la quantité offerte (300) : le prix d'équilibre est **3 €** et la quantité d'équilibre **300 barquettes**.\n2. À 4 € : offre 400, demande 200 : l'**offre excède la demande** de 400 − 200 = **200 barquettes** (invendus). Les vendeurs baissent leurs prix : le prix **baisse** vers 3 €.\n3. À 2 € : demande 400, offre 200 : la **demande excède l'offre** de **200 barquettes** (pénurie). Le prix **monte** vers 3 €.\n4. Non : ce sont des quantités **souhaitées** à chaque prix (ce que les acheteurs voudraient acheter, ce que les vendeurs voudraient vendre). Seule une quantité est réellement échangée : celle de l'équilibre, lorsque le marché s'y établit."}$exo$::jsonb),
  ('40def777-4077-596e-9439-4e9a0c5a3ff1'::uuid, 3, 'redaction', $exo${"titre":"Quand les courbes se déplacent","consigne":"Analyse les documents, justifie chaque réponse, puis rédige un paragraphe pour la dernière question.","enonce":"**Document 1 (marché imaginaire du jus d'orange, en milliers de litres).**\n\n| Prix (€ le litre) | 1 | 2 | 3 | 4 | 5 |\n| Demande (avant) | 500 | 400 | 300 | 200 | 100 |\n| Offre | 100 | 200 | 300 | 400 | 500 |\n\n**Document 2.** Le revenu des ménages augmente fortement ; à chaque prix, la demande s'accroît de 200 milliers de litres.\n\n1. Donne l'équilibre initial, puis construis la nouvelle ligne de demande et détermine le **nouvel équilibre**.\n2. Explique pourquoi on parle ici d'un **déplacement de la courbe** de demande et non d'un déplacement **le long** de la courbe.\n3. Pour chacun des événements suivants, dis quelle courbe se déplace et dans quel sens : **a.** un progrès technique dans la récolte des oranges ; **b.** une nouvelle taxe sur chaque litre produit ; **c.** une boisson concurrente devient beaucoup moins chère.\n4. En un paragraphe, explique ce qu'est l'**élasticité-prix de la demande** et pourquoi une taxe sur le tabac rapporte beaucoup tout en faisant peu baisser la consommation à court terme.","bareme":[{"critere":"Équilibre initial 3 € / 300 ; nouvelle demande 700-600-500-400-300 ; nouvel équilibre 4 € / 400","points":6},{"critere":"Distinction déplacement de courbe (revenu) / déplacement le long (prix du bien)","points":4},{"critere":"a offre vers la droite, b offre vers la gauche, c demande vers la gauche","points":5},{"critere":"Élasticité définie, demande de tabac peu élastique, recettes élevées et consommation stable","points":5}],"dureeMin":18,"corrige":"1. Équilibre initial : **3 €** et **300** milliers de litres. Nouvelle demande : 700 ; 600 ; 500 ; 400 ; 300 pour 1 à 5 €. À **4 €**, demande 400 = offre 400 : nouvel équilibre **4 € et 400 milliers de litres**. Le prix et la quantité augmentent.\n2. Ce n'est pas le prix du jus qui change, mais un autre facteur (le **revenu**) : à chaque prix, on demande davantage, donc **toute la courbe de demande se déplace** (vers la droite). Une variation du prix du bien lui-même, elle, fait se déplacer **le long** de la courbe.\n3. **a.** Progrès technique : la **courbe d'offre** se déplace vers la **droite** (on offre plus à chaque prix). **b.** Taxe : la **courbe d'offre** se déplace vers la **gauche** (produire coûte plus cher). **c.** Substitut moins cher : la **courbe de demande** se déplace vers la **gauche**.\n4. L'**élasticité-prix de la demande** mesure la sensibilité des quantités demandées au prix. Elle est **faible** pour un bien dont on a du mal à se passer, **forte** pour un bien facilement remplaçable. La demande de tabac est **peu élastique** à court terme : quand la taxe fait monter le prix, les fumeurs achètent presque autant. La consommation baisse peu, et comme les quantités restent élevées, la taxe **rapporte beaucoup**."}$exo$::jsonb),
  ('5aa28b76-f2e0-570c-a092-2ab1bcdb1437'::uuid, 1, 'redaction', $exo${"titre":"Une défaillance de marché","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Explique, en trois étapes, pourquoi une entreprise qui rejette du dioxyde de carbone produit **trop** et **trop bon marché**.\n2. Comment appelle-t-on cette situation ?\n3. Présente les **trois instruments** de la politique environnementale, avec leur principe et un exemple chacun.","bareme":[{"critere":"Raisonnement en étapes : coût non payé, externalité négative, prix trop bas et quantité trop élevée","points":7},{"critere":"Défaillance de marché nommée","points":3},{"critere":"Réglementation, taxation, marché de quotas : principe et exemple pour chacun","points":10}],"dureeMin":7,"corrige":"1. L'entreprise rejette du CO2 mais **ne paie pas** le coût du réchauffement ; ce coût est **supporté par tous** : c'est une **externalité négative** ; le prix de son produit ne l'intègre pas, il est donc **trop bas**, et la quantité produite **trop élevée**.\n2. C'est une **défaillance de marché** : le marché aboutit à un résultat que personne n'a voulu.\n3. La **réglementation** interdit ou plafonne (normes d'émission, pesticides interdits, zones à faibles émissions). La **taxation** renchérit le comportement polluant selon le principe **pollueur-payeur** (taxe carbone, malus automobile). Le **marché de quotas** fixe un plafond d'émissions et laisse s'échanger les droits (marché carbone européen)."}$exo$::jsonb),
  ('5aa28b76-f2e0-570c-a092-2ab1bcdb1437'::uuid, 2, 'redaction', $exo${"titre":"Moins de voitures en centre-ville","consigne":"Lis la situation, puis réponds en comparant les instruments du cours.","enonce":"**Situation (ville imaginaire).**\n\n> Le conseil municipal de Villebrune veut réduire la pollution de l'air due aux voitures. Trois propositions sont sur la table :\n> - **P1** : interdire aux véhicules les plus anciens d'entrer dans le centre ;\n> - **P2** : faire payer chaque entrée dans le centre selon le niveau d'émission du véhicule ;\n> - **P3** : fixer un nombre maximal de vignettes d'accès par an, que les entreprises de livraison peuvent s'échanger entre elles.\n\n1. Associe chaque proposition à un **instrument** de la politique environnementale.\n2. Pour P1 et P2, donne une **force** et une **faiblesse** selon le cours.\n3. Avec P3, qu'est-ce qui est fixé, et qu'est-ce qui s'ajuste ?","bareme":[{"critere":"P1 réglementation, P2 taxation (pollueur-payeur), P3 marché de quotas","points":6},{"critere":"Forces et faiblesses exactes de la réglementation et de la taxe","points":8},{"critere":"Quotas : la quantité est fixée, le prix résulte des échanges ; conditions (prix suffisant, allocation équitable)","points":6}],"dureeMin":11,"corrige":"1. **P1** : **réglementation** (interdire, comme une zone à faibles émissions). **P2** : **taxation**, selon le principe **pollueur-payeur**. **P3** : **marché de quotas**.\n2. **P1** : force : **simple à comprendre** ; faiblesse : **peu souple** (même règle pour tous) et **coûteuse à contrôler**. **P2** : force : **efficace** et elle **rapporte des recettes** ; faiblesse : elle peut être **régressive**, pesant plus lourd sur les ménages modestes, qui ont souvent des véhicules plus anciens.\n3. Avec P3, c'est la **quantité** (le plafond de vignettes) qui est **fixée** : le plafond est garanti. Le **prix** des vignettes **s'ajuste** selon les échanges entre entreprises. Pour que cela fonctionne, il faut un prix suffisant et une **allocation initiale équitable** des vignettes."}$exo$::jsonb),
  ('5aa28b76-f2e0-570c-a092-2ab1bcdb1437'::uuid, 3, 'redaction', $exo${"titre":"Efficace, mais acceptée ?","consigne":"Analyse le document, puis rédige. La dernière question attend un paragraphe argumenté.","enonce":"**Document (données imaginaires).** Part du revenu consacrée aux carburants et coût d'une hausse de la taxe carbone.\n\n| Ménage | Revenu mensuel | Dépense en carburant | Coût de la hausse de taxe |\n| Ménage rural modeste | 1 600 € | 160 € | 16 € par mois |\n| Ménage urbain aisé | 6 000 € | 120 € | 12 € par mois |\n\n1. Calcule, pour chaque ménage, la part de son revenu consacrée au carburant, puis la part du revenu que représente la hausse de la taxe.\n2. En quoi ce document illustre-t-il le caractère **régressif** d'une taxe environnementale ?\n3. Quel mouvement social de 2018 est né en partie d'une hausse des taxes sur les carburants ?\n4. En un paragraphe argumenté, explique pourquoi une politique environnementale **efficace** n'est pas nécessairement **acceptée**, et présente les **leviers** qui peuvent la rendre acceptable.","bareme":[{"critere":"Calculs justes : 10 % et 2 % du revenu en carburant ; 1 % et 0,2 % pour la hausse","points":6},{"critere":"Régressivité expliquée : la taxe pèse plus lourd sur les ménages modestes","points":4},{"critere":"Gilets jaunes, 2018","points":2},{"critere":"Paragraphe : efficacité de la taxe, rejet possible, trois leviers (compensations, alternatives, affectation visible)","points":8}],"dureeMin":17,"corrige":"1. Ménage rural modeste : 160 / 1 600 × 100 = **10 %** du revenu en carburant ; hausse : 16 / 1 600 × 100 = **1 %** du revenu. Ménage urbain aisé : 120 / 6 000 × 100 = **2 %** ; hausse : 12 / 6 000 × 100 = **0,2 %**.\n2. La taxe coûte en euros un montant proche aux deux ménages, mais elle représente une part du revenu **cinq fois plus forte** pour le ménage modeste (1 % contre 0,2 %). Son incidence est **régressive** : elle pèse plus lourd sur les ménages modestes, qui dépendent davantage de la voiture.\n3. Le mouvement des **gilets jaunes**, en **2018**.\n4. Paragraphe attendu : une taxe carbone est **efficace** : elle renchérit le comportement polluant (pollueur-payeur) et rapporte des recettes. Mais si elle frappe surtout ceux qui n'ont pas d'autre choix que la voiture, elle est vécue comme **injuste** et peut être rejetée, comme en 2018. Pour la rendre acceptable : des **compensations** qui protègent les ménages modestes ; des **alternatives disponibles** (transports en commun, aides pour changer de véhicule) qui rendent le changement possible ; une **affectation visible** des recettes, qui montre à quoi sert la taxe. On peut aussi comparer avec la réglementation (simple mais peu souple) et les quotas (plafond garanti)."}$exo$::jsonb),
  ('52ea8d1e-7aca-575d-9c1a-3319e3e8b0e5'::uuid, 1, 'redaction', $exo${"titre":"Normes, valeurs et rôles","consigne":"Réponds à chaque question par des phrases complètes, en donnant un exemple quand c'est demandé.","enonce":"1. Définis la **socialisation**.\n2. Définis une **norme**, une **valeur** et un **rôle**, et donne un exemple de chacun.\n3. Distingue la socialisation **primaire** et la socialisation **secondaire** : quand ont-elles lieu, que façonnent-elles ?","bareme":[{"critere":"Socialisation : processus d'intériorisation des normes, valeurs et rôles","points":4},{"critere":"Norme, valeur, rôle définis avec un exemple cohérent pour chacun","points":9},{"critere":"Primaire (enfance, la plus durable) et secondaire (âge adulte) distinguées avec exemples","points":7}],"dureeMin":6,"corrige":"1. La **socialisation** est le processus par lequel un individu **intériorise** les normes, les valeurs et les rôles de la société où il vit.\n2. Une **norme** est une **règle de comportement** (ex. : dire bonjour, lever la main en classe). Une **valeur** est un **idéal partagé** qui justifie les normes (ex. : la politesse, le respect d'autrui). Un **rôle** est l'ensemble des **comportements attendus d'une position sociale** (ex. : ce qu'on attend d'un élève, d'un parent, d'un médecin).\n3. La socialisation **primaire** a lieu dans l'**enfance** : elle façonne la langue, les manières, les goûts, les repères moraux ; c'est la plus **intense** et la plus **durable**. La socialisation **secondaire** a lieu à l'**âge adulte** : monde professionnel, couple, associations, partis. Elle peut compléter la première ou entrer en tension avec elle."}$exo$::jsonb),
  ('52ea8d1e-7aca-575d-9c1a-3319e3e8b0e5'::uuid, 2, 'redaction', $exo${"titre":"Comment Noé apprend","consigne":"Lis la situation, puis réponds en mobilisant les notions du cours.","enonce":"**Situation (inventée).**\n\n> Noé a 7 ans. À table, ses parents lui répètent : « On ne parle pas la bouche pleine », et le privent de dessert quand il oublie. Il ne s'en rend pas compte, mais il parle déjà avec les mêmes expressions que son père et soutient la même équipe de football que lui. À l'école, la maîtresse félicite les élèves qui rangent leur matériel. Le soir, il regarde des dessins animés.\n\n1. Relève les **instances de socialisation** présentes dans le texte.\n2. Relève un exemple d'**inculcation explicite** et un exemple d'**imprégnation implicite**. Justifie.\n3. Laquelle de ces deux transmissions est souvent la plus puissante ? Pourquoi ?","bareme":[{"critere":"Trois instances relevées : famille, école, médias","points":5},{"critere":"Inculcation (règle énoncée, sanction, félicitation) et imprégnation (imitation des expressions, de l'équipe) justifiées","points":9},{"critere":"Imprégnation la plus puissante car invisible ; ce qui est intériorisé n'est plus ressenti comme une contrainte","points":6}],"dureeMin":10,"corrige":"1. La **famille** (les parents), l'**école** (la maîtresse), les **médias** (dessins animés).\n2. **Inculcation explicite** : « On ne parle pas la bouche pleine », avec la **sanction** (pas de dessert) ; ou la maîtresse qui **récompense** les élèves qui rangent. On énonce la règle, on récompense, on sanctionne. **Imprégnation implicite** : Noé reprend les **expressions** de son père et soutient la **même équipe**, sans qu'on le lui ait demandé : par **imitation** et **exposition répétée**.\n3. L'**imprégnation implicite** est souvent la plus puissante, parce qu'elle **ne se voit pas** : Noé ne se rend pas compte de ce qu'il apprend. Ce qui est intériorisé cesse d'être ressenti comme une contrainte : on ne se force pas, on le fait."}$exo$::jsonb),
  ('52ea8d1e-7aca-575d-9c1a-3319e3e8b0e5'::uuid, 3, 'redaction', $exo${"titre":"Entre la famille et les amis","consigne":"Analyse le document et rédige des réponses argumentées. La dernière question attend un paragraphe structuré.","enonce":"**Document (témoignage imaginaire).**\n\n> « Chez moi, on m'a toujours dit que les études passaient avant tout, et on ne regardait presque pas la télé. Au collège, mes amis trouvaient ridicule de trop travailler, et sur les réseaux sociaux on ne voyait que des influenceurs qui gagnaient de l'argent sans diplôme. J'ai gardé le goût de la lecture de mes parents, mais j'ai adopté la façon de parler de mes amis. Aujourd'hui, je suis entrée en école d'infirmière : j'apprends un vocabulaire, des gestes et une manière de me tenir avec les patients que je ne connaissais pas. » — Chloé, 19 ans\n\n1. Identifie dans le document des exemples de socialisation **primaire** et **secondaire**.\n2. Montre que les **instances de socialisation** peuvent transmettre des messages **contradictoires**.\n3. Relève ce qui montre que Chloé n'est pas un **réceptacle passif**.\n4. En un paragraphe argumenté, explique pourquoi la socialisation n'est pas un simple dressage, en t'appuyant sur le document et sur le cours.","bareme":[{"critere":"Primaire (famille, goût de la lecture) et secondaire (école d'infirmière, rôle professionnel) identifiées","points":5},{"critere":"Messages contradictoires : famille contre pairs et médias","points":4},{"critere":"Chloé compose : elle garde la lecture, adopte le langage des amis","points":4},{"critere":"Paragraphe : intériorisation, instances multiples, individu qui sélectionne et compose, primaire durable mais secondaire possible","points":7}],"dureeMin":17,"corrige":"1. **Primaire** : dans l'enfance, la **famille** transmet l'importance des études et le **goût de la lecture** ; les **pairs** au collège aussi. **Secondaire** : en école d'infirmière, Chloé apprend un **vocabulaire**, des **gestes**, une manière de se tenir : un **rôle professionnel**, à l'âge adulte.\n2. La **famille** valorise les études, alors que les **groupes de pairs** trouvent ridicule de trop travailler et que les **médias** (réseaux sociaux) montrent la réussite sans diplôme : les instances envoient des messages **contradictoires**.\n3. Chloé **sélectionne** : elle garde le goût de la lecture de ses parents mais adopte la façon de parler de ses amis. Elle **compose** entre les influences.\n4. Paragraphe attendu : la socialisation est l'**intériorisation** de normes, valeurs et rôles, par **inculcation** et surtout par **imprégnation**. Mais elle passe par des **instances multiples** (famille, école, pairs, médias, travail) qui ne disent pas toutes la même chose ; l'individu n'est donc pas un réceptacle passif : il **sélectionne**, **réinterprète**, parfois **résiste**. La socialisation **primaire** est la plus durable, mais la **secondaire** peut la compléter ou entrer en tension avec elle. C'est un processus continu, pas un dressage une fois pour toutes."}$exo$::jsonb),
  ('c9e03eea-0b56-5737-953a-7afef2745dfe'::uuid, 1, 'redaction', $exo${"titre":"L'identité sociale","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Définis l'**identité sociale**. Est-elle figée ? entièrement choisie ?\n2. Distingue le **groupe d'appartenance** et le **groupe de référence**, avec un exemple.\n3. Qu'est-ce qu'un **conflit de rôles** ? Donne un exemple.","bareme":[{"critere":"Identité sociale définie, construite dans l'interaction, ni figée ni entièrement choisie","points":7},{"critere":"Groupes d'appartenance et de référence distingués avec exemple","points":7},{"critere":"Conflit de rôles défini avec un exemple pertinent","points":6}],"dureeMin":6,"corrige":"1. L'**identité sociale** est la manière dont un individu **se définit**, et **est défini par les autres**, à partir de ses **appartenances**. Elle n'est **ni figée ni entièrement choisie** : elle se construit dans l'**interaction**, à travers le regard des autres.\n2. Le **groupe d'appartenance** est celui auquel on appartient effectivement ; le **groupe de référence** est celui auquel on **aspire** et dont on adopte les manières. Ex. : un lycéen appartient à sa classe (appartenance) mais imite les joueurs professionnels de son sport (référence).\n3. Un **conflit de rôles** apparaît quand des appartenances **s'opposent** : les attentes liées à deux positions sont contradictoires. Ex. : une mère de famille cadre dont l'entreprise exige une réunion tardive le soir du spectacle de son enfant (exigences professionnelles contre familiales)."}$exo$::jsonb),
  ('c9e03eea-0b56-5737-953a-7afef2745dfe'::uuid, 2, 'redaction', $exo${"titre":"Le parcours de Karim","consigne":"Lis la situation, puis réponds en mobilisant les notions du cours.","enonce":"**Situation (inventée).**\n\n> Karim, fils d'agriculteurs d'un petit village, vient d'entrer en école de commerce. Dès la terminale, il s'était mis à lire la presse économique et à s'habiller comme les étudiants qu'il voyait sur les brochures. Aujourd'hui, il est à la fois étudiant, joueur dans le club de rugby de son village et aide ses parents à la ferme pendant les vacances. Pendant la période des récoltes, ses partiels tombent en même temps.\n\n1. Quel processus Karim a-t-il connu en terminale ? Justifie.\n2. Relève ses **appartenances multiples**. Quel est son **groupe de référence** en terminale ?\n3. Identifie la situation de **conflit de rôles** dans le texte et explique-la.","bareme":[{"critere":"Socialisation anticipatrice identifiée : adoption à l'avance des codes d'un groupe visé","points":7},{"critere":"Appartenances relevées (étudiant, rugbyman, fils d'agriculteurs, villageois) et groupe de référence (étudiants d'école de commerce)","points":6},{"critere":"Conflit de rôles : récoltes contre partiels, attentes contradictoires expliquées","points":7}],"dureeMin":10,"corrige":"1. Karim a connu une **socialisation anticipatrice** : il a adopté **d'avance** les codes (lectures, tenue) d'un groupe qu'il souhaitait rejoindre, celui des étudiants d'école de commerce.\n2. Appartenances : **étudiant** en école de commerce, **joueur de rugby** du club local, **fils d'agriculteurs**, habitant d'un **village**. En terminale, son **groupe de référence** est celui des **étudiants d'école de commerce** : il y aspire et en adopte les manières.\n3. Pendant les récoltes, ses parents attendent son aide à la ferme (rôle de fils), tandis que son école attend qu'il réussisse ses partiels (rôle d'étudiant). Ces deux attentes sont **contradictoires** : c'est un **conflit de rôles**, dû à des appartenances qui s'opposent."}$exo$::jsonb),
  ('c9e03eea-0b56-5737-953a-7afef2745dfe'::uuid, 3, 'redaction', $exo${"titre":"L'habitus et l'orientation","consigne":"Analyse le document, puis rédige des réponses argumentées. La dernière question attend un paragraphe structuré.","enonce":"**Document (témoignages imaginaires).**\n\n> **Clara**, 15 de moyenne, fille de deux professeurs : « La prépa ? Évidemment. Tout le monde en parle à la maison, je me vois bien là-bas. »\n>\n> **Enzo**, 15 de moyenne, fils d'un chauffeur-livreur : « Une prépa, c'est pour les autres. Je ne m'y sentirais pas à ma place. Je vais faire un BTS, c'est plus sûr. »\n\n1. Qu'est-ce que l'**habitus** selon Pierre Bourdieu ?\n2. En quoi ces deux témoignages illustrent-ils la notion d'habitus ?\n3. Qu'est-ce qu'une **resocialisation** ? Donne deux exemples du cours et explique en quoi elle diffère de la socialisation anticipatrice.\n4. En un paragraphe argumenté, montre que l'identité sociale dépend de la **trajectoire** mais qu'elle peut **changer**.","bareme":[{"critere":"Habitus : dispositions incorporées qui orientent les pratiques sans y penser","points":4},{"critere":"Application : notes égales, choix différents selon ce que chacun juge possible pour lui","points":5},{"critere":"Resocialisation définie, deux exemples (armée, conversion, immigration, changement de milieu), différence avec l'anticipatrice","points":5},{"critere":"Paragraphe : dispositions durables, reproduction partielle des positions, identités multiples, processus de changement","points":6}],"dureeMin":18,"corrige":"1. L'**habitus** est un ensemble de **dispositions incorporées** (goûts, façons de parler, rapport à l'école, ambitions) qui **orientent les pratiques** sans que l'individu ait besoin d'y penser.\n2. Clara et Enzo ont les **mêmes notes** mais ne demandent pas la même orientation. Clara se sent **à sa place** en prépa : son milieu lui a transmis une familiarité avec ces études. Enzo juge que « c'est pour les autres » : ses dispositions socialisées orientent ce qu'il juge **possible** pour lui. C'est ainsi que se **reproduisent en partie** les positions sociales.\n3. La **resocialisation** est une **transformation profonde** de l'identité : entrée à l'**armée**, **conversion**, **immigration**, changement radical de milieu professionnel. La socialisation anticipatrice consiste seulement à adopter **d'avance** les codes d'un rôle futur, sans rupture aussi profonde.\n4. Paragraphe attendu : la socialisation transmet des **dispositions durables** (l'habitus) qui orientent nos choix et reproduisent en partie les positions sociales : notre identité dépend donc de notre **trajectoire**. Mais elle n'est pas figée : elle se construit dans l'**interaction**, chacun cumule des **appartenances multiples** qui peuvent se renforcer ou s'opposer, et des processus comme la **socialisation anticipatrice** ou la **resocialisation** la transforment."}$exo$::jsonb),
  ('24604193-0057-5f52-a210-9ca28202a90e'::uuid, 1, 'redaction', $exo${"titre":"Sexe, genre et socialisation","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Distingue le **sexe** et le **genre**.\n2. Cite trois **vecteurs** de la socialisation différenciée selon le genre.\n3. Pourquoi peut-on affirmer que les écarts entre femmes et hommes (orientation, travail domestique) ne sont pas **naturels** ?","bareme":[{"critere":"Sexe biologique / genre construction sociale (rôles et attributs associés au masculin et au féminin)","points":6},{"critere":"Trois vecteurs : couleurs, jouets, vocabulaire ; tolérance à l'agitation ou à l'émotion ; école, manuels, médias, pairs","points":7},{"critere":"Argument de la variation selon les époques et les pays","points":7}],"dureeMin":6,"corrige":"1. Le **sexe** désigne les **caractéristiques biologiques**. Le **genre** désigne les **rôles et attributs socialement associés** au masculin et au féminin : c'est une construction sociale.\n2. Trois parmi : les **couleurs**, les **jouets**, le **vocabulaire** dès la naissance ; la **tolérance** différente à l'**agitation** ou à l'**émotion** selon le sexe de l'enfant ; l'**école**, les **manuels**, les **médias**, les **pairs**, qui prolongent la différenciation.\n3. Ces écarts **varient selon les époques et les pays**. Si le partage des tâches ou les choix d'orientation étaient biologiques, ils seraient **les mêmes partout** : leur variation prouve qu'ils sont **sociaux**."}$exo$::jsonb),
  ('24604193-0057-5f52-a210-9ca28202a90e'::uuid, 2, 'redaction', $exo${"titre":"Des jouets et des filières","consigne":"Analyse le document, puis réponds en mobilisant le cours.","enonce":"**Document (lycée imaginaire).** Répartition des élèves de terminale selon deux spécialités.\n\n| Spécialité | Filles | Garçons |\n| Humanités, littérature et philosophie | 78 % | 22 % |\n| Numérique et sciences informatiques | 14 % | 86 % |\n\n**Situation.** Dans un magasin, le rayon « filles » propose poupées, dînettes et kits de maquillage ; le rayon « garçons » propose jeux de construction, robots et voitures.\n\n1. Fais une phrase donnant la signification du chiffre 14 %.\n2. Montre comment les jouets participent à la **socialisation de genre** : quelles activités et compétences valorisent-ils ?\n3. Fais le lien entre cette socialisation et les écarts d'orientation du document. Quels autres effets de la socialisation différenciée le cours mentionne-t-il ?","bareme":[{"critere":"Lecture exacte : dans ce lycée, 14 % des élèves de la spécialité NSI sont des filles","points":4},{"critere":"Jouets : activités domestiques et apparence pour les filles, technique et construction pour les garçons","points":7},{"critere":"Lien avec l'orientation et autres effets (travail domestique, carrières)","points":9}],"dureeMin":10,"corrige":"1. Dans ce lycée, parmi les élèves de terminale suivant la spécialité numérique et sciences informatiques, **14 %** sont des **filles**.\n2. Les jouets orientent les activités : pour les filles, le soin, la cuisine, l'**apparence** (poupées, dînettes, maquillage) ; pour les garçons, la **technique**, la **construction**, la mécanique (jeux de construction, robots, voitures). Ils valorisent des **compétences différentes** et transmettent dès l'enfance des rôles associés au féminin et au masculin : c'est un **vecteur** de la socialisation de genre.\n3. Des enfants habitués très tôt à des activités différentes développent des goûts et des aptitudes différents et jugent certaines filières « faites pour eux » : les filles sont **majoritaires** en filières littéraires (78 %) et **très minoritaires** en informatique (14 %), comme dans le cours. Autres effets : une **répartition inégale du travail domestique** et des **carrières** à la progression et à la rémunération différentes."}$exo$::jsonb),
  ('24604193-0057-5f52-a210-9ca28202a90e'::uuid, 3, 'redaction', $exo${"titre":"Socialisation et reproduction sociale","consigne":"Rédige un développement argumenté et organisé, avec une introduction, deux parties et une conclusion.","enonce":"**Sujet.** Montrez que la socialisation différenciée selon le **milieu social** contribue à la **reproduction sociale**, sans la rendre inévitable.\n\n**Document (témoignage imaginaire d'une enseignante de CP).**\n\n> « Certains enfants arrivent en connaissant déjà des mots comme “bibliothèque” ou “musée”, ils ont l'habitude qu'on leur lise une histoire le soir et ils posent des questions sans crainte. D'autres sont plus silencieux, ils n'osent pas. Pourtant, chaque année, quelques-uns de ces élèves discrets deviennent les meilleurs de la classe. »\n\nTu t'appuieras sur le document et sur les notions de **capital culturel**, de pratiques éducatives et de **mobilité**.","bareme":[{"critere":"Introduction : socialisation différenciée et reproduction sociale définies","points":3},{"critere":"Pratiques éducatives qui varient selon le milieu (langage, lecture, loisirs, rapport à l'autorité et à l'école) reliées au document","points":5},{"critere":"Capital culturel de Bourdieu : familiarité avec la culture scolaire qui avantage sans règle écrite","points":5},{"critere":"Effets : réussite scolaire, pratiques culturelles, aspirations ; limite : reproduction jamais totale, mobilité","points":5},{"critere":"Organisation et conclusion","points":2}],"dureeMin":20,"corrige":"**Introduction.** La socialisation n'est pas uniforme : elle **différencie** selon le milieu social. La **reproduction sociale** est la tendance des positions sociales à se **transmettre** d'une génération à l'autre.\n\n**1. Une socialisation qui avantage certains enfants.** Les pratiques éducatives varient selon la position sociale : rapport au **langage** (vocabulaire, formes de l'échange), à la **lecture** (histoire du soir), aux **loisirs** (musée, bibliothèque), à l'**autorité** et à l'**école** (confiance ou distance). Le document le montre : certains enfants arrivent avec le vocabulaire et l'aisance attendus par l'école. Les familles de cadres transmettent souvent cette familiarité avec la culture scolaire, le **capital culturel** de **Bourdieu**, qui avantage leurs enfants **sans qu'aucune règle ne le prévoie**. Il en résulte des inégalités de **réussite scolaire** à compétences comparables, des **pratiques culturelles** distinctes et des **aspirations** différentes : c'est un mécanisme central de la **reproduction sociale**.\n\n**2. Une reproduction qui n'est jamais totale.** Le document le rappelle : des élèves discrets deviennent les meilleurs. La socialisation passe par plusieurs instances (école, pairs, médias) et l'individu compose ; la **mobilité sociale existe**.\n\n**Conclusion.** La socialisation différenciée pèse lourdement sur les destins scolaires et sociaux, mais elle rend la reproduction probable, non inévitable."}$exo$::jsonb),
  ('774f4dad-c5f7-5246-9004-37176c8e7ff3'::uuid, 1, 'redaction', $exo${"titre":"Les critères de la démocratie","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Cite au moins **cinq critères** d'un régime démocratique.\n2. Définis l'**État de droit**.\n3. Présente les **trois formes** de démocratie, avec un exemple de chacune.","bareme":[{"critere":"Cinq critères justes parmi les six du cours","points":8},{"critere":"État de droit : chacun, gouvernants compris, soumis à la loi","points":4},{"critere":"Démocratie directe, représentative, participative avec exemples","points":8}],"dureeMin":7,"corrige":"1. La **souveraineté du peuple** ; des **élections libres, régulières, pluralistes** au **suffrage universel** ; la **séparation des pouvoirs** (exécutif, législatif, judiciaire) ; les **libertés fondamentales** (expression, presse, réunion, association) ; l'**État de droit** ; le respect des **minorités**.\n2. L'**État de droit** est un système où **chacun, gouvernants compris**, est **soumis à la loi**.\n3. **Directe** : les citoyens décident eux-mêmes (référendum, certains cantons suisses). **Représentative** : des **élus** décident (la forme dominante, ex. le Parlement). **Participative** : les citoyens participent entre deux élections (consultations, **budgets participatifs**, conventions citoyennes tirées au sort)."}$exo$::jsonb),
  ('774f4dad-c5f7-5246-9004-37176c8e7ff3'::uuid, 2, 'redaction', $exo${"titre":"Des élections sans démocratie","consigne":"Lis le document, puis réponds en t'appuyant sur les critères du cours.","enonce":"**Document (pays imaginaire).**\n\n> En Valdorie, le président est réélu tous les cinq ans avec plus de 90 % des voix. Les deux principaux opposants ont été emprisonnés avant le scrutin, sur décision d'un juge nommé par le président. Les trois journaux indépendants ont été fermés. Le Parlement vote toutes les lois proposées par le gouvernement, sans débat.\n\n1. La Valdorie organise des élections : est-elle pour autant une démocratie ? Relève au moins **quatre critères** qui ne sont pas respectés.\n2. Explique la phrase : « Une élection sans alternance possible n'est pas une élection. »\n3. Quel nom le cours donne-t-il à ce type de régime ? Quel rôle jouent les **contre-pouvoirs** qui y ont été affaiblis ?","bareme":[{"critere":"Quatre critères manquants identifiés avec les indices du texte","points":8},{"critere":"Élire, c'est aussi pouvoir renvoyer ; pas d'alternance sans opposition libre","points":5},{"critere":"Régime hybride ; contre-pouvoirs (justice, presse, Parlement) et ce qu'ils empêchent","points":7}],"dureeMin":10,"corrige":"1. Non. Critères non respectés : des élections **pluralistes et libres** (opposants emprisonnés) ; la **séparation des pouvoirs** (juge nommé par le président, Parlement qui vote sans débat) ; les **libertés fondamentales**, dont la **liberté de la presse** (journaux fermés) ; l'**État de droit** (la justice sert le pouvoir) ; le respect des **minorités** et de l'opposition.\n2. Élire, ce n'est pas seulement désigner, c'est aussi **pouvoir renvoyer** les gouvernants. Si l'opposition ne peut pas se présenter, les électeurs n'ont pas de choix réel : le vote ne permet aucune **alternance**, il n'est qu'une façade.\n3. Un **régime hybride** : il garde les élections en vidant les libertés. Les **contre-pouvoirs** empêchent la concentration du pouvoir : une **justice indépendante** empêche l'impunité, le **Parlement** la décision solitaire, la **presse libre** le secret. Leur affaiblissement est le signal de ces régimes."}$exo$::jsonb),
  ('774f4dad-c5f7-5246-9004-37176c8e7ff3'::uuid, 3, 'redaction', $exo${"titre":"Une démocratie à entretenir","consigne":"Rédige un développement argumenté, avec une introduction, deux parties et une conclusion.","enonce":"**Sujet.** « La démocratie est un régime qui doit être entretenu, non un état acquis. » Expliquez cette affirmation.\n\n**Document (situation imaginaire).**\n\n> Dans une ville moyenne, seuls 38 % des inscrits ont voté aux dernières élections municipales. Pendant la campagne, une fausse information sur un candidat a circulé massivement sur les réseaux sociaux. Pour relancer la participation, la nouvelle équipe a créé un budget participatif : les habitants votent pour des projets financés sur une part du budget de la ville.\n\nTu mobiliseras les **critères** de la démocratie, ses **fragilités** et ses **formes**.","bareme":[{"critere":"Introduction : définition de la démocratie par ses critères (pas seulement des élections)","points":3},{"critere":"Fragilités expliquées et reliées au document (abstention, désinformation, défiance, financement opaque, inégal accès à la parole)","points":6},{"critere":"Réponses : contre-pouvoirs, démocratie participative (budget participatif) à côté de la représentative","points":7},{"critere":"Organisation et conclusion nuancée","points":4}],"dureeMin":20,"corrige":"**Introduction.** Une démocratie ne se reconnaît pas seulement à la tenue d'élections : elle suppose la souveraineté du peuple, des élections libres et pluralistes, la séparation des pouvoirs, les libertés fondamentales, l'État de droit et le respect des minorités. Ces conditions peuvent s'affaiblir.\n\n**1. Des fragilités qui la menacent.** L'**abstention** (62 % d'abstentionnistes dans le document) produit une **représentation déformée** : les élus sont choisis par une minorité. La **désinformation** (la fausse information sur le candidat) **fausse le débat**. S'y ajoutent la **défiance** envers les partis et les élus, qui affaiblit la légitimité, le **financement opaque** des campagnes et l'**inégalité d'accès** à la parole publique.\n\n**2. Des moyens de l'entretenir.** Les **contre-pouvoirs** (justice indépendante, Parlement, presse libre, syndicats et associations, autorités indépendantes) empêchent la concentration du pouvoir. La **démocratie participative** complète la démocratie **représentative** : consultations, **budget participatif** (comme dans le document), conventions citoyennes tirées au sort, qui associent les citoyens entre deux élections.\n\n**Conclusion.** La démocratie n'est jamais acquise : elle vit de la participation des citoyens et de la vigueur de ses contre-pouvoirs."}$exo$::jsonb),
  ('9c0a995a-7916-5b30-a85d-24b6f6867471'::uuid, 1, 'redaction', $exo${"titre":"Les institutions de la Ve République","consigne":"Réponds à chaque question par des phrases complètes et précises.","enonce":"1. De quand date la Constitution de la Ve République ? Dans quel but a-t-elle été conçue ?\n2. Comment et pour combien de temps le **président** est-il élu ? Cite trois de ses pouvoirs.\n3. Présente les deux chambres du **Parlement** : nombre de membres, mode d'élection, durée du mandat.","bareme":[{"critere":"4 octobre 1958, stabilité de l'exécutif","points":4},{"critere":"Suffrage universel direct depuis 1962, cinq ans depuis 2000, trois pouvoirs exacts","points":8},{"critere":"Assemblée : 577 députés, uninominal majoritaire à deux tours, cinq ans ; Sénat : 348 sénateurs, suffrage indirect, six ans","points":8}],"dureeMin":7,"corrige":"1. Du **4 octobre 1958**. Elle a été conçue pour donner à l'**exécutif** une **stabilité** que la IVe République n'avait pas.\n2. Le président est élu au **suffrage universel direct** depuis **1962**, pour **cinq ans** depuis le **quinquennat** de 2000. Pouvoirs (trois parmi) : **nommer le Premier ministre**, **présider le conseil des ministres**, **dissoudre** l'Assemblée nationale, recourir au **référendum**, pouvoirs exceptionnels.\n3. L'**Assemblée nationale** : **577 députés**, élus au **scrutin uninominal majoritaire à deux tours**, pour **cinq ans**. Le **Sénat** : **348 sénateurs**, élus au **suffrage indirect** par de grands électeurs, pour **six ans**."}$exo$::jsonb),
  ('9c0a995a-7916-5b30-a85d-24b6f6867471'::uuid, 2, 'redaction', $exo${"titre":"Qui fait quoi ?","consigne":"Pour chaque situation, nomme l'institution concernée et justifie à l'aide du cours.","enonce":"**Situations (inventées ou générales).**\n\n- **A.** Après une grave crise politique, le chef de l'État décide de provoquer de nouvelles élections législatives avant la date prévue.\n- **B.** Une majorité de députés vote pour renverser le gouvernement.\n- **C.** Lors d'un procès, un avocat soutient qu'une loi appliquée à son client porte atteinte aux droits garantis par la Constitution.\n- **D.** Le Sénat et l'Assemblée nationale sont en désaccord persistant sur un projet de loi.\n\n1. Pour chaque situation, indique qui agit ou qui décide, et selon quelle règle.\n2. Explique la phrase : « Le président n'est pas responsable devant le Parlement ; le gouvernement, si. »","bareme":[{"critere":"A : dissolution par le président","points":3},{"critere":"B : gouvernement responsable devant l'Assemblée nationale","points":3},{"critere":"C : question prioritaire de constitutionnalité, Conseil constitutionnel, depuis 2008","points":4},{"critere":"D : l'Assemblée nationale a le dernier mot","points":3},{"critere":"Dissymétrie expliquée : le gouvernement peut être renversé, pas le président","points":7}],"dureeMin":11,"corrige":"1. **A** : le **président de la République**, qui peut **dissoudre** l'Assemblée nationale. **B** : l'**Assemblée nationale** : le gouvernement est **responsable devant elle**, elle peut le renverser. **C** : la **question prioritaire de constitutionnalité** (QPC), possible **depuis 2008** : le **Conseil constitutionnel** contrôle la conformité de la loi à la Constitution. **D** : en cas de désaccord persistant, l'**Assemblée nationale a le dernier mot**.\n2. Les députés peuvent **renverser le gouvernement**, mais ils ne peuvent pas renvoyer le président, élu directement par le peuple pour cinq ans. En revanche, le président peut **dissoudre** l'Assemblée. Cette **dissymétrie** donne au président une position forte et stable : toute la mécanique du régime en découle."}$exo$::jsonb),
  ('9c0a995a-7916-5b30-a85d-24b6f6867471'::uuid, 3, 'redaction', $exo${"titre":"Un régime semi-présidentiel","consigne":"Rédige des réponses argumentées. La dernière question attend un paragraphe structuré.","enonce":"**Document.**\n\n> La Ve République a connu trois cohabitations. Depuis le passage au quinquennat en 2000, et l'organisation des élections législatives juste après l'élection présidentielle, les Français élisent d'abord leur président, puis, quelques semaines plus tard, leurs députés.\n\n1. Définis la **cohabitation**. Pourquoi le **quinquennat** et l'**inversion du calendrier électoral** la rendent-ils plus improbable ?\n2. Pendant une cohabitation, qui détermine et conduit la politique de la nation ? Justifie.\n3. En un paragraphe argumenté, explique pourquoi la Ve République est dite **semi-présidentielle**, c'est-à-dire ni pleinement présidentielle ni pleinement parlementaire.","bareme":[{"critere":"Cohabitation définie ; mandats de même durée, législatives juste après la présidentielle donc majorité souvent du même camp","points":6},{"critere":"Gouvernement du Premier ministre, soutenu par la majorité de l'Assemblée devant laquelle il est responsable","points":5},{"critere":"Traits présidentiels (élection directe, pouvoirs propres, irresponsabilité) et parlementaires (gouvernement responsable, dissolution)","points":9}],"dureeMin":16,"corrige":"1. La **cohabitation** : un **président** et une **majorité parlementaire** de **camps opposés**. Avec le quinquennat, président et députés sont élus pour la même durée (cinq ans), et les législatives suivent de près la présidentielle : les électeurs donnent généralement au président élu une majorité de son camp. La cohabitation devient **plus improbable**.\n2. Le **gouvernement**, dirigé par le **Premier ministre**, **détermine et conduit la politique de la nation**. Comme il est **responsable devant l'Assemblée**, il doit être soutenu par la majorité parlementaire ; en cohabitation, le président doit donc nommer un Premier ministre issu du camp opposé.\n3. Paragraphe attendu : le régime a des traits **présidentiels** : le président est élu au **suffrage universel direct**, dispose de pouvoirs propres (nomination du Premier ministre, dissolution, référendum, pouvoirs exceptionnels) et n'est **pas responsable devant le Parlement**. Il a aussi des traits **parlementaires** : un **exécutif à deux têtes**, un **gouvernement responsable devant l'Assemblée**, qui peut le renverser, et un droit de **dissolution**. Ni pleinement présidentiel ni pleinement parlementaire, il est dit **semi-présidentiel** ; son équilibre change selon que le président dispose ou non d'une majorité (cohabitation)."}$exo$::jsonb),
  ('888e3db4-e94e-57d7-80b6-a84fde2f85d3'::uuid, 1, 'redaction', $exo${"titre":"Majoritaire ou proportionnel","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Explique le principe du scrutin **majoritaire** et celui du scrutin **proportionnel**.\n2. Pour chacun, cite une élection française où il est utilisé.\n3. Donne un **avantage** et un **inconvénient** de chaque mode de scrutin.","bareme":[{"critere":"Principes exacts des deux modes","points":6},{"critere":"Exemples : législatives ou présidentielle / européennes","points":4},{"critere":"Avantage et inconvénient justes pour chaque mode","points":10}],"dureeMin":6,"corrige":"1. **Majoritaire** : est élu celui qui a **le plus de voix**, en un ou deux tours. **Proportionnel** : les **sièges** sont répartis selon le **pourcentage de voix** de chaque liste.\n2. Majoritaire : **législatives**, **présidentielle**. Proportionnel : **européennes** (et partiellement régionales et municipales).\n3. **Majoritaire** : avantage : une **majorité claire**, la **stabilité**, le lien élu-circonscription ; inconvénient : beaucoup de **voix non représentées**, les **petits partis écrasés**. **Proportionnel** : avantage : une **représentation fidèle** de la diversité des opinions ; inconvénient : difficulté à dégager une **majorité**, **coalitions**, **instabilité**."}$exo$::jsonb),
  ('888e3db4-e94e-57d7-80b6-a84fde2f85d3'::uuid, 2, 'redaction', $exo${"titre":"Mêmes voix, deux assemblées","consigne":"Fais les calculs en détaillant, puis compare les résultats.","enonce":"**Situation (pays imaginaire).** Une assemblée de **20 sièges** est élue. Au niveau national, les voix se répartissent ainsi : parti A : **40 %** ; parti B : **35 %** ; parti C : **25 %**.\n\n- **Règle 1 (proportionnelle)** : les sièges sont répartis selon le pourcentage national de voix.\n- **Règle 2 (majoritaire à un tour)** : le pays est découpé en 20 circonscriptions ; le parti A arrive en tête dans 13 d'entre elles, le parti B dans 7, le parti C dans aucune.\n\n1. Calcule la répartition des sièges avec la règle 1.\n2. Donne la répartition des sièges avec la règle 2.\n3. Compare : quelle règle donne une **majorité absolue** à un parti ? Quelle règle représente le mieux les électeurs du parti C ?\n4. Explique la phrase : « Le majoritaire fabrique des gouvernements ; le proportionnel fabrique des représentations. »","bareme":[{"critere":"Règle 1 : A 8, B 7, C 5 sièges, calcul détaillé","points":6},{"critere":"Règle 2 : A 13, B 7, C 0","points":3},{"critere":"Comparaison : majorité absolue (11 sièges) seulement avec la règle 2 ; C représenté seulement avec la règle 1","points":5},{"critere":"Explication de la formule : stabilité contre fidélité, aucun mode ne fait les deux","points":6}],"dureeMin":11,"corrige":"1. Règle 1 : A : 40 % × 20 = **8 sièges** ; B : 35 % × 20 = **7 sièges** ; C : 25 % × 20 = **5 sièges**.\n2. Règle 2 : A : **13 sièges** ; B : **7 sièges** ; C : **0 siège**.\n3. La majorité absolue est de 11 sièges sur 20. Avec la **règle 2**, A obtient **13 sièges** : il a la majorité absolue avec seulement 40 % des voix. Avec la règle 1, aucun parti ne l'a (A n'a que 8 sièges) : il faudra une **coalition**. Les électeurs de C (25 %) ne sont représentés qu'avec la **règle 1** ; avec la règle 2, leurs voix ne donnent aucun siège.\n4. Le scrutin **majoritaire** amplifie l'avance du premier parti et lui donne une majorité **stable** pour gouverner. Le **proportionnel** reflète **fidèlement** la diversité des opinions, mais sans garantir de majorité. Avec les **mêmes bulletins**, deux règles donnent deux assemblées : aucun mode ne fait les deux à la fois, et le mode de scrutin n'est **jamais neutre**."}$exo$::jsonb),
  ('888e3db4-e94e-57d7-80b6-a84fde2f85d3'::uuid, 3, 'redaction', $exo${"titre":"Le poids des règles annexes","consigne":"Analyse la situation, fais les calculs, puis rédige un paragraphe argumenté pour la dernière question.","enonce":"**Situation (pays imaginaire).** Une assemblée de **100 sièges** est élue à la proportionnelle nationale, avec un **seuil de 5 %** des voix pour obtenir des sièges. Résultats : parti A : 40 % ; parti B : 24 % ; parti C : 16 % ; cinq petits partis, D, E, F, G et H, obtiennent chacun 4 %.\n\n1. Quels partis obtiennent des sièges ? Quel pourcentage des voix exprimées n'est pas représenté ?\n2. On répartit les 100 sièges proportionnellement aux voix des seuls partis qualifiés. Calcule le nombre de sièges de A, B et C.\n3. Cite deux autres **règles annexes** du cours et leur effet.\n4. En un paragraphe argumenté, montre que le mode de scrutin et ses règles annexes ne sont **pas un choix technique neutre**. Appuie-toi sur tes calculs et sur l'exemple des **systèmes mixtes**.","bareme":[{"critere":"A, B et C qualifiés ; D à H exclus ; 20 % des voix non représentées","points":4},{"critere":"Sièges : A 50, B 30, C 20 (calcul sur 80 % des voix)","points":5},{"critere":"Deux règles annexes avec leur effet (découpage, ordre des listes, parité)","points":4},{"critere":"Paragraphe : règles qui orientent la composition de l'assemblée, compromis des systèmes mixtes (Allemagne, municipales et régionales)","points":7}],"dureeMin":18,"corrige":"1. Seuls **A, B et C** dépassent 5 %. D, E, F, G et H (4 % chacun) n'ont **aucun siège** : 5 × 4 = **20 %** des voix exprimées ne sont pas représentées.\n2. Les partis qualifiés totalisent 40 + 24 + 16 = **80 %**. A : 40 / 80 × 100 = **50 sièges** ; B : 24 / 80 × 100 = **30 sièges** ; C : 16 / 80 × 100 = **20 sièges**. Avec 40 % des voix, A obtient la moitié des sièges : le seuil fait gagner des sièges aux partis qualifiés, surtout au premier.\n3. Deux parmi : le **découpage** des circonscriptions, qui peut être manipulé (« charcutage électoral ») ; l'**ordre des candidats** sur une liste, qui décide qui est réellement élu ; les règles de **parité**, qui modifient la composition de l'assemblée.\n4. Paragraphe attendu : avec les mêmes voix, les règles changent l'assemblée. Un **seuil** exclut les petites listes (ici 20 % des électeurs sans représentant) et renforce les grands partis ; le **découpage** peut favoriser un camp ; l'ordre de liste et la parité décident des personnes élues. Ces règles pèsent **autant que le mode de scrutin lui-même**. Les **systèmes mixtes** cherchent un compromis : l'**Allemagne** élit la moitié de ses députés au majoritaire et l'autre à la proportionnelle ; les **municipales et régionales** françaises combinent une **prime majoritaire** et une répartition proportionnelle. Choisir un mode de scrutin, c'est donc choisir entre stabilité et fidélité de la représentation : un choix **politique**."}$exo$::jsonb),
  ('45f39efe-52f9-59bf-a0d5-81abe64e8ce8'::uuid, 1, 'redaction', $exo${"titre":"Partis et groupes d'intérêt","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Cite les **quatre fonctions** d'un parti politique.\n2. Comment les partis sont-ils financés en France ?\n3. Qu'est-ce qu'un **groupe d'intérêt** ? Donne deux exemples. Comment le **lobbying** est-il encadré ?","bareme":[{"critere":"Sélectionner des candidats, élaborer des programmes, mobiliser, structurer le débat","points":8},{"critere":"Financement en partie public selon les résultats et la parité, comptes contrôlés","points":5},{"critere":"Groupe d'intérêt défini avec deux exemples, registre des représentants d'intérêts","points":7}],"dureeMin":6,"corrige":"1. **Sélectionner** des candidats ; **élaborer** des programmes ; **mobiliser** les électeurs ; **structurer** le débat public.\n2. En partie sur **fonds publics**, selon leurs **résultats électoraux** et le respect de la **parité** ; leurs **comptes sont contrôlés**.\n3. Un **groupe d'intérêt** est une organisation qui **défend des intérêts particuliers** ou une cause auprès des pouvoirs publics. Exemples : **syndicats** de salariés, **organisations patronales**, **ordres professionnels**, **ONG**, **associations d'usagers**. Le **lobbying** est encadré par un **registre des représentants d'intérêts**."}$exo$::jsonb),
  ('45f39efe-52f9-59bf-a0d5-81abe64e8ce8'::uuid, 2, 'redaction', $exo${"titre":"Participer à la vie politique","consigne":"Lis les portraits, puis réponds en mobilisant le cours.","enonce":"**Portraits (inventés).**\n\n- **Inès**, 45 ans, vote à chaque élection, mais ne fait rien d'autre.\n- **Malik**, 30 ans, milite depuis dix ans dans un parti et distribue des tracts chaque semaine.\n- **Jeanne**, 17 ans, a signé une pétition pour sauver un parc et refuse d'acheter les produits d'une marque qu'elle juge polluante.\n- **Théo**, 22 ans, ne vote plus : « De toute façon, rien ne change. »\n\n1. Pour chaque portrait, identifie la **forme de participation** et son **intensité** selon le cours.\n2. Le comportement de Théo est-il un comportement politique ? Justifie.\n3. Chez qui l'**abstention** progresse-t-elle surtout ? Théo correspond-il à ce profil ?","bareme":[{"critere":"Inès : vote ponctuel ; Malik : militantisme durable ; Jeanne : pétition et boycott, participation ciblée","points":8},{"critere":"Abstention comme comportement politique (indifférence ou protestation), ici protestation ou défiance","points":7},{"critere":"Progression chez les jeunes et les moins diplômés ; Théo jeune, diplôme non précisé","points":5}],"dureeMin":10,"corrige":"1. **Inès** : **voter**, participation **ponctuelle**. **Malik** : **adhérer, militer**, participation **durable**. **Jeanne** : **pétitionner** et **boycotter**, participation **ciblée** (elle n'a pas encore le droit de vote, mais participe déjà à la vie politique).\n2. Oui : l'**abstention** est **aussi un comportement politique**. Elle peut exprimer de l'**indifférence** ou une **protestation**. La phrase de Théo (« rien ne change ») traduit une **défiance** envers les élus, une forme de protestation.\n3. L'abstention progresse surtout chez les **jeunes** et les **moins diplômés**. Théo, 22 ans, appartient au groupe des jeunes ; le texte ne dit pas son niveau de diplôme."}$exo$::jsonb),
  ('45f39efe-52f9-59bf-a0d5-81abe64e8ce8'::uuid, 3, 'redaction', $exo${"titre":"Les acteurs du débat démocratique","consigne":"Analyse le document, puis rédige. La dernière question attend un paragraphe argumenté.","enonce":"**Document (situation imaginaire).**\n\n> Un projet de loi prévoit d'interdire un pesticide. Les syndicats d'agriculteurs rencontrent les députés pour s'y opposer, tandis qu'une ONG environnementale lance une pétition qui réunit 300 000 signatures. Les partis prennent position. Sur les réseaux sociaux, une vidéo trompeuse affirmant que « l'interdiction ferait doubler le prix du pain » est partagée des millions de fois. Un sondage indique que 60 % des Français soutiennent l'interdiction.\n\n1. Identifie les différents **acteurs** de la vie politique présents dans le document et le rôle de chacun.\n2. Quels risques les **réseaux sociaux** font-ils peser sur ce débat ?\n3. Le sondage doit-il décider de la loi ? Justifie.\n4. En un paragraphe argumenté, explique la phrase : « Une démocratie sans corps intermédiaires laisse face à face un pouvoir seul et des individus isolés. »","bareme":[{"critere":"Acteurs identifiés : groupes d'intérêt (syndicats, ONG), partis, médias et réseaux, citoyens, élus","points":5},{"critere":"Risques : désinformation, bulles de filtre, diffusion accélérée","points":4},{"critere":"Les sondages nourrissent le débat sans le décider","points":3},{"critere":"Paragraphe : rôle des partis, syndicats, associations dans la représentation et l'organisation des intérêts","points":8}],"dureeMin":17,"corrige":"1. **Groupes d'intérêt** : les **syndicats d'agriculteurs** (intérêts professionnels) font du **lobbying** auprès des députés ; l'**ONG** défend une cause. Les **partis** structurent le débat en prenant position. Les **médias** et **réseaux sociaux** diffusent l'information. Les **citoyens** participent en signant la **pétition**. Les **élus** (députés) décident.\n2. La **désinformation** (vidéo trompeuse sur le prix du pain), la **diffusion accélérée** et les **bulles de filtre**, qui enferment chacun dans les contenus qui confirment ses opinions : le débat est faussé.\n3. Non : les sondages **nourrissent le débat sans le décider**. C'est une estimation de l'opinion ; la loi est votée par les élus, qui arbitrent entre les intérêts.\n4. Paragraphe attendu : les **corps intermédiaires** (partis, syndicats, organisations patronales, associations, ONG) **organisent** les intérêts et les opinions, les **portent** auprès du pouvoir et **structurent** le débat. Sans eux, chaque citoyen serait seul face à l'État, sans moyen de peser ; le pouvoir, lui, ne rencontrerait aucune résistance organisée. Ils servent aussi de **contre-pouvoirs** et empêchent la confiscation du débat. Leur rôle est d'autant plus important quand les réseaux sociaux favorisent la désinformation."}$exo$::jsonb),
  ('cb6f3233-0a54-5a2a-b338-772ca64f0631'::uuid, 1, 'redaction', $exo${"titre":"Le capital humain","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Définis le **capital humain**. Quel économiste a formulé cette théorie ?\n2. Cite les **trois façons** d'accumuler du capital humain.\n3. Qu'est-ce que la **qualification** ? Et le **déclassement** ?","bareme":[{"critere":"Capital humain (connaissances, compétences, santé qui rendent le travail productif), Gary Becker","points":7},{"critere":"Formation initiale, expérience, formation continue","points":6},{"critere":"Qualification et déclassement définis","points":7}],"dureeMin":6,"corrige":"1. Le **capital humain** désigne les **connaissances**, les **compétences** et la **santé**, considérées comme un capital qui rend le travail **plus productif**. Théorie formulée par **Gary Becker**.\n2. La **formation initiale** (avant l'entrée dans l'emploi), l'**expérience** (en travaillant), la **formation continue** (tout au long de la carrière).\n3. La **qualification** est l'ensemble des savoirs et savoir-faire **reconnus**, par un **diplôme** ou une **convention collective**. Le **déclassement** consiste à occuper un emploi **moins qualifié** que son diplôme."}$exo$::jsonb),
  ('cb6f3233-0a54-5a2a-b338-772ca64f0631'::uuid, 2, 'redaction', $exo${"titre":"Le calcul de Yanis","consigne":"Fais les calculs en détaillant chaque étape, puis interprète-les avec le cours.","enonce":"**Situation (inventée).**\n\n> Yanis, 18 ans, hésite. Il peut travailler tout de suite comme employé de logistique pour 1 400 € net par mois. Ou il peut préparer un BTS pendant deux ans : les frais (inscription, matériel, transport) lui coûteraient 1 000 € par an, et il ne toucherait pas de salaire. Après le BTS, il pourrait espérer un salaire de 1 700 € net par mois.\n\n1. Calcule les **coûts directs** et les **coûts indirects** (le coût d'opportunité) des deux années de BTS.\n2. Calcule le gain annuel de salaire après le BTS, puis le nombre d'années nécessaire pour « rembourser » l'investissement (sans tenir compte des hausses de salaire).\n3. Quels autres **avantages** de la formation Yanis pourrait-il prendre en compte ?","bareme":[{"critere":"Coûts directs 2 000 € ; coût d'opportunité 1 400 × 12 × 2 = 33 600 € ; total 35 600 €","points":8},{"critere":"Gain annuel 300 × 12 = 3 600 € ; environ 10 ans (35 600 / 3 600 ≈ 9,9)","points":6},{"critere":"Autres avantages : risque de chômage plus faible, meilleures conditions de travail, carrière plus ascendante","points":6}],"dureeMin":11,"corrige":"1. **Coûts directs** : 1 000 × 2 = **2 000 €**. **Coûts indirects** (le **coût d'opportunité**, les salaires non perçus) : 1 400 × 12 × 2 = **33 600 €**. Coût total de l'investissement : **35 600 €**.\n2. Gain mensuel : 1 700 − 1 400 = 300 € ; gain annuel : 300 × 12 = **3 600 €**. Durée de « remboursement » : 35 600 / 3 600 ≈ **9,9 ans**, soit environ **10 ans** après le BTS. On compare bien des années d'études à des années de salaire.\n3. Le calcul ne compte que le salaire de départ. Yanis peut aussi attendre : un **risque de chômage plus faible**, de **meilleures conditions de travail**, une **carrière plus ascendante** (salaire qui progresse plus vite). Ces avantages rendent l'investissement plus rentable que ce simple calcul."}$exo$::jsonb),
  ('cb6f3233-0a54-5a2a-b338-772ca64f0631'::uuid, 3, 'redaction', $exo${"titre":"Capital humain ou signal ?","consigne":"Analyse le document, puis rédige. La dernière question attend un paragraphe argumenté.","enonce":"**Document (témoignages imaginaires).**\n\n> **Sofia**, responsable du recrutement : « Quand je reçois 200 candidatures, je ne peux pas tester tout le monde. Un master me dit que la personne a su tenir cinq ans d'études, qu'elle apprend vite. »\n>\n> **Marc**, chef d'atelier : « Nos techniciens formés en alternance sont plus efficaces dès le premier jour : ils ont appris les gestes et les logiciels du métier. »\n>\n> **Laura**, titulaire d'un master de biologie, est aujourd'hui vendeuse dans une boutique de vêtements.\n\n1. Quel témoignage illustre la théorie du **capital humain** ? Lequel illustre la théorie du **signal** ? Justifie.\n2. Quelle situation Laura vit-elle ? Définis-la.\n3. En un paragraphe argumenté, explique pourquoi on peut analyser les études comme un **investissement**, en montrant que les deux mécanismes, capital humain et signal, **coexistent** sur le marché du travail.","bareme":[{"critere":"Marc : capital humain (formation rendant plus productif) ; Sofia : signal (diplôme informant sur des qualités difficiles à observer)","points":6},{"critere":"Laura : déclassement, emploi moins qualifié que son diplôme","points":4},{"critere":"Calcul coût-avantage : coûts directs et coût d'opportunité, avantages attendus","points":5},{"critere":"Coexistence des deux mécanismes, argumentée à l'aide du document","points":5}],"dureeMin":17,"corrige":"1. **Marc** illustre le **capital humain** : la formation a rendu les techniciens **réellement plus productifs** (gestes, logiciels). **Sofia** illustre le **signal** : le diplôme **informe** l'employeur sur des qualités **difficiles à observer** (persévérance, capacité d'apprentissage), sans qu'elle vérifie les compétences précises.\n2. Laura vit un **déclassement** : elle occupe un emploi **moins qualifié** que son diplôme. La qualification ne se confond pas avec le poste occupé.\n3. Paragraphe attendu : selon **Gary Becker**, se former, c'est **investir** : on supporte des **coûts** directs (frais de scolarité, logement, matériel) et indirects (le **coût d'opportunité**, les salaires non perçus) en espérant des **avantages** futurs (salaire plus élevé, risque de chômage plus faible, meilleures conditions de travail, carrière plus ascendante). Deux mécanismes expliquent ces avantages : la formation accroît la **productivité** (capital humain, cas de Marc) et le diplôme **signale** des qualités à l'employeur (cas de Sofia). Ils **coexistent** : un même diplôme apprend un métier et trie les candidats. L'investissement n'est pas garanti : le **déclassement** (Laura) montre que le diplôme ne suffit pas toujours à obtenir un emploi à sa mesure."}$exo$::jsonb),
  ('d86f45b5-6282-5658-8d73-973c1c8461a3'::uuid, 1, 'redaction', $exo${"titre":"Qui est chômeur ?","consigne":"Réponds en justifiant chaque cas avec la définition du cours.","enonce":"1. Donne la définition d'un **chômeur** au sens du BIT, et celle de la **population active**.\n2. Les personnes suivantes sont-elles au chômage au sens du BIT ? Justifie.\n- **a.** Lou, 20 ans, étudiante à temps plein, ne cherche pas d'emploi.\n- **b.** Hugo, 35 ans, a perdu son emploi, envoie des candidatures chaque semaine et peut commencer demain.\n- **c.** Nadia, 50 ans, sans emploi, a arrêté de chercher car elle est découragée.\n3. Comment calcule-t-on le **taux de chômage** ?","bareme":[{"critere":"Définitions : sans emploi, disponible, en recherche active ; actifs occupés plus chômeurs","points":6},{"critere":"Trois cas justes et justifiés (a non, b oui, c non)","points":9},{"critere":"Taux de chômage : chômeurs / population active × 100, et non population totale","points":5}],"dureeMin":7,"corrige":"1. Un **chômeur** au sens du BIT est une personne **sans emploi**, **disponible** pour travailler et à la **recherche active** d'un emploi. La **population active** regroupe les **actifs occupés plus les chômeurs**.\n2. **a.** **Non** : Lou ne cherche pas d'emploi, elle est inactive (étudiante). **b.** **Oui** : Hugo est sans emploi, disponible et en recherche active. **c.** **Non** : Nadia ne cherche plus activement ; elle n'est pas chômeuse au sens du BIT, bien qu'elle soit sans emploi.\n3. Taux de chômage = **chômeurs / population active** × 100 (et **non** rapportés à la population totale)."}$exo$::jsonb),
  ('d86f45b5-6282-5658-8d73-973c1c8461a3'::uuid, 2, 'redaction', $exo${"titre":"Calculer et expliquer le chômage","consigne":"Fais les calculs demandés, puis justifie avec le cours.","enonce":"**Document (pays imaginaire).**\n\n| Catégorie | Nombre de personnes |\n| Population totale | 20 000 000 |\n| Actifs occupés | 9 000 000 |\n| Chômeurs (BIT) | 1 000 000 |\n\n1. Calcule la **population active**, puis le **taux de chômage**.\n2. Un journaliste écrit : « 5 % de la population est au chômage. » D'où vient son erreur ?\n3. Pour chaque cas, identifie le **type de chômage** :\n- **a.** Mehdi a démissionné pour déménager ; il cherche un poste dans sa nouvelle ville depuis trois semaines.\n- **b.** Pendant un fort ralentissement de l'activité, une usine licencie faute de commandes.\n- **c.** Une caissière perd son emploi à cause de l'installation de caisses automatiques ; les emplois créés dans la région demandent des compétences en informatique qu'elle n'a pas.","bareme":[{"critere":"Population active 10 000 000 ; taux de chômage 10 %","points":6},{"critere":"Erreur : rapporter les chômeurs à la population totale au lieu de la population active","points":4},{"critere":"a frictionnel, b conjoncturel, c structurel lié à la qualification, justifiés","points":10}],"dureeMin":10,"corrige":"1. Population active = 9 000 000 + 1 000 000 = **10 000 000**. Taux de chômage = 1 000 000 / 10 000 000 × 100 = **10 %**.\n2. Le journaliste a divisé les chômeurs par la **population totale** (1 / 20 = 5 %), qui comprend les enfants, les étudiants, les retraités. Le taux de chômage se calcule sur la **population active**.\n3. **a.** Chômage **frictionnel** : le temps de recherche entre deux emplois. **b.** Chômage **conjoncturel** : une **demande insuffisante** en période de ralentissement. **c.** Chômage **structurel** lié à la qualification : l'**automatisation** détruit surtout des emplois **routiniers** peu qualifiés, et les emplois créés demandent des qualifications qu'elle n'a pas (**inadéquation**)."}$exo$::jsonb),
  ('d86f45b5-6282-5658-8d73-973c1c8461a3'::uuid, 3, 'redaction', $exo${"titre":"Des postes vacants et des chômeurs","consigne":"Analyse le document, puis rédige. La dernière question attend un paragraphe argumenté.","enonce":"**Document (région imaginaire).**\n\n> Dans la région de Valmont, 4 000 offres d'emploi restent non pourvues : techniciens de maintenance industrielle, développeurs, aides-soignants. Au même moment, la région compte 25 000 chômeurs, dont beaucoup d'anciens employés de la grande usine textile fermée il y a deux ans, et de jeunes sortis de l'école sans diplôme. Le taux de chômage des non-diplômés y est trois fois supérieur à celui des diplômés du supérieur.\n\n1. Comment expliquer que des emplois restent **non pourvus** alors qu'il y a des chômeurs ? Nomme ce type de chômage.\n2. Pourquoi le **progrès technique** et l'**automatisation** touchent-ils surtout les moins qualifiés ?\n3. Le conseil régional hésite entre deux mesures : un grand plan de **formation** et d'**apprentissage**, ou une **relance de la demande**. Laquelle correspond le mieux à la situation ? Justifie.\n4. En un paragraphe argumenté, montre que le manque de qualifications est **une** des causes du chômage, mais pas la seule, et que les politiques doivent s'adapter à la cause.","bareme":[{"critere":"Inadéquation des qualifications, chômage structurel","points":4},{"critere":"Destruction d'emplois routiniers peu qualifiés, emplois créés plus qualifiés qui ne bénéficient pas aux mêmes personnes","points":4},{"critere":"Formation et apprentissage adaptés au chômage structurel ; relance pour le conjoncturel","points":5},{"critere":"Paragraphe : autres causes (conjoncturel, frictionnel, coût du travail) et politiques correspondantes (formation, allègements, soutien à la demande)","points":7}],"dureeMin":18,"corrige":"1. Les qualifications **recherchées** par les employeurs (maintenance, informatique, soins) ne correspondent pas aux qualifications **offertes** par les chômeurs (anciens ouvriers du textile, jeunes sans diplôme) : c'est une **inadéquation**. Il y a en même temps des postes non pourvus et des chômeurs : c'est du chômage **structurel** lié à la qualification.\n2. Le progrès technique, la numérisation et l'automatisation détruisent surtout les emplois **routiniers** peu qualifiés, faciles à confier à une machine. Les emplois créés sont **plus qualifiés** et ne bénéficient pas aux mêmes personnes. D'où un chômage des non-diplômés bien plus élevé.\n3. Le plan de **formation et d'apprentissage** : il vise le chômage **structurel** en donnant aux chômeurs les qualifications demandées. La **relance de la demande** vise le chômage **conjoncturel** ; or ici les emplois existent, c'est la qualification qui manque.\n4. Paragraphe attendu : le manque de qualifications explique qu'une économie puisse créer des emplois tout en laissant au bord de la route ceux qui n'ont pas la qualification demandée. Mais il existe d'autres causes : le chômage **conjoncturel** (demande insuffisante en ralentissement), **frictionnel** (temps de recherche entre deux emplois), et celui lié au **coût du travail** pour les emplois les moins productifs, au voisinage du salaire minimum. Les politiques diffèrent : **formation**, apprentissage, accompagnement contre le structurel ; **allègements de cotisations** sur les bas salaires et aides à la mobilité ; **soutien à la demande** contre le conjoncturel. Elles ne traitent pas le même problème."}$exo$::jsonb),
  ('369cfec7-eca8-59f5-9860-88c5614e0628'::uuid, 1, 'redaction', $exo${"titre":"Diplôme, expérience et salaire","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Décris les trois effets du **diplôme** sur le salaire au cours d'une carrière.\n2. Distingue l'**expérience** et l'**ancienneté**.\n3. Cite trois **règles collectives** qui encadrent les salaires, en précisant leur niveau.","bareme":[{"critere":"Salaire de départ croissant avec le diplôme, progression plus rapide, écart qui se creuse","points":7},{"critere":"Expérience (productivité, valeur sur le marché) / ancienneté (rémunérée par les conventions)","points":6},{"critere":"Trois règles : salaire minimum (légal), conventions collectives (branche), négociation d'entreprise, égalité femmes-hommes","points":7}],"dureeMin":6,"corrige":"1. Le **salaire de départ** croît avec le niveau de diplôme ; la **progression** est plus rapide pour les diplômés du supérieur ; l'**écart se creuse** au fil de la carrière.\n2. L'**expérience** accroît la **productivité** et la valeur du salarié sur le marché du travail. L'**ancienneté** (le temps passé dans une entreprise) est souvent **rémunérée par les conventions collectives**, indépendamment de la productivité.\n3. Trois parmi : le **salaire minimum**, plancher **légal** ; les **conventions collectives**, grilles par **branche** ; la **négociation d'entreprise**, ajustement **local** ; l'**égalité de rémunération femmes-hommes**, imposée par la **loi** pour un même travail."}$exo$::jsonb),
  ('369cfec7-eca8-59f5-9860-88c5614e0628'::uuid, 2, 'redaction', $exo${"titre":"Lire une courbe salaire-âge","consigne":"Analyse le document, puis réponds en faisant les calculs demandés.","enonce":"**Document (données imaginaires).** Salaire net mensuel moyen selon l'âge et le diplôme.\n\n| Âge | Sans diplôme | Bac + 5 |\n| 25 ans | 1 450 € | 2 300 € |\n| 35 ans | 1 650 € | 3 300 € |\n| 45 ans | 1 750 € | 4 000 € |\n| 55 ans | 1 800 € | 4 300 € |\n\n1. Calcule l'**écart** de salaire entre les deux diplômes à 25 ans et à 55 ans. Que constates-tu ?\n2. Pour les diplômés de bac + 5, calcule la hausse du salaire entre 25 et 35 ans, puis entre 45 et 55 ans. Comment évolue la **courbe salaire-âge** ?\n3. Donne une explication à cette forme de courbe, et explique pourquoi l'effet de l'âge est plus marqué pour les plus diplômés.","bareme":[{"critere":"Écarts : 850 € à 25 ans, 2 500 € à 55 ans ; l'écart se creuse","points":6},{"critere":"Hausses : + 1 000 € puis + 300 € ; forte hausse puis aplatissement","points":6},{"critere":"Explication : expérience qui accroît la productivité surtout en début de carrière, progression plus rapide des cadres","points":8}],"dureeMin":10,"corrige":"1. À 25 ans : 2 300 − 1 450 = **850 €**. À 55 ans : 4 300 − 1 800 = **2 500 €**. L'écart **se creuse** au fil de la carrière : c'est le **rendement du diplôme**.\n2. Entre 25 et 35 ans : 3 300 − 2 300 = **+ 1 000 €**. Entre 45 et 55 ans : 4 300 − 4 000 = **+ 300 €**. La courbe **monte fortement** en début de carrière, puis **s'aplatit**.\n3. En début de carrière, l'**expérience** accroît rapidement la productivité et la valeur sur le marché ; ensuite, les gains d'expérience sont plus faibles. L'**ancienneté**, rémunérée par les conventions, entretient une légère hausse. L'effet est plus marqué pour les plus diplômés (proches des **cadres**) que pour les moins diplômés (proches des **ouvriers**) : leur **progression** est plus rapide, ils accèdent à des postes de responsabilité."}$exo$::jsonb),
  ('369cfec7-eca8-59f5-9860-88c5614e0628'::uuid, 3, 'redaction', $exo${"titre":"Même diplôme, salaires différents","consigne":"Analyse la situation, puis rédige. La dernière question attend un paragraphe argumenté.","enonce":"**Situation (inventée).**\n\n> Élise et Samir ont obtenu le même diplôme d'ingénieur la même année, avec des résultats comparables. Élise travaille dans une grande entreprise de l'énergie en région parisienne ; elle a négocié son salaire à l'embauche avec l'appui d'un syndicat très présent dans son entreprise. Samir travaille dans une petite entreprise de l'agroalimentaire, dans une ville moyenne. Cinq ans plus tard, Élise gagne 30 % de plus que Samir.\n\n1. Relève dans la situation au moins **quatre déterminants** du salaire, autres que le diplôme, et explique le sens de chacun.\n2. Quel rôle jouent les **règles collectives** dans la fixation des salaires ?\n3. En un paragraphe argumenté, réponds à la question : **le salaire dépend-il seulement du diplôme ?** Tu t'appuieras sur la situation et sur le cours (rendement du diplôme, expérience, règles collectives, autres déterminants).","bareme":[{"critere":"Quatre déterminants : secteur, taille de l'entreprise, région, pouvoir de négociation, avec leur sens","points":6},{"critere":"Règles collectives : salaire minimum, conventions de branche, négociation d'entreprise","points":4},{"critere":"Paragraphe : poids réel du diplôme et de l'expérience, puis autres déterminants et rapport de force","points":10}],"dureeMin":17,"corrige":"1. Le **secteur** d'activité : certains, comme l'énergie, paient structurellement plus. La **taille** de l'entreprise : les grandes paient en moyenne davantage. La **région** : la région parisienne a un coût de la vie plus élevé et un marché du travail plus tendu. Le **pouvoir de négociation** : Élise a négocié, avec l'appui d'un **syndicat** : le salaire est aussi un **rapport de force**.\n2. Le **salaire minimum** fixe un plancher **légal** ; les **conventions collectives** fixent des grilles par **branche** (ce qui explique aussi des écarts entre secteurs) ; la **négociation d'entreprise** ajuste localement. Le salaire n'est donc pas fixé seulement entre un employeur et un salarié.\n3. Paragraphe attendu : le diplôme compte beaucoup : le **salaire de départ** croît avec le niveau de diplôme, la **progression** est plus rapide pour les diplômés du supérieur et l'écart se creuse ; l'**expérience** accroît aussi la productivité, et l'**ancienneté** est rémunérée. Mais à diplôme égal, les salaires diffèrent : le **secteur**, la **taille** de l'entreprise, la **région**, le statut public ou privé, le temps de travail et le **pouvoir de négociation** individuel ou syndical pèsent aussi, comme le montrent Élise et Samir. Le salaire dépend donc de la productivité attendue, de la rareté de la qualification, des **règles collectives** et du **rapport de force** : pas seulement du diplôme."}$exo$::jsonb),
  ('397acfda-c0ea-56f0-9307-929388ac6bce'::uuid, 1, 'redaction', $exo${"titre":"Les écarts entre femmes et hommes","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Donne l'ordre de grandeur de l'écart de salaire entre femmes et hommes en France, **en équivalent temps plein** et **à poste et profil comparables**. Pourquoi ces deux chiffres sont-ils différents ?\n2. Cite les **trois mécanismes** qui expliquent une partie de l'écart.\n3. Qu'est-ce que le **plafond de verre** ?","bareme":[{"critere":"Environ 14 % et environ 4 %, différence expliquée par les mécanismes (postes, temps partiel, métiers)","points":7},{"critere":"Temps partiel, ségrégation professionnelle, interruptions de carrière","points":7},{"critere":"Plafond de verre : obstacle invisible à l'accès des femmes aux postes de direction","points":6}],"dureeMin":7,"corrige":"1. Environ **14 %** en équivalent temps plein, environ **4 %** à poste et profil comparables. Le premier chiffre compare l'ensemble des femmes et des hommes : il inclut le fait que les femmes occupent des métiers et des postes moins rémunérés. Le second compare des personnes au même poste : il reste un écart inexpliqué par ces différences.\n2. Le **temps partiel**, très majoritairement **féminin** ; la **ségrégation professionnelle** : les femmes sont concentrées dans des **métiers moins rémunérés** ; les **interruptions de carrière**, liées aux **enfants**.\n3. Le **plafond de verre** est un **obstacle invisible** qui limite l'accès des femmes aux **postes de direction**, malgré une réussite scolaire en moyenne supérieure. Il ne figure dans aucun règlement mais produit des effets mesurables."}$exo$::jsonb),
  ('397acfda-c0ea-56f0-9307-929388ac6bce'::uuid, 2, 'redaction', $exo${"titre":"Mesurer une discrimination","consigne":"Analyse le document, fais les calculs, puis réponds en justifiant.","enonce":"**Document (test imaginaire).**\n\n> Des chercheurs ont répondu à 200 offres d'emploi de comptable en envoyant, pour chaque offre, deux CV identiques (même diplôme, même expérience, même âge), qui ne diffèrent que par le quartier de résidence du candidat : un quartier aisé, un quartier populaire. Le candidat du quartier aisé a été convoqué à 50 entretiens, celui du quartier populaire à 30.\n\n1. Calcule le **taux de réponse positive** de chaque candidat.\n2. Pourquoi les chercheurs envoient-ils des CV **identiques** sauf sur un seul critère ? Que permet de mesurer ce test ?\n3. Ce test mesure les **discriminations à l'embauche**. Cite deux autres **ressources** qui, à diplôme égal, avantagent les enfants de cadres, et explique pourquoi elles ne figurent sur aucun CV.","bareme":[{"critere":"Taux justes : 25 % et 15 %","points":5},{"critere":"Principe du test : isoler un seul critère, l'écart mesure la discrimination","points":7},{"critere":"Deux ressources parmi réseaux, information, codes des entretiens, aide financière, expliquées","points":8}],"dureeMin":10,"corrige":"1. Quartier aisé : 50 / 200 × 100 = **25 %**. Quartier populaire : 30 / 200 × 100 = **15 %**.\n2. Tous les autres éléments étant **identiques**, la seule différence entre les candidats est le **quartier** : l'écart de réponses (25 % contre 15 %) ne peut s'expliquer que par ce critère. Le test permet donc de **mesurer** une **discrimination à l'embauche**.\n3. Deux parmi : les **réseaux familiaux** (stages, contacts, recommandations) ; l'**information** sur les filières (choix mieux orientés) ; l'aisance dans les **codes des entretiens** (avantage à performance égale) ; l'**aide financière** (stages non rémunérés, mobilité possible). Elles viennent du milieu d'origine et non de la formation : elles ne figurent sur **aucun CV**, mais elles comptent dans les trajectoires. Les discriminations **s'ajoutent** à ces inégalités de ressources."}$exo$::jsonb),
  ('397acfda-c0ea-56f0-9307-929388ac6bce'::uuid, 3, 'redaction', $exo${"titre":"À diplôme égal, des carrières inégales","consigne":"Rédige un développement argumenté, avec une introduction, deux parties et une conclusion.","enonce":"**Sujet.** « Le diplôme explique beaucoup, mais pas tout. » Montrez que le **genre** et l'**origine sociale** influencent les trajectoires professionnelles à diplôme égal, puis nuancez.\n\n**Document (portraits imaginaires).**\n\n> Anna et Paul, sortis de la même école de commerce, ont été embauchés au même salaire. Dix ans plus tard, Paul dirige une équipe ; Anna, qui a pris un temps partiel après la naissance de ses deux enfants, n'a pas été promue. Dans la même promotion, Hugo, fils d'un directeur de banque, a obtenu son premier stage grâce à un ami de son père ; Rayan, fils d'un ouvrier, est devenu directeur financier après des années de formation continue.\n\nTu mobiliseras au moins quatre notions du cours.","bareme":[{"critere":"Introduction : le diplôme compte, mais les carrières diffèrent selon le sexe et le milieu d'origine","points":2},{"critere":"Genre : temps partiel, interruptions de carrière, ségrégation professionnelle, plafond de verre, écarts de 14 % et 4 %","points":6},{"critere":"Origine sociale : réseaux, information, codes, aide financière ; discriminations mesurées par des tests","points":6},{"critere":"Nuance : mobilité sociale existante (exemple de Rayan), reproduction plus forte aux extrémités, remèdes (parité, index d'égalité)","points":4},{"critere":"Organisation et conclusion","points":2}],"dureeMin":20,"corrige":"**Introduction.** Le diplôme est un déterminant majeur de la carrière, mais à niveau de formation identique, les carrières diffèrent selon le **sexe** et le **milieu d'origine**.\n\n**1. Le poids du genre.** L'écart de salaire entre femmes et hommes est d'environ **14 %** en équivalent temps plein, et d'environ **4 %** à poste et profil comparables. Il s'explique par le **temps partiel**, très majoritairement féminin, les **interruptions de carrière** liées aux enfants (cas d'Anna) et la **ségrégation professionnelle**. Les femmes accèdent aussi moins souvent aux postes de direction : c'est le **plafond de verre**, obstacle invisible mais mesurable.\n\n**2. Le poids de l'origine sociale.** À diplôme égal, les enfants de cadres accèdent plus souvent aux positions élevées grâce à des ressources qui ne figurent sur aucun CV : **réseaux familiaux** (le stage d'Hugo), **information** sur les filières, aisance dans les **codes** des entretiens, **aide financière**. Les **discriminations à l'embauche**, mesurées par des **tests**, s'y ajoutent.\n\n**Nuance.** La **mobilité sociale existe** : beaucoup d'enfants occupent une position différente de celle de leurs parents, notamment grâce à la hausse du niveau de diplôme (Rayan, par la formation continue). Mais la **reproduction** reste forte, surtout aux deux extrémités de l'échelle. Des remèdes sont tentés : lois sur la **parité** dans les conseils d'administration, **index d'égalité professionnelle**.\n\n**Conclusion.** Le diplôme ouvre des portes, mais le genre et l'origine sociale pèsent sur la manière de les franchir."}$exo$::jsonb),
  ('8c9d248b-fa2d-5956-885f-076c440901c9'::uuid, 1, 'redaction', $exo${"titre":"Ce qu'est vraiment Internet","consigne":"Réponds à chaque question par des phrases complètes, avec le vocabulaire du cours.","enonce":"1. Donne une définition d'Internet. Explique pourquoi ce n'est ni une entreprise ni un ordinateur géant.\n2. Que s'est-il passé en **1969** ? Et en **1983** ?\n3. Décris les **trois étapes** de la commutation de paquets.","bareme":[{"critere":"Définition : un réseau de réseaux qui parlent la même langue (protocoles communs), sans centre ni propriétaire","points":7},{"critere":"1969 : ARPANET relie quatre sites de recherche ; 1983 : TCP/IP devient la règle commune","points":6},{"critere":"Les trois étapes dans l'ordre : découpage en paquets, voyage indépendant, réassemblage à l'arrivée","points":7}],"dureeMin":6,"corrige":"1. Internet est un **réseau de réseaux** : des millions de réseaux locaux reliés entre eux, qui acceptent de parler la même langue, c'est-à-dire d'utiliser les mêmes **protocoles**. Ce n'est pas une entreprise (personne ne le possède) ni un ordinateur géant : il **n'a pas de centre**.\n2. En **1969**, **ARPANET** relie quatre sites américains (trois universités et un institut de recherche), avec l'objectif de faire circuler l'information même si une partie du réseau tombe. En **1983**, la famille de protocoles **TCP/IP** devient la règle commune : c'est la naissance d'Internet tel qu'on le connaît.\n3. (1) Le message est **découpé en paquets** ; (2) chaque paquet voyage **indépendamment**, par le chemin disponible ; (3) les paquets sont **réassemblés** à l'arrivée."}$exo$::jsonb),
  ('8c9d248b-fa2d-5956-885f-076c440901c9'::uuid, 2, 'redaction', $exo${"titre":"La photo de Yanis","consigne":"Lis la situation, puis réponds en justifiant avec le cours.","enonce":"**Situation.** Yanis, à Lille, envoie à sa cousine de Marseille une photo de **6 000 octets**. Le réseau la découpe en paquets de **1 500 octets** chacun.\n\n1. En combien de paquets la photo est-elle découpée ? Montre ton calcul.\n2. Pendant l'envoi, juste après le passage des deux premiers paquets, un lien du réseau tombe en panne. Que deviennent les paquets suivants ?\n3. La cousine reçoit-elle la photo complète ? Explique ce que doit faire sa machine à l'arrivée.\n4. Quel mot du cours désigne cette capacité du réseau à continuer de fonctionner malgré la panne ?","bareme":[{"critere":"Calcul juste : 6 000 / 1 500 = 4 paquets","points":4},{"critere":"Les paquets suivants empruntent un autre chemin disponible, car chacun voyage indépendamment","points":6},{"critere":"Oui, la photo arrive : les paquets, arrivés par des chemins différents, sont réassemblés","points":6},{"critere":"Le mot « résilient » (résilience) employé et relié à l'absence de centre","points":4}],"dureeMin":10,"corrige":"1. 6 000 / 1 500 = **4 paquets**.\n2. Les paquets suivants (le 3e et le 4e) ne sont pas bloqués : comme chaque paquet voyage **indépendamment**, ils **passent ailleurs**, par un autre chemin disponible, sans qu'aucune autorité centrale ait à décider quoi que ce soit.\n3. Oui, la cousine reçoit la photo complète. Les paquets ont pu arriver par des chemins différents ; sa machine les **réassemble** pour reconstituer la photo.\n4. On dit que le réseau est **résilient** : si un lien tombe, les paquets suivants passent ailleurs. Cette résilience vient de la commutation de paquets et du fait qu'**Internet n'a pas de centre**."}$exo$::jsonb),
  ('8c9d248b-fa2d-5956-885f-076c440901c9'::uuid, 3, 'redaction', $exo${"titre":"Couches, Web et courrier","consigne":"Réponds à chaque question en justifiant. La dernière question demande un court paragraphe argumenté.","enonce":"**Situation.** Léa, dans sa chambre reliée à la box par la **fibre**, envoie un **courrier électronique** (protocole SMTP) à son professeur, puis ouvre une **page web** (protocole HTTP). Ses données sont acheminées par **TCP** et adressées grâce à **IP**.\n\n1. Range chacun des éléments suivants dans l'une des quatre couches du modèle TCP/IP : la fibre, IP, TCP, SMTP, HTTP.\n2. Parmi les deux actions de Léa, laquelle utilise le Web ? Laquelle utilise Internet sans passer par le Web ? Justifie en distinguant infrastructure et application.\n3. Qui a inventé le Web, où et en quelle année ?\n4. En quelques lignes, explique pourquoi le fait qu'Internet n'ait pas de centre est à la fois un choix technique et ce qui le rend difficile à couper.","bareme":[{"critere":"Classement juste : fibre en accès réseau, IP en couche Internet, TCP en transport, SMTP et HTTP en application","points":5},{"critere":"La page web utilise le Web ; le courrier utilise Internet sans le Web ; Internet = infrastructure, Web = une application parmi d'autres","points":6},{"critere":"Tim Berners-Lee, au CERN, en 1989","points":3},{"critere":"Paragraphe : pas de centre, paquets indépendants qui contournent une panne, donc aucun point unique à couper","points":6}],"dureeMin":16,"corrige":"1. **Accès réseau** : la fibre (le support physique). **Internet** : IP (l'adressage). **Transport** : TCP (l'acheminement). **Application** : SMTP et HTTP (ce que voit l'utilisateur). Chaque couche ignore les détails des autres.\n2. L'ouverture de la **page web** (HTTP) utilise le **Web**. Le **courrier électronique** utilise Internet **sans passer par le Web** : c'est une autre application, indépendante. Internet est l'**infrastructure** ; le Web n'est qu'**une application parmi d'autres** qui l'utilise, comme le courrier ou la messagerie instantanée.\n3. Le Web a été inventé par **Tim Berners-Lee**, au **CERN**, en **1989**.\n4. Internet a été conçu sans centre : ARPANET devait faire circuler l'information même si une partie du réseau tombait. Grâce à la **commutation de paquets**, chaque paquet voyage indépendamment ; si un lien tombe, les suivants passent ailleurs. Il n'existe donc **aucun point unique** dont la coupure arrêterait tout : c'est un choix technique (la résilience), et c'est aussi ce qui rend Internet **si difficile à couper**."}$exo$::jsonb),
  ('978cc21e-6553-5062-b072-04ba7fd35319'::uuid, 1, 'redaction', $exo${"titre":"IP, TCP et DNS","consigne":"Réponds à chaque question en une ou deux phrases précises.","enonce":"1. De quoi se charge le protocole **IP** ? Qu'est-ce qu'il ne fait pas ?\n2. De quoi se charge le protocole **TCP** ? Qu'est-ce qu'il ne fait pas ?\n3. Compare **IPv4** et **IPv6** : taille des adresses et état actuel.\n4. À quoi sert le **DNS** ?","bareme":[{"critere":"IP achemine les paquets grâce aux adresses mais ne garantit pas leur arrivée ; TCP vérifie, remet dans l'ordre, redemande, mais ne choisit pas la route","points":10},{"critere":"IPv4 : 32 bits, environ 4,3 milliards, épuisées ; IPv6 : 128 bits, pratiquement illimité, en déploiement","points":6},{"critere":"Le DNS traduit un nom de domaine en adresse IP (l'annuaire d'Internet)","points":4}],"dureeMin":7,"corrige":"1. **IP** achemine les paquets grâce aux **adresses**. Il ne **garantit pas** qu'ils arrivent.\n2. **TCP** **vérifie** l'arrivée, **remet dans l'ordre** et **redemande les paquets manquants**. Il ne **choisit pas la route**. Ensemble, ils forment la pile TCP/IP.\n3. **IPv4** : adresses de **32 bits** (ex. 192.168.1.1), environ **4,3 milliards** d'adresses, aujourd'hui **épuisées**. **IPv6** : adresses de **128 bits**, nombre pratiquement **illimité**, **en déploiement**.\n4. Le **DNS** traduit un **nom de domaine** lisible en **adresse IP** : c'est l'annuaire d'Internet."}$exo$::jsonb),
  ('978cc21e-6553-5062-b072-04ba7fd35319'::uuid, 2, 'redaction', $exo${"titre":"Qui fait quoi dans le réseau ?","consigne":"Pour chaque situation, nomme l'élément ou le protocole responsable et justifie.","enonce":"**Situation.** Sofia regarde le site de son club de basket depuis son téléphone.\n\n1. Elle tape le nom du site dans la barre d'adresse. Quel service trouve l'adresse IP correspondante ?\n2. Sur le trajet, chaque équipement rencontré choisit seulement le **prochain saut** vers la destination. Comment s'appelle cet équipement ? Connaît-il le chemin complet ?\n3. Le troisième paquet de la page n'est jamais arrivé. Quel protocole s'en aperçoit et que fait-il ?\n4. Le cours dit que la pile TCP/IP sépare **deux responsabilités**. Lesquelles, et quel avantage cette séparation apporte-t-elle ?","bareme":[{"critere":"Le DNS traduit le nom de domaine en adresse IP","points":4},{"critere":"Le routeur ; il ne connaît pas le chemin complet, seulement le prochain saut","points":5},{"critere":"TCP détecte le paquet manquant et le redemande, puis remet les paquets dans l'ordre","points":5},{"critere":"IP achemine, TCP fiabilise ; on peut faire évoluer l'un sans toucher à l'autre","points":6}],"dureeMin":10,"corrige":"1. C'est le **DNS** : il traduit le nom de domaine lisible en **adresse IP**.\n2. C'est le **routeur**. Il **ne connaît pas le chemin complet** : il choisit seulement le **prochain saut** vers la destination. Deux paquets d'un même message peuvent donc suivre des chemins différents.\n3. C'est **TCP** : il vérifie l'arrivée, constate que le troisième paquet manque, le **redemande** et **remet les paquets dans l'ordre** avant de livrer la page.\n4. **IP** se charge d'**acheminer** les paquets grâce aux adresses (sans garantir leur arrivée) ; **TCP** se charge de **vérifier, remettre dans l'ordre et redemander** (sans choisir la route). Séparer les deux responsabilités permet de **faire évoluer l'une sans toucher à l'autre** : par exemple passer d'IPv4 à IPv6 sans changer TCP."}$exo$::jsonb),
  ('978cc21e-6553-5062-b072-04ba7fd35319'::uuid, 3, 'redaction', $exo${"titre":"Trois idées reçues sur Internet","consigne":"Pour chaque affirmation, dis si elle est juste ou fausse et argumente avec le cours.","enonce":"**Document.** Dans un exposé, Nathan affirme :\n\n> A. « Internet fonctionne parce qu'une grande machine centrale dirige tous les paquets. »\n> B. « Les paquets d'un même message suivent forcément le même chemin, sinon ils arriveraient mélangés. »\n> C. « On aurait pu garder IPv4 pour toujours : 4,3 milliards d'adresses, c'est largement assez. »\n\nOn suppose en outre que **10 milliards d'appareils** veulent chacun une adresse sur le réseau.\n\n1. Discute l'affirmation A.\n2. Discute l'affirmation B : explique comment les paquets peuvent arriver dans le désordre sans que le message soit perdu.\n3. Discute l'affirmation C à l'aide de la donnée ci-dessus.\n4. Le cours présente le DNS comme « le point de fragilité le plus exploité ». Explique pourquoi une panne du DNS gênerait tous les internautes, alors que les routeurs fonctionnent encore.","bareme":[{"critere":"A fausse : aucune machine ne dirige Internet, réseau de réseaux sans centre, ce qui le rend robuste","points":4},{"critere":"B fausse : chemins différents possibles (prochain saut) ; TCP remet dans l'ordre et redemande les manquants","points":6},{"critere":"C fausse : 10 milliards > 4,3 milliards, adresses IPv4 épuisées ; IPv6 sur 128 bits offre un nombre pratiquement illimité","points":5},{"critere":"Sans DNS, les noms ne sont plus traduits en adresses IP : les sites deviennent injoignables par leur nom","points":5}],"dureeMin":16,"corrige":"1. **A est fausse.** Internet est un **réseau de réseaux** : **aucune machine ne le dirige**. C'est précisément cette absence de centre qui le rend **robuste** : si un lien tombe, les paquets suivants passent ailleurs sans décision centrale.\n2. **B est fausse.** Le message est découpé en **paquets indépendants**, qui peuvent prendre des **chemins différents**, car chaque **routeur** ne choisit que le **prochain saut**. Ils peuvent donc arriver dans le désordre, mais **TCP** les **remet dans l'ordre**, vérifie qu'ils sont tous là et **redemande les manquants** : le message est reconstitué entier.\n3. **C est fausse.** IPv4 code les adresses sur 32 bits, soit environ **4,3 milliards** d'adresses. Avec 10 milliards d'appareils, il en manquerait plus de 5 milliards : les adresses IPv4 sont d'ailleurs **épuisées**. **IPv6**, sur **128 bits**, offre un nombre d'adresses **pratiquement illimité**, d'où son déploiement.\n4. Le **DNS** traduit les **noms de domaine** en **adresses IP**. Les internautes tapent des noms, pas des adresses. Si le DNS tombe, les routeurs savent toujours acheminer les paquets vers une adresse IP, mais **plus personne ne peut trouver l'adresse** qui correspond au nom : les sites deviennent injoignables par leur nom. C'est pourquoi il est un point de fragilité, et une cible."}$exo$::jsonb),
  ('4bc27b20-cbe9-50b1-aa90-d4411955da9e'::uuid, 1, 'redaction', $exo${"titre":"Des adresses valides ou non","consigne":"Justifie chaque réponse à l'aide des règles d'écriture vues en cours.","enonce":"Voici quatre écritures proposées comme adresses IPv4 :\n\n| Écriture |\n|---|\n| 192.168.0.12 |\n| 10.4.300.2 |\n| 81.56.120.7 |\n| 192.168.1 |\n\n1. Rappelle comment s'écrit une adresse IPv4 et sur combien de bits elle est codée.\n2. Pour chacune des quatre écritures, dis si c'est une adresse IPv4 valide. Justifie.\n3. Parmi les adresses valides, lesquelles sont des adresses **privées** d'après le cours ? Où circulent-elles ?","bareme":[{"critere":"Règle : quatre nombres de 0 à 255 séparés par des points, 32 bits","points":5},{"critere":"Validité juste et justifiée : 192.168.0.12 et 81.56.120.7 valides ; 10.4.300.2 (300 > 255) et 192.168.1 (trois nombres) invalides","points":9},{"critere":"192.168.0.12 est privée (commence par 192.168) et ne circule que dans le réseau local","points":6}],"dureeMin":7,"corrige":"1. Une adresse IPv4 s'écrit avec **quatre nombres de 0 à 255**, séparés par des **points** ; elle est codée sur **32 bits**.\n2. **192.168.0.12** : valide (quatre nombres entre 0 et 255). **10.4.300.2** : **invalide**, car 300 dépasse 255. **81.56.120.7** : valide. **192.168.1** : **invalide**, il n'y a que trois nombres.\n3. **192.168.0.12** est une adresse **privée**, car elle commence par 192.168. Une adresse privée ne circule **que dans le réseau local** ; sur Internet, c'est l'adresse **publique** (portée par la box) qui est utilisée. 81.56.120.7 ne commence ni par 192.168 ni par 10 : ce n'est pas une adresse privée au sens du cours."}$exo$::jsonb),
  ('4bc27b20-cbe9-50b1-aa90-d4411955da9e'::uuid, 2, 'redaction', $exo${"titre":"La box de la famille Martin","consigne":"Lis la situation et réponds en utilisant les mots du cours (DHCP, NAT, partie réseau, partie hôte).","enonce":"**Situation.** Chez les Martin, la box a donné ces adresses :\n\n| Appareil | Adresse |\n|---|---|\n| Ordinateur | 192.168.1.10 |\n| Téléphone | 192.168.1.11 |\n| Tablette | 192.168.1.12 |\n\nDans ce réseau, le masque de sous-réseau indique que les **trois premiers nombres** forment la partie réseau. L'adresse **publique** de la box est 88.170.12.45.\n\n1. Quel mécanisme a attribué automatiquement ces adresses ?\n2. Pour l'ordinateur, écris la partie réseau et la partie hôte de son adresse. Laquelle est commune aux trois appareils ?\n3. On branche une console. Propose une adresse possible pour elle, et justifie.\n4. Le téléphone consulte un site. Quelle adresse le site voit-il ? Quel mécanisme le permet ?","bareme":[{"critere":"Le DHCP de la box attribue les adresses privées","points":4},{"critere":"Partie réseau 192.168.1 commune aux trois ; partie hôte 10 propre à l'ordinateur","points":6},{"critere":"Adresse proposée en 192.168.1.x, x non déjà pris et entre 0 et 255, justifiée par la partie réseau commune","points":4},{"critere":"Le site voit l'adresse publique 88.170.12.45 ; le NAT traduit l'adresse privée en adresse publique","points":6}],"dureeMin":10,"corrige":"1. C'est le **DHCP** : la box attribue automatiquement les adresses privées aux appareils qui se connectent.\n2. Pour 192.168.1.10 : partie **réseau** = **192.168.1**, partie **hôte** = **10**. La partie réseau 192.168.1 est **commune** aux trois appareils du même réseau local ; la partie hôte (10, 11, 12) est propre à chacun.\n3. Par exemple **192.168.1.13** : la console appartient au même réseau local, elle garde donc la partie réseau 192.168.1, avec une partie hôte qui n'est pas encore utilisée (ni 10, ni 11, ni 12) et qui reste entre 0 et 255.\n4. Le site voit l'adresse **publique** de la box, **88.170.12.45**, et non 192.168.1.11 : les adresses privées ne circulent que dans le réseau local. C'est le **NAT** qui traduit l'adresse privée vers l'unique adresse publique du foyer."}$exo$::jsonb),
  ('4bc27b20-cbe9-50b1-aa90-d4411955da9e'::uuid, 3, 'redaction', $exo${"titre":"« Grâce à son adresse IP, on sait qui c'est »","consigne":"Réponds en argumentant : chaque réponse doit s'appuyer sur une notion précise du cours.","enonce":"**Document.** Sur un forum, un message insultant a été posté. Un utilisateur écrit :\n\n> « J'ai relevé l'adresse IP de l'auteur : 88.170.12.45. Donc c'est forcément Tom, 16 ans, qui habite à cette adresse. »\n\nOn sait que cette adresse est l'adresse publique d'une box familiale, derrière laquelle sont connectés quatre appareils (ceux de Tom, de sa sœur et de ses parents).\n\n1. Qu'identifie réellement une adresse IP ? Cite la phrase du cours qui le résume.\n2. Explique, à l'aide du NAT, pourquoi les quatre appareils de la famille apparaissent sur Internet sous la même adresse.\n3. Deux foyers voisins ont chacun un ordinateur à l'adresse 192.168.1.10. Est-ce un problème ? Justifie.\n4. Conclus : l'affirmation du document est-elle fondée ?","bareme":[{"critere":"Une adresse IP désigne où joindre une machine à un instant donné, pas une personne","points":5},{"critere":"Le NAT traduit les adresses privées vers l'unique adresse publique de la box, partagée par tout le foyer","points":5},{"critere":"Pas de conflit : adresses privées qui ne circulent que dans chaque réseau local","points":5},{"critere":"Conclusion argumentée : affirmation non fondée, l'adresse ne désigne ni un appareil unique ni une personne","points":5}],"dureeMin":15,"corrige":"1. Une adresse IP identifie **une machine**, ou plus exactement un **accès**, à **un instant donné**. Le cours le résume ainsi : « Une adresse IP ne dit pas qui vous êtes : elle dit où joindre la machine que vous utilisez, à cet instant. »\n2. Chez eux, chaque appareil a une adresse **privée** (attribuée par le DHCP de la box), qui ne circule que dans le réseau local. Pour sortir sur Internet, le **NAT** traduit ces adresses privées vers l'**unique adresse publique** du foyer, portée par la box. Vu de l'extérieur, les quatre appareils ont donc tous l'adresse **88.170.12.45**.\n3. **Non**, ce n'est pas un problème : 192.168.1.10 est une adresse **privée**, qui ne circule que **dans chaque réseau local**. Sur Internet, chaque foyer apparaît sous sa propre adresse publique ; les deux 192.168.1.10 ne se rencontrent jamais.\n4. L'affirmation **n'est pas fondée** : l'adresse 88.170.12.45 désigne l'accès d'un foyer entier à un instant donné. Le message peut venir de n'importe lequel des quatre appareils, et même d'une personne de passage utilisant le wifi. Une adresse IP ne désigne pas une personne."}$exo$::jsonb),
  ('9f5472f3-59d3-513c-9cc9-3c8eacab1707'::uuid, 1, 'redaction', $exo${"titre":"Les briques du Web","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"1. Le cours dit que « confondre Internet et le Web, c'est confondre la route et les voitures ». Explique cette phrase.\n2. Qui a inventé le Web, et où ?\n3. Cite les **trois briques** inventées pour le Web et donne le rôle de chacune.\n4. Quelle est la différence entre **HTML** et **CSS** ?","bareme":[{"critere":"Internet = infrastructure (la route) ; le Web = une application qui l'utilise (les voitures)","points":5},{"critere":"Tim Berners-Lee, au CERN","points":3},{"critere":"HTML décrit une page, URL donne une adresse unique à chaque ressource, HTTP transfère la ressource","points":7},{"critere":"HTML = structure du contenu ; CSS = présentation","points":5}],"dureeMin":6,"corrige":"1. **Internet** est l'**infrastructure** qui relie les machines : c'est la route. Le **Web** est une **application** qui circule sur cette infrastructure, comme les voitures sur la route. Le Web n'est pas Internet lui-même.\n2. Le Web a été inventé par **Tim Berners-Lee**, au **CERN** (entre 1989 et 1991).\n3. **HTML** : un langage pour **décrire une page**. **URL** : une **adresse unique** pour chaque ressource. **HTTP** : un **protocole pour transférer** la ressource entre le serveur et le navigateur.\n4. **HTML** décrit la **structure** du contenu (titres, paragraphes, liens, images) ; **CSS** décrit la **présentation** (couleurs, polices, mise en page)."}$exo$::jsonb),
  ('9f5472f3-59d3-513c-9cc9-3c8eacab1707'::uuid, 2, 'redaction', $exo${"titre":"Le site de recettes d'Inès","consigne":"Lis la situation et réponds en justifiant à l'aide du cours.","enonce":"**Situation.** Inès consulte un site de recettes depuis le wifi d'un café.\n\n1. Pour chaque élément, dis s'il relève du **HTML** ou du **CSS** : a) la liste des ingrédients ; b) la couleur rose des titres ; c) la photo du gâteau ; d) la police d'écriture choisie.\n2. Qui joue le rôle de **client** et qui joue le rôle de **serveur** quand Inès affiche la recette ?\n3. Le site utilise **HTTP** et non **HTTPS**. Inès s'y connecte avec un mot de passe. Quel risque court-elle sur ce wifi ?\n4. Le créateur du site veut changer entièrement son apparence sans réécrire les recettes. Est-ce possible ? Pourquoi ?","bareme":[{"critere":"a et c : HTML (structure, contenu) ; b et d : CSS (présentation)","points":6},{"critere":"Le navigateur d'Inès est le client qui demande ; le serveur renvoie la page","points":4},{"critere":"Sans HTTPS, pas de chiffrement : tout circule en clair et le mot de passe peut être lu par un intermédiaire","points":5},{"critere":"Oui : HTML et CSS séparés, on change la feuille de style sans toucher au contenu","points":5}],"dureeMin":10,"corrige":"1. a) La liste des ingrédients : **HTML** (structure du contenu). b) La couleur rose des titres : **CSS** (présentation). c) La photo : **HTML** (les images font partie du contenu). d) La police : **CSS**.\n2. Le **navigateur** d'Inès est le **client** : il demande la page. Le **serveur** du site la **renvoie**.\n3. Sans **HTTPS**, les échanges ne sont **pas chiffrés** : tout le contenu, y compris son **mot de passe**, circule **en clair** et peut être lu par **n'importe quel intermédiaire** du réseau, par exemple quelqu'un sur le même wifi du café.\n4. **Oui**. Comme la **structure** (HTML) et la **présentation** (CSS) sont séparées, on peut changer entièrement l'apparence du site en modifiant le CSS, **sans toucher à une ligne du contenu**."}$exo$::jsonb),
  ('9f5472f3-59d3-513c-9cc9-3c8eacab1707'::uuid, 3, 'redaction', $exo${"titre":"Quatre pages et un classement","consigne":"Réponds aux questions, puis rédige un court paragraphe argumenté pour la dernière.","enonce":"**Document.** Un tout petit Web compte quatre pages, reliées par ces liens :\n\n| Page de départ | Pointe vers |\n|---|---|\n| B | A |\n| C | A |\n| D | A et C |\n| A | B |\n\n1. Décris les **trois étapes** du fonctionnement d'un moteur de recherche.\n2. Pour chaque page, compte le nombre de liens qui pointent **vers** elle.\n3. D'après le principe du **PageRank**, quelle page semble la plus importante ? Pourquoi le seul nombre de liens ne suffit-il pas toujours ?\n4. En quelques lignes, explique la phrase du cours : « La première page de résultats est un choix, pas un fait. »","bareme":[{"critere":"Crawling (robots de lien en lien), indexation (stockage en mots-clés), classement par un algorithme","points":5},{"critere":"Liens entrants justes : A 3, B 1, C 1, D 0","points":4},{"critere":"A la plus importante ; une page est importante si des pages importantes la citent, la qualité des liens compte","points":5},{"critere":"Paragraphe : classement produit d'un algorithme et d'un modèle économique, jamais neutre","points":6}],"dureeMin":15,"corrige":"1. **Crawling** : des robots parcourent le Web de lien en lien. **Indexation** : le contenu est stocké et découpé en mots-clés. **Classement** : un algorithme ordonne les résultats.\n2. Liens entrants : **A : 3** (de B, C et D) ; **B : 1** (de A) ; **C : 1** (de D) ; **D : 0**.\n3. **A** semble la plus importante : c'est la page vers laquelle pointent le plus de pages. Mais le PageRank ne compte pas seulement les liens : **une page est importante si des pages importantes la citent**. Un seul lien venant d'une page très importante peut peser plus que plusieurs liens venant de pages que personne ne cite. Ici, B n'a qu'un lien, mais il vient de A, la page la plus citée.\n4. Le classement **n'est jamais neutre** : il est le **produit d'un algorithme**, dont les critères ont été choisis par l'entreprise, et d'un **modèle économique**. Ce qui apparaît en premier n'est donc pas « la vérité » ni forcément la meilleure réponse : c'est le résultat d'un **choix**, qu'il faut garder en tête avant de faire confiance au premier lien."}$exo$::jsonb),
  ('3c162a9f-ddab-5e7f-b7cc-6229a458f4c0'::uuid, 1, 'redaction', $exo${"titre":"Routeurs et TCP","consigne":"Réponds à chaque question par des phrases complètes.","enonce":"1. Quel est le rôle d'un **routeur** ? Qu'est-ce qu'une **table de routage** ?\n2. Cite deux critères qui peuvent servir à calculer le coût d'une route.\n3. Cite les **quatre** actions de TCP et ce que chacune garantit.\n4. Donne un usage de **UDP** et explique pourquoi on le préfère à TCP dans ce cas.","bareme":[{"critere":"Le routeur relie deux réseaux et choisit pour chaque paquet le voisin vers qui l'envoyer ; la table associe destinations et directions","points":5},{"critere":"Deux critères parmi : nombre de sauts, débit, latence","points":3},{"critere":"Numérotation (ordre), accusés de réception (arrivée), redemande (intégralité), ajustement du débit (congestion)","points":8},{"critere":"Usage d'UDP (visio, jeu, streaming) : une image perdue vaut mieux qu'une image en retard","points":4}],"dureeMin":7,"corrige":"1. Un **routeur** relie deux réseaux et décide, **pour chaque paquet**, vers quel **voisin** l'envoyer. La **table de routage** associe des **destinations** à des **directions**.\n2. Le **nombre de sauts** (routeurs traversés), le **débit** disponible (capacité du lien), la **latence** (le délai).\n3. TCP **numérote** les paquets (remise dans l'ordre) ; il attend des **accusés de réception** (certitude de l'arrivée) ; il **redemande** les manquants (intégralité du message) ; il **ajuste le débit** (éviter la congestion).\n4. UDP sert à la **visioconférence**, au **jeu en ligne** ou au **streaming**. Il n'offre aucune garantie et n'attend pas d'accusé, donc il est plus rapide : en visioconférence, **une image perdue vaut mieux qu'une image en retard**."}$exo$::jsonb),
  ('3c162a9f-ddab-5e7f-b7cc-6229a458f4c0'::uuid, 2, 'redaction', $exo${"titre":"La table du routeur R1","consigne":"Utilise le document pour répondre, en justifiant chaque choix.","enonce":"**Document 1 — table de routage du routeur R1**\n\n| Destination | Envoyer vers |\n|---|---|\n| Réseau A | Routeur R2 |\n| Réseau B | Routeur R3 |\n| Toute autre destination | Routeur R4 |\n\n**Document 2 — deux routes possibles entre deux villes**\n\n| Route | Nombre de sauts |\n|---|---|\n| Route 1 | 3 |\n| Route 2 | 5 |\n\n1. R1 reçoit trois paquets destinés respectivement au réseau B, au réseau A et au réseau C. Vers quel routeur envoie-t-il chacun ?\n2. Si le coût d'une route est le nombre de sauts, laquelle des deux routes du document 2 est choisie ? Pourquoi ?\n3. Quelle commande permet de visualiser les routeurs réellement traversés par des paquets ?\n4. Explique la phrase : « Le réseau optimise ses coûts, pas la carte. »","bareme":[{"critere":"B vers R3, A vers R2, C vers R4 (autre destination)","points":6},{"critere":"Route 1 choisie : 3 sauts, coût le plus faible","points":4},{"critere":"La commande traceroute","points":3},{"critere":"Explication : le chemin choisi minimise un coût (sauts, débit, latence), pas la distance géographique ; exemple Lille-Lyon via Francfort","points":7}],"dureeMin":10,"corrige":"1. Paquet pour le **réseau B** : vers **R3**. Paquet pour le **réseau A** : vers **R2**. Paquet pour le **réseau C** : C n'est pas dans la table, c'est une « autre destination », donc vers **R4**.\n2. La **route 1** : avec 3 sauts contre 5, elle a le **coût le plus faible** quand le coût est le nombre de routeurs traversés.\n3. La commande **traceroute**.\n4. Le routage ne cherche pas le trajet le plus court sur une carte : il choisit la route dont le **coût** (nombre de sauts, débit disponible, latence) est le plus faible. Une route géographiquement plus longue peut être moins coûteuse. C'est pourquoi **un message envoyé de Lille à Lyon peut passer par Francfort**."}$exo$::jsonb),
  ('3c162a9f-ddab-5e7f-b7cc-6229a458f4c0'::uuid, 3, 'redaction', $exo${"titre":"TCP ou UDP ?","consigne":"Justifie chaque choix à partir des garanties de chaque protocole. La dernière question demande une explication pas à pas.","enonce":"**Situation.** Malik utilise son ordinateur pour quatre activités :\n\n| Activité |\n|---|\n| a) Télécharger un fichier de cours |\n| b) Appeler sa grand-mère en visioconférence |\n| c) Afficher une page web |\n| d) Jouer à un jeu en ligne |\n\n1. Pour chaque activité, choisis TCP ou UDP et justifie par les garanties (ou l'absence de garanties) du protocole.\n2. Pendant le téléchargement, les paquets 1, 2, 4 et 5 arrivent, mais pas le 3. Décris pas à pas ce que fait TCP jusqu'à la remise du fichier complet.\n3. Pourquoi dit-on que TCP « rend fiable un réseau qui, lui, ne l'est pas » ?","bareme":[{"critere":"a et c : TCP (ordre, intégralité, retransmission indispensables)","points":4},{"critere":"b et d : UDP (pas d'attente d'accusé ; une donnée perdue vaut mieux qu'une donnée en retard)","points":4},{"critere":"Étapes : numéros, absence d'accusé pour le 3, redemande, réception, remise dans l'ordre 1 à 5","points":7},{"critere":"Le réseau perd ou désordonne des paquets ; TCP compense par numérotation, accusés, retransmission","points":5}],"dureeMin":15,"corrige":"1. a) **TCP** : un fichier doit arriver **entier et dans l'ordre**, sinon il est inutilisable. b) **UDP** : en visioconférence, **une image perdue vaut mieux qu'une image en retard** ; attendre une retransmission créerait des décalages. c) **TCP** : c'est l'usage du Web, la page doit être complète. d) **UDP** : le jeu en ligne a besoin de rapidité, une information arrivée en retard ne sert plus à rien.\n2. TCP a **numéroté** les paquets à l'envoi. À la réception de 1, 2, 4 et 5, il constate qu'il manque le **numéro 3** : aucun **accusé de réception** n'est envoyé pour lui. Il **redemande** le paquet 3 à l'expéditeur, qui le renvoie. Une fois le 3 arrivé, TCP **remet les paquets dans l'ordre** (1, 2, 3, 4, 5) et livre le fichier **intégral** au logiciel de Malik.\n3. Le réseau lui-même ne garantit rien : les paquets suivent des chemins différents, certains se perdent, d'autres arrivent dans le désordre. TCP compense ces défauts grâce à la **numérotation**, aux **accusés de réception**, à la **retransmission** et à l'**ajustement du débit** : l'utilisateur reçoit un message complet et ordonné, **comme si** le réseau était fiable."}$exo$::jsonb),
  ('6697f4c7-1143-5d65-8a31-e631929ea2f5'::uuid, 1, 'redaction', $exo${"titre":"Graphe social et gratuité","consigne":"Réponds à chaque question avec le vocabulaire du cours.","enonce":"1. Dans le graphe d'un réseau social, que représentent les **sommets** ? Les **arêtes** ?\n2. Définis le **degré** d'un sommet et le **diamètre** d'un graphe.\n3. Comment un réseau social gratuit se finance-t-il ? Pourquoi le **temps passé** devient-il l'objectif de conception ?","bareme":[{"critere":"Sommets = utilisateurs ; arêtes = relations","points":5},{"critere":"Degré = nombre de relations d'un sommet ; diamètre = plus longue distance minimale entre deux sommets","points":7},{"critere":"Publicité ciblée ; plus l'utilisateur reste et est connu, plus l'espace publicitaire se vend cher","points":8}],"dureeMin":6,"corrige":"1. Les **sommets** sont les **utilisateurs** ; les **arêtes** sont les **relations** entre eux.\n2. Le **degré** d'un sommet est son **nombre de relations**. Le **diamètre** d'un graphe est la **plus longue des distances minimales** entre deux sommets.\n3. La gratuité est financée par la **publicité ciblée** : plus le service **connaît** l'utilisateur, plus l'espace publicitaire se **vend cher**. Le produit, c'est donc l'**attention** des utilisateurs. Le **temps passé** devient l'objectif de conception, avant même la qualité du service rendu : ce n'est pas un dérapage, c'est ce que le modèle économique demande."}$exo$::jsonb),
  ('6697f4c7-1143-5d65-8a31-e631929ea2f5'::uuid, 2, 'redaction', $exo${"titre":"Le groupe de Chloé","consigne":"Utilise le graphe pour répondre. Montre les chemins que tu utilises.","enonce":"**Document.** Sur un réseau social, cinq amis sont reliés ainsi (une ligne = une relation) :\n\n| Relation |\n|---|\n| Alice — Bilal |\n| Alice — Chloé |\n| Bilal — Chloé |\n| Chloé — Dan |\n| Dan — Emma |\n\n1. Donne le **degré** de chaque personne.\n2. Quelle est la **distance** entre Alice et Emma ? Écris le chemin le plus court.\n3. Quel est le **diamètre** de ce graphe ? Justifie.\n4. Quelle personne a la plus forte **centralité** ? Explique ce que cela signifie ici.","bareme":[{"critere":"Degrés justes : Alice 2, Bilal 2, Chloé 3, Dan 2, Emma 1","points":5},{"critere":"Distance Alice-Emma = 3 par Alice-Chloé-Dan-Emma","points":5},{"critere":"Diamètre = 3 (Alice-Emma ou Bilal-Emma), aucune distance plus grande","points":5},{"critere":"Chloé : passage obligé entre Alice/Bilal et Dan/Emma","points":5}],"dureeMin":10,"corrige":"1. **Alice : 2** (Bilal, Chloé) ; **Bilal : 2** (Alice, Chloé) ; **Chloé : 3** (Alice, Bilal, Dan) ; **Dan : 2** (Chloé, Emma) ; **Emma : 1** (Dan).\n2. Le chemin le plus court est **Alice — Chloé — Dan — Emma** : la distance est de **3**.\n3. Les plus grandes distances minimales sont Alice-Emma = 3 et Bilal-Emma = 3 (Bilal — Chloé — Dan — Emma). Toutes les autres paires sont plus proches (par exemple Alice-Dan = 2, Bilal-Dan = 2, Chloé-Emma = 2). Le **diamètre** vaut donc **3**.\n4. **Chloé** : tout chemin entre Alice ou Bilal d'un côté et Dan ou Emma de l'autre **passe obligatoirement par elle**. C'est la **centralité** : elle est un passage obligé ; si elle quittait le réseau, le groupe serait coupé en deux."}$exo$::jsonb),
  ('6697f4c7-1143-5d65-8a31-e631929ea2f5'::uuid, 3, 'redaction', $exo${"titre":"« Si c'est gratuit, c'est toi le produit »","consigne":"Rédige une réponse argumentée, en plusieurs paragraphes, en t'appuyant sur les notions du cours.","enonce":"**Document.**\n\n> « Si c'est gratuit, c'est toi le produit. » (formule souvent citée à propos des réseaux sociaux)\n\n1. Explique cette formule à l'aide du **modèle économique** des réseaux sociaux.\n2. Montre comment ce modèle influence les **algorithmes de recommandation** : que cherchent-ils à optimiser, et quelles en sont les conséquences (bulles de filtre, contenus clivants) ?\n3. Cite **deux risques** liés aux réseaux sociaux et le texte ou la mesure qui encadre chacun.","bareme":[{"critere":"Gratuité financée par la publicité ciblée ; le produit vendu est l'attention et la connaissance de l'utilisateur","points":6},{"critere":"Algorithmes optimisés sur l'engagement : ils favorisent ce qui fait réagir","points":5},{"critere":"Conséquences expliquées : bulles de filtre, viralité des contenus clivants plus que nuancés","points":4},{"critere":"Deux risques avec leur encadrement juste (RGPD 2018, DSA 2023, délit de cyberharcèlement, âge minimal)","points":5}],"dureeMin":18,"corrige":"1. Le réseau social ne fait pas payer l'utilisateur : il est financé par la **publicité ciblée**. Plus il connaît l'utilisateur, plus l'espace publicitaire se vend cher. Ce qui est vendu, ce n'est pas le service : ce sont l'**attention** et les **données** de l'utilisateur, proposées aux annonceurs. D'où la formule : l'utilisateur est le produit. Le **temps passé** devient l'objectif de conception.\n2. Les **algorithmes de recommandation** choisissent ce qui apparaît dans le fil. Ils sont optimisés sur l'**engagement** : ils favorisent ce qui **fait réagir**. Conséquences : les **bulles de filtre** (on voit surtout des contenus conformes à ses opinions) et la **viralité des contenus clivants**, qui suscitent plus de réactions que les contenus nuancés.\n3. Deux risques parmi : les **données personnelles**, encadrées par le **RGPD** (2018) ; la **modération et la transparence**, encadrées par le **DSA** européen (2023) ; le **cyberharcèlement**, délit aggravé au code pénal ; l'**exposition des mineurs**, encadrée par un âge minimal et le contrôle parental."}$exo$::jsonb),
  ('816dc421-1b2a-5de9-851d-0f8418d9aa8c'::uuid, 1, 'redaction', $exo${"titre":"De la donnée à la connaissance","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"1. Le nombre **12** apparaît dans un fichier. À partir de cet exemple, explique la différence entre une **donnée**, une **information** et une **connaissance** (invente le contexte et l'interprétation).\n2. Dans une table, que représente une **ligne** ? Une **colonne** ?\n3. Cite trois **types** d'attributs et explique pourquoi le type d'un attribut est important.","bareme":[{"critere":"Donnée brute, information = donnée + contexte, connaissance = interprétation, avec un exemple cohérent","points":8},{"critere":"Ligne = un enregistrement (une entité décrite) ; colonne = un attribut","points":6},{"critere":"Trois types parmi entier, flottant, chaîne, booléen, date ; le type autorise ou interdit un traitement","points":6}],"dureeMin":6,"corrige":"1. **Donnée** : 12, brut, sans rien d'autre. **Information** : on ajoute le **contexte**, par exemple « 12 sur 20, note de Léo en maths ». **Connaissance** : on ajoute l'**interprétation**, par exemple « c'est une note au-dessus de la moyenne ». La donnée devient information grâce au contexte, puis connaissance grâce à l'interprétation.\n2. Une **ligne** est un **enregistrement** : une entité décrite (par exemple un élève). Une **colonne** est un **attribut** (par exemple la classe ou la note).\n3. Types possibles : **entier**, **flottant**, **chaîne**, **booléen**, **date**. Le type **autorise ou interdit un traitement** : on peut faire la moyenne d'une colonne de flottants, mais **on ne fait pas la moyenne d'une chaîne**."}$exo$::jsonb),
  ('816dc421-1b2a-5de9-851d-0f8418d9aa8c'::uuid, 2, 'redaction', $exo${"titre":"Les notes de la seconde","consigne":"Utilise la table pour appliquer les traitements demandés. Montre tes calculs.","enonce":"**Document — fichier CSV `notes`**\n\n| Nom | Classe | Age | Moyenne |\n|---|---|---|---|\n| Léo | 2B | 15 | 12,5 |\n| Maya | 2A | 16 | 14 |\n| Sami | 2B | 15 | 9,5 |\n| Jade | 2B | 16 | 15 |\n| Hugo | 2A | 15 | 11 |\n\n1. Donne le **type** de chacun des quatre attributs.\n2. **Filtre** la table pour ne garder que les élèves de la 2B.\n3. **Trie** ces élèves de la 2B par moyenne décroissante.\n4. **Agrège** : calcule la moyenne des moyennes des élèves de la 2B (arrondie au centième).","bareme":[{"critere":"Types : Nom et Classe chaînes, Age entier, Moyenne flottant","points":4},{"critere":"Filtre juste : Léo, Sami, Jade","points":4},{"critere":"Tri décroissant juste : Jade 15, Léo 12,5, Sami 9,5","points":5},{"critere":"Agrégation juste : (12,5 + 9,5 + 15) / 3 = 37 / 3 ≈ 12,33","points":7}],"dureeMin":10,"corrige":"1. **Nom** : chaîne ; **Classe** : chaîne ; **Age** : entier ; **Moyenne** : flottant.\n2. Filtrer (ne garder que les lignes qui vérifient Classe = 2B) : **Léo, Sami, Jade**.\n3. Trier par moyenne décroissante : **Jade (15)**, **Léo (12,5)**, **Sami (9,5)**.\n4. Agréger (moyenner) : (12,5 + 9,5 + 15) / 3 = 37 / 3 ≈ **12,33**. La moyenne des élèves de la 2B est d'environ 12,33. Ce calcul n'est possible que parce que l'attribut Moyenne est d'un type numérique (flottant)."}$exo$::jsonb),
  ('816dc421-1b2a-5de9-851d-0f8418d9aa8c'::uuid, 3, 'redaction', $exo${"titre":"Fusionner et choisir un format","consigne":"Réponds à chaque question en justifiant. La dernière demande un court paragraphe argumenté.","enonce":"**Document 1 — table `eleves`**\n\n| Nom | Classe |\n|---|---|\n| Léo | 2B |\n| Maya | 2A |\n| Jade | 2B |\n\n**Document 2 — table `classes`**\n\n| Classe | Professeur principal |\n|---|---|\n| 2A | Mme Roux |\n| 2B | M. Diallo |\n\n1. Quel traitement permet d'obtenir, pour chaque élève, le nom de son professeur principal ? Sur quel attribut se fait-il ? Écris la table obtenue.\n2. Le lycée veut enregistrer, pour chaque élève, la **liste** de toutes ses notes. Le format **CSV** convient-il ? Quel format choisir ? Justifie.\n3. Le lycée hésite entre un format **ouvert** et le format **propriétaire** d'un logiciel payant. Argumente en faveur d'un choix.\n4. Cite les **3 V** du big data.","bareme":[{"critere":"Fusion (jointure) sur l'attribut commun Classe ; table juste : Léo-2B-M. Diallo, Maya-2A-Mme Roux, Jade-2B-M. Diallo","points":6},{"critere":"CSV ne convient pas (pas d'imbrication ni de type) ; JSON permet une liste imbriquée et typée","points":5},{"critere":"Format ouvert : interopérabilité et pérennité, contre la dépendance à un logiciel qui peut disparaître","points":6},{"critere":"Volume, vitesse, variété","points":3}],"dureeMin":16,"corrige":"1. Il faut **fusionner** (joindre) les deux tables sur l'**attribut commun Classe**. Table obtenue :\n\n| Nom | Classe | Professeur principal |\n|---|---|---|\n| Léo | 2B | M. Diallo |\n| Maya | 2A | Mme Roux |\n| Jade | 2B | M. Diallo |\n\n2. **CSV ne convient pas** : c'est du texte simple, une ligne par enregistrement, **sans type ni imbrication** ; on ne peut pas y ranger proprement une liste de notes à l'intérieur d'un élève. Il faut choisir **JSON**, qui permet l'**imbrication** (une liste de notes dans chaque élève) et les **types**. Sa limite : il est plus verbeux.\n3. Le lycée devrait choisir un **format ouvert**. Il garantit l'**interopérabilité** (n'importe quel logiciel peut lire le fichier) et la **pérennité** : un fichier propriétaire dépend d'un logiciel qui peut disparaître, alors qu'un format ouvert **se relit dans vingt ans**.\n4. **Volume, vitesse, variété**."}$exo$::jsonb),
  ('970faf30-16a6-5f8d-a271-e2757120f527'::uuid, 1, 'redaction', $exo${"titre":"Client-serveur ou pair-à-pair","consigne":"Réponds par des phrases complètes.","enonce":"1. Décris le principe du modèle **client-serveur**, puis celui du modèle **pair-à-pair**.\n2. Où se trouve le contenu dans chacun des deux modèles ?\n3. Donne le **point faible** de chaque modèle.\n4. Donne un usage de chaque modèle.","bareme":[{"critere":"Client-serveur : un serveur répond, un client demande ; pair-à-pair : chaque machine est client et serveur","points":6},{"critere":"Contenu centralisé sur le serveur / réparti entre les participants","points":4},{"critere":"Point unique de défaillance / contrôle des contenus difficile","points":6},{"critere":"Un usage juste pour chaque modèle","points":4}],"dureeMin":6,"corrige":"1. **Client-serveur** : un **serveur** attend des requêtes et y **répond** ; le **client** **demande**. **Pair-à-pair** : chaque machine est à la fois **client et serveur**.\n2. En client-serveur, le contenu est **centralisé sur le serveur** ; en pair-à-pair, il est **réparti entre les participants**.\n3. Le client-serveur a un **point unique de défaillance** : si le serveur tombe, plus rien ne fonctionne. Le pair-à-pair rend le **contrôle des contenus difficile**.\n4. Client-serveur : le **Web**, le courrier, les applications mobiles. Pair-à-pair : le **partage de fichiers**, les mises à jour de jeux, les crypto-monnaies, les messageries décentralisées."}$exo$::jsonb),
  ('970faf30-16a6-5f8d-a271-e2757120f527'::uuid, 2, 'redaction', $exo${"titre":"La mise à jour du jeu Galaxie","consigne":"Lis la situation et compare les deux modèles en justifiant.","enonce":"**Situation.** Le studio qui édite le jeu **Galaxie** publie une grosse mise à jour. Le jour de sa sortie, **un million de joueurs** veulent la télécharger en même temps.\n\n1. Si la mise à jour est distribuée par un **serveur unique**, que se passe-t-il quand la demande augmente ? Quel risque court le studio si ce serveur tombe ?\n2. Si elle est distribuée en **pair-à-pair**, que se passe-t-il quand le nombre de joueurs augmente ? Explique pourquoi.\n3. Le studio garde un modèle client-serveur. Propose une **parade** pour chacun de ces trois risques : la panne, la saturation, l'éloignement géographique des joueurs.","bareme":[{"critere":"Serveur unique : il ralentit ; s'il tombe, plus personne ne télécharge (point unique de défaillance)","points":6},{"critere":"Pair-à-pair : le réseau accélère, car chaque joueur qui a reçu des morceaux les fournit aux autres","points":6},{"critere":"Parades justes : réplication, fermes de serveurs, réseaux de distribution de contenu","points":8}],"dureeMin":10,"corrige":"1. Avec un serveur unique, plus la demande augmente, plus le serveur **ralentit** : il doit répondre seul à un million de requêtes. S'il tombe, **plus personne ne peut télécharger** : c'est un **point unique de défaillance**.\n2. En pair-à-pair, chaque joueur est à la fois **client et serveur** : dès qu'il a reçu une partie de la mise à jour, il la **fournit aux autres**. Plus il y a de joueurs, plus il y a de sources : le réseau **accélère** au lieu de ralentir. Il **monte en charge naturellement**.\n3. Contre la **panne** : la **réplication** sur plusieurs machines. Contre la **saturation** (et le **déni de service**) : les **fermes de serveurs**. Contre l'**éloignement géographique** : les **réseaux de distribution de contenu**."}$exo$::jsonb),
  ('970faf30-16a6-5f8d-a271-e2757120f527'::uuid, 3, 'redaction', $exo${"titre":"Parlo, un service mixte","consigne":"Analyse la situation en t'appuyant sur les forces et les faiblesses de chaque modèle.","enonce":"**Document.** Présentation de Parlo, un service de visioconférence imaginaire :\n\n> « Pour utiliser Parlo, vous créez un compte. Nos serveurs vérifient votre identité et tiennent l'annuaire de vos contacts. Une fois l'appel lancé, la vidéo passe directement d'un ordinateur à l'autre, sans transiter par nos serveurs. »\n\n1. Quelles parties de Parlo relèvent du modèle **client-serveur** ? Laquelle relève du **pair-à-pair** ?\n2. Pourquoi est-il intéressant de faire passer la vidéo en pair-à-pair plutôt que par les serveurs de Parlo ?\n3. Un groupe malveillant envoie un flot énorme de requêtes vers les serveurs de connexion de Parlo. Comment s'appelle cette attaque ? Quelle partie du service est touchée, et pourquoi ?\n4. Le cours dit que le pair-à-pair **résiste à la censure**. Explique cette force et sa contrepartie.","bareme":[{"critere":"Client-serveur : authentification et annuaire ; pair-à-pair : transfert de la vidéo","points":5},{"critere":"Le transfert lourd ne sature pas un serveur central et monte en charge naturellement","points":4},{"critere":"Déni de service ; les serveurs d'authentification et d'annuaire, point unique de défaillance, empêchent de lancer des appels","points":5},{"critere":"Contenu réparti, aucune autorité ne peut le retirer ; contrepartie : retrait d'un contenu illicite difficile","points":6}],"dureeMin":16,"corrige":"1. **Client-serveur** : la **vérification d'identité** (authentification) et l'**annuaire** des contacts, tenus par les serveurs de Parlo. **Pair-à-pair** : le **transfert de la vidéo**, qui passe directement d'un ordinateur à l'autre. C'est un modèle **mixte**, comme beaucoup de services de visioconférence.\n2. La vidéo est le **transfert lourd**. En pair-à-pair, elle ne passe pas par les serveurs de Parlo, qui ne risquent donc pas d'être **saturés** quand le nombre d'appels augmente : le service **monte en charge naturellement**.\n3. C'est une attaque par **déni de service** : une saturation volontaire d'un serveur par un flot de requêtes. Elle touche la partie **client-serveur** : si les serveurs de connexion et d'annuaire sont saturés, plus personne ne peut se connecter ni trouver ses contacts, donc **plus aucun appel ne peut démarrer**, même si la vidéo, elle, ne passe pas par eux. Le serveur est un **point unique de défaillance**.\n4. En pair-à-pair, le contenu est **réparti** entre les participants : aucun point central ne permet de le faire disparaître, d'où sa **résistance à la censure**. La contrepartie : le **retrait d'un contenu illicite est difficile**, et aucune autorité ne garantit la qualité ; c'est ce qui explique son usage massif pour le partage illégal d'œuvres protégées."}$exo$::jsonb),
  ('8f1b9c6f-dc13-51e4-a936-cbcf62419874'::uuid, 1, 'redaction', $exo${"titre":"L'idée de l'hypertexte","consigne":"Réponds par des phrases complètes.","enonce":"1. Qu'est-ce que l'**hypertexte** ?\n2. Associe chaque date à son nom et à son apport : **1945**, **1965**, **1989** — Vannevar Bush, Ted Nelson, Tim Berners-Lee.\n3. Cite les **trois inventions fondatrices** du Web et le rôle de chacune.","bareme":[{"critere":"Texte dont certains mots renvoient à d'autres documents atteignables d'un clic","points":5},{"critere":"1945 Bush et le Memex ; 1965 Nelson invente le mot ; 1989 Berners-Lee au CERN et le Web","points":8},{"critere":"URL (adresse unique), HTTP (demander la ressource), HTML (décrire la page et ses liens)","points":7}],"dureeMin":6,"corrige":"1. L'**hypertexte** est un texte dont certains mots **renvoient à d'autres documents**, atteignables d'un **simple clic**. C'est l'idée qui distingue le Web de ce qui existait avant.\n2. **1945** : **Vannevar Bush** imagine le **Memex**, une machine reliant des documents par associations. **1965** : **Ted Nelson** invente le mot **hypertexte**. **1989** : **Tim Berners-Lee**, au CERN, crée un système reliant les documents de laboratoires du monde entier : le **Web**.\n3. L'**URL** donne une **adresse unique** à chaque ressource ; le **HTTP** est le protocole qui permet de la **demander** ; le **HTML** est le langage qui **décrit** la page et ses liens."}$exo$::jsonb),
  ('8f1b9c6f-dc13-51e4-a936-cbcf62419874'::uuid, 2, 'redaction', $exo${"titre":"Décortiquer une URL","consigne":"Découpe l'adresse et justifie avec le cours.","enonce":"**Document.** Au CDI, Clara ouvre cette adresse :\n\n> https://cdi.lycee-voltaire.fr/livres/recherche.html?auteur=hugo\n\n1. Découpe cette URL : donne le **protocole**, le **nom de domaine**, le **chemin** et les **paramètres**.\n2. Le nom de domaine se lit de droite à gauche. Identifie l'**extension**, le **domaine** et le **sous-domaine**.\n3. À quoi sert, selon toi, le paramètre auteur=hugo dans cette adresse ?\n4. Le cours dit qu'un lien hypertexte est une « adresse exécutable ». Explique la différence avec un renvoi de bas de page dans un livre.","bareme":[{"critere":"Protocole https, domaine cdi.lycee-voltaire.fr, chemin /livres/recherche.html, paramètres après le ?","points":6},{"critere":"Extension fr, domaine lycee-voltaire, sous-domaine cdi","points":5},{"critere":"Paramètre : donnée transmise à la page (rechercher les livres de l'auteur Hugo)","points":4},{"critere":"Un clic mène directement au document, alors qu'un renvoi oblige le lecteur à aller le chercher","points":5}],"dureeMin":10,"corrige":"1. **Protocole** : https. **Nom de domaine** : cdi.lycee-voltaire.fr. **Chemin** : /livres/recherche.html (la page visée). **Paramètres** : auteur=hugo, après le point d'interrogation.\n2. De droite à gauche : l'**extension** est **fr**, le **domaine** est **lycee-voltaire**, le **sous-domaine** est **cdi**.\n3. Les paramètres sont des **données transmises à la page** : ici, on demande à la page de recherche d'afficher les livres dont l'auteur est **Hugo**.\n4. Un renvoi de bas de page indique où se trouve un autre document, mais le lecteur doit aller le chercher lui-même. Un lien hypertexte est une **adresse exécutable** : un simple **clic** suffit pour que le navigateur demande et affiche le document visé. C'est ce qui change tout."}$exo$::jsonb),
  ('8f1b9c6f-dc13-51e4-a936-cbcf62419874'::uuid, 3, 'redaction', $exo${"titre":"Le graphe du site du lycée","consigne":"Utilise le document pour répondre, puis rédige un court paragraphe argumenté.","enonce":"**Document.** Le site d'un lycée compte cinq pages. Voici leurs liens :\n\n| La page… | …contient des liens vers |\n|---|---|\n| Accueil | Horaires, Cantine, Clubs |\n| Horaires | Accueil |\n| Cantine | Accueil, Horaires |\n| Clubs | Accueil, Horaires |\n| Archives | Clubs |\n\n1. Explique pourquoi l'ensemble de ces pages forme un **graphe**. Que sont les sommets, que sont les liens ?\n2. Compte, pour chaque page, le nombre de liens qui pointent **vers** elle.\n3. D'après le principe du PageRank, quelles pages semblent les plus importantes ? Quelle page ne serait jamais trouvée par un robot qui partirait de l'Accueil ? Pourquoi ?\n4. Explique, en quelques lignes, la phrase : « Sans hypertexte, pas de PageRank. »","bareme":[{"critere":"Graphe : pages = sommets, liens hypertextes = liaisons orientées entre elles","points":4},{"critere":"Comptage juste : Accueil 3, Horaires 3, Cantine 1, Clubs 2, Archives 0","points":5},{"critere":"Accueil et Horaires les plus importantes ; Archives inaccessible car aucune page ne pointe vers elle","points":5},{"critere":"Le PageRank mesure la popularité par le nombre et la qualité des liens entrants : sans liens, rien à mesurer","points":6}],"dureeMin":16,"corrige":"1. Les pages sont les **sommets** du graphe et les **liens hypertextes** relient ces sommets entre eux (dans un sens donné : de la page qui contient le lien vers la page visée). Le Web entier forme ainsi un immense **graphe** de pages reliées.\n2. Liens entrants : **Accueil : 3** (Horaires, Cantine, Clubs) ; **Horaires : 3** (Accueil, Cantine, Clubs) ; **Cantine : 1** (Accueil) ; **Clubs : 2** (Accueil, Archives) ; **Archives : 0**.\n3. **Accueil** et **Horaires** reçoivent le plus de liens : elles semblent les plus importantes (le PageRank tient aussi compte de la qualité des pages qui pointent). **Archives** ne serait jamais trouvée par un robot parti de l'Accueil : il avance de lien en lien, et **aucune page ne pointe vers Archives**.\n4. Le PageRank mesure la **popularité** d'une page par le **nombre et la qualité des liens qui pointent vers elle**. Cette mesure n'est possible que parce que les pages sont reliées par des liens hypertextes : sans eux, il n'y aurait ni graphe, ni liens entrants à compter, et les robots ne pourraient pas parcourir le Web. D'où la phrase du cours : sans hypertexte, pas de PageRank, et probablement pas de moteur de recherche efficace."}$exo$::jsonb),
  ('ec59583c-2859-5492-9bfa-be68f903ff7b'::uuid, 1, 'redaction', $exo${"titre":"GPS et pixels","consigne":"Réponds par des phrases complètes.","enonce":"1. Comment un récepteur GPS calcule-t-il sa distance à un satellite ? Comment s'appelle cette méthode ?\n2. Combien faut-il de satellites au minimum ? À quoi sert chacun ?\n3. Combien d'octets pèse un pixel codé en RVB ? Combien de couleurs cela permet-il ?\n4. Quelle est la différence entre la **définition** et la **résolution** d'une image ?","bareme":[{"critere":"Distance par le temps de trajet du signal ; trilatération","points":5},{"critere":"4 satellites : 3 pour la position, 1 de plus pour corriger l'horloge du récepteur","points":5},{"critere":"3 octets, environ 16,7 millions de couleurs","points":5},{"critere":"Définition = nombre total de pixels ; résolution = leur densité en points par pouce","points":5}],"dureeMin":7,"corrige":"1. Les satellites émettent en permanence l'**heure exacte** et leur **position**. Le récepteur calcule sa distance à chaque satellite grâce au **temps de trajet du signal**. C'est la **trilatération**.\n2. **4** satellites : **3** pour déterminer la position, **1 de plus** pour **corriger l'horloge du récepteur**.\n3. Un pixel RVB pèse **3 octets** (trois composantes de 0 à 255), soit environ **16,7 millions** de couleurs possibles.\n4. La **définition** est le **nombre total de pixels** de l'image ; la **résolution** est leur **densité**, en points par pouce."}$exo$::jsonb),
  ('ec59583c-2859-5492-9bfa-be68f903ff7b'::uuid, 2, 'redaction', $exo${"titre":"La photo du jardin d'Emma","consigne":"Montre tes calculs, puis réponds en justifiant.","enonce":"**Situation.** Emma prend avec son téléphone une photo de **4 000 × 3 000 pixels**, en couleurs RVB, dans le jardin de sa maison. Elle veut la publier sur un réseau social.\n\n1. Calcule la **définition** de cette image.\n2. Calcule son **poids brut**, en octets, puis en mégaoctets (1 Mo = 1 000 000 octets).\n3. Quelles informations les **métadonnées EXIF** de cette photo peuvent-elles contenir ?\n4. Quel risque Emma prend-elle en publiant cette photo telle quelle ?","bareme":[{"critere":"Définition : 4 000 × 3 000 = 12 000 000 pixels","points":4},{"critere":"Poids brut : 12 000 000 × 3 = 36 000 000 octets = 36 Mo","points":6},{"critere":"EXIF : date, modèle d'appareil, réglages et souvent position GPS","points":5},{"critere":"Risque : la position GPS révèle l'endroit où elle habite","points":5}],"dureeMin":10,"corrige":"1. Définition : 4 000 × 3 000 = **12 000 000 pixels** (12 millions de pixels).\n2. Chaque pixel RVB pèse 3 octets : 12 000 000 × 3 = **36 000 000 octets**, soit **36 Mo**.\n3. Les **métadonnées EXIF** enregistrent la **date**, le **modèle d'appareil**, les **réglages** et souvent la **position GPS** du lieu de prise de vue.\n4. La photo a été prise dans son jardin : si la position GPS est enregistrée, **publier la photo, c'est publier l'endroit où elle habite**. La plupart des gens l'ignorent, et aucun réseau social ne le rappelle au moment de l'envoi. Emma devrait retirer la position avant de publier."}$exo$::jsonb),
  ('ec59583c-2859-5492-9bfa-be68f903ff7b'::uuid, 3, 'redaction', $exo${"titre":"Le quatrième satellite","consigne":"Réponds en montrant ton raisonnement.","enonce":"**Donnée.** D'après le cours, une erreur d'**un millionième de seconde** sur l'horloge du récepteur fausse la position de **300 mètres**.\n\n1. Explique pourquoi une petite erreur sur le **temps** produit une erreur sur la **distance**.\n2. Quelle erreur de position produirait une erreur de **deux millionièmes** de seconde ? Et de **cinq millionièmes** ?\n3. Le cours dit que le quatrième satellite « n'est pas un supplément de précision ». Explique cette phrase.\n4. Lou utilise **OpenStreetMap** sur son téléphone. Explique ce qu'est cette carte et ce que sont les **couches** d'une carte numérique.\n5. Le GPS du téléphone de Lou émet-il des signaux vers les satellites ? Justifie.","bareme":[{"critere":"La distance est calculée à partir du temps de trajet : une erreur de temps fausse la distance","points":4},{"critere":"Proportionnalité juste : 600 m et 1 500 m","points":4},{"critere":"Le 4e satellite sert à corriger l'horloge du récepteur ; sans lui, la position serait fausse","points":5},{"critere":"OpenStreetMap carte libre alimentée par des contributeurs ; couches superposées (relief, routes, bâtiments) activées séparément","points":4},{"critere":"Non : les satellites émettent, le récepteur se contente de recevoir et calculer","points":3}],"dureeMin":16,"corrige":"1. Le récepteur calcule sa distance à chaque satellite par le **temps de trajet du signal**. Si son horloge est décalée, il se trompe sur ce temps, donc sur la **distance**, donc sur la position.\n2. L'erreur est proportionnelle : 1 millionième de seconde → 300 m, donc **2 millionièmes → 2 × 300 = 600 m**, et **5 millionièmes → 5 × 300 = 1 500 m**.\n3. Trois satellites suffisent en théorie pour la position, mais seulement si l'horloge du récepteur est exacte. Le **quatrième** sert à **corriger l'horloge du récepteur** : sans lui, une erreur minuscule fausserait la position de centaines de mètres. Il n'améliore pas un résultat déjà bon : il est **indispensable** pour obtenir un résultat juste.\n4. **OpenStreetMap** est une **carte libre**, alimentée par ses **contributeurs**. Les cartes numériques superposent des **couches** (relief, routes, bâtiments) que l'on **active séparément**.\n5. **Non**. Ce sont les satellites qui émettent en permanence l'heure et leur position ; le récepteur se contente de **recevoir** ces signaux et de **calculer** sa position."}$exo$::jsonb),
  ('8ea815b3-95dd-5167-bf75-e5984fe9a394'::uuid, 1, 'redaction', $exo${"titre":"Codes HTTP, HTML et CSS","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"1. Comment fonctionne le protocole **HTTP** ?\n2. Donne la signification des codes de réponse **200**, **301**, **404** et **500**.\n3. Qu'ajoute **HTTPS** ?\n4. Complète la phrase du cours : « HTML dit … ; CSS dit … ».","bareme":[{"critere":"HTTP fonctionne par requête du client et réponse du serveur","points":3},{"critere":"200 succès, 301 redirection, 404 introuvable, 500 erreur du serveur","points":8},{"critere":"HTTPS : chiffrement TLS et authentification du site par un certificat","points":5},{"critere":"HTML dit ce que sont les choses ; CSS dit à quoi elles ressemblent","points":4}],"dureeMin":6,"corrige":"1. HTTP fonctionne par **requête** (le navigateur demande une ressource) et **réponse** (le serveur la renvoie, avec un code).\n2. **200** : succès. **301** : redirection. **404** : introuvable. **500** : erreur du serveur.\n3. **HTTPS** ajoute le **chiffrement TLS** : le contenu devient illisible pour un tiers, et l'**identité du site** est authentifiée par un **certificat**.\n4. « HTML dit **ce que sont** les choses ; CSS dit **à quoi elles ressemblent**. »"}$exo$::jsonb),
  ('8ea815b3-95dd-5167-bf75-e5984fe9a394'::uuid, 2, 'redaction', $exo${"titre":"La page du club d'échecs","consigne":"Lis la situation et réponds en utilisant les balises et notions du cours.","enonce":"**Situation.** Karim crée la page web du club d'échecs de son lycée. Il veut y mettre : le titre principal « Club d'échecs » ; un paragraphe de présentation ; la liste des trois horaires d'entraînement ; un lien vers le site de la fédération ; la photo du tournoi de l'an dernier.\n\n1. Pour chaque élément, donne la **balise HTML** qui convient.\n2. Karim veut que tous les titres soient bleus et que la page s'adapte aux écrans de téléphone. Quel langage utilise-t-il ? Comment s'appelle une page qui s'adapte à la taille de l'écran ?\n3. Un visiteur clique sur un lien vers une page que Karim a supprimée. Quel code HTTP le serveur renvoie-t-il ?\n4. Pourquoi une page bien structurée est-elle utile aux personnes qui utilisent un **lecteur d'écran** ?","bareme":[{"critere":"Balises : h1, p, ul et li, a, img","points":7},{"critere":"CSS ; page responsive grâce aux requêtes de média","points":5},{"critere":"Code 404 (introuvable)","points":3},{"critere":"La structure permet au lecteur d'écran de repérer titres, paragraphes, listes ; aussi mieux comprise par les moteurs","points":5}],"dureeMin":10,"corrige":"1. Titre principal : **h1** ; paragraphe : **p** ; liste des horaires : **ul** avec un **li** par horaire ; lien : **a** ; photo : **img**.\n2. Il utilise le **CSS**, qui applique des règles de style (couleur, taille, police, marges, disposition). Adapter l'affichage à la taille de l'écran grâce aux **requêtes de média**, c'est rendre la page **responsive**.\n3. Le serveur renvoie le code **404** : la ressource demandée est **introuvable**.\n4. Une page bien structurée (vrais titres, paragraphes, listes) est **lisible par un lecteur d'écran**, qui peut annoncer les titres et permettre de naviguer de l'un à l'autre. Elle est aussi **mieux comprise par un moteur de recherche**."}$exo$::jsonb),
  ('8ea815b3-95dd-5167-bf75-e5984fe9a394'::uuid, 3, 'redaction', $exo${"titre":"Ce qui se passe à l'affichage","consigne":"Réponds aux questions en justifiant. La question 3 demande un court paragraphe.","enonce":"**Document.** Les étapes de l'affichage d'une page, dans le désordre :\n\n| Étape |\n|---|\n| A. Il télécharge feuilles de style, images et scripts. |\n| B. JavaScript modifie la page sans la recharger. |\n| C. Le navigateur télécharge le HTML. |\n| D. Il dessine le résultat. |\n| E. Il construit une représentation de la page. |\n\n1. Remets ces étapes dans l'ordre.\n2. Un site de vente affiche un panier qui se met à jour quand on ajoute un article, sans recharger la page. Quel langage le permet ?\n3. Le cours dit que « mélanger HTML et CSS est la première erreur du débutant ». Explique pourquoi, en t'appuyant sur l'avantage d'une seule feuille de style.\n4. Sur ce site de vente, un client s'apprête à saisir son numéro de carte. Explique ce que HTTPS apporte et pourquoi le certificat compte.","bareme":[{"critere":"Ordre juste : C, E, A, D, B","points":5},{"critere":"JavaScript rend la page interactive sans rechargement","points":3},{"critere":"Séparer contenu et présentation : une seule feuille habille des milliers de pages, on change le style sans toucher au contenu","points":6},{"critere":"HTTPS : chiffrement TLS, données illisibles pour un tiers ; certificat qui authentifie l'identité du site","points":6}],"dureeMin":15,"corrige":"1. Ordre : **C** (télécharger le HTML), **E** (construire une représentation de la page), **A** (télécharger feuilles de style, images, scripts), **D** (dessiner le résultat), **B** (JavaScript modifie la page sans la recharger).\n2. **JavaScript** : il peut modifier la page **sans la recharger**, c'est ce qui la rend **interactive**.\n3. HTML décrit **ce que sont** les choses (la structure), CSS **à quoi elles ressemblent** (la présentation). Si on mélange les deux, chaque page porte son propre style et il faut les modifier une à une. En les séparant, **une seule feuille de style peut habiller des milliers de pages** : on change toute l'apparence d'un site en modifiant un seul fichier, sans toucher au contenu.\n4. **HTTPS** ajoute le **chiffrement TLS** : le numéro de carte devient **illisible pour un tiers** qui intercepterait les échanges. Le **certificat** **authentifie l'identité du site** : le client a la garantie de parler au vrai site de vente, et pas à un imitateur."}$exo$::jsonb),
  ('dcb3c715-962c-5aca-bb37-37235e8ad924'::uuid, 1, 'redaction', $exo${"titre":"Ce que fait un navigateur","consigne":"Réponds par des phrases complètes.","enonce":"1. Cite, dans l'ordre, les étapes par lesquelles un navigateur affiche une page.\n2. Quelle est la différence entre un cookie **propre au site** et un cookie **tiers** ?\n3. Qu'impose le **RGPD** depuis 2018 pour les cookies non nécessaires ?","bareme":[{"critere":"Résoudre le DNS, envoyer une requête HTTP, télécharger les ressources, exécuter le JavaScript, dessiner la page","points":8},{"critere":"Propre au site : se souvenir de vous (panier, connexion, préférences) ; tiers : suivre la navigation d'un site à l'autre","points":8},{"critere":"Consentement libre et éclairé","points":4}],"dureeMin":6,"corrige":"1. Le navigateur **résout le DNS** (trouve l'adresse IP du site), **envoie une requête HTTP** (demande la page), **télécharge les ressources** (images, styles, scripts), **exécute le JavaScript** (rend la page interactive), puis **dessine la page**.\n2. Un cookie **propre au site** sert à **se souvenir de vous** : panier, connexion, préférences. Un cookie **tiers**, déposé par une régie publicitaire, sert à **suivre votre navigation d'un site à l'autre**.\n3. Le **RGPD** impose depuis 2018 le **consentement libre et éclairé** de l'utilisateur pour les cookies non nécessaires."}$exo$::jsonb),
  ('dcb3c715-962c-5aca-bb37-37235e8ad924'::uuid, 2, 'redaction', $exo${"titre":"Un message trop pressé","consigne":"Analyse le document et réponds en justifiant.","enonce":"**Document.** Rayan reçoit ce message :\n\n> « Votre compte bancaire sera bloqué dans 24 h. Pour l'éviter, connectez-vous immédiatement ici : http://banque-verif-securite.com et saisissez votre identifiant et votre mot de passe. »\n\n1. De quelle menace s'agit-il ? Quel est son mécanisme ?\n2. Relève deux indices qui doivent alerter Rayan.\n3. Quels **réflexes** Rayan doit-il avoir avant toute saisie de mot de passe ?\n4. Si Rayan s'est déjà fait piéger, quelle protection aurait limité les dégâts, même avec son mot de passe volé ? Explique.","bareme":[{"critere":"Hameçonnage : imiter un site de confiance pour voler des identifiants","points":5},{"critere":"Deux indices : urgence, adresse qui n'est pas celle de la banque, absence de HTTPS","points":5},{"critere":"Vérifier l'adresse exacte et le cadenas HTTPS avant toute saisie","points":5},{"critere":"Double authentification : le mot de passe seul ne suffit plus","points":5}],"dureeMin":10,"corrige":"1. C'est du **hameçonnage** : on **imite un site de confiance** (ici une banque) pour **voler des identifiants**.\n2. Indices : l'**urgence** (« bloqué dans 24 h ») qui pousse à agir sans réfléchir ; l'**adresse** banque-verif-securite.com, qui n'est pas celle de la banque ; le lien en **http**, **sans HTTPS** ; la demande de saisir identifiant et mot de passe via un lien reçu.\n3. **Vérifier l'adresse exacte du site** et la présence du **cadenas HTTPS** **avant toute saisie** de mot de passe ; en cas de doute, ne pas cliquer et aller sur le site de la banque par son adresse habituelle.\n4. La **double authentification** : elle ajoute une seconde preuve d'identité. Avec elle, **le mot de passe seul ne suffit plus** à entrer dans le compte. Et des **mots de passe différents** pour chaque site font qu'une fuite n'en compromet qu'un."}$exo$::jsonb),
  ('dcb3c715-962c-5aca-bb37-37235e8ad924'::uuid, 3, 'redaction', $exo${"titre":"Les habitudes de Lina","consigne":"Pour chaque habitude, explique le risque puis propose le bon réflexe. Termine par une phrase de conclusion.","enonce":"**Situation.** Lina décrit ses habitudes :\n\n> A. « J'utilise le même mot de passe court pour tous mes comptes, c'est plus simple. »\n> B. « Je repousse toujours les mises à jour de mon navigateur. »\n> C. « J'ai installé douze extensions, elles sont toutes gratuites. »\n> D. « Quand je veux être anonyme, j'ouvre une fenêtre de navigation privée. »\n> E. « Je consulte mes comptes sur le wifi public non chiffré de la gare. »\n\n1. Analyse chacune des cinq habitudes : quel risque, quel réflexe ?\n2. Explique pourquoi les services en ligne que Lina utilise sont gratuits, selon le cours.","bareme":[{"critere":"A : une fuite compromet tous les comptes ; mots de passe longs et différents, gestionnaire","points":4},{"critere":"B : failles connues non corrigées ; mettre à jour navigateur et système","points":3},{"critere":"C : chaque extension voit tout ce qu'on fait ; limiter les extensions","points":3},{"critere":"D : la navigation privée n'efface la trace que sur la machine, pas chez le FAI ni le site ; E : échanges exposés sur wifi non chiffré","points":6},{"critere":"Gratuité : l'attention et les données sont le produit (modèle économique)","points":4}],"dureeMin":16,"corrige":"1. **A.** Avec un seul mot de passe court, **une fuite** sur un site **compromet tous les comptes**. Réflexe : des **mots de passe longs et différents**, gérés par un **gestionnaire**, et la **double authentification**.\n**B.** Sans mise à jour, les **failles connues** restent ouvertes. Réflexe : **mettre à jour** navigateur et système, car les mises à jour corrigent ces failles.\n**C.** **Chaque extension voit tout ce que l'on fait** dans le navigateur. Réflexe : **limiter les extensions** au strict nécessaire.\n**D.** La navigation privée **n'efface la trace que sur la machine** : ni chez le **fournisseur d'accès**, ni chez le **site visité**. Elle ne rend pas anonyme.\n**E.** Sur un **wifi public non chiffré**, les **échanges sont exposés**. Réflexe : éviter d'y consulter ses comptes, et vérifier au minimum le **cadenas HTTPS**.\n2. Selon le cours, le service est gratuit parce que **l'attention et les données sont le produit** : ce n'est pas un slogan, c'est un **modèle économique** (les cookies tiers des régies publicitaires en sont l'outil)."}$exo$::jsonb),
  ('9b9370c8-9f01-59c6-ac29-a129b766e6cf'::uuid, 1, 'redaction', $exo${"titre":"Les trois étapes d'un moteur","consigne":"Réponds par des phrases complètes.","enonce":"1. Un moteur de recherche parcourt-il le Web au moment où tu tapes ta requête ? Explique.\n2. Décris les **trois étapes** du fonctionnement d'un moteur de recherche.\n3. Qu'est-ce qu'un **index inversé** ?\n4. Cite les deux critères de classement vus en cours.","bareme":[{"critere":"Non : il a déjà tout lu et rangé, il interroge son propre index","points":4},{"critere":"Exploration par des crawlers, indexation, interrogation et classement","points":7},{"critere":"Index inversé : à chaque mot, la liste des pages où il figure","points":5},{"critere":"Pertinence et popularité (liens entrants)","points":4}],"dureeMin":6,"corrige":"1. **Non**. Le moteur a **déjà tout lu et tout rangé** : au moment de la requête, il **interroge son propre index**.\n2. **Exploration** : des robots, les **crawlers**, suivent les liens de page en page et téléchargent leur contenu. **Indexation** : chaque page est analysée et rangée dans un **index inversé**. **Interrogation** : à la requête, le moteur consulte l'index et **classe** les résultats.\n3. Un **index inversé** associe **à chaque mot la liste des pages où il figure**.\n4. La **pertinence** (les mots de la requête figurent-ils dans la page, le titre, les liens ?) et la **popularité** (le nombre et la qualité des liens entrants)."}$exo$::jsonb),
  ('9b9370c8-9f01-59c6-ac29-a129b766e6cf'::uuid, 2, 'redaction', $exo${"titre":"Construire un index inversé","consigne":"Construis l'index à partir du document, puis réponds aux questions.","enonce":"**Document.** Trois pages, réduites à leurs mots-clés :\n\n| Page | Mots-clés |\n|---|---|\n| P1 | volcan, éruption, Islande |\n| P2 | volcan, Auvergne, randonnée |\n| P3 | randonnée, Islande, glacier |\n\n1. Construis l'**index inversé** de ces trois pages (un mot par ligne, avec la liste des pages).\n2. Quelles pages contiennent le mot « randonnée » ?\n3. Un utilisateur cherche les pages qui contiennent **à la fois** « volcan » et « Islande ». Lesquelles l'index donne-t-il ? Explique comment tu les trouves.\n4. Pourquoi cette organisation permet-elle de répondre très vite, sans relire toutes les pages ?","bareme":[{"critere":"Index juste : volcan P1 P2, éruption P1, Islande P1 P3, Auvergne P2, randonnée P2 P3, glacier P3","points":7},{"critere":"randonnée : P2 et P3","points":3},{"critere":"volcan (P1, P2) et Islande (P1, P3) : pages communes, soit P1","points":5},{"critere":"On lit directement la ligne du mot dans l'index déjà construit, au lieu de parcourir les pages","points":5}],"dureeMin":10,"corrige":"1. Index inversé :\n\n| Mot | Pages |\n|---|---|\n| volcan | P1, P2 |\n| éruption | P1 |\n| Islande | P1, P3 |\n| Auvergne | P2 |\n| randonnée | P2, P3 |\n| glacier | P3 |\n\n2. « randonnée » : **P2 et P3**.\n3. On lit la ligne de « volcan » (P1, P2) et celle d'« Islande » (P1, P3), puis on garde les pages présentes dans les deux listes : **P1**.\n4. L'index a été construit **à l'avance**, lors de l'indexation. À la requête, le moteur **lit directement la ligne de chaque mot** au lieu de relire toutes les pages : il n'interroge que son propre index. Il ne reste ensuite qu'à **classer** les pages trouvées."}$exo$::jsonb),
  ('9b9370c8-9f01-59c6-ac29-a129b766e6cf'::uuid, 3, 'redaction', $exo${"titre":"Deux élèves, deux pages de résultats","consigne":"Réponds en argumentant avec le cours ; la question 3 demande une méthode détaillée.","enonce":"**Situation.** Pour un exposé, Anaïs et Paul tapent exactement la même requête sur le même moteur, chacun sur son téléphone. Ils n'obtiennent pas la même page de résultats. Paul dit : « Je prends le premier lien, c'est forcément le plus fiable. »\n\n1. Explique pourquoi Anaïs et Paul n'obtiennent pas les mêmes résultats. Cite au moins deux facteurs.\n2. Discute l'affirmation de Paul.\n3. Anaïs cherche la phrase exacte d'un discours, uniquement sur le site d'un musée, publiée ces derniers mois. Indique les **techniques** qu'elle doit utiliser.\n4. Avant de citer une information dans l'exposé, que doivent-ils vérifier ?","bareme":[{"critere":"Facteurs : personnalisation (historique, localisation), liens sponsorisés, référencement","points":5},{"critere":"Premier résultat = le mieux classé par un algorithme aux critères privés, pas la vérité","points":5},{"critere":"Guillemets pour l'expression exacte, restriction au site, filtre par date, mots précis","points":5},{"critere":"Recouper : auteur, date, source, et croiser avec une autre origine","points":5}],"dureeMin":15,"corrige":"1. Les résultats sont **personnalisés** selon l'**historique** et la **localisation** de chacun. S'y ajoutent les **liens sponsorisés** (signalés comme publicité) et le **référencement**, c'est-à-dire l'optimisation faite par les sites eux-mêmes. Deux personnes tapant la même requête n'obtiennent donc pas nécessairement la même page.\n2. Paul a tort : **le premier résultat n'est pas la vérité**, c'est la réponse **la mieux classée par un algorithme dont les critères sont privés** (pertinence, popularité, personnalisation), et ce peut même être un lien sponsorisé. Être bien classé ne prouve pas être fiable.\n3. Anaïs doit mettre la phrase **entre guillemets** (expression exacte), **restreindre la recherche au site** du musée, utiliser le **filtre par date** pour l'information récente, et choisir des **mots précis** pour réduire le bruit.\n4. Ils doivent **recouper** : vérifier l'**auteur**, la **date**, la **source**, et **croiser avec une autre origine** avant de citer."}$exo$::jsonb),
  ('51bdc90b-47ca-5ffd-a3b9-f2a538abada5'::uuid, 1, 'redaction', $exo${"titre":"Du Web lu au Web écrit","consigne":"Réponds par des phrases complètes.","enonce":"1. Qu'est-ce que le **web 2.0** ? À partir de quand apparaît-il ?\n2. Cite trois services du web 2.0 et ce que chacun permet.\n3. Qu'est-ce qui change vraiment avec le web 2.0 : la technique ou autre chose ?\n4. Qu'est-ce que le **contenu généré par les utilisateurs** ?","bareme":[{"critere":"Un Web où chacun publie sans savoir programmer, à partir des années 2000","points":5},{"critere":"Trois services justes avec leur usage (blogs, wikis, réseaux sociaux, avis, cartes collaboratives)","points":6},{"critere":"Les techniques existaient ; ce qui change, c'est l'interface","points":4},{"critere":"Contenu publié par les internautes eux-mêmes, devenu majoritaire","points":5}],"dureeMin":6,"corrige":"1. Le **web 2.0** est un Web où **chacun peut publier sans savoir programmer** : le premier Web se lisait, celui-ci s'écrit. Il apparaît à partir des **années 2000**.\n2. Par exemple : les **blogs** et forums (publier un texte sans savoir coder) ; les **wikis** (écrire à plusieurs sur la même page) ; les **réseaux sociaux** et plateformes vidéo (diffuser à un large public) ; les commentaires, avis, cartes collaboratives (enrichir le contenu des autres).\n3. Les **techniques existaient déjà** : ce qui change, c'est l'**interface**, qui rend la publication accessible à tous.\n4. C'est le contenu **publié par les internautes eux-mêmes** ; il devient **majoritaire** sur le Web."}$exo$::jsonb),
  ('51bdc90b-47ca-5ffd-a3b9-f2a538abada5'::uuid, 2, 'redaction', $exo${"titre":"Pourquoi Zoé ne change pas d'appli","consigne":"Lis la situation et explique-la avec les notions du cours.","enonce":"**Situation.** Zoé utilise la messagerie **Kiwi**, où se trouvent ses 50 amis. Une nouvelle application, **Pomme**, est plus rapide et plus respectueuse de la vie privée, mais aucun de ses amis n'y est inscrit.\n\n1. Pourquoi Zoé a-t-elle du mal à quitter Kiwi, alors que Pomme est meilleure ? Utilise la notion d'**effet de réseau**.\n2. Qu'est-ce que le **coût de sortie** ? Quelle conséquence a-t-il sur le marché des plateformes ?\n3. Le cours dit que c'est « un mécanisme économique, pas seulement technique ». Explique à partir de la situation de Zoé.","bareme":[{"critere":"Effet de réseau : la valeur de Kiwi croît avec le nombre d'utilisateurs ; ses amis y sont, pas sur Pomme","points":7},{"critere":"Coût de sortie : ce qu'on perd en partant ; il favorise la concentration en quelques très grands acteurs","points":7},{"critere":"Ce n'est pas la qualité technique qui décide mais le nombre d'utilisateurs, d'où un mécanisme économique","points":6}],"dureeMin":10,"corrige":"1. Kiwi bénéficie d'un **effet de réseau** : **sa valeur croît avec le nombre de ses utilisateurs**. Pour Zoé, Kiwi vaut beaucoup parce que ses 50 amis y sont ; Pomme, même meilleure techniquement, ne lui permet de parler à personne.\n2. Le **coût de sortie** est ce que l'on perd en quittant le service : ici, le contact avec ses amis. **Plus il y a de monde, plus il est coûteux de partir.** Ce coût favorise la **concentration** du marché en **quelques très grands acteurs** : les utilisateurs restent là où sont déjà les autres.\n3. Ce qui décide du choix de Zoé n'est pas la qualité technique (Pomme est meilleure) mais le **nombre d'utilisateurs** déjà présents. C'est un **mécanisme économique** : la position de Kiwi se renforce d'elle-même, parce qu'elle est déjà la plus grande."}$exo$::jsonb),
  ('51bdc90b-47ca-5ffd-a3b9-f2a538abada5'::uuid, 3, 'redaction', $exo${"titre":"L'intelligence collective a-t-elle des limites ?","consigne":"Réponds à chaque question, puis rédige une conclusion argumentée de quelques lignes.","enonce":"**Document.**\n\n> « Une encyclopédie écrite par des inconnus a fini par battre celles écrites par des spécialistes payés. Personne ne l'avait prévu. » (extrait du cours)\n\n1. De quelle encyclopédie s'agit-il ? Cite deux autres exemples réussis d'intelligence collective.\n2. Pour chacun des trois exemples, donne sa **condition de réussite**.\n3. Que produit la contribution ouverte **sans** ces règles ?\n4. Sami publie ses dessins sur une plateforme. Quelles licences lui permettent d'autoriser certains usages de ses œuvres ? Que devient ce qu'il publie, selon le cours ?\n5. Conclus : la contribution ouverte suffit-elle à garantir la qualité ?","bareme":[{"critere":"Wikipédia ; OpenStreetMap et les logiciels libres","points":4},{"critere":"Conditions : règles, vérification, contributeurs réguliers ; communauté qui corrige ; gouvernance du projet","points":5},{"critere":"Sans règles : vandalisme, désinformation, harcèlement","points":3},{"critere":"Licences Creative Commons ; publications = traces et source de données monétisées","points":4},{"critere":"Conclusion argumentée : non, la qualité dépend des règles et de la communauté","points":4}],"dureeMin":18,"corrige":"1. Il s'agit de **Wikipédia**. Autres exemples : **OpenStreetMap** et les **logiciels libres**.\n2. **Wikipédia** : des **règles**, une **vérification**, des **contributeurs réguliers**. **OpenStreetMap** : une **communauté qui corrige**. **Logiciels libres** : une **gouvernance** du projet.\n3. Sans ces règles, la contribution ouverte produit **vandalisme**, **désinformation** et **harcèlement**.\n4. Les licences **Creative Commons** permettent à un auteur d'autoriser certains usages de son œuvre. Ce que Sami publie laisse des **traces**, pose la question de ses **données personnelles**, et fait de lui **une source de données monétisées** : le contributeur n'est jamais seulement un lecteur.\n5. **Non** : la contribution ouverte peut produire une œuvre remarquable, comme Wikipédia, mais seulement quand elle est encadrée par des **règles**, une **vérification** et une **communauté** qui corrige. Le nombre de contributeurs ne suffit pas ; c'est l'organisation qui fait la qualité."}$exo$::jsonb),
  ('ef530192-87f4-5e81-acea-34beaf26774d'::uuid, 1, 'redaction', $exo${"titre":"Ce qu'est une donnée ouverte","consigne":"Réponds par des phrases complètes.","enonce":"1. Définis l'**open data**. Peut-on réutiliser une donnée ouverte à des fins commerciales ?\n2. Cite **quatre critères** qu'une donnée doit remplir pour être ouverte.\n3. Quelle loi, et de quelle année, impose aux administrations françaises de publier leurs données d'intérêt public ? Quel portail les rassemble ?","bareme":[{"critere":"Donnée que chacun peut librement consulter, réutiliser et redistribuer, y compris à des fins commerciales","points":6},{"critere":"Quatre critères justes parmi : accessible, gratuite, format ouvert, lisible par machine, métadonnées, licence explicite","points":8},{"critere":"Loi pour une République numérique de 2016 ; data.gouv.fr","points":6}],"dureeMin":6,"corrige":"1. L'**open data** désigne une donnée que **chacun peut librement consulter, réutiliser et redistribuer**, **y compris à des fins commerciales** : oui, la réutilisation commerciale est permise.\n2. Critères : **accessible** (en ligne, sans démarche) ; **gratuite** (ou à coût marginal) ; dans un **format ouvert** (CSV, JSON, XML, et non un PDF scanné) ; **lisible par machine** (exploitable sans ressaisie) ; **documentée par des métadonnées** ; sous **licence explicite** autorisant la réutilisation.\n3. La **loi pour une République numérique** de **2016** impose la publication par défaut des données d'intérêt public. Le portail **data.gouv.fr** les rassemble (budgets, résultats électoraux, horaires de transport, qualité de l'air…)."}$exo$::jsonb),
  ('ef530192-87f4-5e81-acea-34beaf26774d'::uuid, 2, 'redaction', $exo${"titre":"Trois fichiers de la mairie","consigne":"Examine chaque fichier au regard des critères de l'open data et justifie.","enonce":"**Document.** Une mairie publie en ligne, gratuitement, trois fichiers :\n\n| Fichier | Description |\n|---|---|\n| A | Les horaires des bus, dans un PDF scanné |\n| B | Les mesures de qualité de l'air au format CSV, avec une fiche qui décrit chaque colonne et une licence autorisant la réutilisation |\n| C | La liste des accidents de la route au format JSON, sans aucune description des champs ni licence |\n\n1. Pour chaque fichier, dis s'il respecte les critères de l'open data. Cite le ou les critères manquants.\n2. Quel fichier une développeuse pourrait-elle utiliser tout de suite pour créer une application de carte de la qualité de l'air ? Pourquoi ?\n3. Que faudrait-il changer au fichier A pour qu'il devienne réellement ouvert ?","bareme":[{"critere":"A non conforme : PDF scanné, ni format ouvert ni lisible par machine","points":5},{"critere":"B conforme : format ouvert, métadonnées, licence explicite","points":4},{"critere":"C non conforme : format ouvert mais sans métadonnées ni licence","points":5},{"critere":"Application sur B, exploitable sans ressaisie et réutilisation autorisée ; A publié en CSV ou JSON avec métadonnées et licence","points":6}],"dureeMin":10,"corrige":"1. **A** : **non conforme**. Un PDF scanné n'est **ni un format ouvert ni lisible par machine** : il faudrait tout ressaisir. **B** : **conforme** : format ouvert (CSV), **métadonnées** (la fiche décrit chaque colonne), **licence explicite**, accessible et gratuit. **C** : **non conforme** malgré son format ouvert (JSON) : il manque les **métadonnées** (on ne sait pas ce que contient le fichier) et la **licence** (la réutilisation n'est pas autorisée explicitement).\n2. Le fichier **B** : il est **exploitable sans ressaisie**, on sait ce que contient chaque colonne, et la licence **autorise la réutilisation**, y compris dans une application.\n3. Il faudrait publier les horaires dans un **format ouvert lisible par machine** (CSV ou JSON), **documenté par des métadonnées** et placé sous une **licence explicite**."}$exo$::jsonb),
  ('ef530192-87f4-5e81-acea-34beaf26774d'::uuid, 3, 'redaction', $exo${"titre":"Faut-il tout ouvrir ?","consigne":"Réponds en argumentant ; la dernière question demande un court paragraphe.","enonce":"**Situation.** Un élu propose de publier en open data le fichier des élèves inscrits à la cantine : **nom**, **adresse**, **classe**, **allergies**. Il ajoute : « Même si on retire les noms, ce sera anonyme. »\n\n1. Ces données peuvent-elles être ouvertes telles quelles ? Justifie.\n2. Discute la phrase de l'élu en expliquant le risque de **réidentification par croisement**.\n3. Cite **deux** autres limites de l'open data, en dehors des données personnelles.\n4. Cite **trois** usages utiles de l'open data et montre, en quelques lignes, qu'une donnée ouverte « ne vaut que par ce qu'on en fait ».","bareme":[{"critere":"Non : données personnelles, non ouvrables sans anonymisation solide","points":4},{"critere":"Retirer le nom ne suffit pas : adresse, classe, allergies croisées avec d'autres sources permettent de retrouver l'élève","points":6},{"critere":"Deux limites parmi : secret statistique et sécurité, qualité inégale, coût de mise à jour","points":4},{"critere":"Trois usages (applications, journalisme de données, recherche, contrôle citoyen) et idée qu'un fichier non réutilisé n'est pas une politique publique","points":6}],"dureeMin":16,"corrige":"1. **Non**. Ce sont des **données personnelles** (et les allergies touchent à la santé). Elles ne sont **pas ouvrables sans anonymisation solide**.\n2. L'élu se trompe : retirer le nom ne suffit pas. L'**adresse**, la **classe** et les **allergies**, **croisées** avec d'autres informations (un annuaire, une photo de classe, ce que chacun sait de ses voisins), permettent souvent de **retrouver l'élève**. C'est la **réidentification par croisement**, un **risque réel**.\n3. Deux limites parmi : le **secret statistique** et la **sécurité** (certaines données ne peuvent pas être publiées) ; la **qualité inégale** des jeux publiés (fichiers incomplets ou mal documentés) ; le **coût de mise à jour** (une donnée périmée vaut peu).\n4. Usages : des **applications** (horaires en temps réel, comparateurs de prix, cartes de qualité de l'air) ; le **journalisme de données** ; la **recherche** ; le **contrôle citoyen** de l'action publique. Publier ne suffit pas : ces usages n'existent que si quelqu'un se saisit du fichier. **Un fichier que personne ne réutilise est un fichier, pas une politique publique.**"}$exo$::jsonb),
  ('ca47ce74-3bde-5940-af86-fdf4f214bd51'::uuid, 1, 'redaction', $exo${"titre":"Le nuage est un bâtiment","consigne":"Réponds par des phrases complètes.","enonce":"1. Définis le **cloud**. Pourquoi le cours dit-il qu'il « n'a rien d'immatériel » ?\n2. Cite les **trois niveaux de service** du cloud et ce que chacun fournit.\n3. Cite trois éléments qu'on trouve dans un **datacenter** et le rôle de chacun.","bareme":[{"critere":"Ressources informatiques hébergées ailleurs, mises à disposition par le réseau et facturées à l'usage ; stockées sur des disques dans des bâtiments","points":7},{"critere":"Infrastructure (machines, stockage), plateforme (environnement d'exécution), logiciel (application prête à l'emploi)","points":6},{"critere":"Trois éléments justes avec leur rôle (serveurs, alimentation redondante, climatisation, liaisons multiples, réplication)","points":7}],"dureeMin":6,"corrige":"1. Le **cloud** est la mise à disposition, **par le réseau**, de **ressources informatiques hébergées ailleurs** et **facturées à l'usage**. Il n'a rien d'immatériel : un fichier envoyé « dans le nuage » atterrit **sur un disque**, dans un **bâtiment** que quelqu'un possède, alimente et refroidit.\n2. **Infrastructure** : des machines et du stockage. **Plateforme** : un environnement d'exécution. **Logiciel** : une application prête à l'emploi.\n3. Par exemple : des milliers de **serveurs en baies** (capacité de calcul et de stockage) ; une **alimentation redondante** et des **groupes électrogènes** (survivre à une coupure) ; la **climatisation** (évacuer la chaleur) ; des **liaisons réseau multiples** (rester joignable) ; la **réplication** sur plusieurs machines et plusieurs sites (survivre à une panne ou à un incendie)."}$exo$::jsonb),
  ('ca47ce74-3bde-5940-af86-fdf4f214bd51'::uuid, 2, 'redaction', $exo${"titre":"Comparer deux datacenters","consigne":"Montre tes calculs, puis justifie tes réponses.","enonce":"**Document.** Consommation d'électricité sur une année de deux datacenters :\n\n| Datacenter | Énergie totale consommée | Énergie utilisée par les calculs |\n|---|---|---|\n| Alpha | 30 GWh | 20 GWh |\n| Bêta | 26 GWh | 20 GWh |\n\n1. Rappelle la définition du **PUE**.\n2. Calcule le PUE de chaque datacenter.\n3. Lequel est le plus efficace ? Justifie. À quoi sert, selon toi, l'énergie qui ne va pas aux calculs ?\n4. Les données des clients sont **répliquées** sur plusieurs sites. Pourquoi ?","bareme":[{"critere":"PUE = énergie totale rapportée à celle qui sert réellement aux calculs","points":4},{"critere":"Calculs justes : Alpha 30 / 20 = 1,5 ; Bêta 26 / 20 = 1,3","points":6},{"critere":"Bêta plus efficace (PUE plus proche de 1) ; énergie restante surtout pour le refroidissement","points":5},{"critere":"Réplication : survivre à une panne matérielle ou à un sinistre","points":5}],"dureeMin":10,"corrige":"1. Le **PUE** est l'**énergie totale** consommée par le datacenter **rapportée à celle qui sert réellement aux calculs**.\n2. **Alpha** : 30 / 20 = **1,5**. **Bêta** : 26 / 20 = **1,3**.\n3. **Bêta** est le plus efficace : son PUE est plus petit, plus proche de 1 ; pour la même énergie de calcul (20 GWh), il consomme moins au total. L'énergie qui ne va pas aux calculs sert surtout au **refroidissement** (climatisation) et au fonctionnement du bâtiment : chez Alpha, 10 GWh ; chez Bêta, 6 GWh.\n4. La **réplication** sur plusieurs machines et plusieurs sites permet aux données de **survivre à une panne matérielle ou à un sinistre** (un incendie, par exemple)."}$exo$::jsonb),
  ('ca47ce74-3bde-5940-af86-fdf4f214bd51'::uuid, 3, 'redaction', $exo${"titre":"Le lycée passe au cloud","consigne":"Rédige une réponse argumentée, organisée en paragraphes.","enonce":"**Situation.** Un lycée veut abandonner ses propres serveurs et stocker tous les travaux des élèves et les dossiers administratifs sur le cloud d'une grande entreprise étrangère.\n\n1. Présente **trois avantages** de ce choix pour le lycée.\n2. Présente la **contrepartie** de chacun de ces avantages.\n3. Explique la question de la **souveraineté** des données : pourquoi le pays de stockage et la nationalité de l'hébergeur comptent-ils ?\n4. Un professeur dit : « Au moins, le cloud ne pollue pas. » Réponds-lui avec les repères du cours sur l'empreinte environnementale du numérique.","bareme":[{"critere":"Trois avantages : accès de partout et partage, sauvegarde automatique, capacité élastique sans investissement","points":5},{"critere":"Contreparties : dépendance à la connexion, dépendance au fournisseur, coût qui grimpe avec le volume","points":5},{"critere":"Souveraineté : la loi applicable dépend du pays de stockage et de la nationalité de l'hébergeur","points":4},{"critere":"Réponse au professeur : environ 4 % des émissions mondiales, électricité et refroidissement des datacenters, fabrication des terminaux premier poste","points":6}],"dureeMin":18,"corrige":"1. Avantages : **accès depuis n'importe où**, synchronisation et **partage** ; **sauvegarde automatique** ; une capacité **élastique** (on paie plus d'espace quand on en a besoin) **sans investissement matériel**.\n2. Contreparties : sans connexion, plus d'accès (**dépendance à la connexion**) ; le lycée dépend d'une seule entreprise (**dépendance au fournisseur**) ; un **coût qui grimpe avec le volume** stocké.\n3. Les données sont stockées dans un pays et par une entreprise d'une certaine nationalité : **la loi applicable dépend du pays de stockage et de la nationalité de l'hébergeur**. Des données d'élèves confiées à une entreprise étrangère peuvent donc relever d'une autre loi que la loi française : c'est la question de la **souveraineté**.\n4. Le professeur se trompe : le nuage, ce sont des **bâtiments climatisés**, des câbles et des factures d'électricité. Le numérique représente **environ 4 %** des émissions mondiales de gaz à effet de serre, **en croissance**. Le poste des datacenters, c'est l'**électricité et le refroidissement** (mesuré par le PUE) ; et le **principal poste** du numérique reste la **fabrication des terminaux**."}$exo$::jsonb),
  ('ed70a8c4-8a56-5978-a4aa-665810b5c881'::uuid, 1, 'redaction', $exo${"titre":"Vocabulaire des graphes et petit monde","consigne":"Réponds par des phrases complètes.","enonce":"1. Définis : le **degré** d'un sommet, la **distance** entre deux sommets, le **diamètre** d'un graphe.\n2. Qu'est-ce qu'un graphe **orienté** ? Donne un exemple tiré des réseaux sociaux.\n3. Présente l'expérience du **petit monde** : auteur, date, protocole, résultat.","bareme":[{"critere":"Degré = nombre de voisins ; distance = longueur de la plus courte chaîne ; diamètre = la plus grande de ces distances","points":7},{"critere":"Graphe orienté : relation à sens unique (je te suis sans que tu me suives)","points":4},{"critere":"Milgram, 1967, lettre à un inconnu de Boston par des connaissances personnelles, environ six intermédiaires","points":9}],"dureeMin":7,"corrige":"1. Le **degré** d'un sommet est le **nombre de ses voisins**. La **distance** entre deux sommets est la **longueur de la plus courte chaîne** qui les relie. Le **diamètre** du graphe est la **plus grande de ces distances**.\n2. Dans un graphe **orienté**, les relations ont un sens : **je te suis sans que tu me suives**, comme l'abonnement à un compte sur certains réseaux sociaux.\n3. En **1967**, le psychologue **Stanley Milgram** demande de faire parvenir une lettre à un **inconnu de Boston**, en passant **uniquement par des connaissances personnelles**. Résultat : environ **six intermédiaires** en moyenne. D'où l'expression des **six degrés de séparation**."}$exo$::jsonb),
  ('ed70a8c4-8a56-5978-a4aa-665810b5c881'::uuid, 2, 'redaction', $exo${"titre":"Les six amis","consigne":"Utilise le graphe et montre les chaînes que tu utilises.","enonce":"**Document.** Six élèves sont reliés par ces relations d'amitié :\n\n| Relation |\n|---|\n| Ana — Ben |\n| Ana — Céline |\n| Ben — Céline |\n| Céline — Driss |\n| Driss — Élia |\n| Élia — Farid |\n\n1. Donne le **degré** de chaque élève.\n2. Quelle est la **distance** entre Ana et Farid ? Écris la chaîne la plus courte.\n3. Quel est le **diamètre** de ce graphe ? Justifie.\n4. Repère un **triangle** dans ce graphe. Que signifie-t-il ?","bareme":[{"critere":"Degrés justes : Ana 2, Ben 2, Céline 3, Driss 2, Élia 2, Farid 1","points":5},{"critere":"Distance Ana-Farid = 4 : Ana-Céline-Driss-Élia-Farid","points":5},{"critere":"Diamètre = 4 (Ana-Farid, Ben-Farid), aucune distance plus grande","points":5},{"critere":"Triangle Ana-Ben-Céline : mes amis sont amis entre eux","points":5}],"dureeMin":10,"corrige":"1. **Ana : 2** (Ben, Céline) ; **Ben : 2** (Ana, Céline) ; **Céline : 3** (Ana, Ben, Driss) ; **Driss : 2** (Céline, Élia) ; **Élia : 2** (Driss, Farid) ; **Farid : 1** (Élia).\n2. Chaîne la plus courte : **Ana — Céline — Driss — Élia — Farid**, donc une distance de **4**.\n3. Les plus grandes distances sont Ana-Farid = 4 et Ben-Farid = 4 (Ben — Céline — Driss — Élia — Farid). Les autres paires sont plus proches (Céline-Farid = 3, Ana-Élia = 3…). Le **diamètre** vaut **4**.\n4. **Ana — Ben — Céline** forme un **triangle** : Ana, Ben et Céline sont tous amis entre eux. Cela traduit le fait, fréquent dans les grands réseaux sociaux, que **mes amis sont amis entre eux** (forte densité de triangles)."}$exo$::jsonb),
  ('ed70a8c4-8a56-5978-a4aa-665810b5c881'::uuid, 3, 'redaction', $exo${"titre":"La force des liens faibles","consigne":"Reprends le graphe, fais les calculs demandés, puis argumente.","enonce":"**Document.** On reprend le groupe de six élèves :\n\n| Relation |\n|---|\n| Ana — Ben |\n| Ana — Céline |\n| Ben — Céline |\n| Céline — Driss |\n| Driss — Élia |\n| Élia — Farid |\n\nDans ce graphe, le diamètre vaut 4. Ana rencontre Farid lors d'un stage : une nouvelle relation **Ana — Farid** apparaît.\n\n1. Quelle est maintenant la distance entre Ben et Farid ? Entre Céline et Farid ?\n2. Quel est le nouveau **diamètre** du graphe ? Donne une paire d'élèves qui l'atteint.\n3. Explique, à partir de cet exemple, ce que le cours appelle les **liens faibles** et pourquoi ils raccourcissent les chemins.\n4. Une rumeur part de Ben. Pourquoi le même modèle de graphe peut-il servir à étudier la diffusion d'une rumeur et celle d'un virus ? Cite une autre application de l'analyse des graphes.","bareme":[{"critere":"Ben-Farid = 2 (Ben-Ana-Farid) ; Céline-Farid = 2 (Céline-Ana-Farid)","points":5},{"critere":"Nouveau diamètre = 3, atteint par la seule paire Ben-Élia, les autres paires étant à 1 ou 2","points":5},{"critere":"Lien faible : connaissance lointaine qui relie des mondes séparés et fait chuter les distances","points":5},{"critere":"Diffusion de proche en proche le long des arêtes, pour une information comme pour une épidémie ; autre application juste","points":5}],"dureeMin":18,"corrige":"1. **Ben-Farid = 2** : Ben — Ana — Farid (avant : 4). **Céline-Farid = 2** : Céline — Ana — Farid (avant : 3).\n2. Nouvelles distances : Ben-Élia = 3 (Ben — Ana — Farid — Élia, ou Ben — Céline — Driss — Élia) ; toutes les autres paires sont à 1 ou 2 (par exemple Ben-Driss = 2, Ana-Driss = 2, Driss-Farid = 2, Céline-Élia = 2). Le **nouveau diamètre vaut 3**, atteint par la paire **Ben — Élia**.\n3. La relation Ana — Farid est un **lien faible** : une connaissance lointaine, nouée hors du groupe habituel. Ce ne sont pas les amis proches qui raccourcissent les chemins, mais ces liens qui **relient des mondes séparés** : une seule arête a fait passer le diamètre de 4 à 3 et rapproché Farid de tout le groupe.\n4. Une rumeur, comme un virus, se **transmet de proche en proche le long des arêtes** du graphe : le même modèle décrit donc la **diffusion** d'une information et celle d'une **épidémie**. Autres applications : **recommander** des contacts ou des contenus (proximité dans le graphe), **détecter des communautés** (zones fortement connectées), **repérer des comptes influents** (degré et position)."}$exo$::jsonb),
  ('ba5278ba-f4bf-5c15-83bb-5d7853cc5ed9'::uuid, 1, 'redaction', $exo${"titre":"Bulle de filtre et chambre d'écho","consigne":"Réponds par des phrases complètes.","enonce":"1. Un fil d'actualité est-il chronologique ? Sur quoi repose son classement ?\n2. Qu'est-ce que le **filtrage collaboratif** ?\n3. Quel objectif les algorithmes de recommandation optimisent-ils ?\n4. Distingue la **bulle de filtre** et la **chambre d'écho**.","bareme":[{"critere":"Non : classé par un algorithme qui prédit les réactions (clics, temps passé, interactions)","points":5},{"critere":"Recommander à partir des comportements d'utilisateurs jugés semblables","points":4},{"critere":"L'engagement : le temps et l'attention","points":4},{"critere":"Bulle : enfermement algorithmique (Eli Pariser) ; chambre d'écho : phénomène social, on ne discute qu'avec ceux qui pensent pareil","points":7}],"dureeMin":6,"corrige":"1. **Non**. Le fil est **classé** par un algorithme qui **prédit vos réactions** à partir de vos clics, du temps passé et de vos interactions.\n2. Le **filtrage collaboratif** recommande à un utilisateur ce qu'ont apprécié des **utilisateurs jugés semblables**.\n3. Ils optimisent l'**engagement** : le **temps** et l'**attention**. Ils n'optimisent ni la vérité ni l'équilibre, mais la **réaction**.\n4. La **bulle de filtre**, popularisée par **Eli Pariser**, est l'**enfermement algorithmique** dans des contenus conformes à ses opinions. La **chambre d'écho** est le **phénomène social** correspondant : on ne discute qu'avec ceux qui pensent comme soi."}$exo$::jsonb),
  ('ba5278ba-f4bf-5c15-83bb-5d7853cc5ed9'::uuid, 2, 'redaction', $exo${"titre":"La photo de l'inondation","consigne":"Analyse la situation et justifie avec les notions du cours.","enonce":"**Situation.** Théo voit passer dans son fil une photo de rues inondées, avec ce titre : « SCANDALE : ce matin, la ville est sous l'eau et personne n'en parle ! » La publication a déjà été partagée des milliers de fois. Théo, persuadé que les médias cachent tout, s'apprête à la partager lui aussi.\n\n1. Pourquoi ce type de publication circule-t-il plus vite qu'une information vérifiée ? Cite deux facteurs du cours.\n2. Quel **biais** pousse Théo à croire la publication sans la vérifier ?\n3. Quel réflexe permet de savoir si la photo est ancienne ou détournée ?\n4. Cite deux autres réflexes que Théo devrait avoir avant de partager.","bareme":[{"critere":"Surprise et indignation ; effet de répétition ou illusion de familiarité","points":6},{"critere":"Biais de confirmation : on retient ce qui nous donne raison","points":4},{"critere":"Recherche d'image inversée","points":4},{"critere":"Deux réflexes : source et date, document d'origine, recoupement, rubriques de vérification, méfiance envers l'émotion forte","points":6}],"dureeMin":10,"corrige":"1. La publication joue sur la **surprise** et l'**indignation** : une infox circule plus vite qu'une information vérifiée. Les milliers de partages créent un **effet de répétition** (ce qu'on lit souvent paraît vrai) et une **illusion de familiarité** (ce qui est connu paraît fiable).\n2. Le **biais de confirmation** : Théo pense déjà que les médias cachent tout, il retient ce qui **lui donne raison**.\n3. Une **recherche d'image inversée** montre si la photo est **ancienne ou détournée**.\n4. Vérifier la **source et sa date** (qui parle, et quand) ; retrouver l'**information d'origine** ; chercher la même information **ailleurs** (recouper) ; consulter les **rubriques de vérification** des rédactions. Et se méfier d'un titre qui provoque une émotion forte : **sa propre indignation est le levier utilisé**."}$exo$::jsonb),
  ('ba5278ba-f4bf-5c15-83bb-5d7853cc5ed9'::uuid, 3, 'redaction', $exo${"titre":"Optimiser la réaction","consigne":"Rédige une réponse argumentée, en plusieurs paragraphes, appuyée sur les notions du cours.","enonce":"**Document.**\n\n> « Un algorithme qui maximise l'engagement n'optimise ni la vérité, ni l'équilibre : il optimise la réaction. » (extrait du cours)\n\n1. Explique pourquoi une sélection des publications est **inévitable** sur un réseau social, et ce qui pose question dans cette sélection.\n2. Explique la phrase du document : comment fonctionne un système de recommandation, et pourquoi favorise-t-il ce qui fait réagir ?\n3. Montre comment ce fonctionnement peut conduire à la **bulle de filtre** et renforcer les convictions de chacun.\n4. Propose trois moyens, pour un utilisateur, de se défendre de ces effets.","bareme":[{"critere":"Personne ne peut tout lire ; la question est qui sélectionne et selon quels critères","points":4},{"critere":"Classement non chronologique, prédiction des réactions, filtrage collaboratif, objectif d'engagement","points":6},{"critere":"Bulle de filtre : contenus conformes aux opinions, convictions renforcées, avis contraires qui paraissent minoritaires","points":5},{"critere":"Trois réflexes justes : source et date, document d'origine, recoupement, image inversée, rubriques de vérification","points":5}],"dureeMin":18,"corrige":"1. **Aucun utilisateur ne peut lire tout ce qui se publie** : une sélection est donc inévitable. La question est de savoir **qui la fait**, et **selon quels critères**.\n2. Le fil **n'est pas chronologique** : il est **classé** par un algorithme qui **prédit vos réactions** à partir de vos clics, du temps passé, de vos interactions, et du comportement d'utilisateurs jugés semblables (**filtrage collaboratif**). L'objectif optimisé est l'**engagement** : le temps et l'attention. Ce qui fait réagir (la surprise, l'indignation) est donc mis en avant, qu'il soit vrai ou faux, nuancé ou non : l'algorithme optimise la **réaction**.\n3. En montrant surtout ce qui plaît à chacun, l'algorithme enferme dans des contenus **conformes à ses opinions** : c'est la **bulle de filtre** (Eli Pariser). Elle se double d'une **chambre d'écho** sociale. Résultat : **les convictions se renforcent**, et les **avis contraires paraissent minoritaires**.\n4. Vérifier la **source et sa date** ; retrouver l'**information d'origine** ; chercher la même information **ailleurs** ; faire une **recherche d'image inversée** ; consulter les **rubriques de vérification** ; se méfier des titres qui provoquent une émotion forte."}$exo$::jsonb),
  ('7176b272-9c72-569f-a00b-29ae5f6b1749'::uuid, 1, 'redaction', $exo${"titre":"Trois sortes de traces","consigne":"Classe et justifie à l'aide du cours.","enonce":"Voici six traces laissées par Inès en ligne :\n\n| Trace |\n|---|\n| a) L'avis qu'elle a écrit sur un restaurant |\n| b) L'adresse IP de sa connexion |\n| c) Une photo de classe où un ami l'a identifiée |\n| d) Son historique d'achats sur un site |\n| e) La photo de vacances qu'elle a publiée |\n| f) Un commentaire d'une camarade qui la cite |\n\n1. Classe chaque trace : **volontaire**, **involontaire** ou **héritée**. Justifie en définissant chaque catégorie.\n2. Depuis quand le **RGPD** est-il en vigueur ? Quelle autorité française contrôle son application ?","bareme":[{"critere":"Définitions justes des trois catégories (ce que l'on publie, laissée par la machine, laissée par les autres)","points":6},{"critere":"Classement juste : a et e volontaires, b et d involontaires, c et f héritées","points":9},{"critere":"RGPD depuis 2018 ; la CNIL","points":5}],"dureeMin":7,"corrige":"1. Une trace **volontaire** est ce que l'on **publie** soi-même ; une trace **involontaire** est **laissée par la machine** ; une trace **héritée** est **laissée par les autres** à notre sujet.\n- a) l'avis sur le restaurant : **volontaire**.\n- b) l'adresse IP : **involontaire**.\n- c) la photo de classe où un ami l'a identifiée : **héritée**.\n- d) l'historique d'achats : **involontaire**.\n- e) la photo de vacances qu'elle a publiée : **volontaire**.\n- f) le commentaire qui la cite : **héritée**.\n2. Le **RGPD** est en vigueur depuis **2018**. En France, c'est la **CNIL** qui contrôle et sanctionne."}$exo$::jsonb),
  ('7176b272-9c72-569f-a00b-29ae5f6b1749'::uuid, 2, 'redaction', $exo${"titre":"La photo de Manon","consigne":"Lis la situation et réponds en citant les droits et notions du cours.","enonce":"**Situation.** Manon découvre qu'un camarade a publié, sans lui demander, une photo d'elle prise à une fête, en l'identifiant par son nom. La photo est commentée et partagée. Par ailleurs, Manon voudrait savoir quelles données un réseau social a collectées sur elle depuis son inscription.\n\n1. De quel type de trace s'agit-il pour la photo ?\n2. Quel droit du RGPD permet à Manon de savoir quelles données le réseau social détient sur elle ? Et d'obtenir leur suppression ?\n3. Que peut faire Manon auprès de la plateforme au sujet de la photo ? Que dit la loi de la diffusion d'images sans consentement ?\n4. Le camarade dit : « Je l'ai supprimée de mon compte, donc elle a disparu. » A-t-il raison ?","bareme":[{"critere":"Trace héritée, laissée par un autre","points":3},{"critere":"Droit d'accès ; droit à l'effacement (droit à l'oubli)","points":6},{"critere":"Signaler le contenu à la plateforme ; diffusion d'images sans consentement = délit","points":6},{"critere":"Non : ce qui a été copié ou partagé subsiste","points":5}],"dureeMin":10,"corrige":"1. C'est une trace **héritée** : elle a été laissée par un autre, qui l'a publiée et identifiée.\n2. Le **droit d'accès** lui permet d'**obtenir ses données** ; le **droit à l'effacement**, dit **droit à l'oubli**, lui permet d'en demander la suppression. Elle peut aussi être informée, rectifier une erreur, s'opposer à un traitement, récupérer ses données (portabilité).\n3. Elle peut **exercer ses droits auprès de la plateforme** et **signaler** le contenu. La **diffusion d'images sans consentement** est un **délit**, aggravé pour les images intimes.\n4. **Non**. La photo a été commentée et partagée : **un contenu supprimé ne fait pas disparaître ce qui a déjà été copié**. Elle peut ressurgir plus tard, sortie de son contexte."}$exo$::jsonb),
  ('7176b272-9c72-569f-a00b-29ae5f6b1749'::uuid, 3, 'redaction', $exo${"titre":"« À 18 ans, je supprime tout »","consigne":"Rédige une réponse argumentée, organisée en paragraphes.","enonce":"**Document.** Adam, 15 ans, explique :\n\n> « Je publie tout ce que je veux, même les blagues limites. De toute façon, à 18 ans, je supprimerai mon compte et tout disparaîtra. Et puis j'ai accepté les conditions d'utilisation une fois, donc j'ai donné mon accord pour toujours. »\n\n1. Réponds à Adam sur l'idée que supprimer son compte fera tout disparaître. Utilise la notion de **résurgence**.\n2. Explique la phrase du cours : « Publier, c'est écrire à trois publics à la fois. »\n3. Discute l'idée d'un accord « pour toujours » à l'aide des conditions d'un **consentement** valable au sens du RGPD.\n4. Propose à Adam **trois bonnes pratiques**.","bareme":[{"critere":"Compte supprimé ne fait pas disparaître ce qui a été copié ; résurgence hors contexte, par exemple lors d'un recrutement","points":5},{"critere":"Trois publics : ceux que l'on vise, ceux que l'on n'a pas prévus, ceux qui liront dans dix ans","points":5},{"critere":"Consentement libre, spécifique, éclairé et révocable : pas un accord pour toujours","points":5},{"critere":"Trois bonnes pratiques justes : confidentialité, séparer les usages, image d'autrui, exercer ses droits et signaler","points":5}],"dureeMin":16,"corrige":"1. Adam se trompe : **un compte supprimé ne fait pas disparaître ce qui a déjà été copié**. Une publication recopiée, **sortie de son contexte**, peut **ressortir des années plus tard**, par exemple **lors d'un recrutement** : c'est la **résurgence**. Une « blague limite » peut aussi relever du **cyberharcèlement**, qui est un délit.\n2. Quand on publie, on s'adresse à **ceux que l'on vise** (ses amis), mais aussi à **ceux que l'on n'a pas prévus** (quelqu'un à qui la publication est transférée) et à **ceux qui liront dans dix ans** (un futur employeur). On ne choisit pas vraiment son public.\n3. Au sens du RGPD, le consentement doit être **libre, spécifique, éclairé et révocable**. Il n'est donc **pas donné pour toujours** : Adam peut le **retirer**, et il peut aussi exercer ses droits (accès, rectification, **effacement**, opposition).\n4. Bonnes pratiques : régler les **paramètres de confidentialité** ; **séparer les usages** (personnel, scolaire, professionnel) ; **réfléchir avant de publier l'image d'autrui** ; **exercer ses droits** auprès des plateformes et **signaler** les contenus illicites."}$exo$::jsonb),
  ('099e65eb-373f-5b5b-b745-3d1651a8782a'::uuid, 1, 'redaction', $exo${"titre":"Le pixel et ses couleurs","consigne":"Réponds en justifiant.","enonce":"1. Qu'est-ce qu'un **pixel** dans une image matricielle ?\n2. Dans le modèle **RVB**, combien de niveaux compte chaque composante codée sur 8 bits ? Combien de bits pèse un pixel couleur ? Combien de couleurs sont possibles ?\n3. Donne les composantes RVB du **noir**, du **blanc** et du **rouge vif**.","bareme":[{"critere":"Point élémentaire d'une image découpée en lignes et colonnes, portant une valeur","points":5},{"critere":"256 niveaux, 24 bits, environ 16,7 millions de couleurs","points":9},{"critere":"Noir (0, 0, 0), blanc (255, 255, 255), rouge vif (255, 0, 0)","points":6}],"dureeMin":6,"corrige":"1. Une image matricielle est découpée en **pixels**, rangés en **lignes et en colonnes**. Chaque pixel porte une **valeur** : un niveau de gris, ou trois valeurs pour la couleur.\n2. Chaque composante (rouge, vert, bleu) est codée sur **8 bits**, soit **256 niveaux** (de 0 à 255). Un pixel couleur pèse donc **24 bits** (3 × 8). Cela donne environ **16,7 millions** de couleurs possibles.\n3. **Noir** : (0, 0, 0). **Blanc** : (255, 255, 255). **Rouge vif** : (255, 0, 0)."}$exo$::jsonb),
  ('099e65eb-373f-5b5b-b745-3d1651a8782a'::uuid, 2, 'redaction', $exo${"titre":"Poids et formats","consigne":"Montre tes calculs, puis justifie tes choix de format.","enonce":"**Rappel.** Poids brut = nombre de pixels × nombre d'octets par pixel. 1 Mo = 1 000 000 octets.\n\n1. Calcule le poids brut d'une image couleur RVB de **1 920 × 1 080** pixels (un pixel RVB pèse 3 octets). Donne le résultat en octets puis en Mo (arrondi au dixième).\n2. Calcule le poids brut d'une image en **niveaux de gris** de **1 000 × 1 000** pixels, sachant qu'un pixel gris pèse 1 octet.\n3. Pour chaque usage, choisis entre **PNG**, **JPEG** et **GIF** et justifie : a) le logo du club, avec un fond transparent ; b) une photo de paysage ; c) une petite animation.","bareme":[{"critere":"1 920 × 1 080 = 2 073 600 pixels ; × 3 = 6 220 800 octets ≈ 6,2 Mo","points":7},{"critere":"1 000 × 1 000 × 1 = 1 000 000 octets = 1 Mo","points":4},{"critere":"Logo : PNG (sans perte, transparence) ; photo : JPEG (avec perte, adapté aux photos) ; animation : GIF","points":9}],"dureeMin":10,"corrige":"1. Nombre de pixels : 1 920 × 1 080 = **2 073 600**. Poids brut : 2 073 600 × 3 = **6 220 800 octets**, soit environ **6,2 Mo**.\n2. 1 000 × 1 000 = 1 000 000 pixels, × 1 octet = **1 000 000 octets = 1 Mo**. Comme le dit le cours : un million d'octets, rien d'autre.\n3. a) Le logo : **PNG**, compression **sans perte**, adapté aux logos et captures, et il gère la **transparence**. b) La photo : **JPEG**, compression **avec perte**, adaptée aux photographies (des artefacts apparaissent seulement si on compresse trop). c) L'animation : **GIF**, fait pour les petites animations (limité à 256 couleurs)."}$exo$::jsonb),
  ('099e65eb-373f-5b5b-b745-3d1651a8782a'::uuid, 3, 'redaction', $exo${"titre":"La banderole du lycée","consigne":"Réponds en montrant tes calculs et en argumentant.","enonce":"**Situation.** Pour la fête du lycée, Maëlys doit imprimer une banderole de 3 mètres de long avec le **logo** du lycée, et publier en ligne une **photo** de la fête prise en 1 920 × 1 080 pixels.\n\n1. Le logo existe en deux versions : une image **matricielle** de 200 × 100 pixels et une image **vectorielle** (SVG). Laquelle choisir pour la banderole ? Justifie par le comportement de chaque type à l'agrandissement.\n2. Pourquoi ne peut-on pas enregistrer la photo de la fête en vectoriel ?\n3. Le poids brut de la photo est de 6 220 800 octets. Enregistrée en JPEG, elle ne pèse plus que 1 500 000 octets. Combien de fois est-elle plus légère (arrondi à l'unité) ? Quelle contrepartie cette compression a-t-elle ?\n4. Avant de publier la photo, que doit vérifier Maëlys dans ses **métadonnées EXIF** ? Pourquoi ?","bareme":[{"critere":"Vectoriel : formes décrites par des équations, aucune perte à l'agrandissement ; le matriciel pixelliserait","points":6},{"critere":"Le vectoriel convient mal à la photographie","points":3},{"critere":"6 220 800 / 1 500 000 ≈ 4 fois ; contrepartie : compression avec perte, artefacts si trop compressée","points":6},{"critere":"EXIF : appareil, date et parfois position GPS à retirer avant publication","points":5}],"dureeMin":16,"corrige":"1. Il faut choisir la version **vectorielle** (SVG). Une image vectorielle stocke des **formes décrites par des équations** : on peut l'agrandir **sans aucune perte de qualité**. L'image matricielle de 200 × 100 pixels stocke une grille de pixels ; étirée sur 3 mètres, elle **pixelliserait** (chaque pixel deviendrait un gros carré visible).\n2. Le vectoriel décrit des formes géométriques ; une photographie est faite de nuances infinies qu'on ne peut pas décrire ainsi : **le vectoriel convient mal à la photographie**.\n3. 6 220 800 / 1 500 000 ≈ 4,1 : la photo est environ **4 fois plus légère**. La contrepartie : le JPEG compresse **avec perte** ; une partie de l'information est supprimée, et des **artefacts** deviennent visibles si l'on compresse trop.\n4. Les **métadonnées EXIF** enregistrent l'**appareil**, la **date** et parfois la **position GPS** du lieu de prise de vue. Maëlys doit vérifier qu'aucune position sensible ne sera publiée avec la photo."}$exo$::jsonb),
  ('a1e01900-f3b8-5864-854f-a929df5e7796'::uuid, 1, 'redaction', $exo${"titre":"Négatif et niveaux de gris","consigne":"Montre tes calculs.","enonce":"1. Comment calcule-t-on le **négatif** d'un pixel codé sur 8 bits ?\n2. Calcule le négatif des pixels suivants : (255, 0, 0) ; (0, 0, 0) ; (100, 200, 50).\n3. Convertis le pixel (90, 120, 150) en niveau de gris par la méthode de la **moyenne**.\n4. Pourquoi la méthode de la **luminance** donne-t-elle un meilleur résultat visuel que la moyenne ?","bareme":[{"critere":"Chaque composante remplacée par 255 moins sa valeur","points":4},{"critere":"Négatifs justes : (0, 255, 255), (255, 255, 255), (155, 55, 205)","points":7},{"critere":"(90 + 120 + 150) / 3 = 120","points":4},{"critere":"Moyenne pondérée où le vert compte davantage, car l'œil y est plus sensible","points":5}],"dureeMin":7,"corrige":"1. On remplace **chaque composante** par **255 moins sa valeur**.\n2. (255, 0, 0) → **(0, 255, 255)** : le rouge vif devient cyan. (0, 0, 0) → **(255, 255, 255)** : le noir devient blanc. (100, 200, 50) → (255 − 100, 255 − 200, 255 − 50) = **(155, 55, 205)**.\n3. (90 + 120 + 150) / 3 = 360 / 3 = **120**. Le pixel gris vaut (120, 120, 120).\n4. La **luminance** est une **moyenne pondérée** dans laquelle le **vert compte davantage**, parce que **l'œil est plus sensible au vert** qu'au bleu. Le gris obtenu correspond mieux à la clarté que l'on perçoit."}$exo$::jsonb),
  ('a1e01900-f3b8-5864-854f-a929df5e7796'::uuid, 2, 'redaction', $exo${"titre":"Une image de quatre pixels","consigne":"Applique chaque traitement pixel par pixel en montrant tes calculs.","enonce":"**Document.** Une minuscule image couleur de 2 × 2 pixels :\n\n| Pixel | R | V | B |\n|---|---|---|---|\n| P1 | 200 | 150 | 100 |\n| P2 | 30 | 60 | 90 |\n| P3 | 255 | 255 | 255 |\n| P4 | 120 | 90 | 60 |\n\n1. Convertis chaque pixel en niveau de gris par la méthode de la **moyenne**.\n2. Applique ensuite un **seuillage** avec un seuil de **128** : chaque pixel gris au-dessus du seuil devient blanc, en dessous il devient noir. Donne le résultat.\n3. À quoi sert le seuillage dans les traitements automatiques ?","bareme":[{"critere":"Gris justes : P1 150, P2 60, P3 255, P4 90","points":8},{"critere":"Seuillage juste : P1 blanc, P2 noir, P3 blanc, P4 noir","points":6},{"critere":"Il sépare la forme du fond : base de la reconnaissance de caractères","points":6}],"dureeMin":10,"corrige":"1. **P1** : (200 + 150 + 100) / 3 = 450 / 3 = **150**. **P2** : (30 + 60 + 90) / 3 = 180 / 3 = **60**. **P3** : (255 + 255 + 255) / 3 = **255**. **P4** : (120 + 90 + 60) / 3 = 270 / 3 = **90**.\n2. Seuil 128 : **P1** (150) → **blanc** ; **P2** (60) → **noir** ; **P3** (255) → **blanc** ; **P4** (90) → **noir**.\n3. Le seuillage **sépare la forme du fond** : l'image ne garde que du noir et du blanc. C'est la **base de la reconnaissance de caractères** et de nombreux traitements automatiques."}$exo$::jsonb),
  ('a1e01900-f3b8-5864-854f-a929df5e7796'::uuid, 3, 'redaction', $exo${"titre":"Les « vraies couleurs » de 1900","consigne":"Montre tes calculs, puis rédige une réponse argumentée à la dernière question.","enonce":"**Situation.** Un logiciel de retouche propose plusieurs filtres.\n\n1. On **permute** le rouge et le bleu du pixel (255, 0, 0). Quel pixel obtient-on ? Et pour (40, 180, 220) ?\n2. On applique **deux fois de suite** le négatif au pixel (40, 180, 220). Montre le calcul et conclus sur une propriété du négatif.\n3. Le cours dit qu'« une retouche est une fonction appliquée à un million de nombres ». Explique cette phrase.\n4. Un documentaire annonce : « Grâce à la colorisation automatique, découvrez les vraies couleurs de Paris en 1900. » Discute cette affirmation.","bareme":[{"critere":"Permutation : (0, 0, 255) et (220, 180, 40)","points":4},{"critere":"Négatif : (215, 75, 35) puis retour à (40, 180, 220) ; opération réversible","points":5},{"critere":"L'image est un tableau de nombres ; un filtre applique le même calcul à chaque pixel","points":5},{"critere":"Un modèle d'apprentissage prédit des couleurs plausibles : résultat vraisemblable, pas véridique","points":6}],"dureeMin":16,"corrige":"1. Permuter rouge et bleu : (255, 0, 0) → **(0, 0, 255)**, le rouge vif devient bleu. (40, 180, 220) → **(220, 180, 40)**.\n2. Premier négatif : (255 − 40, 255 − 180, 255 − 220) = **(215, 75, 35)**. Second négatif : (255 − 215, 255 − 75, 255 − 35) = **(40, 180, 220)**. On retrouve le pixel de départ : le négatif est **réversible**.\n3. Une image est un **tableau de nombres**. Une retouche n'est pas un geste mystérieux : c'est **un calcul (une fonction) appliqué à chacun des pixels**. Une photo d'un million de pixels, c'est un million de fois le même calcul.\n4. L'affirmation est trompeuse. La colorisation automatique utilise un **modèle d'apprentissage** qui **prédit des couleurs plausibles** ; il ne peut pas retrouver des couleurs qui n'ont jamais été enregistrées sur une photo en noir et blanc. Le résultat est **vraisemblable, pas véridique** : coloriser une photo de 1900, c'est **inventer** des couleurs plausibles, pas les retrouver."}$exo$::jsonb),
  ('8fecef23-e135-55ab-bb60-6267155cef4e'::uuid, 1, 'redaction', $exo${"titre":"Lire un histogramme","consigne":"Réponds en justifiant.","enonce":"1. Que compte l'**histogramme** d'une image ? Que porte l'abscisse, que porte l'ordonnée ?\n2. Donne le diagnostic pour chacune de ces allures :\n\n| Image | Allure de l'histogramme |\n|---|---|\n| A | Tassé à gauche |\n| B | Resserré au centre |\n| C | Tassé à droite |\n| D | Étalé sur toute la plage |\n\n3. L'histogramme dit-il si une image est belle ? Qu'indique-t-il ?","bareme":[{"critere":"Nombre de pixels pour chaque valeur ; abscisse 0 à 255 du sombre au clair, ordonnée nombre de pixels","points":6},{"critere":"A sous-exposée, B peu contrastée, C surexposée, D information bien répartie","points":10},{"critere":"Non : il dit si l'information est répartie ou entassée","points":4}],"dureeMin":6,"corrige":"1. L'histogramme compte, **pour chaque valeur possible, le nombre de pixels qui la portent**. En **abscisse** : les valeurs de **0 à 255**, des tons sombres à gauche aux tons clairs à droite. En **ordonnée** : le **nombre de pixels**.\n2. **A** : tassé à gauche → image **sous-exposée**. **B** : resserré au centre → image **peu contrastée**. **C** : tassé à droite → image **surexposée**. **D** : étalé → **information bien répartie**.\n3. **Non**. L'histogramme ne dit pas si l'image est belle : il dit si l'**information est répartie ou entassée**. C'est un outil de diagnostic."}$exo$::jsonb),
  ('8fecef23-e135-55ab-bb60-6267155cef4e'::uuid, 2, 'redaction', $exo${"titre":"Étirer un histogramme","consigne":"Applique la formule en montrant tes calculs.","enonce":"**Situation.** Une photo prise par temps de brouillard a des pixels dont les valeurs vont seulement de **80** à **170**. On applique un **étirement d'histogramme** : 80 devient 0 et 170 devient 255. Toutes les autres valeurs sont transformées par la formule :\n\n> nouvelle valeur = (ancienne valeur − 80) × 255 / 90\n\n1. À quelle allure d'histogramme correspond cette photo avant traitement ? Quel défaut a-t-elle ?\n2. Vérifie avec la formule que 80 donne 0 et que 170 donne 255.\n3. Calcule la nouvelle valeur d'un pixel à **110** et d'un pixel à **125** (arrondis à l'unité).\n4. L'étirement a-t-il inventé des détails ? Explique ce qu'il fait réellement.","bareme":[{"critere":"Histogramme resserré (au centre) : image peu contrastée","points":4},{"critere":"Vérifications justes : 0 × 255 / 90 = 0 et 90 × 255 / 90 = 255","points":4},{"critere":"110 → 30 × 255 / 90 = 85 ; 125 → 45 × 255 / 90 = 127,5, soit 127 ou 128","points":6},{"critere":"Aucun détail inventé : il étale les valeurs occupées sur toute la plage, le contraste augmente","points":6}],"dureeMin":10,"corrige":"1. Les valeurs n'occupent qu'une partie de la plage 0-255 : l'histogramme est **resserré** (ici vers le centre). L'image est **peu contrastée**.\n2. Pour 80 : (80 − 80) × 255 / 90 = 0 × 255 / 90 = **0**. Pour 170 : (170 − 80) × 255 / 90 = 90 × 255 / 90 = **255**.\n3. Pour **110** : (110 − 80) × 255 / 90 = 30 × 255 / 90 = 7 650 / 90 = **85**. Pour **125** : (125 − 80) × 255 / 90 = 45 × 255 / 90 = 127,5, soit **127 ou 128** selon l'arrondi.\n4. **Non**. L'étirement **étale les valeurs occupées sur toute la plage disponible** : les pixels sombres deviennent plus sombres, les clairs plus clairs, donc **le contraste augmente**. Mais **aucun détail n'est inventé** : on utilise mieux la place existante."}$exo$::jsonb),
  ('8fecef23-e135-55ab-bb60-6267155cef4e'::uuid, 3, 'redaction', $exo${"titre":"Sauver une photo d'astronomie","consigne":"Argumente en t'appuyant sur les notions du cours.","enonce":"**Situation.** Nour, passionnée d'astronomie, a pris deux photos.\n\n- **Photo 1** : une nébuleuse très faible, presque noire ; son histogramme est tassé à gauche et étroit.\n- **Photo 2** : la Lune, dont une grande zone est entièrement blanche, à la valeur **255**.\n\n1. Pour la photo 1, compare l'**étirement** et l'**égalisation** d'histogramme : que fait chacun ? Lequel révélera le plus de détails invisibles ?\n2. Quel **coût** l'égalisation a-t-elle ? Que risque de voir apparaître Nour ?\n3. Nour espère récupérer les détails de la zone blanche de la photo 2 par traitement. Est-ce possible ? Justifie.\n4. Nour réglait jusque-là son exposition en regardant l'écran de son appareil. Pourquoi les photographes surveillent-ils plutôt l'histogramme ?","bareme":[{"critere":"Étirement : étale les valeurs occupées sur la plage ; égalisation : redistribue pour aplatir l'histogramme","points":5},{"critere":"L'égalisation renforce fortement le contraste local et révèle des détails invisibles (utile en astronomie)","points":4},{"critere":"Coût : elle accentue le bruit, image parfois peu naturelle","points":4},{"critere":"Zone à 255 brûlée irrécupérable : les traitements ne créent pas d'information","points":4},{"critere":"L'écran trompe par sa luminosité ; l'histogramme montre objectivement la répartition","points":3}],"dureeMin":16,"corrige":"1. L'**étirement** étale les valeurs occupées sur **toute la plage disponible** : le contraste global augmente. L'**égalisation** **redistribue** les valeurs pour rendre l'histogramme **aussi plat que possible** : elle renforce fortement le **contraste local** et **révèle des détails invisibles**. Pour une nébuleuse faible, c'est l'égalisation qui en montrera le plus : elle est très utile en imagerie **astronomique**, médicale ou satellitaire.\n2. L'égalisation **accentue le bruit** : Nour risque de voir apparaître du grain, et l'image peut devenir **peu naturelle**.\n3. **Non**. Ces traitements **ne créent pas d'information** : une zone entièrement à **255**, **brûlée** par la surexposition, ne contient plus aucune différence entre ses pixels. Elle est **irrécupérable**.\n4. Parce que la **luminosité de l'écran trompe** : une image peut paraître bien exposée sur un écran lumineux. L'histogramme montre objectivement si l'information est répartie ou entassée, et s'il y a des zones brûlées. C'est pourquoi les photographes **exposent en surveillant l'histogramme** plutôt que l'écran."}$exo$::jsonb),
  ('fdeb2169-c94c-55a8-ba32-a7a3a19ca385'::uuid, 1, 'redaction', $exo${"titre":"Définition, résolution, poids","consigne":"Réponds en justifiant.","enonce":"1. Définis la **définition**, la **résolution** et le **poids** d'une image, avec leur unité.\n2. Une image fait 4 000 × 3 000 pixels. Quelle est sa définition ?\n3. Pourquoi la même image imprimée en très grand format paraît-elle floue ?\n4. Réduire la définition d'une image : que perd-on ? Et l'agrandir : que fait l'algorithme ?","bareme":[{"critere":"Définition = nombre de pixels ; résolution = densité en points par pouce ; poids = définition × octets par pixel, en octets","points":7},{"critere":"12 millions de pixels","points":3},{"critere":"Ses pixels s'étalent sur une plus grande surface","points":4},{"critere":"Réduire supprime de l'information définitivement ; agrandir interpole à partir des voisins","points":6}],"dureeMin":7,"corrige":"1. La **définition** est le **nombre de pixels** en largeur et en hauteur. La **résolution** est la **densité** à l'affichage ou à l'impression, en **points par pouce**. Le **poids** vaut **définition × octets par pixel**, en **octets**.\n2. 4 000 × 3 000 = **12 millions de pixels**.\n3. Le nombre de pixels ne change pas : imprimée en grand, l'image a ses **pixels qui s'étalent** sur une plus grande surface, donc une densité plus faible, et elle paraît floue.\n4. **Réduire** la définition **supprime de l'information, définitivement**. **Agrandir** **interpole** : l'algorithme invente des valeurs intermédiaires à partir des voisins. L'image paraît plus grande, **pas plus détaillée**."}$exo$::jsonb),
  ('fdeb2169-c94c-55a8-ba32-a7a3a19ca385'::uuid, 2, 'redaction', $exo${"titre":"Imprimer la photo de classe","consigne":"Montre tes calculs, arrondis au dixième.","enonce":"**Situation.** Le photographe du lycée fournit une photo de classe de **3 000 × 2 000 pixels**, en couleurs RVB (3 octets par pixel).\n\n**Donnée.** 1 pouce = 2,54 cm. Pour une impression nette, on vise 300 points par pouce.\n\n1. Calcule la **définition** et le **poids brut** de la photo (en octets, puis en Mo avec 1 Mo = 1 000 000 octets).\n2. À **300 points par pouce**, quelles seront les dimensions de l'impression en pouces, puis en centimètres ?\n3. Maxime veut l'imprimer en poster de **50,8 cm** de large. Quelle sera alors la résolution, en points par pouce ? La photo sera-t-elle aussi nette ? Pourquoi ?\n4. Maxime propose d'« agrandir la photo dans un logiciel pour ajouter des détails ». Réponds-lui.","bareme":[{"critere":"6 000 000 pixels ; 18 000 000 octets = 18 Mo","points":5},{"critere":"10 × 6,7 pouces soit 25,4 cm × 16,9 cm","points":5},{"critere":"50,8 cm = 20 pouces ; 3 000 / 20 = 150 points par pouce ; moins nette car les pixels s'étalent","points":5},{"critere":"Agrandir interpole à partir des voisins : plus grand, pas plus détaillé","points":5}],"dureeMin":12,"corrige":"1. Définition : 3 000 × 2 000 = **6 000 000 pixels**. Poids brut : 6 000 000 × 3 = **18 000 000 octets = 18 Mo**.\n2. Largeur : 3 000 / 300 = **10 pouces**, soit 10 × 2,54 = **25,4 cm**. Hauteur : 2 000 / 300 ≈ **6,7 pouces**, soit environ 6,67 × 2,54 ≈ **16,9 cm**.\n3. 50,8 / 2,54 = **20 pouces**. Résolution : 3 000 / 20 = **150 points par pouce**, deux fois moins que 300. La photo sera **moins nette** : le même nombre de pixels **s'étale** sur une surface plus grande.\n4. C'est impossible : agrandir **interpole**, c'est-à-dire **invente des valeurs intermédiaires** à partir des pixels voisins. L'image paraît **plus grande, pas plus détaillée**. Zoomer pour rendre lisible un détail invisible n'existe qu'au cinéma."}$exo$::jsonb),
  ('fdeb2169-c94c-55a8-ba32-a7a3a19ca385'::uuid, 3, 'redaction', $exo${"titre":"Un filtre de moyenne contre le bruit","consigne":"Montre tes calculs, puis justifie tes réponses.","enonce":"**Principe.** Un filtre de **moyenne** remplace la valeur du pixel central par la moyenne des 9 valeurs du carré 3 × 3 qui l'entoure (lui compris).\n\n**Document 1 — zone régulière (niveaux de gris)**\n\n| 10 | 20 | 30 |\n|---|---|---|\n| 40 | 50 | 60 |\n| 70 | 80 | 90 |\n\n**Document 2 — zone d'une photo prise dans l'obscurité**\n\n| 50 | 52 | 48 |\n|---|---|---|\n| 51 | 250 | 49 |\n| 50 | 50 | 50 |\n\n1. Comment s'appelle la petite matrice qui définit la façon de combiner les voisins ?\n2. Calcule la nouvelle valeur du pixel central du document 1, puis du document 2 (arrondie au dixième).\n3. Dans le document 2, le pixel central à 250 est un point de **bruit**. Quel est l'effet du filtre sur lui ? Quel usage des filtres cela illustre-t-il ?\n4. Quel effet général produit un filtre de moyenne sur une image ? Cite deux autres effets qu'on peut obtenir avec d'autres noyaux, et un domaine qui les utilise.","bareme":[{"critere":"Le noyau (filtrage par convolution)","points":3},{"critere":"Doc 1 : 450 / 9 = 50 ; doc 2 : 650 / 9 ≈ 72,2","points":6},{"critere":"Le point de bruit passe de 250 à environ 72, proche de ses voisins : réduction du bruit par lissage","points":5},{"critere":"Moyenne = flou ; autres noyaux : netteté renforcée, détection des contours ; domaine (reconnaissance de caractères, imagerie médicale)","points":6}],"dureeMin":16,"corrige":"1. C'est le **noyau** : un **filtre** remplace la valeur de chaque pixel par une combinaison de celles de ses voisins, définie par cette petite matrice (filtrage par **convolution**).\n2. **Document 1** : 10 + 20 + 30 + 40 + 50 + 60 + 70 + 80 + 90 = 450 ; 450 / 9 = **50**. Le pixel central ne change pas : la zone est régulière.\n**Document 2** : 50 + 52 + 48 = 150 ; 51 + 250 + 49 = 350 ; 50 + 50 + 50 = 150 ; total 650 ; 650 / 9 ≈ **72,2**.\n3. Le point de bruit passe de **250 à environ 72** : il se rapproche fortement de ses voisins (autour de 50) et devient beaucoup moins visible. C'est l'usage du **lissage** pour **réduire le bruit** d'une photo prise dans l'obscurité.\n4. Un filtre de moyenne produit un **flou**. D'autres noyaux donnent une **netteté renforcée** (accentuation des écarts) ou la **détection des contours** (variations brutales). La détection des formes et des contours sert à la **reconnaissance de caractères** et à l'**imagerie médicale** ; empilées, ces opérations forment les premières couches des réseaux de neurones de vision."}$exo$::jsonb),
  ('7b26be24-a961-5b58-b713-f3ec83094cef'::uuid, 1, 'redaction', $exo${"titre":"Le capteur et ses photosites","consigne":"Réponds par des phrases complètes.","enonce":"1. Quelles sont les **trois étapes** par lesquelles un capteur transforme la lumière en image ?\n2. Qu'est-ce qu'un **photosite** ? Quelle technologie équipe le plus souvent les capteurs ?\n3. Un photosite perçoit-il la couleur ? Comment obtient-on quand même une image en couleurs ?","bareme":[{"critere":"Collecter, mesurer, coder","points":4},{"critere":"Photosite : cellule qui accumule des charges proportionnelles à la lumière reçue pendant la pose ; CMOS","points":7},{"critere":"Non : il compte des photons ; filtre coloré (matrice de Bayer, deux verts pour un rouge et un bleu) puis dématriçage","points":9}],"dureeMin":7,"corrige":"1. **Collecter** la lumière, la **mesurer**, la **coder** en nombres.\n2. Un **photosite** est une cellule du capteur qui **accumule des charges électriques proportionnelles à la lumière reçue** pendant la pose. Un capteur en porte des millions. La technologie la plus courante est le **CMOS** (l'autre est le CCD).\n3. **Non** : un photosite **compte des photons**, il ne voit pas la couleur. On place devant chacun un **filtre coloré**, selon la **matrice de Bayer** (deux verts pour un rouge et un bleu). Puis un algorithme, le **dématriçage**, reconstitue les trois composantes de chaque pixel à partir des voisins."}$exo$::jsonb),
  ('7b26be24-a961-5b58-b713-f3ec83094cef'::uuid, 2, 'redaction', $exo${"titre":"Compter les filtres de Bayer","consigne":"Montre tes calculs et justifie.","enonce":"**Situation.** Le capteur d'un appareil photo compte **4 000 × 3 000 photosites**, chacun derrière un filtre de la **matrice de Bayer**.\n\n1. Combien de photosites le capteur compte-t-il en tout ?\n2. Dans la matrice de Bayer, le motif compte deux filtres verts pour un rouge et un bleu. Combien de photosites sont derrière un filtre **vert** ? **rouge** ? **bleu** ?\n3. Pourquoi y a-t-il deux fois plus de filtres verts ?\n4. Chaque photosite ne mesure qu'une seule couleur, pourtant chaque pixel de la photo finale a trois composantes. Explique comment.\n5. Un **convertisseur analogique-numérique** code chaque mesure sur 8 bits. Combien de niveaux cela donne-t-il ?","bareme":[{"critere":"12 000 000 photosites","points":3},{"critere":"Vert 6 000 000, rouge 3 000 000, bleu 3 000 000","points":6},{"critere":"La sensibilité de l'œil au vert","points":3},{"critere":"Le dématriçage reconstitue les composantes manquantes à partir des voisins","points":5},{"critere":"256 niveaux","points":3}],"dureeMin":10,"corrige":"1. 4 000 × 3 000 = **12 000 000 photosites**.\n2. Sur 4 filtres, 2 sont verts, 1 rouge, 1 bleu. **Vert** : 12 000 000 × 2 / 4 = **6 000 000**. **Rouge** : 12 000 000 / 4 = **3 000 000**. **Bleu** : **3 000 000**.\n3. Parce que l'**œil humain est plus sensible au vert** : on mesure davantage cette couleur.\n4. Un algorithme, le **dématriçage**, **reconstitue les trois composantes** de chaque pixel **à partir des voisins** : par exemple, pour un photosite vert, le rouge et le bleu sont estimés à partir des photosites rouges et bleus qui l'entourent. Un capteur ne voit pas les couleurs : le reste est du calcul.\n5. Sur **8 bits**, chaque mesure prend **256 niveaux**."}$exo$::jsonb),
  ('7b26be24-a961-5b58-b713-f3ec83094cef'::uuid, 3, 'redaction', $exo${"titre":"48 mégapixels, est-ce mieux ?","consigne":"Rédige une réponse argumentée en t'appuyant sur les facteurs de qualité vus en cours.","enonce":"**Situation.** Julien compare deux appareils :\n\n| | Téléphone | Appareil photo |\n|---|---|---|\n| Nombre de pixels | 48 millions | 24 millions |\n| Taille du capteur | Très petit | Grand |\n| Formats proposés | JPEG | JPEG et RAW (12 bits, soit 4 096 niveaux par composante) |\n\nJulien affirme : « Le téléphone est deux fois meilleur, il a deux fois plus de mégapixels. »\n\n1. Discute l'affirmation de Julien : quel facteur compte davantage que le nombre de mégapixels ? Pourquoi ?\n2. Julien photographie un concert dans une salle sombre et monte la **sensibilité**. Quel défaut apparaît ? Cite deux autres réglages ou éléments qui déterminent la quantité de lumière ou la netteté.\n3. Quel est l'intérêt du format **RAW** ? Compare les 4 096 niveaux par composante aux 256 d'un codage sur 8 bits.\n4. Pourquoi le téléphone peut-il malgré tout donner de bonnes photos ?","bareme":[{"critere":"Affirmation fausse : la taille du capteur et des photosites est plus déterminante que le nombre de mégapixels","points":5},{"critere":"Montée de la sensibilité = bruit ; ouverture, durée d'exposition ou qualité de l'optique citées","points":5},{"critere":"RAW conserve les données du capteur avant traitement ; 4 096 niveaux, 16 fois plus que 256","points":5},{"critere":"Le traitement logiciel embarqué, aujourd'hui décisif dans les téléphones","points":5}],"dureeMin":18,"corrige":"1. Julien se trompe. Selon le cours, la **taille du capteur et des photosites** est **plus déterminante que le seul nombre de mégapixels**. Sur un très petit capteur, 48 millions de photosites sont minuscules : chacun reçoit peu de lumière. L'appareil a deux fois moins de pixels, mais des photosites bien plus grands.\n2. La montée de la **sensibilité** génère du **bruit**. La quantité de lumière reçue dépend aussi de l'**ouverture** et de la **durée d'exposition** ; la netteté dépend de la **qualité de l'optique** (aberrations).\n3. Le format **RAW** **conserve les données du capteur avant traitement**. Sur 12 bits, il offre **4 096 niveaux** par composante, contre **256** sur 8 bits : 4 096 / 256 = **16 fois plus** de nuances, donc plus de marge pour corriger la photo ensuite.\n4. Parce que le **traitement logiciel embarqué** est aujourd'hui **décisif dans les téléphones** : il compense en partie la petite taille du capteur."}$exo$::jsonb),
  ('4d812c22-0c4f-5705-aec8-bde78a19c657'::uuid, 1, 'redaction', $exo${"titre":"Le principe du positionnement","consigne":"Réponds par des phrases complètes.","enonce":"1. Un téléphone émet-il un signal vers les satellites pour se localiser ? Explique ce que fait le satellite et ce que fait le récepteur.\n2. Associe chaque système de positionnement à son origine : GPS, Galileo, GLONASS, Beidou.\n3. Pourquoi les satellites embarquent-ils une **horloge atomique** ?","bareme":[{"critere":"Non : le satellite émet l'heure d'émission et sa position, le récepteur compare à l'heure de réception et en déduit sa distance","points":8},{"critere":"GPS États-Unis, Galileo Union européenne, GLONASS Russie, Beidou Chine","points":6},{"critere":"L'heure doit être extrêmement précise : une infime erreur de temps donne une grande erreur de distance","points":6}],"dureeMin":6,"corrige":"1. **Non** : le téléphone **écoute et calcule**. Le **satellite** émet en permanence l'**heure d'émission**, donnée par une horloge atomique, et **sa position**. Le **récepteur** compare cette heure à l'**heure de réception** et en déduit sa **distance** au satellite.\n2. **GPS** : États-Unis. **Galileo** : Union européenne. **GLONASS** : Russie. **Beidou** : Chine.\n3. La distance est calculée à partir d'un **temps de vol** : une **erreur infime sur l'heure** produit une **grande erreur de distance**. Il faut donc une horloge extrêmement précise, l'**horloge atomique**."}$exo$::jsonb),
  ('4d812c22-0c4f-5705-aec8-bde78a19c657'::uuid, 2, 'redaction', $exo${"titre":"Satellite après satellite","consigne":"Montre tes calculs et explique chaque étape de la trilatération.","enonce":"**Donnée.** Le signal d'un satellite voyage à environ **300 000 km par seconde**.\n\n1. Le signal d'un satellite met **0,07 seconde** pour arriver au récepteur. À quelle distance du satellite se trouve le récepteur ?\n2. Complète : avec **1** satellite, la position possible est… ; avec **2**, … ; avec **3**, … ; avec **4**, … .\n3. Le cours précise : « Ce n'est pas de la triangulation d'angles. » Explique.\n4. Une erreur de **0,001 seconde** (un millième) sur l'horloge du récepteur fausserait la distance de combien de kilomètres ? Qu'en conclus-tu sur le rôle du quatrième satellite ?","bareme":[{"critere":"300 000 × 0,07 = 21 000 km","points":4},{"critere":"1 : une sphère ; 2 : un cercle ; 3 : deux points dont un seul plausible ; 4 : position et altitude avec correction de l'horloge","points":7},{"critere":"Calcul de distances à partir de temps de vol, et non mesure d'angles","points":4},{"critere":"300 000 × 0,001 = 300 km ; le 4e satellite corrige l'horloge du récepteur, qui n'est pas atomique","points":5}],"dureeMin":12,"corrige":"1. Distance = vitesse × temps = 300 000 × 0,07 = **21 000 km**.\n2. Avec **1** satellite : une **sphère** de positions possibles. Avec **2** : un **cercle**. Avec **3** : **deux points**, dont un seul est plausible. Avec **4** : la **position et l'altitude**, en **corrigeant l'horloge du récepteur**.\n3. On ne mesure pas des angles : on calcule des **distances** à partir de **temps de vol** du signal. C'est la **trilatération**.\n4. 300 000 × 0,001 = **300 km** d'erreur. L'horloge du récepteur **n'est pas atomique** : une erreur minuscule rendrait la position inutilisable. Le **quatrième satellite** sert justement à **corriger cette horloge**."}$exo$::jsonb),
  ('4d812c22-0c4f-5705-aec8-bde78a19c657'::uuid, 3, 'redaction', $exo${"titre":"La journée de Zoé","consigne":"Analyse chaque situation, puis rédige un court paragraphe argumenté.","enonce":"**Situation.** Zoé utilise la localisation de son téléphone toute la journée :\n\n| Moment | Lieu |\n|---|---|\n| 8 h | Dans une rue étroite, entre de hauts immeubles |\n| 10 h | En randonnée, sur un plateau dégagé |\n| 12 h | Dans un centre commercial |\n| 15 h | Dans un tunnel routier |\n\n1. Pour chaque moment, indique la **précision** attendue du positionnement par satellite et explique pourquoi.\n2. Au centre commercial et dans le tunnel, le téléphone indique tout de même une position. Quels **appoints** utilise-t-il ? Que fait chacun ?\n3. Une application de lampe de poche demande à Zoé l'accès permanent à sa position. En quelques lignes, explique pourquoi la position est une donnée **sensible** et ce que Zoé devrait faire.","bareme":[{"critere":"8 h dégradée par réflexion sur les façades ; 10 h quelques mètres en terrain dégagé","points":5},{"critere":"12 h et 15 h fortement dégradée voire nulle (intérieur, tunnel)","points":4},{"critere":"Appoints : antennes du réseau mobile, wifi répertoriés, capteurs internes, avec leur apport","points":5},{"critere":"Position sensible : domicile, travail, habitudes, fréquentations ; protégée par le RGPD ; limiter l'autorisation à l'usage réel","points":6}],"dureeMin":18,"corrige":"1. **8 h** : en ville, la précision est **dégradée** par la **réflexion des signaux sur les façades**. **10 h** : en terrain dégagé, précision de **quelques mètres**. **12 h** : en intérieur, précision **fortement dégradée, voire nulle** (les signaux traversent mal les bâtiments). **15 h** : en tunnel, **fortement dégradée, voire nulle**.\n2. Le téléphone utilise des **appoints** : les **antennes du réseau mobile** (une position approchée, rapide) ; les **réseaux wifi répertoriés** (une position en intérieur, utile au centre commercial) ; les **capteurs internes** (accéléromètre, gyroscope, boussole), qui assurent la **continuité entre deux points**, par exemple dans le tunnel.\n3. La position est l'une des données les plus **sensibles** : elle révèle le **domicile**, le **travail**, les **habitudes**, les **fréquentations**. Le **RGPD** la protège. Une lampe de poche n'a aucun besoin de savoir où est Zoé : l'autorisation demandée par une application **mérite d'être limitée à l'usage réel**. Zoé devrait **refuser** cet accès."}$exo$::jsonb),
  ('c470312a-57d1-583f-a0d5-fdddf942241e'::uuid, 1, 'redaction', $exo${"titre":"La route devient un graphe","consigne":"Réponds par des phrases complètes.","enonce":"1. Pour calculer un itinéraire, comment modélise-t-on un réseau routier ? Que représentent les **sommets**, les **arêtes** et le **poids** ?\n2. Cite trois poids possibles et l'itinéraire que chacun donne.\n3. Présente l'**algorithme de Dijkstra** : sa date, ce qu'il calcule, sa condition sur les poids.","bareme":[{"critere":"Graphe pondéré : sommets = intersections, arêtes = tronçons, poids = ce que l'on minimise","points":6},{"critere":"Distance (plus court), durée (plus rapide), coût composite (péages, pente, interdictions)","points":6},{"critere":"1959 ; plus court chemin d'un sommet vers tous les autres ; poids positifs","points":8}],"dureeMin":6,"corrige":"1. On modélise le réseau par un **graphe pondéré** : les **sommets** sont les **intersections**, les **arêtes** les **tronçons de route**, et le **poids** de chaque arête est **ce que l'on cherche à minimiser**.\n2. La **distance** donne le trajet le plus **court** ; la **durée** donne le plus **rapide** (vitesse autorisée, type de voie, feux, trafic) ; un **coût composite** tient compte des **péages**, de la **pente** ou des **interdictions de tourner**.\n3. L'**algorithme de Dijkstra** date de **1959**. Il calcule le **plus court chemin d'un sommet vers tous les autres**. Il part de l'origine, explore les sommets les plus proches et met à jour les distances. Condition : les poids doivent être **positifs**."}$exo$::jsonb),
  ('c470312a-57d1-583f-a0d5-fdddf942241e'::uuid, 2, 'redaction', $exo${"titre":"De la maison au lycée","consigne":"Applique l'algorithme de Dijkstra en présentant tes étapes.","enonce":"**Document.** Le trajet de Nils entre sa maison **M** et le lycée **L** passe par trois carrefours A, B et C. Les distances sont en kilomètres :\n\n| Tronçon | Distance |\n|---|---|\n| M — A | 2 |\n| M — B | 5 |\n| A — B | 1 |\n| A — C | 6 |\n| B — C | 2 |\n| B — L | 7 |\n| C — L | 1 |\n\n1. Applique l'algorithme de Dijkstra à partir de M : à chaque étape, indique le sommet choisi et les distances mises à jour.\n2. Quel est le plus court chemin de M à L, et sa longueur ?\n3. Vérifie ton résultat en calculant la longueur du chemin M — B — L.","bareme":[{"critere":"Étapes justes : M 0 ; A choisi (2), B mis à jour à 3 ; B choisi (3), C à 5 et L à 10 ; C choisi (5), L mis à jour à 6","points":10},{"critere":"Plus court chemin M-A-B-C-L de 6 km","points":6},{"critere":"M-B-L = 5 + 7 = 12 km, plus long","points":4}],"dureeMin":12,"corrige":"1. Départ : M = 0, les autres inconnus.\n- On part de **M** : A = 2, B = 5.\n- Sommet le plus proche non traité : **A (2)**. Par A : B = min(5 ; 2 + 1) = **3** ; C = 2 + 6 = **8**.\n- Suivant : **B (3)**. Par B : C = min(8 ; 3 + 2) = **5** ; L = 3 + 7 = **10**.\n- Suivant : **C (5)**. Par C : L = min(10 ; 5 + 1) = **6**.\n- Suivant : **L (6)** : c'est fini.\n2. Le plus court chemin est **M — A — B — C — L**, de longueur 2 + 1 + 2 + 1 = **6 km**.\n3. M — B — L = 5 + 7 = **12 km** : deux fois plus long. Le chemin le plus direct en nombre de tronçons n'est pas le plus court."}$exo$::jsonb),
  ('c470312a-57d1-583f-a0d5-fdddf942241e'::uuid, 3, 'redaction', $exo${"titre":"Le plus court n'est pas le plus rapide","consigne":"Fais les calculs demandés, puis argumente.","enonce":"**Document.** Même réseau que pour le trajet de Nils, mais on connaît cette fois la **durée** de chaque tronçon aux heures de pointe, en minutes :\n\n| Tronçon | Distance (km) | Durée (min) |\n|---|---|---|\n| M — A | 2 | 4 |\n| M — B | 5 | 6 |\n| A — B | 1 | 3 |\n| A — C | 6 | 10 |\n| B — C | 2 | 8 |\n| B — L | 7 | 5 |\n| C — L | 1 | 2 |\n\n1. Le chemin le plus court en distance est M — A — B — C — L (6 km). Calcule sa durée.\n2. Calcule la durée des chemins M — B — L et M — A — B — L. Quel est le plus rapide des trois ? Quelle distance fait-il ?\n3. Que montre cet exemple sur le choix du **poids** ?\n4. Sur un réseau de millions de sommets, pourquoi utilise-t-on l'algorithme **A étoile** plutôt que Dijkstra seul ? Explique son principe.\n5. Toutes les applications envoient les automobilistes par la même petite rue. Cite deux effets réels de ce calcul d'itinéraire sur le terrain.","bareme":[{"critere":"M-A-B-C-L = 4 + 3 + 8 + 2 = 17 min","points":4},{"critere":"M-B-L = 11 min, M-A-B-L = 12 min ; le plus rapide M-B-L, 12 km","points":5},{"critere":"Changer le poids change l'itinéraire : le plus court n'est pas le plus rapide","points":3},{"critere":"A étoile : estimation de la distance restante (vol d'oiseau) pour explorer d'abord dans la bonne direction ; Dijkstra explore trop","points":4},{"critere":"Deux effets : report du trafic dans des rues résidentielles, commerce écarté, déviation saturée","points":4}],"dureeMin":18,"corrige":"1. M — A — B — C — L : 4 + 3 + 8 + 2 = **17 minutes**.\n2. M — B — L : 6 + 5 = **11 minutes**. M — A — B — L : 4 + 3 + 5 = **12 minutes**. Le plus rapide est **M — B — L**, en 11 minutes, mais il fait 5 + 7 = **12 km**, deux fois plus que le plus court.\n3. **Changer le poids change l'itinéraire** : minimiser la distance donne M — A — B — C — L, minimiser la durée donne M — B — L. **Le plus court n'est pas le plus rapide.** Un GPS ne cherche pas la belle route : il minimise la quantité qu'on lui a demandé de minimiser.\n4. Sur un réseau de millions de sommets, **Dijkstra seul explore trop** : il avance dans toutes les directions. **A étoile** ajoute une **estimation de la distance restante** (le **vol d'oiseau**) pour **explorer d'abord dans la bonne direction**. On utilise aussi des **prétraitements** qui hiérarchisent le réseau (les autoroutes d'abord).\n5. Effets réels : **reporter le trafic dans des rues résidentielles**, **faire disparaître un commerce d'un trajet**, **saturer une déviation** que tout le monde emprunte au même moment."}$exo$::jsonb),
  ('a90a6e27-fd3f-5109-b05b-7c7b6ece37f2'::uuid, 1, 'redaction', $exo${"titre":"Capteurs, commande, actionneurs","consigne":"Classe chaque élément et justifie à l'aide des définitions du cours.","enonce":"Voici des éléments d'un **portail automatique** :\n\n| Élément |\n|---|\n| a) Le moteur qui ouvre le portail |\n| b) Le détecteur de présence |\n| c) Le microcontrôleur qui applique le programme |\n| d) Le voyant clignotant |\n| e) Le capteur de lumière |\n\n1. Définis les **trois organes** d'un système automatisé.\n2. Classe chacun des cinq éléments dans l'un des trois organes.","bareme":[{"critere":"Capteurs : transforment une grandeur physique en signal ; commande : applique un programme ; actionneurs : agissent sur le monde","points":9},{"critere":"Classement juste : a et d actionneurs, b et e capteurs, c partie commande","points":11}],"dureeMin":6,"corrige":"1. Les **capteurs** transforment une **grandeur physique en signal** (température, lumière, distance, présence…). La **partie commande** **applique un programme** (un microcontrôleur). Les **actionneurs** **agissent sur le monde** (moteur, vérin, résistance chauffante, vanne, voyant).\n2. a) Le moteur : **actionneur**. b) Le détecteur de présence : **capteur**. c) Le microcontrôleur : **partie commande**. d) Le voyant clignotant : **actionneur**. e) Le capteur de lumière : **capteur**."}$exo$::jsonb),
  ('a90a6e27-fd3f-5109-b05b-7c7b6ece37f2'::uuid, 2, 'redaction', $exo${"titre":"Grille-pain ou thermostat","consigne":"Lis la situation et réponds en justifiant.","enonce":"**Situation.** Dans la cuisine de Salomé, deux appareils :\n\n- un **grille-pain** qui chauffe pendant 2 minutes, puis s'arrête, que le pain soit doré ou non ;\n- un **radiateur** réglé sur **20 °C** : il mesure la température de la pièce, chauffe quand elle est en dessous de 20 °C et s'arrête quand elle l'atteint.\n\n1. Lequel fonctionne en **boucle ouverte** ? Lequel en **boucle fermée** ? Justifie.\n2. Pour le radiateur, identifie le **capteur**, l'**actionneur** et la **consigne**.\n3. Explique la phrase du cours : « Sans rétroaction, une machine applique une recette. Avec rétroaction, elle poursuit un objectif. »","bareme":[{"critere":"Grille-pain en boucle ouverte (exécute sans vérifier) ; radiateur en boucle fermée (mesure et corrige)","points":7},{"critere":"Capteur de température, résistance chauffante (actionneur), consigne 20 °C","points":6},{"critere":"Boucle ouverte : suit une durée fixe quel que soit le résultat ; boucle fermée : mesure l'effet et corrige pour atteindre la consigne","points":7}],"dureeMin":10,"corrige":"1. Le **grille-pain** fonctionne en **boucle ouverte** : il exécute sa tâche (chauffer 2 minutes) **sans vérifier le résultat**. Le **radiateur** fonctionne en **boucle fermée** : il **mesure l'effet de son action** (la température) et **corrige** (il chauffe ou s'arrête).\n2. **Capteur** : le capteur de **température**. **Actionneur** : la **résistance chauffante** du radiateur. **Consigne** : **20 °C**, la valeur à laquelle la partie commande compare la mesure.\n3. Le grille-pain **applique une recette** : 2 minutes, quel que soit l'état du pain. Le radiateur **poursuit un objectif** : il ajuste son action tant que la température n'est pas celle de la consigne. C'est la **rétroaction** qui fait la différence."}$exo$::jsonb),
  ('a90a6e27-fd3f-5109-b05b-7c7b6ece37f2'::uuid, 3, 'redaction', $exo${"titre":"La serre du lycée","consigne":"Analyse le système, puis argumente sur ses enjeux.","enonce":"**Situation.** Le lycée installe une serre automatisée. Un capteur mesure la température ; un microcontrôleur la compare à une **consigne de 22 °C** ; s'il fait trop chaud, il ouvre les fenêtres de toit grâce à un **vérin** ; s'il fait trop froid, il allume un **chauffage**. Le système est relié au réseau du lycée pour être surveillé à distance.\n\n1. Décris la **boucle de rétroaction** de la serre, étape par étape, en nommant les trois organes.\n2. Un jour, le capteur tombe en panne et indique **30 °C** en permanence, alors qu'il fait 12 °C dehors. Que fait le système ? Quelles conséquences pour les plantes ?\n3. Quel risque supplémentaire apparaît parce que la serre est **connectée** au réseau ?\n4. Le cours affirme qu'« un même schéma décrit une machine à laver et un avion en pilotage automatique ». Explique, puis cite une question qui reste ouverte pour les véhicules autonomes.","bareme":[{"critere":"Boucle : capteur mesure, commande compare à 22 °C, actionneurs (vérin, chauffage) corrigent, nouvelle mesure","points":6},{"critere":"Capteur défaillant : le système croit qu'il fait trop chaud, ouvre les fenêtres, n'allume jamais le chauffage ; les plantes gèlent ou souffrent du froid","points":5},{"critere":"Cybersécurité : un système connecté peut être attaqué ou piloté à distance","points":4},{"critere":"Même triplet capteurs, commande, actionneurs, seule la complexité change ; question de la responsabilité en cas d'accident","points":5}],"dureeMin":18,"corrige":"1. Le **capteur** mesure la température de la serre et la transforme en signal. La **partie commande** (le microcontrôleur) la **compare à la consigne** de 22 °C. Si elle est trop haute, elle commande le **vérin**, qui ouvre les fenêtres ; si elle est trop basse, elle commande le **chauffage** : ce sont les **actionneurs**. Le capteur mesure à nouveau l'effet de l'action, et le système corrige encore : c'est une **boucle fermée**.\n2. Le système **décide à partir d'une information fausse** : il croit qu'il fait 30 °C, donc trop chaud. Il **ouvre les fenêtres** et **n'allume jamais le chauffage**, alors qu'il fait 12 °C dehors. Les plantes risquent de souffrir du froid, voire de geler. C'est le risque de **fiabilité** : un capteur en panne fait prendre une mauvaise décision.\n3. La **cybersécurité** : dès que le système est **connecté**, quelqu'un peut tenter d'y entrer, de fausser ses mesures ou de le piloter à distance.\n4. Tous ces systèmes reposent sur le **même triplet** : des **capteurs**, une **partie commande**, des **actionneurs**, souvent en boucle fermée ; **seule la complexité change**. Pour les **véhicules autonomes**, la question de la **responsabilité en cas d'accident** reste largement ouverte."}$exo$::jsonb),
  ('b4d04c80-bd68-5fcf-bfed-8dbc829fba0a'::uuid, 1, 'redaction', $exo${"titre":"Des objets qui parlent au réseau","consigne":"Réponds par des phrases complètes.","enonce":"1. Qu'est-ce que l'**Internet des objets** ?\n2. Cite **trois facteurs** qui l'ont rendu possible et l'apport de chacun.\n3. Associe chaque application à son domaine : compteur communicant, sonde d'humidité dans un champ, traçabilité des colis, éclairage adaptatif des rues.","bareme":[{"critere":"Extension du réseau à des objets du quotidien capables de mesurer, communiquer et parfois agir","points":5},{"critere":"Trois facteurs justes avec leur apport : miniaturisation et baisse du coût des capteurs, réseaux sans fil, IPv6, cloud","points":9},{"critere":"Énergie, agriculture, logistique, ville","points":6}],"dureeMin":6,"corrige":"1. L'**Internet des objets** désigne l'**extension du réseau à des objets du quotidien** capables de **mesurer**, de **communiquer** et parfois d'**agir**.\n2. La **miniaturisation** et la **chute du coût des capteurs** (des objets à quelques euros) ; les réseaux **sans fil** (wifi, Bluetooth, 4G et 5G, réseaux basse consommation à longue portée) ; l'**IPv6** (un adressage sans limite pratique) ; le **cloud** (stocker et traiter les flux collectés).\n3. Compteur communicant : **énergie**. Sonde d'humidité : **agriculture** (agriculture de précision). Traçabilité des colis : **logistique**. Éclairage adaptatif : **ville**."}$exo$::jsonb),
  ('b4d04c80-bd68-5fcf-bfed-8dbc829fba0a'::uuid, 2, 'redaction', $exo${"titre":"La maison connectée d'Hugo","consigne":"Analyse la situation et propose des corrections justifiées.","enonce":"**Situation.** Hugo a installé chez lui une caméra connectée à 25 €, une montre qui suit son sommeil et un thermostat pilotable depuis son téléphone. Il n'a jamais changé le mot de passe de la caméra (« admin »), ni fait une seule mise à jour.\n\n1. Relève les **faiblesses** de l'installation d'Hugo et la conséquence de chacune.\n2. Pourquoi la caméra d'Hugo pourrait-elle servir à attaquer d'autres personnes ? Appuie-toi sur l'exemple vu en cours.\n3. Quelles informations **intimes** ces trois objets mesurent-ils ?\n4. Propose deux corrections simples à Hugo.","bareme":[{"critere":"Mot de passe par défaut : objet accessible à tous ; absence de mise à jour : failles ouvertes (et éventuel chiffrement absent)","points":6},{"critere":"Recrue d'un réseau de machines compromises ; botnet Mirai, caméras, grands services saturés en 2016","points":5},{"critere":"Présence, sommeil, déplacements","points":4},{"critere":"Changer le mot de passe par défaut et faire les mises à jour (ou vérifier le chiffrement)","points":5}],"dureeMin":10,"corrige":"1. Le **mot de passe par défaut** (« admin ») : l'objet est **accessible à tous**. L'**absence de mise à jour** : les **failles restent ouvertes**. S'y ajoute peut-être l'absence de **chiffrement** : les données circuleraient en clair. Ces objets deviennent des **portes d'entrée sur le réseau domestique**.\n2. Un objet mal protégé peut être pris en main et devenir une **recrue d'un réseau de machines compromises**. En **2016**, le botnet **Mirai** a mobilisé des **caméras connectées** pour **saturer de grands services**.\n3. Ces objets mesurent la **présence** à la maison (caméra, thermostat), le **sommeil** (montre), les **déplacements**.\n4. **Changer le mot de passe par défaut** pour un mot de passe long et unique ; **faire les mises à jour** pour corriger les failles connues."}$exo$::jsonb),
  ('b4d04c80-bd68-5fcf-bfed-8dbc829fba0a'::uuid, 3, 'redaction', $exo${"titre":"Des milliards de capteurs à trois euros","consigne":"Rédige une réponse argumentée, organisée en paragraphes.","enonce":"**Document.**\n\n> « Un capteur à trois euros qui envoie une mesure par heure, multiplié par des milliards : voilà le véritable changement d'échelle. » (extrait du cours)\n\n1. Explique ce document : en quoi le changement d'échelle tient-il au nombre d'objets plutôt qu'à la puissance de chacun ? Cite deux usages qui en profitent (industrie, agriculture, ville…).\n2. Un capteur envoie **une mesure par heure**. Combien de mesures envoie-t-il en une journée ? En une année de 365 jours ? Que représentent ces mesures pour **un million** de capteurs en une année ?\n3. Présente les enjeux de l'Internet des objets pour la **vie privée**, l'**environnement** et la **souveraineté**.","bareme":[{"critere":"Changement d'échelle expliqué (objets peu chers, en masse, qui mesurent en continu) et deux usages justes","points":5},{"critere":"24 mesures par jour, 8 760 par an, 8 760 000 000 pour un million de capteurs","points":5},{"critere":"Vie privée : présence, sommeil, déplacements mesurés","points":3},{"critere":"Environnement : fabrication, terres rares, obsolescence, déchets électroniques","points":4},{"critere":"Souveraineté : un objet peut cesser de fonctionner quand le fabricant ferme ses serveurs","points":3}],"dureeMin":18,"corrige":"1. Chaque capteur est simple et peu cher (**quelques euros**, grâce à la miniaturisation), mais on en déploie **des milliards**, qui mesurent en continu. C'est leur **nombre** qui change tout : une multitude de mesures sur l'habitat, l'énergie, les champs, les villes. Usages : la **maintenance prédictive** dans l'industrie, l'**agriculture de précision** (sondes d'humidité), l'**éclairage adaptatif**, le **stationnement** et la **qualité de l'air** en ville, les **compteurs communicants**.\n2. Une mesure par heure : **24** par jour ; 24 × 365 = **8 760** par an. Pour un million de capteurs : 8 760 × 1 000 000 = **8 760 000 000** mesures par an, près de 9 milliards : d'où le besoin du **cloud** pour stocker et traiter ces flux.\n3. **Vie privée** : ces objets mesurent la **présence**, le **sommeil**, les **déplacements**. **Environnement** : leur **fabrication**, les **terres rares**, l'**obsolescence** et les **déchets électroniques**. **Souveraineté** : un objet **cesse parfois de fonctionner quand son fabricant ferme ses serveurs** ; l'utilisateur dépend d'une entreprise pour un objet qu'il a acheté."}$exo$::jsonb),
  ('754e6de5-1d60-5787-9c66-645ba7b1a14b'::uuid, 1, 'redaction', $exo${"titre":"Les réglages de la charge d'entraînement","consigne":"Réponds à chaque question par quelques phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Cite les **quatre paramètres** de la charge d'entraînement et dis comment chacun se mesure.\n2. Explique les trois temps de la **surcompensation**.\n3. Énonce le principe de **progressivité** (avec son chiffre) et celui de **spécificité**.","bareme":[{"critere":"Volume, intensité, densité, fréquence avec leur mesure","points":8},{"critere":"Effort, récupération, surcompensation expliqués dans l'ordre","points":7},{"critere":"Progressivité par paliers de 5 à 10 % par semaine et spécificité","points":5}],"dureeMin":7,"corrige":"1. Le **volume** (quantité de travail : durée, distance, nombre de répétitions) ; l'**intensité** (difficulté : pourcentage de VMA ou de charge maximale) ; la **densité** (rapport effort / repos : temps de récupération entre les séries) ; la **fréquence** (nombre de séances par semaine).\n2. **L'effort** fatigue : le niveau descend sous le niveau de départ. **La récupération** répare : le niveau remonte. **La surcompensation** dépasse : l'organisme reconstruit un peu au-dessus du niveau initial, par anticipation. La séance suivante doit tomber à ce moment.\n3. **Progressivité** : augmenter la charge par paliers de **5 à 10 % par semaine**, pas davantage. **Spécificité** : on progresse dans ce que l'on travaille (un nageur ne gagne pas en natation ce qu'il gagne en course à pied)."}$exo$::jsonb),
  ('754e6de5-1d60-5787-9c66-645ba7b1a14b'::uuid, 2, 'redaction', $exo${"titre":"Le programme de course de Maëlle","consigne":"Lis la situation, puis réponds en justifiant chaque réponse avec les principes du cours. Détaille les calculs.","enonce":"**Situation.** Maëlle, en seconde, prépare un 5 km. Elle court actuellement **3 fois par semaine**, **20 km** au total par semaine, avec des fractionnés à 90 % de sa VMA et 1 min 30 de récupération entre les séries.\n\nLa semaine prochaine, elle veut passer à **5 séances**, **30 km** au total, et réduire la récupération à **45 secondes**.\n\n1. Identifie les paramètres de la charge qu'elle veut modifier.\n2. Calcule l'augmentation de son volume hebdomadaire en pourcentage. Respecte-t-elle le principe de progressivité ?\n3. Explique pourquoi modifier plusieurs paramètres en même temps est une erreur.\n4. Propose-lui un plan corrigé pour la semaine prochaine, et justifie.","bareme":[{"critere":"Fréquence, volume et densité identifiés","points":4},{"critere":"Calcul juste (+50 %) et non-respect de la progressivité justifié","points":6},{"critere":"Un seul paramètre à la fois : effet illisible sinon, progrès ou blessure","points":4},{"critere":"Plan corrigé réaliste (un paramètre, +5 à 10 %) et justifié","points":6}],"dureeMin":10,"corrige":"1. Elle modifie la **fréquence** (3 → 5 séances), le **volume** (20 → 30 km) et la **densité** (récupération de 1 min 30 à 45 s). Seule l'intensité (90 % de VMA) reste identique.\n2. Augmentation : (30 − 20) ÷ 20 × 100 = **+50 %**. Le principe de **progressivité** impose des paliers de **5 à 10 % par semaine** : 50 %, c'est cinq fois trop. Elle risque la blessure et le surentraînement.\n3. Il ne faut modifier **qu'un seul paramètre à la fois** : avec deux ou trois changements simultanés, l'effet devient **illisible** — on ne sait plus lequel a produit le progrès, ni lequel a produit la blessure.\n4. Exemple : garder 3 séances et la même récupération, et passer à **21 ou 22 km** (+5 à +10 %) ; changer la fréquence ou la densité plus tard, un paramètre à la fois. Elle laisse ainsi le temps à la **récupération**, qui fait progresser."}$exo$::jsonb),
  ('754e6de5-1d60-5787-9c66-645ba7b1a14b'::uuid, 3, 'redaction', $exo${"titre":"Nathan s'entraîne plus et progresse moins","consigne":"Analyse le document, puis rédige une réponse argumentée qui relie les signes observés aux mécanismes du cours.","enonce":"**Document : carnet d'entraînement de Nathan, 16 ans, joueur de handball.**\n\n| Semaine | Séances | Fréquence cardiaque au repos | Sommeil | Test de sprint (30 m) |\n|---|---|---|---|---|\n| 1 | 3 | 58 battements/min | Bon | 4,60 s |\n| 2 | 4 | 58 | Bon | 4,55 s |\n| 3 | 6 | 63 | Réveils la nuit | 4,62 s |\n| 4 | 7 | 66 | Endormissement long | 4,75 s |\n\nNathan note aussi : « Je suis fatigué dès le matin et j'ai moins envie d'aller à l'entraînement. Je vais rajouter une séance pour rattraper mon retard. »\n\n1. Décris l'évolution de la charge et de la performance de Nathan entre les semaines 1 et 4.\n2. Relève dans le document **quatre** signes du surentraînement. Pourquoi ces signes sont-ils difficiles à repérer à temps ?\n3. À l'aide de la surcompensation, explique pourquoi Nathan progresse entre les semaines 1 et 2 puis régresse ensuite.\n4. Que penses-tu de sa décision de rajouter une séance ? Propose-lui un plan pour les deux semaines suivantes.","bareme":[{"critere":"Évolution de la charge (fréquence x2,3) et de la performance décrite avec les chiffres","points":4},{"critere":"Quatre signes relevés et lus au repos","points":5},{"critere":"Surcompensation mobilisée : séances trop rapprochées, reprise pendant la fatigue","points":6},{"critere":"Décision critiquée et plan centré sur la récupération","points":5}],"dureeMin":20,"corrige":"1. La **fréquence** passe de 3 à 7 séances par semaine (plus du double) en trois semaines. Le sprint s'améliore d'abord (4,60 → 4,55 s), puis se dégrade (4,62 puis **4,75 s**) : la performance **baisse malgré le travail**.\n2. Signes : la **fréquence cardiaque de repos** élevée de plusieurs battements (58 → 66) ; les troubles du **sommeil** (réveils nocturnes, endormissement long) ; la **fatigue** qui persiste dès le matin ; la **performance** qui baisse ; la **perte de motivation**. Ces signes se lisent **au repos, pas à l'effort** : à l'entraînement, Nathan peut encore se sentir capable, ce qui les rend difficiles à repérer à temps.\n3. La surcompensation se déroule en trois temps : l'effort fait baisser le niveau, la récupération le fait remonter, puis il dépasse le niveau de départ. En semaine 2, l'augmentation est modérée et les séances tombent au bon moment : il progresse. Ensuite, les séances sont **trop rapprochées** : il reprend pendant la **phase 1**, encore fatigué, ce qui **épuise sans construire** ; le niveau descend de séance en séance. De plus, passer de 4 à 7 séances ne respecte pas la progressivité (5 à 10 % par semaine).\n4. Rajouter une séance est une erreur : face au surentraînement, la réponse **n'est jamais d'en faire plus**, c'est de **récupérer**. Plan : réduire nettement la charge (revenir à 3 séances, en baissant le volume et l'intensité), dormir davantage, surveiller la fréquence cardiaque de repos ; quand elle revient à 58 et que le sommeil redevient bon, remonter la charge progressivement, **un paramètre à la fois**, par paliers de 5 à 10 %."}$exo$::jsonb),
  ('d793bb1f-6df1-5977-aedc-5228f608c707'::uuid, 1, 'redaction', $exo${"titre":"Les trois leviers hors du terrain","consigne":"Réponds à chaque question par quelques phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Donne le rôle des **glucides**, des **protéines** et des **lipides**, avec un aliment pour chacun.\n2. Que faut-il faire 3 h avant l'effort, pendant l'effort, et dans les 2 h qui suivent ?\n3. Combien d'heures de sommeil faut-il à un adolescent ? Que se passe-t-il pendant le sommeil profond ?","bareme":[{"critere":"Rôle et exemple des trois nutriments","points":8},{"critere":"Avant, pendant, après l'effort correctement décrits","points":7},{"critere":"8 à 9 heures, réparation tissulaire et hormone de croissance","points":5}],"dureeMin":7,"corrige":"1. **Glucides** : le **carburant principal** de l'effort (pâtes, riz, pain, fruits). **Protéines** : elles **réparent et construisent le muscle** (viande, poisson, œufs, légumineuses). **Lipides** : une énergie de **longue durée** (huiles, oléagineux, poissons gras).\n2. **3 h avant** : un repas complet et digestible (réserves pleines, digestion finie). **Pendant** : boire régulièrement, par petites quantités, avant d'avoir soif. **Dans les 2 h après** : des glucides et des protéines, la fenêtre où le muscle reconstitue ses réserves et se répare.\n3. **8 à 9 heures**. Pendant le sommeil profond se produisent la **réparation tissulaire** et la sécrétion d'**hormone de croissance** : l'entraînement ne devient du progrès que la nuit."}$exo$::jsonb),
  ('d793bb1f-6df1-5977-aedc-5228f608c707'::uuid, 2, 'redaction', $exo${"titre":"La journée de tournoi d'Inès","consigne":"Lis la situation, repère les erreurs et propose des corrections justifiées par le cours.","enonce":"**Situation.** Inès, 15 ans, joue un tournoi de volley qui commence à **14 h**. La veille, elle a regardé des vidéos sur son téléphone jusqu'à 1 h du matin et s'est levée à 7 h. À **13 h 30**, elle mange une grande assiette de frites. Pendant le tournoi, elle ne boit qu'une fois, « quand j'avais vraiment soif ». Entre deux matchs, elle boit une boisson énergisante pour « se réveiller ». Le soir, elle ne dîne pas : « je veux perdre du poids ».\n\n1. Relève **cinq** erreurs dans la journée d'Inès.\n2. Pour chacune, explique la conséquence sur sa performance ou sa récupération.\n3. Propose-lui un programme corrigé pour la veille et le jour du tournoi.","bareme":[{"critere":"Cinq erreurs correctement relevées","points":6},{"critere":"Conséquence expliquée pour chaque erreur, avec les notions du cours","points":8},{"critere":"Programme corrigé complet : sommeil, repas, hydratation, récupération","points":6}],"dureeMin":12,"corrige":"1 et 2. Erreurs et conséquences :\n- **Écrans jusqu'à 1 h, 6 h de sommeil** : les écrans retardent l'endormissement en freinant la **mélatonine** ; il lui manque 2 à 3 h sur les 8 à 9 h nécessaires ; la dette de sommeil se paie en performance et en blessures.\n- **Repas 30 min avant** : il faut manger environ **3 h avant** pour que la digestion soit finie ; un repas gras et lourd (frites) juste avant gêne l'effort.\n- **Boire seulement quand elle a soif** : la soif est déjà un signe de **déshydratation installée** ; dès **−2 %** du poids en eau, la performance chute.\n- **Boisson énergisante** : une fausse solution, qui n'améliore pas durablement la performance ; rien ne remplace la régularité.\n- **Pas de dîner** : elle manque la fenêtre des **2 h après** l'effort (glucides et protéines pour recharger et réparer) ; un régime drastique retire une fonction à l'organisme.\n3. Exemple : la veille, dîner complet et écrans coupés tôt pour dormir **8 à 9 h** ; le jour J, repas complet et digestible (féculents, protéines, légumes) vers **11 h** ; boire régulièrement par petites gorgées avant, pendant et entre les matchs ; eau plutôt que boisson énergisante ; dans les 2 h après le tournoi, un repas avec **glucides et protéines**."}$exo$::jsonb),
  ('d793bb1f-6df1-5977-aedc-5228f608c707'::uuid, 3, 'redaction', $exo${"titre":"Le complément miracle","consigne":"Analyse le document, puis rédige une réponse argumentée en plusieurs paragraphes, appuyée sur les connaissances du cours.","enonce":"**Document : publicité vue sur un réseau social.**\n\n> **MUSCLE MAX** — Le secret des champions ! Supprime les glucides, remplace tes repas par nos gélules protéinées et gagne en puissance en 7 jours. Plus besoin de dormir 9 heures : nos gélules récupèrent pour toi ! Idéal avant chaque match.\n\n**Données.** Hugo, 16 ans, pèse **60 kg**. Pendant un match de football par temps chaud, il perd environ **1,5 L** d'eau (on considère que 1 L d'eau pèse 1 kg).\n\n1. Relève **trois** affirmations de la publicité et montre, pour chacune, pourquoi elle est fausse ou dangereuse.\n2. Calcule la perte de poids en eau de Hugo en pourcentage. Que peux-tu en conclure pour sa performance, et que doit-il faire ?\n3. Explique pourquoi le sommeil ne peut être remplacé par aucun produit.\n4. Rédige un conseil à Hugo (8 à 10 lignes) sur ce qui fait vraiment progresser un sportif en dehors du terrain.","bareme":[{"critere":"Trois affirmations réfutées avec le rôle des nutriments et du sommeil","points":6},{"critere":"Calcul de 2,5 % et conclusion sur la chute de performance et l'hydratation","points":4},{"critere":"Sommeil : réparation tissulaire, hormone de croissance, 8 à 9 h","points":4},{"critere":"Conseil argumenté et organisé : assiette, timing, sommeil, refus des fausses solutions et du dopage","points":6}],"dureeMin":20,"corrige":"1. « **Supprime les glucides** » : ce sont le **carburant principal de l'effort** ; un régime qui retire une famille entière retire aussi une fonction. « **Remplace tes repas par des gélules protéinées** » : les protéines réparent et construisent le muscle, mais ne fournissent pas l'énergie de l'effort, et aucun des trois nutriments n'est à supprimer. « **Plus besoin de dormir** » : c'est pendant le sommeil profond que le corps se répare ; aucun produit ne le remplace. On peut aussi relever « en 7 jours » : les **compléments miracles** promettent de remplacer la régularité, que rien ne remplace.\n2. 1,5 kg ÷ 60 kg × 100 = **2,5 %**. Dès **2 %** du poids en eau, la performance chute déjà : Hugo perd en efficacité en fin de match. Il doit **boire avant d'avoir soif**, régulièrement, par petites quantités, avant et pendant le match.\n3. Pendant le **sommeil profond** se produisent la **réparation tissulaire** et la sécrétion d'**hormone de croissance** : l'entraînement ne devient du progrès que la nuit. Un adolescent a besoin de **8 à 9 heures** ; la dette de sommeil se paie en performance et en blessures.\n4. Conseil attendu : la performance se construit autant hors séance que pendant, grâce à trois leviers qu'aucun entraînement ne rattrape. **L'assiette** : glucides, protéines et lipides, aucun à supprimer. **Le timing** : un repas complet 3 h avant, boire pendant, glucides et protéines dans les 2 h après. **Le sommeil** : 8 à 9 h, écrans coupés le soir. Refuser les boissons énergisantes et les compléments miracles, et bien sûr le **dopage**, interdit et dangereux. La régularité fait progresser."}$exo$::jsonb),
  ('b2faf294-26a4-5a6a-a81c-5f5c1c7979a6'::uuid, 1, 'redaction', $exo${"titre":"Olympisme, dopage et santé","consigne":"Réponds à chaque question par quelques phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Qui a rénové les Jeux olympiques modernes, et en quelle année ? Cite deux valeurs affichées par l'olympisme.\n2. Quel organisme fixe la liste des produits interdits ? Les contrôles antidopage n'ont-ils lieu qu'en compétition ?\n3. Combien de minutes d'activité physique par jour l'OMS recommande-t-elle pour un adolescent ?\n4. Qu'est-ce que l'**activité physique adaptée** ?","bareme":[{"critere":"Coubertin, 1894, deux valeurs (excellence, amitié, respect)","points":6},{"critere":"AMA et contrôles hors compétition","points":6},{"critere":"60 minutes par jour","points":3},{"critere":"Activité physique prescrite par un médecin comme un soin, depuis 2016","points":5}],"dureeMin":6,"corrige":"1. **Pierre de Coubertin**, en **1894**. Valeurs : l'**excellence**, l'**amitié**, le **respect**.\n2. L'**AMA** (Agence mondiale antidopage). Non : les contrôles peuvent avoir lieu **hors compétition**, à l'entraînement comme au domicile.\n3. Au moins **60 minutes** par jour.\n4. Depuis **2016**, une activité physique qui peut être **prescrite par un médecin comme un soin**, pour les maladies chroniques."}$exo$::jsonb),
  ('b2faf294-26a4-5a6a-a81c-5f5c1c7979a6'::uuid, 2, 'redaction', $exo${"titre":"Les Jeux, une scène politique","consigne":"Appuie-toi sur le document et sur le cours pour rédiger des réponses développées.","enonce":"**Document : repères de l'histoire olympique.**\n\n| Date | Événement |\n|---|---|\n| 1936 | Jeux de Berlin |\n| 1968 | Poing levé de deux athlètes sur le podium de Mexico |\n| 1980 et 1984 | Boycotts des Jeux de Moscou puis de Los Angeles |\n\n> « Le sport n'a rien à voir avec la politique. » (propos entendu dans une émission)\n\n1. Pour chaque événement du document, explique ce qu'il révèle du lien entre sport et politique.\n2. Quel idéal Pierre de Coubertin associait-il aux Jeux en 1894 ?\n3. Rédige un paragraphe argumenté qui discute le propos cité, à l'aide des exemples du document.","bareme":[{"critere":"Trois événements correctement expliqués (vitrine nazie, tribune, guerre froide)","points":9},{"critere":"Idéal de paix par le sport","points":3},{"critere":"Paragraphe argumenté qui réfute le propos avec des exemples précis","points":8}],"dureeMin":12,"corrige":"1. **Berlin 1936** : les Jeux sont une **vitrine offerte au régime nazi**, qui s'en sert pour sa propagande. **Mexico 1968** : le **podium devient une tribune politique** ; des athlètes l'utilisent pour protester devant le monde entier. **1980 et 1984** : les **boycotts croisés** montrent que la **guerre froide** entre jusque dans le stade : chaque bloc refuse de participer aux Jeux organisés chez l'autre.\n2. Un **idéal de paix par le sport**, avec des valeurs d'excellence, d'amitié et de respect.\n3. Paragraphe attendu : le propos est démenti par l'histoire. Les Jeux affichent des valeurs de paix, mais ils sont, **depuis toujours**, une **scène politique** : un régime peut s'en servir comme vitrine (Berlin 1936), des athlètes comme tribune (Mexico 1968), des États comme arme diplomatique (les boycotts de 1980 et 1984). Regarder le sport comme un **fait social**, c'est refuser de croire qu'il est neutre : c'est une institution, une économie et un discours."}$exo$::jsonb),
  ('b2faf294-26a4-5a6a-a81c-5f5c1c7979a6'::uuid, 3, 'redaction', $exo${"titre":"L'égalité au bout de la piste ?","consigne":"Analyse les documents, puis rédige une réponse organisée (introduction, deux parties, conclusion courte) qui mobilise le cours.","enonce":"**Document 1.** Aux Jeux de **Paris 2024**, pour la première fois, le nombre de places attribuées aux athlètes femmes et hommes est **égal**.\n\n**Document 2 : extrait d'un article.**\n\n> Dans les fédérations sportives françaises, les présidences restent très majoritairement masculines. Les compétitions féminines occupent une petite part du temps d'antenne consacré au sport, et les écarts de salaires entre sportives et sportifs professionnels demeurent considérables.\n\n**Document 3 : un rappel.** Les femmes étaient exclues des premiers Jeux modernes.\n\n**Sujet.** « Depuis Paris 2024, l'égalité entre femmes et hommes est atteinte dans le sport. » Discute cette affirmation.\n\n1. Montre, à l'aide des documents 1 et 3, les progrès accomplis.\n2. Montre, à l'aide du document 2 et du cours, ce qui reste inégal.\n3. Rédige ta réponse organisée au sujet.","bareme":[{"critere":"Progrès décrits : de l'exclusion à la parité des athlètes en 2024","points":5},{"critere":"Inégalités persistantes : médiatisation, salaires, responsabilités","points":6},{"critere":"Distinction égalité des places / égalité des moyens","points":4},{"critere":"Réponse organisée : introduction, deux parties, conclusion","points":5}],"dureeMin":20,"corrige":"1. Les femmes, **exclues des premiers Jeux modernes**, ont conquis les épreuves **une à une**, jusqu'à la **parité des athlètes à Paris en 2024** : autant de places pour les femmes que pour les hommes.\n2. L'égalité des **places** n'est pas celle des **moyens** : la **médiatisation** des compétitions féminines reste faible, les **salaires** sont très inégaux, et l'**accès aux responsabilités** reste fermé — on compte encore très peu de femmes à la tête des fédérations.\n3. Réponse attendue (plan) :\n- **Introduction** : l'affirmation s'appuie sur la parité des athlètes à Paris 2024 ; il faut se demander si l'égalité des places suffit à faire l'égalité.\n- **Partie 1 : un progrès réel.** De l'exclusion des premiers Jeux à la parité de 2024, les femmes ont conquis les épreuves une à une ; c'est une égalité d'accès à la compétition.\n- **Partie 2 : une égalité encore incomplète.** Médiatisation, salaires, responsabilités : l'égalité des places n'est pas celle des moyens ; les instances qui décident restent dominées par les hommes.\n- **Conclusion** : l'affirmation est donc excessive ; Paris 2024 marque une étape, pas l'aboutissement. Le sport, fait social, reflète les inégalités de la société."}$exo$::jsonb),
  ('e505ae5b-c90a-53a9-91b9-e31835363b55'::uuid, 1, 'application', $exo${"titre":"Ce que toutes les cellules ont en commun","consigne":"Réponds à chaque question par une ou deux phrases complètes, en utilisant le vocabulaire du cours.","enonce":"**Questions de cours.**\n\n1. Cite les **trois éléments** que possède toute cellule, et donne le rôle de chacun.\n2. Qu'est-ce qui distingue une cellule **eucaryote** d'une cellule **procaryote** ? Donne un exemple de cellule procaryote.\n3. Quel instrument faut-il utiliser pour observer des **mitochondries** ? Justifie.\n4. Range dans l'ordre, du plus simple au plus complexe : organe, appareil, tissu. Définis le **tissu**.","bareme":[{"critere":"Membrane plasmique, cytoplasme et ADN cités avec leur rôle","points":7},{"critere":"Eucaryote : ADN dans un noyau ; procaryote sans noyau, exemple de la bactérie","points":5},{"critere":"Microscope électronique justifié par la petite taille des organites","points":3},{"critere":"Ordre tissu, organe, appareil et définition correcte du tissu","points":5}],"dureeMin":7,"corrige":"1. Toute cellule possède :\n- une **membrane plasmique**, qui délimite un milieu intérieur ;\n- un **cytoplasme**, qui contient les molécules et les organites ;\n- de l'**ADN**, qui porte l'information génétique.\n\n2. Chez une cellule **eucaryote**, l'ADN est enfermé dans un **noyau**. Une cellule **procaryote** n'a **pas de noyau** : son ADN est libre dans le cytoplasme. Exemple : une **bactérie**.\n\n3. Il faut le **microscope électronique** : les organites comme les mitochondries sont trop petits pour le microscope optique, qui ne montre que les cellules et leur noyau (jusqu'au micromètre).\n\n4. Ordre : **tissu → organe → appareil**. Un tissu est un ensemble de **cellules spécialisées de même type** (un organe regroupe plusieurs tissus, un appareil plusieurs organes)."}$exo$::jsonb),
  ('e505ae5b-c90a-53a9-91b9-e31835363b55'::uuid, 2, 'application', $exo${"titre":"Le carnet d'observation de Maëlle","consigne":"Exploite le document, puis réponds en justifiant avec tes connaissances.","enonce":"**Situation.** En TP, Maëlle a noté ce qu'elle a observé ou lu sur quatre cellules.\n\n| Cellule | Taille | Ce qu'on remarque |\n| A | 2 µm | Pas de noyau, une paroi, ADN libre |\n| B | environ 7 µm | Pas de noyau, disque rempli d'hémoglobine |\n| C | 50 µm de corps, prolongements de plusieurs cm | Un noyau, de très longs prolongements |\n| D | 100 µm de long | Un noyau, riche en protéines contractiles |\n\n1. La cellule A et la cellule B n'ont pas de noyau. Explique pourquoi pourtant une seule des deux est procaryote. Identifie chacune.\n2. Identifie les cellules C et D et, pour chacune, relie sa forme à sa fonction.\n3. Les cellules B, C et D proviennent d'un même organisme. Ont-elles le même génome ? Justifie.","bareme":[{"critere":"A = bactérie procaryote ; B = globule rouge, cellule eucaryote qui a perdu son noyau","points":6},{"critere":"C = neurone (prolongements, transmettre un message) ; D = fibre musculaire (se contracter)","points":7},{"critere":"Même génome car issues de la cellule-œuf, différences dues à l'expression d'une partie des gènes","points":7}],"dureeMin":10,"corrige":"1. **A** est une **bactérie** : petite taille (quelques micromètres), ADN libre, jamais de noyau → **procaryote**. **B** est un **globule rouge** humain : c'est une cellule d'un organisme **eucaryote** (l'être humain) qui a **perdu** son noyau au cours de sa spécialisation, pour laisser toute la place à l'**hémoglobine** qui transporte le dioxygène. L'absence de noyau n'y est pas une caractéristique de départ mais le résultat de la différenciation.\n\n2. **C** est un **neurone** : ses longs prolongements lui permettent de **transmettre un message** sur de longues distances. **D** est une **fibre musculaire** : allongée et riche en protéines contractiles, elle peut **se contracter**. Relation attendue : la **structure** de la cellule est adaptée à sa **fonction**.\n\n3. **Oui** : toutes les cellules d'un organisme proviennent de la même **cellule-œuf** par divisions et possèdent **le même génome**. Elles diffèrent parce que chaque type cellulaire n'**exprime qu'une partie** des gènes : c'est la **différenciation cellulaire**."}$exo$::jsonb),
  ('e505ae5b-c90a-53a9-91b9-e31835363b55'::uuid, 3, 'application', $exo${"titre":"Un même génome, des cellules si différentes","consigne":"Rédige des réponses argumentées, en t'appuyant sur le document et sur tes connaissances.","enonce":"**Document.** Chez un mammifère, on analyse l'ADN et les protéines de trois types de cellules.\n\n| | Cellule intestinale | Neurone | Fibre musculaire |\n| Gène de la protéine contractile | présent | présent | présent |\n| Protéine contractile fabriquée | non | non | **oui, en grande quantité** |\n| Gène d'une protéine du message nerveux | présent | présent | présent |\n| Protéine du message nerveux fabriquée | non | **oui** | non |\n| Forme | multiplie les replis | longs prolongements | allongée |\n\n1. Que montre la comparaison des lignes « gène présent » et « protéine fabriquée » ? Nomme le phénomène.\n2. Pour la cellule intestinale, relie sa forme à sa fonction.\n3. Un élève affirme : « Si les cellules sont différentes, c'est qu'elles ont des gènes différents. » Réfute cette affirmation.\n4. Explique en quoi l'organisation en tissus, organes et appareils donne un avantage à un organisme pluricellulaire par rapport à un unicellulaire.","bareme":[{"critere":"Les trois cellules ont les mêmes gènes mais n'en expriment qu'une partie : différenciation cellulaire","points":6},{"critere":"Replis de la cellule intestinale reliés à la fonction d'absorption","points":3},{"critere":"Réfutation : même génome issu de la cellule-œuf, différence d'expression et non de gènes","points":5},{"critere":"Organisation hiérarchisée expliquée et division du travail impossible chez un unicellulaire","points":6}],"dureeMin":16,"corrige":"1. Les trois cellules possèdent **les mêmes gènes** (lignes « présent » identiques), mais chacune ne **fabrique** que certaines protéines : seule la fibre musculaire produit la protéine contractile, seul le neurone la protéine du message nerveux. Chaque type cellulaire n'**exprime qu'une partie** de ses gènes : c'est la **différenciation cellulaire**.\n\n2. La cellule intestinale **multiplie les replis** : sa surface d'échange est très grande, ce qui lui permet d'**absorber** efficacement.\n\n3. L'affirmation est fausse. Toutes les cellules d'un organisme proviennent de la même **cellule-œuf** et possèdent **le même génome** — le document le confirme. Leur différence tient à l'**expression** des gènes : même génome, expressions différentes. Chaque cellule acquiert ainsi une **structure** et une **fonction** spécialisées.\n\n4. Les cellules spécialisées de même type forment un **tissu**, plusieurs tissus un **organe**, plusieurs organes un **appareil**. Chaque niveau assure une fonction précise (contraction, absorption, transmission de messages…) : c'est une **division du travail**. Un unicellulaire doit tout faire avec une seule cellule, il ne peut pas se spécialiser ainsi. Le pluricellulaire gagne en efficacité, chaque cellule faisant très bien une seule chose."}$exo$::jsonb),
  ('23be7726-ee58-5f2e-ada1-7b4533e9a1fc'::uuid, 1, 'application', $exo${"titre":"Autotrophe ou hétérotrophe ?","consigne":"Réponds à chaque question avec le vocabulaire précis du cours.","enonce":"**Questions de cours.**\n\n1. Définis le **métabolisme** d'une cellule.\n2. Recopie et complète : une cellule **autotrophe** produit sa matière à partir de matière …… ; une cellule **hétérotrophe** utilise de la matière …… déjà formée.\n3. Écris l'équation-bilan de la **photosynthèse** et indique dans quel organite elle se déroule.\n4. Quel est le rôle d'une **enzyme** ?","bareme":[{"critere":"Métabolisme défini comme l'ensemble des réactions chimiques de la cellule","points":4},{"critere":"Autotrophe : matière minérale ; hétérotrophe : matière organique","points":5},{"critere":"Équation de la photosynthèse juste et chloroplaste cité","points":7},{"critere":"Enzyme : protéine qui catalyse une réaction de façon spécifique","points":4}],"dureeMin":6,"corrige":"1. Le métabolisme est l'**ensemble des réactions chimiques** qui se déroulent dans une cellule. Il sert à produire de la matière et à fournir de l'énergie.\n\n2. Une cellule autotrophe produit sa matière à partir de matière **minérale** (avec la lumière le plus souvent comme source d'énergie) ; une cellule hétérotrophe utilise de la matière **organique** déjà formée.\n\n3. **6 CO2 + 6 H2O + énergie lumineuse → C6H12O6 + 6 O2**. Elle se déroule dans les **chloroplastes**.\n\n4. Une enzyme est une **protéine** qui **catalyse** (accélère) une réaction chimique ; elle est **spécifique** de son substrat et de sa réaction."}$exo$::jsonb),
  ('23be7726-ee58-5f2e-ada1-7b4533e9a1fc'::uuid, 2, 'application', $exo${"titre":"La levure de Samir","consigne":"Exploite les résultats de l'expérience et justifie chaque réponse.","enonce":"**Expérience.** Samir place des levures dans une solution de glucose, en flacon fermé.\n\n| Période | Dioxygène dans le flacon | Ce qu'on mesure |\n| De 0 à 10 min | présent | le dioxygène diminue, du CO2 est rejeté, pas d'éthanol |\n| De 10 à 30 min | épuisé | du CO2 est rejeté, de l'**éthanol** apparaît |\n\n1. Quel métabolisme la levure réalise-t-elle entre 0 et 10 min ? Où a-t-il lieu dans la cellule, et quels en sont les produits ?\n2. Quel métabolisme prend le relais après 10 min ? Justifie à l'aide du document.\n3. Lequel des deux libère le plus d'énergie ? Explique.\n4. Explique pourquoi on peut dire : « même génome, deux métabolismes ».","bareme":[{"critere":"Respiration cellulaire : mitochondries, consommation de dioxygène, produits CO2 et eau","points":6},{"critere":"Fermentation alcoolique identifiée grâce à l'absence de dioxygène et à l'éthanol","points":5},{"critere":"Respiration plus énergétique car dégradation complète du glucose","points":4},{"critere":"Métabolisme dépendant à la fois du génome et de l'environnement (dioxygène)","points":5}],"dureeMin":10,"corrige":"1. Entre 0 et 10 min, le dioxygène diminue et du CO2 est rejeté sans éthanol : la levure réalise la **respiration cellulaire**. Elle a lieu dans les **mitochondries** et dégrade complètement le glucose en **CO2 et eau**.\n\n2. Après 10 min, le dioxygène est **épuisé** et de l'**éthanol** apparaît avec du CO2 : c'est la **fermentation alcoolique**, qui se déroule dans le cytoplasme, en l'**absence** de dioxygène, avec une dégradation **partielle** du glucose.\n\n3. La **respiration** libère **beaucoup plus d'énergie** : elle dégrade le glucose **complètement**, alors que la fermentation laisse une molécule encore riche en énergie (l'éthanol). La fermentation permet en revanche de survivre **sans dioxygène**.\n\n4. La levure a un seul génome, qui porte les gènes des enzymes des deux voies. C'est l'**environnement** (présence ou absence de dioxygène) qui détermine la voie utilisée. Le métabolisme dépend donc du **patrimoine génétique** et de l'**environnement**."}$exo$::jsonb),
  ('23be7726-ee58-5f2e-ada1-7b4533e9a1fc'::uuid, 3, 'application', $exo${"titre":"La feuille, le jour et la nuit","consigne":"Analyse les documents, puis rédige des réponses argumentées.","enonce":"**Document 1.** On mesure les échanges gazeux d'une feuille de pélargonium.\n\n| Condition | Dioxygène | CO2 |\n| Lumière forte | **rejeté** | **absorbé** |\n| Obscurité | **absorbé** | **rejeté** |\n\n**Document 2.** Une souche de bactérie A possède le gène d'une enzyme qui dégrade le lactose ; une souche B ne le possède pas. Sur un milieu où le seul sucre est le lactose, A se multiplie, B non.\n\n1. Interprète les échanges de la feuille à la lumière. Nomme le métabolisme dominant et écris son équation-bilan.\n2. Interprète les échanges à l'obscurité. Quel métabolisme révèle-t-il, et dans quels organites se déroule-t-il ?\n3. Un camarade dit : « la nuit, la plante se met à respirer ». Corrige cette idée.\n4. Explique le résultat du document 2 à l'aide de la notion d'enzyme.\n5. Conclus : quels deux facteurs déterminent le métabolisme d'une cellule ?","bareme":[{"critere":"Lumière : photosynthèse dominante, équation-bilan juste, chloroplastes","points":5},{"critere":"Obscurité : respiration cellulaire dans les mitochondries","points":4},{"critere":"La respiration a lieu en permanence, masquée le jour par la photosynthèse","points":4},{"critere":"Document 2 : sans le gène, pas d'enzyme, donc pas de dégradation du lactose","points":4},{"critere":"Conclusion : patrimoine génétique et environnement","points":3}],"dureeMin":18,"corrige":"1. À la lumière, la feuille **absorbe du CO2** et **rejette du dioxygène** : la **photosynthèse** domine. Dans les **chloroplastes** : **6 CO2 + 6 H2O + énergie lumineuse → C6H12O6 + 6 O2**. La plante est **autotrophe** : elle fabrique sa matière organique à partir de matière minérale.\n\n2. À l'obscurité, la photosynthèse s'arrête : la feuille **absorbe du dioxygène** et **rejette du CO2**. C'est la **respiration cellulaire**, qui se déroule dans les **mitochondries** et dégrade complètement le glucose en CO2 et eau en libérant beaucoup d'énergie.\n\n3. La plante respire **en permanence**, jour et nuit : ses cellules ont toujours besoin d'énergie. Le jour, la photosynthèse, plus intense, **masque** la respiration dans les mesures globales (elle rejette plus de dioxygène que la respiration n'en consomme). La nuit, seule la respiration reste visible.\n\n4. Chaque réaction est catalysée par une **enzyme** spécifique, codée par un **gène**. La souche A possède le gène, donc l'enzyme, et peut dégrader le lactose pour en tirer matière et énergie. La souche B n'a pas le gène, donc pas l'enzyme : elle ne peut pas réaliser la réaction et ne se multiplie pas.\n\n5. Le métabolisme dépend du **patrimoine génétique** (les gènes des enzymes dont la cellule dispose, doc. 2) et de l'**environnement** (lumière, dioxygène, nutriments disponibles, doc. 1)."}$exo$::jsonb),
  ('65e32f40-3559-54dd-a51d-49bf82c1c949'::uuid, 1, 'application', $exo${"titre":"Les trois échelles de la biodiversité","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Cite les **trois échelles** auxquelles on mesure la biodiversité, et dis ce que chacune compte.\n2. Un écosystème est formé de deux composantes. Nomme-les et définis-les.\n3. Définis la **compétition** et le **parasitisme**.\n4. Combien de crises biologiques majeures l'histoire de la Terre compte-t-elle ? Date la plus connue.","bareme":[{"critere":"Écosystèmes, espèces et diversité génétique cités et expliqués","points":6},{"critere":"Biotope (milieu physico-chimique) et biocénose (êtres vivants et relations) définis","points":6},{"critere":"Compétition et parasitisme correctement définis","points":4},{"critere":"Cinq crises, Crétacé-Paléogène il y a 66 millions d'années","points":4}],"dureeMin":6,"corrige":"1. - Les **écosystèmes** : la diversité des milieux ;\n- les **espèces** : le nombre et la variété des espèces ;\n- les **gènes** : la diversité **génétique** au sein de chaque espèce.\n\n2. Le **biotope** est le milieu physique et chimique (température, lumière, eau, sol). La **biocénose** est l'ensemble des êtres vivants et de leurs relations.\n\n3. **Compétition** : des êtres vivants utilisent une même ressource limitée. **Parasitisme** : l'un gagne, l'autre perd (le parasite vit aux dépens de son hôte).\n\n4. **Cinq** crises biologiques majeures. La plus connue est celle de la limite **Crétacé-Paléogène**, il y a **66 millions d'années**."}$exo$::jsonb),
  ('65e32f40-3559-54dd-a51d-49bf82c1c949'::uuid, 2, 'application', $exo${"titre":"La mare du collège de Nathan","consigne":"Exploite le document, puis réponds en justifiant.","enonce":"**Document.** Nathan a relevé ce qui vit dans la mare de son lycée.\n\n> Des algues vertes et des nénuphars poussent à la lumière. Des larves de moustique broutent les algues ; les tritons mangent les larves. Deux espèces de libellules pondent sur les mêmes tiges, peu nombreuses. Des sangsues se fixent sur les tritons et se nourrissent de leur sang. Au fond, des bactéries et des champignons décomposent les feuilles mortes. L'eau est à 14 °C et le fond est vaseux.\n\n1. Donne deux éléments du **biotope** et deux éléments de la **biocénose** de cette mare.\n2. Nomme la relation entre : a) les tritons et les larves ; b) les deux libellules ; c) les sangsues et les tritons.\n3. Par où l'**énergie** entre-t-elle dans cet écosystème ? Que devient-elle ?\n4. Quel est le rôle des bactéries et des champignons du fond dans le cycle de la **matière** ?","bareme":[{"critere":"Deux éléments du biotope et deux de la biocénose correctement classés","points":4},{"critere":"Prédation, compétition et parasitisme identifiés","points":6},{"critere":"Énergie entrant par la photosynthèse des algues et nénuphars, puis dissipée","points":5},{"critere":"Décomposeurs : ils referment le cycle de la matière","points":5}],"dureeMin":10,"corrige":"1. **Biotope** : l'eau à 14 °C, la lumière, le fond vaseux. **Biocénose** : algues, nénuphars, larves de moustique, tritons, libellules, sangsues, bactéries, champignons (et leurs relations).\n\n2. a) Tritons et larves : **prédation** (l'un mange l'autre). b) Les deux libellules : **compétition** pour une ressource limitée (les tiges pour pondre). c) Sangsues et tritons : **parasitisme** (la sangsue gagne, le triton perd).\n\n3. L'énergie entre par la **photosynthèse** des **producteurs primaires** (algues, nénuphars), qui utilisent l'énergie lumineuse. Elle passe ensuite aux consommateurs (larves, puis tritons) et se **dissipe** à chaque étape : elle ne revient pas.\n\n4. Les bactéries et champignons sont des **décomposeurs** : ils dégradent la matière morte et la rendent au milieu sous forme minérale. La matière **cycle** (carbone, azote) : ce sont eux qui **referment** le cycle, et les producteurs peuvent réutiliser ces éléments."}$exo$::jsonb),
  ('65e32f40-3559-54dd-a51d-49bf82c1c949'::uuid, 3, 'application', $exo${"titre":"Une biodiversité en réseau, et provisoire","consigne":"Rédige un texte organisé qui répond aux questions en t'appuyant sur les documents et sur tes connaissances.","enonce":"**Document 1.** Dans une forêt, un champignon du sol vit fixé aux racines des chênes : il leur fournit de l'eau et des sels minéraux, les chênes lui fournissent des sucres. Des geais enterrent des glands pour l'hiver et en oublient une partie, qui germent.\n\n**Document 2.** On a décrit environ 2 millions d'espèces. Les estimations du nombre total vont de quelques millions à plusieurs dizaines de millions.\n\n**Document 3.** Après la crise Crétacé-Paléogène, les groupes survivants, dont les mammifères, se sont diversifiés.\n\n1. Nomme la relation entre le champignon et le chêne, et celle entre le geai et le chêne. Justifie.\n2. Explique ce qui se passerait si le champignon disparaissait de cette forêt. Quelle idée générale sur l'écosystème cet exemple illustre-t-il ?\n3. Que montre le document 2 sur notre connaissance de la biodiversité ?\n4. À l'aide du document 3, explique pourquoi la biodiversité actuelle est « un état, pas un aboutissement ».","bareme":[{"critere":"Coopération entre champignon et chêne, et entre geai et chêne, justifiée par le bénéfice mutuel","points":5},{"critere":"Conséquences en chaîne de la disparition et idée de réseau de relations","points":6},{"critere":"L'essentiel de la biodiversité reste inconnu","points":3},{"critere":"Crises suivies de diversification : la biodiversité actuelle est une étape","points":6}],"dureeMin":18,"corrige":"1. Champignon et chêne : **coopération** — les deux y gagnent (eau et sels minéraux pour le chêne, sucres pour le champignon). Geai et chêne : aussi une **coopération** — le geai trouve de la nourriture, le chêne est dispersé grâce aux glands oubliés qui germent.\n\n2. Sans le champignon, les chênes absorberaient moins d'eau et de sels minéraux : ils pousseraient moins bien, produiraient moins de glands ; les geais, et les autres êtres vivants qui dépendent des chênes, seraient touchés à leur tour. Idée générale : un écosystème n'est **pas une collection d'espèces**, c'est un **réseau de relations**. Retirer une espèce modifie **tout le réseau**.\n\n3. Seules **2 millions** d'espèces sont décrites, alors que le total est estimé entre quelques millions et plusieurs dizaines de millions : **l'essentiel de la biodiversité reste inconnu**.\n\n4. L'histoire de la vie compte **cinq crises biologiques** majeures ; la plus connue, il y a **66 millions d'années**. Chaque crise a été suivie d'une **diversification** des groupes survivants, comme les mammifères. La biodiversité change donc sans cesse : celle d'aujourd'hui n'est qu'une **étape** d'une histoire qui continue, pas un résultat final."}$exo$::jsonb),
  ('dad45caf-2528-584b-903e-92596414b62f'::uuid, 1, 'application', $exo${"titre":"Gènes, allèles et mutations","consigne":"Réponds à chaque question en une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Définis un **gène** et un **allèle**. Combien d'allèles de chaque gène possède un individu diploïde ? Pourquoi ?\n2. Quelle est la **seule** source de nouveaux allèles ?\n3. Donne un exemple de mutation **spontanée** et un exemple d'agent **mutagène**.\n4. Une mutation est-elle toujours défavorable ? Explique.","bareme":[{"critere":"Gène et allèle définis, deux allèles portés par les deux chromosomes de la paire","points":7},{"critere":"La mutation, seule source de nouveaux allèles","points":3},{"critere":"Erreur de réplication et un agent mutagène (UV, rayons X, substance chimique)","points":5},{"critere":"Mutations le plus souvent sans effet, parfois défavorables ou avantageuses selon l'environnement","points":5}],"dureeMin":6,"corrige":"1. Un **gène** est une séquence d'ADN portant l'information d'un caractère. Un **allèle** est une **version** particulière de ce gène. Un individu diploïde possède **deux allèles** de chaque gène, un sur chaque **chromosome de la paire**.\n\n2. La **mutation** : elle seule **crée** de nouveaux allèles (le brassage et la fécondation recombinent ceux qui existent).\n\n3. Mutation spontanée : une **erreur de réplication** de l'ADN. Agent mutagène : les **rayons UV**, les **rayons X** ou certaines **substances chimiques**.\n\n4. Non. La **plupart** des mutations sont **sans effet** ; certaines sont **défavorables** ; quelques-unes sont **avantageuses**, mais seulement **dans un environnement donné**."}$exo$::jsonb),
  ('dad45caf-2528-584b-903e-92596414b62f'::uuid, 2, 'application', $exo${"titre":"Combien de gamètes différents ?","consigne":"Fais les calculs en montrant ta démarche, puis rédige tes explications.","enonce":"**Situation.** Chez l'humain, les cellules ont **23 paires** de chromosomes. Lors de la formation des gamètes, un seul chromosome de chaque paire passe dans le gamète, au hasard et indépendamment des autres paires.\n\n1. Nomme ce brassage. Combien de gamètes différents un individu peut-il produire avec **2** paires de chromosomes ? avec **3** paires ? Donne la règle générale.\n2. Calcule le nombre de combinaisons chez l'humain et arrondis en millions.\n3. Ce nombre est en réalité encore **sous-estimé**. Explique pourquoi en nommant l'autre brassage.\n4. Quelle troisième source de diversité intervient ensuite au moment de la **fécondation** ?","bareme":[{"critere":"Brassage interchromosomique nommé, 4 et 8 gamètes, règle 2 puissance n","points":6},{"critere":"2 puissance 23 = 8 388 608, soit plus de 8 millions","points":5},{"critere":"Brassage intrachromosomique (crossing-over) expliqué comme source supplémentaire","points":5},{"critere":"Fécondation : réunion au hasard de deux gamètes","points":4}],"dureeMin":10,"corrige":"1. C'est le **brassage interchromosomique** : la répartition indépendante des chromosomes de chaque paire. Avec 2 paires : 2 × 2 = **4** gamètes différents ; avec 3 paires : 2 × 2 × 2 = **8**. Règle : avec n paires, **2 puissance n** combinaisons.\n\n2. 2 puissance 23 = **8 388 608**, soit **plus de 8 millions** de gamètes différents.\n\n3. Ce calcul ignore le **brassage intrachromosomique** : lors du **crossing-over**, les chromosomes homologues **échangent des segments**, ce qui crée de nouvelles combinaisons d'allèles sur un même chromosome. Le nombre réel de gamètes possibles est donc bien plus grand.\n\n4. La **fécondation** réunit **au hasard** un gamète du père et un gamète de la mère : chaque cellule-œuf est une combinaison nouvelle, et aucun individu n'est identique à un autre (sauf les vrais jumeaux)."}$exo$::jsonb),
  ('dad45caf-2528-584b-903e-92596414b62f'::uuid, 3, 'application', $exo${"titre":"Le troupeau très sélectionné de Lucie","consigne":"Rédige des réponses argumentées en mobilisant tout le chapitre.","enonce":"**Situation.** Lucie visite deux élevages de vaches.\n\n> **Élevage A** : toutes les vaches descendent de quelques taureaux choisis pour leur production de lait. Elles se ressemblent beaucoup, et les analyses montrent peu d'allèles différents pour la plupart des gènes.\n>\n> **Élevage B** : des vaches de plusieurs races rustiques, issues de nombreux reproducteurs, avec beaucoup d'allèles différents.\n\nUne nouvelle maladie apparaît. Un allèle rare d'un gène de défense permet d'y résister.\n\n1. Rappelle les trois sources de la diversité génétique au sein d'une espèce et le rôle de chacune.\n2. Lequel des deux élevages a le plus de chances de compter des vaches résistantes ? Justifie avec une notion de probabilité.\n3. Pourquoi une espèce réduite à quelques individus est-elle, comme l'élevage A, fragile ?\n4. L'allèle de résistance est-il « bon » en lui-même ? Nuance ta réponse.","bareme":[{"critere":"Mutation (crée), brassage de la méiose (recombine), fécondation (réunit au hasard)","points":6},{"critere":"Élevage B : plus d'allèles, donc plus forte probabilité qu'un individu porte l'allèle avantageux","points":5},{"critere":"Faible diversité génétique d'une petite population et fragilité expliquées","points":5},{"critere":"Avantage d'un allèle relatif à un environnement donné","points":4}],"dureeMin":16,"corrige":"1. - La **mutation** **crée** de nouveaux allèles (spontanée ou provoquée par un agent mutagène) ;\n- le **brassage** de la méiose (inter- et intrachromosomique) **recombine** les allèles existants ;\n- la **fécondation** **réunit au hasard** deux gamètes.\n\n2. L'**élevage B** : génétiquement **divers**, il possède beaucoup d'allèles différents. La **probabilité** qu'au moins certains individus portent l'allèle rare de résistance y est **plus grande**. Ces vaches survivront et le troupeau pourra se maintenir. Dans l'élevage A, issu de quelques taureaux, l'allèle a de fortes chances d'être absent : tout le troupeau risque d'être touché.\n\n3. Une espèce réduite à quelques individus ne porte que les allèles de ces quelques individus : sa **diversité génétique est faible**. Face à un changement (maladie, climat), il est peu probable qu'un individu porte un allèle avantageux : la population est **fragile**, comme un cheptel très sélectionné.\n\n4. Non : un allèle n'est avantageux que **dans un environnement donné**. Sans la maladie, l'allèle de résistance n'apporte peut-être rien. C'est pourquoi conserver une grande diversité d'allèles, même inutiles aujourd'hui, protège l'avenir d'une population."}$exo$::jsonb),
  ('bd0ae00f-ffa7-5a7f-a1d3-d81fc95bb480'::uuid, 1, 'application', $exo${"titre":"Dérive, sélection, spéciation","consigne":"Réponds à chaque question en une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Définis la **dérive génétique**. Dans quelle population son effet est-il le plus marqué ?\n2. Définis la **sélection naturelle**. Est-elle aléatoire ?\n3. La sélection naturelle crée-t-elle de nouveaux allèles ? Explique.\n4. Donne la définition courante de l'**espèce** et une de ses limites.","bareme":[{"critere":"Dérive : variation aléatoire des fréquences alléliques, marquée dans une petite population","points":5},{"critere":"Sélection naturelle : non aléatoire, avantage de survie ou de reproduction","points":5},{"critere":"La sélection trie les allèles créés par la mutation","points":4},{"critere":"Individus interféconds à descendance fertile et une limite (fossiles, asexués, hybrides fertiles)","points":6}],"dureeMin":6,"corrige":"1. La dérive génétique est une modification **aléatoire** de la fréquence des allèles d'une génération à l'autre. Son effet est le plus marqué dans une population **petite** : un allèle peut y disparaître ou devenir majoritaire par pur hasard.\n\n2. La sélection naturelle : les individus porteurs d'allèles qui confèrent un **avantage** (mieux survivre, mieux se reproduire) laissent en moyenne plus de descendants, et la fréquence de ces allèles augmente. Elle est **non aléatoire**.\n\n3. **Non** : la sélection ne crée pas les allèles, elle **trie** ceux que la **mutation** a produits.\n\n4. Une espèce est un ensemble d'individus **interféconds** dont la **descendance est fertile**. Limites : elle ne s'applique pas aux espèces **fossiles**, ni à la reproduction **asexuée**, et bute sur les **hybrides fertiles**."}$exo$::jsonb),
  ('bd0ae00f-ffa7-5a7f-a1d3-d81fc95bb480'::uuid, 2, 'application', $exo${"titre":"La phalène des villes anglaises","consigne":"Exploite le document et justifie chaque réponse.","enonce":"**Document.** La phalène du bouleau est un papillon qui se pose le jour sur les troncs. Elle existe sous une forme **claire** et une forme **sombre**, déterminées par des allèles d'un gène. Les oiseaux la chassent à vue. Valeurs simplifiées pour une région industrielle anglaise :\n\n| Époque | Troncs | Part de formes sombres |\n| Avant l'industrialisation | clairs, couverts de lichens | moins de 5 % |\n| Pendant, avec la suie | noircis | plus de 90 % |\n| Après la dépollution | à nouveau clairs | moins de 20 % |\n\n1. Décris l'évolution de la part de formes sombres.\n2. Explique cette évolution par la **sélection naturelle**, en précisant qui « trie » et selon quel avantage.\n3. La suie a-t-elle provoqué l'apparition de l'allèle sombre ? Justifie.\n4. Pourquoi ce changement n'est-il pas dû à la dérive génétique ?","bareme":[{"critere":"Description chiffrée : forte hausse des formes sombres puis baisse après dépollution","points":4},{"critere":"Sélection naturelle par la prédation des oiseaux, avantage du camouflage selon la couleur des troncs","points":7},{"critere":"L'allèle sombre existait déjà, produit par mutation ; la suie ne fait que le favoriser","points":5},{"critere":"Changement orienté et réversible selon l'environnement, donc non aléatoire","points":4}],"dureeMin":11,"corrige":"1. Avant l'industrialisation, les formes sombres sont rares (moins de 5 %). Pendant la pollution, elles deviennent très **majoritaires** (plus de 90 %). Après la dépollution, elles **reculent** (moins de 20 %) : la forme claire revient.\n\n2. Ce sont les **oiseaux prédateurs** qui trient. Sur des troncs noircis, les phalènes sombres sont **moins visibles** : elles survivent mieux et laissent plus de descendants, la fréquence de l'allèle sombre augmente. Sur des troncs clairs, c'est la forme claire qui est avantagée. C'est la **sélection naturelle** : l'avantage dépend de l'**environnement**.\n\n3. **Non**. L'allèle sombre existait déjà avant (moins de 5 %) : il est issu d'une **mutation**. La sélection ne crée pas les allèles, elle **trie** ceux qui existent. La suie a seulement changé l'environnement, donc l'allèle avantagé.\n\n4. La dérive est **aléatoire** et marquée surtout dans les petites populations. Ici, le changement est **orienté**, se produit dans de grandes populations et **s'inverse** quand l'environnement redevient clair : il suit l'avantage de camouflage, ce qui signe une sélection, non un hasard."}$exo$::jsonb),
  ('bd0ae00f-ffa7-5a7f-a1d3-d81fc95bb480'::uuid, 3, 'application', $exo${"titre":"Les escargots de part et d'autre du fleuve","consigne":"Rédige des réponses argumentées qui mobilisent les mécanismes de l'évolution.","enonce":"**Situation.** Une population d'escargots vit dans une plaine. Un fleuve change de lit et la coupe en deux.\n\n> - Côté nord : une grande population de plusieurs milliers d'escargots, dans une forêt humide et sombre où les grives chassent à vue ; les coquilles foncées y deviennent de plus en plus fréquentes.\n> - Côté sud : seulement une vingtaine d'escargots isolés sur une petite île de graviers ; en quelques générations, un allèle de coquille rayée y disparaît complètement, sans lien apparent avec le milieu.\n>\n> Des milliers d'années plus tard, on remet en contact des escargots des deux côtés : ils s'accouplent rarement, et leurs descendants sont stériles.\n\n1. Quel mécanisme explique l'évolution côté nord ? côté sud ? Justifie chacun.\n2. Pourquoi l'allèle rayé a-t-il pu disparaître côté sud et pas côté nord ?\n3. Les deux populations forment-elles encore une même espèce ? Justifie avec la définition et nomme le processus.\n4. Retrace les étapes qui ont conduit à ce résultat.\n5. Un paléontologue trouve une coquille fossile semblable : peut-il appliquer la même définition ? Explique.","bareme":[{"critere":"Nord : sélection naturelle (prédation, avantage du camouflage) ; sud : dérive génétique","points":5},{"critere":"Effet de la taille de la population sur la dérive expliqué","points":4},{"critere":"Descendance stérile : deux espèces, spéciation","points":4},{"critere":"Étapes : isolement géographique, accumulation de différences génétiques, spéciation","points":4},{"critere":"Définition inapplicable aux fossiles, notion utile mais floue","points":3}],"dureeMin":18,"corrige":"1. **Côté nord** : la **sélection naturelle**. Dans une forêt sombre, les coquilles foncées sont moins visibles des grives : ces escargots survivent mieux et laissent plus de descendants, la fréquence de l'allèle foncé augmente. C'est **non aléatoire**, lié à un avantage. **Côté sud** : la **dérive génétique**. L'allèle rayé disparaît « sans lien avec le milieu », par **hasard**, d'une génération à l'autre.\n\n2. La dérive est d'autant plus forte que la population est **petite**. Avec une vingtaine d'individus, il suffit que quelques porteurs meurent ou se reproduisent moins par hasard pour que l'allèle disparaisse. Dans une grande population (plusieurs milliers), les écarts dus au hasard **s'annulent**.\n\n3. **Non** : ils s'accouplent rarement et leurs descendants sont **stériles**. Ils ne sont plus interféconds avec une descendance fertile : ce sont **deux espèces**. Le processus est la **spéciation**.\n\n4. - **Isolement** : le fleuve forme une barrière géographique, plus aucun échange ;\n- **accumulation** de différences génétiques de chaque côté, par sélection (nord) et dérive (sud), en plus des mutations propres à chaque population ;\n- **spéciation** : les deux populations ne peuvent plus donner une descendance fertile.\n\n5. **Non** : on ne peut pas tester l'interfécondité d'un **fossile**. La définition courante est **utile mais floue** : elle ne s'applique ni aux fossiles, ni à la reproduction asexuée, et bute sur les hybrides fertiles. Le paléontologue doit s'appuyer sur d'autres critères, comme la ressemblance des formes."}$exo$::jsonb),
  ('9ddff01e-0bf5-5699-860f-af373ea71c31'::uuid, 1, 'application', $exo${"titre":"Les causes de la sixième crise","consigne":"Réponds à chaque question en une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Cite **trois** causes naturelles des crises biologiques passées.\n2. Qu'appelle-t-on une **radiation évolutive** ?\n3. Comment le rythme actuel d'extinction se situe-t-il par rapport au rythme moyen des archives fossiles ? Quelle est la particularité de cette crise ?\n4. Cite les **cinq** causes actuelles de l'érosion de la biodiversité et précise laquelle est la première.","bareme":[{"critere":"Trois causes naturelles (volcanisme, astéroïde, climat, atmosphère)","points":4},{"critere":"Radiation évolutive : diversification des survivants dans les niches libérées","points":4},{"critere":"Rythme 10 à 100 fois supérieur, première crise d'origine humaine","points":5},{"critere":"Cinq causes citées, destruction et fragmentation des habitats en premier","points":7}],"dureeMin":7,"corrige":"1. Trois parmi : un **volcanisme massif**, une **chute d'astéroïde**, des **variations climatiques** de grande ampleur, une **modification de l'atmosphère**.\n\n2. Après une crise, les **groupes survivants se diversifient** rapidement et occupent les niches écologiques libérées : c'est une radiation évolutive.\n\n3. Le rythme actuel est **10 à 100 fois supérieur** au rythme moyen des archives fossiles. On parle de **sixième crise biologique**, la première **d'origine humaine**.\n\n4. - La **destruction et la fragmentation des habitats** (**première** cause) ;\n- la **surexploitation** (pêche, chasse, prélèvements) ;\n- les **pollutions** ;\n- les **espèces exotiques envahissantes** ;\n- le **changement climatique**."}$exo$::jsonb),
  ('9ddff01e-0bf5-5699-860f-af373ea71c31'::uuid, 2, 'application', $exo${"titre":"La grenouille du marais de Kenza","consigne":"Exploite le document, puis réponds en justifiant.","enonce":"**Document.** Kenza suit depuis vingt ans une grenouille dans un marais de sa région.\n\n> Le marais a perdu la moitié de sa surface, drainée pour des cultures, et une route à quatre voies le coupe en deux. Les étés sont plus chauds et certaines mares s'assèchent avant que les têtards soient devenus adultes. Des écrevisses américaines, relâchées il y a quinze ans, dévorent les œufs. Un éclairage nocturne a été installé le long de la route. Le nombre de grenouilles comptées au printemps a été divisé par cinq.\n\n1. Relève dans le document **quatre** causes du déclin et classe-les parmi les cinq causes du cours.\n2. Quelle est la cause principale selon le cours ? Explique comment la route aggrave la situation.\n3. Explique la phrase : « une espèce ne disparaît presque jamais d'une seule cause ».\n4. Propose **deux** actions pour ce marais et dis ce que chacune vise.","bareme":[{"critere":"Quatre causes relevées et bien classées (habitat, climat, espèce envahissante, pollution lumineuse)","points":6},{"critere":"Destruction et fragmentation de l'habitat, rôle de la route expliqué","points":4},{"critere":"Addition de causes qui fait basculer une population","points":4},{"critere":"Deux actions pertinentes (corridor, aire protégée, restauration, lutte contre l'écrevisse)","points":6}],"dureeMin":11,"corrige":"1. - Marais drainé pour des cultures, route qui le coupe : **destruction et fragmentation des habitats** ;\n- étés plus chauds, mares asséchées : **changement climatique** ;\n- écrevisses américaines relâchées : **espèce exotique envahissante** ;\n- éclairage nocturne : **pollution** (lumineuse).\n\n2. La première cause est la **destruction et la fragmentation des habitats**. La route **coupe** le marais : les grenouilles ne peuvent plus circuler d'une partie à l'autre, les populations deviennent plus petites et isolées, et beaucoup meurent en traversant.\n\n3. Chaque cause seule aurait peut-être été supportable. C'est leur **addition** — un habitat réduit, un climat qui change, un prédateur introduit, une pollution — qui fait **basculer** la population. Ici, les effectifs ont été divisés par cinq.\n\n4. Exemples attendus (deux) :\n- un **corridor écologique** (passage sous la route) pour **relier** les deux moitiés du marais ;\n- une **aire protégée** pour **soustraire** le reste du marais au drainage ;\n- la **restauration** de mares pour **réparer** le milieu ;\n- la régulation des écrevisses ; l'extinction de l'éclairage la nuit."}$exo$::jsonb),
  ('9ddff01e-0bf5-5699-860f-af373ea71c31'::uuid, 3, 'application', $exo${"titre":"Une crise comme les autres ?","consigne":"Rédige un paragraphe argumenté, organisé en plusieurs parties, qui répond à la question posée.","enonce":"**Question.** Un article affirme : « La biodiversité a déjà connu cinq crises, et elle s'en est toujours remise. La crise actuelle n'a donc rien d'inquiétant. »\n\n**Document 1.** Rythme actuel d'extinction : 10 à 100 fois supérieur au rythme moyen des archives fossiles.\n\n**Document 2.** Des suivis montrent une chute du nombre d'insectes et d'oiseaux **communs** dans les campagnes européennes, pas seulement des espèces rares.\n\n**Document 3.** Après la crise Crétacé-Paléogène, il y a 66 millions d'années, les groupes survivants se sont diversifiés, sur des millions d'années.\n\nDiscute l'affirmation de l'article en montrant ce que la crise actuelle a **en commun** avec les précédentes et ce qui la **distingue**, puis indique ce que l'on peut faire.","bareme":[{"critere":"Points communs : crises déjà survenues, suivies de radiations évolutives","points":4},{"critere":"Différences : origine humaine, vitesse 10 à 100 fois supérieure, recul de l'abondance générale","points":6},{"critere":"Critique de l'affirmation : la récupération prend des millions d'années","points":4},{"critere":"Au moins trois leviers d'action du cours reliés aux causes","points":6}],"dureeMin":18,"corrige":"**Ce qu'elle a en commun.** La biodiversité a toujours varié : **cinq crises** majeures ont eu des causes naturelles (volcanisme, astéroïde, climat, atmosphère). Chacune a été suivie d'une **radiation évolutive** : les survivants se sont diversifiés (doc. 3). L'article a raison sur ce point.\n\n**Ce qui la distingue.**\n- Son **origine est humaine** : c'est la première crise causée par une espèce (habitats détruits et fragmentés, surexploitation, pollutions, espèces envahissantes, changement climatique).\n- Sa **vitesse** : 10 à 100 fois le rythme moyen des archives fossiles (doc. 1).\n- Ce n'est pas seulement l'espèce rare qui recule mais l'**abondance générale** : insectes et oiseaux communs (doc. 2).\n\n**Critique.** La biodiversité « s'en est remise » à l'échelle de **millions d'années** (doc. 3), et avec d'autres espèces qu'avant. À l'échelle humaine, les espèces perdues ne reviennent pas. L'affirmation confond donc le temps géologique et le nôtre : la crise actuelle est bien inquiétante.\n\n**Agir** (au moins trois, reliés aux causes) : **aires protégées** et réserves ; **corridors écologiques** contre la fragmentation ; **restauration** des milieux ; réglementation des prélèvements (**CITES**) contre la surexploitation ; agriculture moins intensive ; **réduction des émissions** contre le changement climatique. Contrairement aux crises passées, celle-ci a une cause sur laquelle on peut agir."}$exo$::jsonb),
  ('6bb01498-8d14-5728-8e10-38915915f7be'::uuid, 1, 'application', $exo${"titre":"Comment les animaux se parlent","consigne":"Réponds à chaque question en une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Qu'est-ce qu'une **phéromone** ? Donne un exemple de son utilisation.\n2. Donne un avantage de la communication **sonore**, avec un exemple.\n3. Cite les **trois** grandes fonctions des signaux échangés au sein d'une espèce.\n4. Qui a décrit la **sélection sexuelle** ? Quelle en est la définition ?","bareme":[{"critere":"Phéromone définie (molécule émise en très faible quantité) avec un exemple","points":5},{"critere":"Avantage du canal sonore (porte loin, de nuit) et exemple","points":4},{"critere":"Reproduction, compétition et cohésion sociale","points":6},{"critere":"Darwin ; favorise les caractères qui augmentent le succès reproducteur","points":5}],"dureeMin":6,"corrige":"1. Une phéromone est une **molécule** émise en **très faible quantité** par un individu, qui modifie le comportement d'un congénère. Exemples : marquage de territoire, **piste des fourmis**, attraction sexuelle des papillons.\n\n2. Le son **porte loin** et fonctionne **de nuit**. Exemples : le chant des oiseaux, la stridulation des criquets, le coassement des grenouilles.\n\n3. - La **reproduction** (attirer un partenaire) ;\n- la **compétition** (défendre un territoire, dissuader un rival sans combattre) ;\n- la **cohésion sociale** (alerter, indiquer une ressource, coordonner un groupe).\n\n4. **Charles Darwin**. La sélection sexuelle favorise les caractères qui augmentent le **succès reproducteur**, même s'ils diminuent la survie."}$exo$::jsonb),
  ('6bb01498-8d14-5728-8e10-38915915f7be'::uuid, 2, 'application', $exo${"titre":"Le carnet de terrain d'Élio","consigne":"Pour chaque observation, identifie le canal et la fonction du signal, en justifiant.","enonce":"**Document.** Pendant un stage, Élio a noté cinq observations.\n\n> a) Au printemps, un rouge-gorge mâle chante perché en bordure de son territoire ; un autre mâle s'approche, puis repart sans combat.\n> b) Des fourmis suivent en file une trace chimique invisible jusqu'à une miette de pain.\n> c) Un mâle de papillon de nuit vole vers une femelle située à plusieurs centaines de mètres, sans la voir.\n> d) Un chevreuil voit un chien, émet un aboiement sonore et s'enfuit ; les chevreuils voisins s'enfuient aussi.\n> e) Deux chimpanzés passent un long moment à se toiletter mutuellement.\n\n1. Présente dans un tableau, pour chaque observation, le **canal** utilisé et la **fonction** du signal.\n2. Dans l'observation a), pourquoi dit-on que le signal permet de dissuader « sans combattre » ? Quel intérêt pour les deux mâles ?\n3. Pourquoi le canal chimique convient-il particulièrement à l'observation c) ?","bareme":[{"critere":"Les cinq canaux correctement identifiés","points":7},{"critere":"Les cinq fonctions correctement identifiées","points":6},{"critere":"Dissuasion sans combat : éviter les blessures et les dépenses d'énergie","points":4},{"critere":"Phéromones actives à très faible dose et sans voir le partenaire, de nuit","points":3}],"dureeMin":11,"corrige":"1. | Observation | Canal | Fonction |\n| a) chant du rouge-gorge | sonore | **compétition** (défense du territoire) |\n| b) piste des fourmis | chimique (phéromone) | **cohésion sociale** (indiquer une ressource) |\n| c) papillon de nuit | chimique (phéromone) | **reproduction** (attirer un partenaire) |\n| d) aboiement du chevreuil | sonore | **cohésion sociale** (alerter d'un danger) |\n| e) toilettage | tactile | **cohésion sociale** (contacts sociaux) |\n\n2. Le chant signale que le territoire est occupé par un mâle en forme. Le rival évalue le signal et repart : le conflit se règle **sans combat**. Les deux mâles évitent ainsi des **blessures** et des dépenses d'énergie ; le propriétaire garde son territoire, l'intrus garde ses chances ailleurs.\n\n3. La phéromone est émise en **très faible quantité** et agit à grande distance ; elle ne demande pas de voir le partenaire, ce qui convient à un animal **de nuit**, à plusieurs centaines de mètres."}$exo$::jsonb),
  ('6bb01498-8d14-5728-8e10-38915915f7be'::uuid, 3, 'application', $exo${"titre":"Le paradoxe de la veuve à longue queue","consigne":"Analyse le document et rédige des réponses argumentées.","enonce":"**Document.** La veuve à longue queue est un oiseau d'Afrique : le mâle porte en période de reproduction une queue d'environ 50 cm, la femelle une queue courte. Une expérience célèbre a été menée sur des mâles :\n\n| Groupe de mâles | Queue | Nombre moyen de nids dans leur territoire |\n| A | raccourcie à environ 14 cm | environ 0,5 |\n| B | laissée intacte | environ 1,5 |\n| C | allongée à environ 75 cm | environ 2 |\n\nOn sait aussi qu'une longue queue gêne le vol et rend l'oiseau plus visible des prédateurs.\n\n1. Analyse les résultats de l'expérience. Quelle forme de sélection sexuelle révèlent-ils ? Justifie.\n2. Pourquoi une queue si longue est-elle un **paradoxe** pour la sélection naturelle ? Résous ce paradoxe.\n3. Explique pourquoi un ornement coûteux constitue pour la femelle une information **fiable**.\n4. Quel caractère des veuves à longue queue la sélection sexuelle explique-t-elle ? Nomme-le.\n5. Comment appelle-t-on l'autre forme de sélection sexuelle ? Donne un exemple.","bareme":[{"critere":"Plus la queue est longue, plus il y a de nids : choix des femelles, sélection intersexuelle","points":5},{"critere":"Coût pour la survie compensé par le gain en succès reproducteur","points":5},{"critere":"Signal coûteux difficile à truquer, donc fiable","points":4},{"critere":"Dimorphisme sexuel nommé et relié aux données","points":3},{"critere":"Sélection intrasexuelle définie avec un exemple (bois des cerfs, combats)","points":3}],"dureeMin":18,"corrige":"1. Le nombre de nids **augmente avec la longueur de la queue** : environ 0,5 (queue raccourcie), 1,5 (intacte), 2 (allongée). Les femelles nichent plus volontiers chez les mâles à longue queue : elles **choisissent** leur partenaire. C'est la sélection sexuelle **intersexuelle** (choix des femelles). Les mâles C, au caractère artificiellement exagéré, sont même préférés aux mâles naturels.\n\n2. La queue **gêne le vol** et **signale l'oiseau aux prédateurs** : elle diminue la survie, et la **sélection naturelle** devrait l'éliminer. Elle persiste pourtant parce que le **succès reproducteur** qu'elle procure (plus de nids, donc plus de descendants) **compense** la perte de survie. Les allèles de la longue queue se transmettent davantage.\n\n3. Seul un mâle en bon état peut produire et porter un ornement aussi coûteux tout en survivant aux prédateurs. Un mâle faible ne pourrait pas le « faire semblant » : le signal est **difficile à truquer**, donc **fiable** pour la femelle.\n\n4. La différence entre la queue du mâle (50 cm) et celle de la femelle (courte) est un **dimorphisme sexuel** : des différences d'ornements entre mâles et femelles, largement expliquées par la sélection sexuelle.\n\n5. La sélection **intrasexuelle** : des mâles **s'affrontent** pour l'accès aux femelles. Exemple : les **bois des cerfs** et leurs combats. Avec la sélection naturelle et la dérive, la sélection sexuelle participe à l'évolution de la biodiversité."}$exo$::jsonb),
  ('2648aea7-54e3-5ed6-a55c-a2eb9dcc817d'::uuid, 1, 'application', $exo${"titre":"Les étapes de l'érosion","consigne":"Réponds à chaque question en une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Cite dans l'ordre les **trois étapes** de l'érosion et dis ce que fait chacune.\n2. Quelle différence y a-t-il entre altération **physique** et altération **chimique** ?\n3. Explique le mécanisme de la **gélifraction**.\n4. Que devient un **granite** altéré ? Quel minéral subsiste ?","bareme":[{"critere":"Altération, ablation, transport, avec le rôle de chacune","points":6},{"critere":"Physique : fragmente sans changer la composition ; chimique : transforme les minéraux","points":5},{"critere":"Gélifraction : l'eau gèle dans une fissure, augmente de volume et fait éclater la roche","points":4},{"critere":"Arène granitique, feldspath en argile, quartz qui subsiste","points":5}],"dureeMin":6,"corrige":"1. - L'**altération** fragilise la roche **sur place** ;\n- l'**ablation** arrache les débris ;\n- le **transport** les emporte vers un lieu de dépôt.\n\n2. L'altération **physique** fragmente la roche **sans changer sa composition** ; l'altération **chimique** **transforme** les minéraux.\n\n3. L'eau s'infiltre dans une fissure ; en **gelant**, elle **augmente de volume** et écarte la fissure, jusqu'à faire **éclater** la roche.\n\n4. Il devient de l'**arène granitique** : par **hydrolyse**, le feldspath devient de l'**argile**, le mica se dégrade, et le **quartz** subsiste sous forme de grains."}$exo$::jsonb),
  ('2648aea7-54e3-5ed6-a55c-a2eb9dcc817d'::uuid, 2, 'application', $exo${"titre":"Du chaos de granite à la plage","consigne":"Exploite la situation et justifie chaque réponse.","enonce":"**Situation.** En Bretagne, Yanis se promène sur une côte de granite. Il observe :\n\n> - des boules de granite arrondies, entourées d'un sable grossier qui s'effrite sous les doigts ;\n> - dans une rivière voisine, des grains de sable encore anguleux ;\n> - sur la plage, loin en aval, des grains de quartz bien arrondis et tous de la même taille.\n\n1. Comment s'appelle le sable grossier qui entoure les boules ? Explique sa formation : type d'altération, réaction, minéraux transformés et minéral qui subsiste.\n2. Pourquoi retrouve-t-on surtout du **quartz** sur la plage ?\n3. Compare les grains de la rivière et ceux de la plage. Que peut-on en déduire sur leur histoire ?\n4. Quel climat accélère ce type d'altération ?","bareme":[{"critere":"Arène granitique formée par hydrolyse : feldspath en argile, mica dégradé, quartz qui subsiste","points":7},{"critere":"Le quartz résiste à l'altération, il est le dernier survivant du granite","points":4},{"critere":"Transport plus long : grains arrondis et triés par taille","points":5},{"critere":"Climat chaud et humide","points":4}],"dureeMin":10,"corrige":"1. C'est de l'**arène granitique**. Elle se forme par **altération chimique** : l'**hydrolyse** des silicates. Le **feldspath** devient de l'**argile**, le **mica** se dégrade, et le **quartz** subsiste en grains. Le granite perd sa cohésion et s'effrite **sur place**.\n\n2. Le quartz n'est pas transformé par l'hydrolyse : il **résiste**. Une fois l'argile emportée, il reste les grains de quartz : un grain de sable de plage est très souvent un cristal de quartz, **dernier survivant** d'un granite désagrégé.\n\n3. Dans la rivière, près de leur source, les grains sont **anguleux** : ils ont peu voyagé. Sur la plage, loin en aval, ils sont **arrondis** et **triés** par taille : ils ont été transportés **longtemps**. La forme d'un grain **raconte son histoire** : plus le transport est long, plus il est arrondi et trié.\n\n4. Un climat **chaud et humide** accélère l'altération chimique."}$exo$::jsonb),
  ('2648aea7-54e3-5ed6-a55c-a2eb9dcc817d'::uuid, 3, 'application', $exo${"titre":"Deux paysages, deux érosions","consigne":"Compare les deux paysages dans un texte organisé, en mobilisant les facteurs de l'érosion.","enonce":"**Paysage A — un plateau calcaire du Sud-Ouest.** Climat doux et humide. On y trouve des grottes, des gouffres, des surfaces de roche creusées de rigoles et des sources qui jaillissent au pied des falaises. Les pentes sont faibles et couvertes de chênes.\n\n**Paysage B — une haute montagne des Alpes.** L'hiver, les températures passent chaque nuit sous 0 °C et remontent le jour. Les pentes sont fortes et nues ; au pied des parois s'accumulent des éboulis de blocs anguleux. Un torrent emporte les débris.\n\n1. Pour chaque paysage, identifie le type d'altération dominant et explique son mécanisme.\n2. Nomme le type de paysage A et relie ses formes à la réaction chimique.\n3. Montre comment la **pente** et la **végétation** modifient l'intensité de l'érosion dans les deux cas.\n4. Si l'érosion est « inexorable », pourquoi les Alpes ne sont-elles pas encore aplanies ? Conclus.","bareme":[{"critere":"A : altération chimique par dissolution du calcaire ; B : altération physique par gélifraction","points":6},{"critere":"Paysage karstique : grottes, gouffres, lapiaz, résurgences reliés à la dissolution par l'eau chargée de CO2","points":4},{"critere":"Rôle de la pente (évacuation) et de la végétation (retient les sols) comparé","points":5},{"critere":"Course entre surrection et usure","points":5}],"dureeMin":18,"corrige":"1. **Paysage A** : altération **chimique**. Le calcaire est **dissous** par l'eau chargée de **CO2** ; le climat doux et humide favorise l'altération chimique. **Paysage B** : altération **physique** par **gélifraction**. L'eau s'infiltre dans les fissures, gèle chaque nuit, augmente de volume et fait éclater la roche : d'où les blocs **anguleux** des éboulis (la composition de la roche ne change pas).\n\n2. C'est un paysage **karstique**. La dissolution creuse les fissures en **lapiaz** (rigoles), les élargit en **gouffres** et en **grottes** ; l'eau circule en profondeur et ressort en **résurgences** au pied des falaises.\n\n3. **Pente** : en B, les pentes fortes accélèrent l'**évacuation** des débris (gravité, torrent) ; en A, les pentes faibles la ralentissent. **Végétation** : en A, les chênes **freinent** l'érosion en retenant les sols ; en B, les pentes nues n'offrent aucune protection. L'érosion mécanique est donc bien plus rapide en B.\n\n4. Parce que des **forces internes** soulèvent les reliefs (**surrection**). Sans elles, l'érosion aurait depuis longtemps aplani les continents. Conclusion : les paysages résultent d'une **course entre surrection et usure**, et l'intensité de l'usure dépend de la nature de la roche, du climat, de la pente et de la végétation."}$exo$::jsonb),
  ('b2db62a2-d23e-5955-92d9-00786aedab1a'::uuid, 1, 'application', $exo${"titre":"Du sédiment à la roche","consigne":"Réponds à chaque question en une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. À quel moment un sédiment se dépose-t-il ? Qu'est-ce que le **tri granulométrique** ?\n2. Nomme et décris les deux étapes de la **diagenèse**.\n3. Quelle roche obtient-on à partir : a) d'un sable ? b) d'une argile ? c) de débris de coquilles ?\n4. Énonce le **principe de superposition**.","bareme":[{"critere":"Dépôt quand l'agent de transport perd de l'énergie, tri selon la taille des grains","points":5},{"critere":"Compaction et cimentation décrites","points":5},{"critere":"Grès, argilite et calcaire","points":5},{"critere":"Principe de superposition correctement énoncé","points":5}],"dureeMin":6,"corrige":"1. Un sédiment se dépose quand l'**agent de transport perd de l'énergie**. Le **tri granulométrique** est le classement des dépôts selon la **taille des grains** : blocs avec un courant fort, sables avec un courant moyen, argiles en eau calme.\n\n2. - La **compaction** : le poids des dépôts supérieurs chasse l'eau ;\n- la **cimentation** : des minéraux précipitent et collent les grains.\n\n3. a) Le **grès** ; b) l'**argilite** ; c) le **calcaire**.\n\n4. Les strates se déposent **horizontalement** ; dans une série non déformée, les couches **les plus anciennes sont en bas**, les plus récentes en haut."}$exo$::jsonb),
  ('b2db62a2-d23e-5955-92d9-00786aedab1a'::uuid, 2, 'application', $exo${"titre":"Du torrent au delta","consigne":"Exploite le document et justifie chaque réponse avec le cours.","enonce":"**Document.** Anaïs suit une rivière de sa source à la mer et prélève les dépôts à quatre endroits.\n\n| Lieu | Courant | Dépôt |\n| 1. Torrent de montagne | très rapide | ? |\n| 2. Plaine | moyen | sables |\n| 3. Delta | lent | limons fins |\n| 4. Large, eau calme | quasi nul | ? |\n\n1. Complète les deux cases « ? » en justifiant.\n2. Énonce la règle qui relie l'énergie du courant et la taille des grains déposés. Nomme ce phénomène.\n3. Le sable de la plaine est enfoui sous des centaines de mètres de dépôts. Explique ce qu'il devient et nomme la roche obtenue.\n4. À quelle famille de roches sédimentaires cette roche appartient-elle ? Justifie et cite une autre roche de cette famille.","bareme":[{"critere":"Blocs dans le torrent et argiles en eau calme","points":5},{"critere":"Plus l'énergie baisse, plus les grains déposés sont fins : tri granulométrique","points":5},{"critere":"Diagenèse : compaction puis cimentation, donnant du grès","points":6},{"critere":"Famille détritique justifiée par l'origine en débris, autre exemple cité","points":4}],"dureeMin":10,"corrige":"1. Lieu 1 (courant très rapide, forte énergie) : les **blocs** (et galets). Lieu 4 (eau calme, énergie faible) : les **argiles**, les particules les plus fines.\n\n2. Un sédiment se dépose quand le courant **perd de l'énergie** : plus l'énergie est forte, plus les grains déposés sont **gros** ; plus elle est faible, plus ils sont **fins**. C'est le **tri granulométrique**, qui organise les dépôts du piémont au delta et jusqu'au fond des océans.\n\n3. C'est la **diagenèse** : la **compaction** (le poids des dépôts supérieurs chasse l'eau), puis la **cimentation** (des minéraux précipitent et collent les grains). Le sable devient un **grès**.\n\n4. Le grès est une roche **détritique** : elle est formée de **débris** issus de l'érosion d'autres roches. Autres exemples : le **conglomérat**, l'**argilite**."}$exo$::jsonb),
  ('b2db62a2-d23e-5955-92d9-00786aedab1a'::uuid, 3, 'application', $exo${"titre":"L'histoire écrite dans une falaise","consigne":"Reconstitue l'histoire de la région dans un texte organisé, en justifiant chaque étape par les indices du document.","enonce":"**Document.** Coupe d'une falaise non déformée, décrite **de bas en haut** :\n\n| Couche | Description |\n| 1 (en bas) | conglomérat : galets arrondis cimentés |\n| 2 | grès à grains moyens, avec des rides laissées par le courant |\n| 3 | argilite très fine |\n| 4 | calcaire riche en coquilles de fossiles marins |\n| 5 (en haut) | craie blanche : squelettes microscopiques d'algues marines |\n\nAujourd'hui, cette falaise domine la mer de 80 m et ses débris tombent sur la plage.\n\n1. Classe les couches de la plus ancienne à la plus récente. Justifie avec un principe.\n2. Comment l'énergie du courant a-t-elle évolué de la couche 1 à la couche 3 ? Justifie.\n3. À quelle famille appartiennent les couches 4 et 5 ? Quel milieu de dépôt indiquent-elles ?\n4. Ces couches se sont formées sous l'eau et se trouvent aujourd'hui à 80 m d'altitude. Replace cette histoire dans le **cycle** des roches sédimentaires et dis ce qui arrive aujourd'hui à la falaise.","bareme":[{"critere":"Ordre 1 à 5 justifié par le principe de superposition","points":4},{"critere":"Énergie décroissante : galets, puis sables, puis argiles fines","points":5},{"critere":"Roches biogènes indiquant un milieu marin grâce aux fossiles","points":5},{"critere":"Cycle : dépôt, diagenèse, soulèvement puis nouvelle érosion de la falaise","points":6}],"dureeMin":18,"corrige":"1. Dans une série non déformée, les strates se déposent horizontalement et **les plus anciennes sont en bas** : c'est le **principe de superposition**. Ordre : couche **1** (la plus ancienne), 2, 3, 4, **5** (la plus récente).\n\n2. L'énergie du courant a **diminué** : la couche 1 contient des **galets** (courant fort), la couche 2 des **sables** avec des rides (courant moyen), la couche 3 des **argiles** très fines (eau calme). C'est le **tri granulométrique** : plus l'énergie baisse, plus les grains déposés sont fins. Les galets arrondis témoignent en plus d'un long transport.\n\n3. Les couches 4 et 5 sont des roches **biogènes**, construites par des restes d'êtres vivants : coquilles pour le calcaire, squelettes microscopiques d'algues pour la craie. Les **fossiles marins** indiquent un milieu de dépôt **marin**, en eau calme.\n\n4. Le **cycle** : 1) l'**érosion** d'anciens reliefs a fourni les débris ; 2) leur **transport** ; 3) leur **dépôt** sous l'eau, en couches successives ; 4) la **diagenèse** (compaction et cimentation) a transformé ces sédiments en roches ; 5) un **soulèvement** les a portées à 80 m d'altitude. Aujourd'hui commence une **nouvelle érosion** : les débris qui tombent sur la plage seront transportés et déposés à leur tour. Les mêmes atomes traversent des roches successives."}$exo$::jsonb),
  ('f099566d-42a8-5493-a615-99cc9af98026'::uuid, 1, 'application', $exo${"titre":"Subir, exploiter, aggraver","consigne":"Réponds à chaque question en une ou deux phrases complètes.","enonce":"**Questions de cours.**\n\n1. Cite **deux** risques liés à l'érosion que les sociétés humaines subissent.\n2. À quoi servent principalement les **granulats** ? Quel est le rang du sable parmi les ressources les plus consommées au monde ?\n3. Cite **trois** pratiques humaines qui aggravent l'érosion et explique l'effet de l'une d'elles.\n4. Qu'appelle-t-on le **repli stratégique** ?","bareme":[{"critere":"Deux risques subis cités (glissements, crues torrentielles, recul du trait de côte, perte des sols)","points":4},{"critere":"Granulats pour le béton ; sable deuxième ressource après l'eau","points":5},{"critere":"Trois pratiques aggravantes et l'effet de l'une expliqué","points":7},{"critere":"Repli stratégique : déplacer les constructions plutôt que défendre le trait de côte","points":4}],"dureeMin":7,"corrige":"1. Deux parmi : les **glissements de terrain** et coulées de boue, les **crues torrentielles**, l'**érosion côtière** (recul du trait de côte, effondrement de falaises), la **perte des sols** agricoles.\n\n2. Les granulats (sables et graviers) sont indispensables à la fabrication du **béton**. Le sable est la **deuxième ressource la plus consommée** au monde, **après l'eau**.\n\n3. Trois parmi : la **déforestation**, le **labour dans le sens de la pente**, la disparition des **haies** et des talus, l'**imperméabilisation** urbaine, le **surpâturage**, les **barrages**. Exemple d'effet : l'imperméabilisation empêche l'eau de s'infiltrer, elle ruisselle davantage ; les barrages piègent les sédiments et privent les plages de sable.\n\n4. Le repli stratégique consiste à **déplacer** un bâtiment ou une activité plutôt que de **défendre indéfiniment** un trait de côte qui recule."}$exo$::jsonb),
  ('f099566d-42a8-5493-a615-99cc9af98026'::uuid, 2, 'application', $exo${"titre":"La coulée de boue de Saint-Aubin","consigne":"Exploite la situation et justifie chaque réponse.","enonce":"**Situation.** Le village de Saint-Aubin est au pied d'un coteau. En vingt ans :\n\n> - le bois qui couvrait le haut du coteau a été défriché ;\n> - les haies entre les champs ont été arrachées pour faire de grandes parcelles ;\n> - les champs sont labourés dans le sens de la pente et restent nus tout l'hiver ;\n> - un lotissement et son parking ont été construits en bas du coteau.\n>\n> Après un orage de mai, une coulée de boue envahit les maisons.\n\n1. Pour chacune des quatre transformations, explique comment elle a favorisé la coulée de boue.\n2. En plus des dégâts dans le village, quelle perte subit l'agriculteur ? Pourquoi est-elle grave ?\n3. Propose **trois** mesures de prévention adaptées, en précisant à quoi sert chacune.","bareme":[{"critere":"Effet de chacune des quatre transformations expliqué (ruissellement, rien ne freine, eau accélérée, pas d'infiltration)","points":8},{"critere":"Perte du sol agricole, qui met des siècles à se former","points":4},{"critere":"Trois mesures adaptées avec leur rôle","points":8}],"dureeMin":12,"corrige":"1. - **Défrichement** du bois : plus de ruissellement, moins de retenue de l'eau et du sol ;\n- **arrachage des haies** : plus rien ne freine l'eau ni ne retient les particules ;\n- **labour dans le sens de la pente** et **sol nu** l'hiver : l'eau accélère dans les sillons et arrache la terre, sans aucune protection de surface ;\n- **lotissement et parking** : l'**imperméabilisation** empêche l'eau de s'infiltrer, elle ruisselle vers les maisons.\n\n2. L'agriculteur perd la couche fertile de son **sol**. C'est grave car un sol met **des siècles** à se former et peut partir **en une saison** : à l'échelle humaine, cette perte est définitive.\n\n3. Trois parmi (avec leur rôle) :\n- **reboiser** le haut du coteau ou cultiver en terrasses : **ralentir l'eau** ;\n- replanter des **haies**, des **talus**, des **bandes enherbées** : **retenir les particules** ;\n- **labourer perpendiculairement à la pente** et **couvrir les sols en hiver** : **protéger la surface** ;\n- établir une **carte d'aléas** et un plan de prévention : **encadrer l'urbanisation** du bas du coteau."}$exo$::jsonb),
  ('f099566d-42a8-5493-a615-99cc9af98026'::uuid, 3, 'application', $exo${"titre":"La plage qui recule","consigne":"Rédige une réponse argumentée et organisée, en t'appuyant sur les documents et sur tes connaissances.","enonce":"**Document 1.** Sur la commune littorale de Port-Mérel, le trait de côte recule en moyenne d'un mètre par an. Une dizaine de maisons sont à moins de 30 m du bord de la dune.\n\n**Document 2.** À 40 km en amont, un barrage a été construit sur le fleuve qui alimentait la côte en sable. Au large, une entreprise a extrait pendant des années du sable pour le béton.\n\n**Document 3.** Trois options sont débattues au conseil municipal : a) construire une digue ; b) laisser faire la nature ; c) déplacer progressivement les maisons menacées.\n\n1. Montre, à l'aide du document 2, que l'activité humaine a aggravé un phénomène naturel. Explique les mécanismes.\n2. Combien d'années faut-il, au rythme actuel, pour que la mer atteigne les maisons les plus proches ? Que peut-on en conclure ?\n3. Présente les avantages et les limites de chacune des trois options.\n4. Pourquoi la décision n'est-elle pas seulement scientifique ?","bareme":[{"critere":"Barrage qui piège les sédiments et extraction qui modifie les courants et prive la côte de sable","points":6},{"critere":"Calcul : 30 m à 1 m par an, environ 30 ans, et conclusion","points":3},{"critere":"Avantages et limites des trois options (digue, laisser faire, repli stratégique)","points":7},{"critere":"Décision mêlant données scientifiques et choix politiques, coûts et conséquences pour les habitants","points":4}],"dureeMin":18,"corrige":"1. L'érosion côtière est un phénomène **naturel**, mais elle est aggravée :\n- le **barrage** **piège les sédiments** : le sable que le fleuve apportait ne parvient plus à la côte, la plage n'est plus alimentée ;\n- l'**extraction de sable** au large ne prélève pas seulement de la matière : elle **modifie l'équilibre des courants** et **fragilise les côtes**.\nLa plage perd plus de sable qu'elle n'en reçoit : le trait de côte recule.\n\n2. 30 m ÷ 1 m par an = **environ 30 ans** (moins si le recul s'accélère avec les tempêtes). Le risque est à l'échelle d'une génération : il faut décider **maintenant**.\n\n3. - **Digue** : protège les maisons à court terme ; mais coûte cher, doit être entretenue sans fin, et ne traite pas la cause (le manque de sable) — c'est défendre indéfiniment le rivage.\n- **Laisser faire** : aucun coût de travaux, la dune évolue naturellement ; mais les maisons seront perdues et les habitants exposés.\n- **Repli stratégique** : déplacer les maisons évite la lutte sans fin contre la mer ; mais coûte cher, et oblige des habitants à quitter leur logement.\nOn peut ajouter la **protection des dunes** et l'encadrement de l'urbanisation par des **cartes d'aléas**.\n\n4. La science mesure le recul et en explique les causes, mais choisir entre **protéger, laisser faire ou reculer** engage des **coûts** différents et des **conséquences** différentes pour les habitants. C'est une **décision politique**, éclairée par les données scientifiques."}$exo$::jsonb),
  ('c2744825-6b56-5e2f-b97e-72c36cc6be09'::uuid, 1, 'application', $exo${"titre":"Qu'y a-t-il dans un sol ?","consigne":"Réponds à chaque question en quelques lignes, avec le vocabulaire du cours.","enonce":"1. Définis la **biomasse** et indique par quel processus les végétaux chlorophylliens la produisent.\n2. Cite les **cinq** composantes d'un sol et donne pour chacune un exemple ou une précision.\n3. Qu'est-ce que l'**humus** ?\n4. Explique pourquoi on dit que le sol est une ressource **non renouvelable** à l'échelle d'une vie humaine.","bareme":[{"critere":"Biomasse définie et photosynthèse citée","points":5},{"critere":"Cinq composantes du sol justes avec exemple, humus défini","points":10},{"critere":"Formation lente (décennies à siècles par cm) reliée au caractère non renouvelable","points":5}],"dureeMin":7,"corrige":"1. La **biomasse** est la masse de matière organique produite par les êtres vivants. Les végétaux chlorophylliens la produisent par **photosynthèse**, à partir de matière minérale et de lumière.\n\n2. Un sol contient :\n- de la **matière minérale** : sables, limons, argiles issus de l'altération de la roche mère ;\n- de la **matière organique** : l'humus ;\n- de l'**eau** et de l'**air**, dans les pores ;\n- des **êtres vivants** : bactéries, champignons, vers de terre, arthropodes (des centaines de millions de micro-organismes par gramme).\n\n3. L'**humus** est la matière organique du sol issue de la **décomposition** des êtres vivants morts et de leurs déchets.\n\n4. Former **un centimètre** de sol demande de **plusieurs décennies à plusieurs siècles**. Un sol détruit ne se reforme donc pas à l'échelle d'une vie humaine : il faut le considérer comme non renouvelable."}$exo$::jsonb),
  ('c2744825-6b56-5e2f-b97e-72c36cc6be09'::uuid, 2, 'application', $exo${"titre":"La parcelle de Mme Keller","consigne":"Lis la situation et réponds aux questions en justifiant tes réponses par le cours.","enonce":"**Situation.** Mme Keller cultive du maïs sur la même parcelle depuis quinze ans. Le sol reste nu tout l'hiver et elle y passe chaque année avec des engins lourds. Elle constate :\n\n| Mesure | Il y a 15 ans | Aujourd'hui |\n| Matière organique du sol | 3,0 % | 1,8 % |\n| Vers de terre (par m²) | 250 | 90 |\n| Épaisseur de terre arable | 30 cm | 27 cm |\n\n1. Calcule la baisse de la matière organique en pourcentage de la valeur de départ.\n2. Identifie **trois** pressions subies par ce sol et relie chacune à une observation ou à une pratique.\n3. Explique pourquoi la baisse des vers de terre inquiète pour la fertilité.\n4. Propose **deux** pratiques qui entretiendraient ce sol.","bareme":[{"critere":"Calcul juste de la baisse relative (40 %)","points":4},{"critere":"Trois pressions identifiées et reliées aux données (érosion, tassement, perte de matière organique)","points":7},{"critere":"Lien entre vie du sol et fertilité expliqué","points":5},{"critere":"Deux pratiques de préservation adaptées","points":4}],"dureeMin":12,"corrige":"1. Baisse : 3,0 − 1,8 = 1,2 point. En valeur relative : 1,2 ÷ 3,0 × 100 = **40 %** de la matière organique de départ a disparu.\n\n2. Trois pressions :\n- la **perte de matière organique** : de 3,0 % à 1,8 %, la monoculture sans apport appauvrit la vie du sol ;\n- l'**érosion** : le sol reste nu tout l'hiver, la terre part ; 3 cm de terre arable perdus ;\n- le **tassement** par les engins lourds : l'air et l'eau ne circulent plus dans les pores.\n\n3. Un sol fertile n'est pas un support inerte : c'est un **écosystème**, et sa fertilité est le produit de son **activité biologique**. Les vers de terre et les micro-organismes décomposent la matière organique en humus et rendent les éléments minéraux (azote…) disponibles pour les plantes. Moins de vie (250 → 90 vers/m²), c'est moins de fertilité. Et 3 cm perdus demandent des siècles à se reformer.\n\n4. Deux pratiques parmi : **rotation des cultures** au lieu de la monoculture ; **couverture permanente** du sol en hiver ; **apports de matière organique** ; **réduction du travail du sol** et des passages d'engins ; agroforesterie, maintien des haies."}$exo$::jsonb),
  ('c2744825-6b56-5e2f-b97e-72c36cc6be09'::uuid, 3, 'application', $exo${"titre":"Deux champs de blé comparés","consigne":"Exploite les documents pour expliquer les différences de rendement, puis argumente.","enonce":"**Document 1 — Deux parcelles voisines de blé, même climat, même variété**\n\n| | Parcelle A | Parcelle B |\n| Pratiques | Rotation blé / légumineuse / colza, couverture hivernale, fumier | Blé tous les ans, sol nu l'hiver |\n| Matière organique | 2,8 % | 1,5 % |\n| Micro-organismes (millions / g de sol) | 900 | 350 |\n| Azote disponible au printemps (kg/ha) | 95 | 60 |\n| Rendement (t/ha) | 7,5 | 6,0 |\n\n**Document 2 — Artificialisation.** En France, plusieurs dizaines de milliers d'hectares de sols sont recouverts chaque année par des constructions et des infrastructures.\n\n1. Calcule l'écart de rendement entre A et B, en t/ha et en pourcentage du rendement de B.\n2. En t'appuyant sur les données, explique la chaîne de causes qui relie les pratiques de A à son meilleur rendement.\n3. Cite les facteurs de rendement du cours qui sont **identiques** pour les deux parcelles, et explique pourquoi c'est important pour conclure.\n4. Le document 2 décrit une autre menace. Explique pourquoi elle est particulièrement grave au regard de la vitesse de formation d'un sol.","bareme":[{"critere":"Écart calculé : 1,5 t/ha et 25 %","points":3},{"critere":"Chaîne pratiques → matière organique → vie du sol → azote disponible → rendement","points":7},{"critere":"Facteurs identiques (lumière, eau, température, variété) et raisonnement expérimental","points":5},{"critere":"Artificialisation : sol perdu, formation en siècles, non renouvelable","points":5}],"dureeMin":20,"corrige":"1. Écart : 7,5 − 6,0 = **1,5 t/ha**. En pourcentage : 1,5 ÷ 6,0 × 100 = **25 %** de plus pour A.\n\n2. Chaîne explicative :\n- A pratique la **rotation**, la **couverture hivernale** et apporte du **fumier** (matière organique) ;\n- son sol est plus riche en **matière organique** (2,8 % contre 1,5 %) ;\n- cette matière nourrit une **vie du sol** plus abondante (900 contre 350 millions de micro-organismes par gramme) ;\n- cette activité biologique rend les **éléments minéraux disponibles** : 95 kg d'azote/ha contre 60 ; la légumineuse de la rotation enrichit aussi le sol en azote ;\n- l'azote étant un facteur limitant du rendement, A produit davantage.\nLa fertilité est donc le produit de l'**activité biologique** du sol.\n\n3. Les deux parcelles sont voisines, de même climat et de même variété : **lumière**, **eau**, **température** sont comparables. Seules les pratiques, et donc l'état biologique du sol, diffèrent : on peut attribuer l'écart de rendement à ce facteur (un seul facteur varie).\n\n4. L'**artificialisation** recouvre le sol de constructions : il est perdu pour l'agriculture. Or former **un centimètre** de sol demande **plusieurs décennies à plusieurs siècles** : à l'échelle humaine, le sol est **non renouvelable**, et chaque hectare artificialisé est perdu durablement pour la production de biomasse."}$exo$::jsonb),
  ('a8c678f6-3100-5392-a8c3-eb40118f47e5'::uuid, 1, 'application', $exo${"titre":"Des modèles agricoles différents","consigne":"Réponds à chaque question en quelques lignes.","enonce":"1. Quelle part approximative de l'énergie passe d'un maillon d'une chaîne alimentaire au suivant ? Que devient le reste ?\n2. Définis en une phrase l'agriculture **vivrière**, l'agriculture **intensive** et l'agriculture **biologique**.\n3. Qu'est-ce que l'**eutrophisation** et quel intrant peut la provoquer ?","bareme":[{"critere":"10 % et dissipation par respiration et déchets","points":6},{"critere":"Trois modèles agricoles correctement définis","points":9},{"critere":"Eutrophisation définie et reliée aux engrais","points":5}],"dureeMin":7,"corrige":"1. Environ **10 %** de l'énergie passe d'un maillon au suivant ; le reste est **dissipé** par la respiration et les déchets.\n\n2.\n- **Vivrière** : nourrir d'abord la famille du producteur, avec peu d'intrants.\n- **Intensive** : maximiser le rendement à l'hectare grâce aux engrais, aux phytosanitaires, à l'irrigation, à la mécanisation et à la sélection.\n- **Biologique** : agriculture sans produits de synthèse ni OGM.\n\n3. L'**eutrophisation** est l'enrichissement excessif d'un milieu aquatique en nutriments, qui finit par l'asphyxier. Elle est provoquée par les **engrais** qui ruissellent vers les eaux."}$exo$::jsonb),
  ('a8c678f6-3100-5392-a8c3-eb40118f47e5'::uuid, 2, 'application', $exo${"titre":"Combien de surface pour un repas ?","consigne":"Exploite les données chiffrées et réponds en justifiant par le cours.","enonce":"**Données.** Un champ produit 10 000 kg de végétaux consommables. On compare deux usages :\n- les végétaux sont mangés directement par des humains ;\n- les végétaux nourrissent du bétail, que des humains mangent ensuite.\n\nOn admet qu'environ **10 %** de l'énergie passe d'un maillon au suivant.\n\n1. Si l'on raisonne en « équivalent énergie », combien de kg de végétaux le premier usage rend-il disponibles pour les humains ? Et le second (en équivalent énergie des végétaux) ?\n2. Combien de fois plus de surface faut-il, dans ce modèle simplifié, pour nourrir une personne avec le second usage ?\n3. Explique d'où vient cette perte d'énergie.\n4. En t'appuyant sur le cours, explique pourquoi la faim dans le monde ne se réduit pas à un problème de volume produit.","bareme":[{"critere":"Calculs justes : 10 000 et 1 000 kg équivalents","points":5},{"critere":"Rapport de surface : environ 10 fois plus","points":4},{"critere":"Perte expliquée par respiration et déchets à chaque maillon","points":5},{"critere":"Faim liée à l'accès et aux revenus, et pertes d'un tiers de la production","points":6}],"dureeMin":12,"corrige":"1. Premier usage : les humains consomment directement l'équivalent de **10 000 kg** de végétaux. Second usage : environ 10 % de l'énergie passe des végétaux au bétail, soit l'équivalent de 10 000 × 0,10 = **1 000 kg** de végétaux sous forme de viande.\n\n2. Pour obtenir la même énergie alimentaire, il faut dans ce modèle environ 10 000 ÷ 1 000 = **10 fois plus** de surface avec le second usage. (Le cours dit : un régime riche en produits animaux mobilise **plusieurs fois plus** de surface qu'un régime majoritairement végétal.)\n\n3. À chaque maillon, l'essentiel de l'énergie est **dissipé** : l'animal en utilise pour respirer, se déplacer, maintenir sa température, et une partie est perdue dans les **déchets**. Seuls ~10 % se retrouvent dans sa matière.\n\n4. La faim tient largement à l'**accès** à la nourriture et aux **revenus**, pas seulement au volume produit. De plus, environ **un tiers** de la production mondiale est perdu ou gaspillé (au champ, au transport, au commerce, chez le consommateur). La question est donc de produire **autrement** et de **répartir**, pas seulement de produire plus."}$exo$::jsonb),
  ('a8c678f6-3100-5392-a8c3-eb40118f47e5'::uuid, 3, 'application', $exo${"titre":"Quel avenir pour la ferme de la vallée ?","consigne":"Analyse la situation à l'aide du cours, puis rédige une argumentation structurée.","enonce":"**Situation.** Dans une vallée, une grande exploitation intensive produit du maïs irrigué pour nourrir des porcs. On observe :\n\n> - Le niveau de la nappe phréatique a baissé de 4 m en vingt ans.\n> - La rivière voisine se couvre d'algues chaque été et des poissons meurent.\n> - Un insecticide utilisé depuis dix ans est de moins en moins efficace sur un ravageur du maïs.\n\n1. Pour chacune des trois observations, identifie l'**intrant** en cause et explique le mécanisme.\n2. Rappelle le principe de l'agriculture intensive et ce qu'elle apporte.\n3. Le conseil municipal veut « produire plus » pour nourrir davantage de monde. En t'appuyant sur les chaînes alimentaires et sur les pertes, rédige un paragraphe argumenté qui montre qu'il existe d'autres leviers.","bareme":[{"critere":"Irrigation → épuisement de la nappe expliqué","points":3},{"critere":"Engrais → eutrophisation expliquée (nutriments, algues, asphyxie)","points":4},{"critere":"Phytosanitaires → sélection de ravageurs résistants expliquée","points":4},{"critere":"Intérêt de l'agriculture intensive (rendement à l'hectare) reconnu","points":3},{"critere":"Argumentation : 10 % par maillon, part végétale, pertes d'un tiers, accès et répartition","points":6}],"dureeMin":20,"corrige":"**1.**\n- **Nappe en baisse** : l'**irrigation** lève la contrainte hydrique, mais pompe plus d'eau que la nappe n'en reçoit : épuisement des nappes.\n- **Algues et poissons morts** : les **engrais** apportés en excès ruissellent vers la rivière. Cet enrichissement excessif en nutriments (nitrates, phosphates) fait proliférer les algues, puis le milieu est asphyxié : c'est l'**eutrophisation**.\n- **Insecticide moins efficace** : l'usage répété du même **phytosanitaire** élimine les ravageurs sensibles et laisse survivre et se reproduire les rares résistants : on **sélectionne** une population **résistante**.\n\n**2.** L'agriculture intensive cherche à **maximiser le rendement à l'hectare** grâce aux engrais, aux phytosanitaires, à l'irrigation, à la mécanisation et à la sélection. Elle produit beaucoup sur peu de surface : c'est son intérêt, mais elle a un coût pour les écosystèmes.\n\n**3. Exemple d'argumentation**\nProduire plus n'est pas le seul levier. D'abord, le maïs sert ici à nourrir des porcs : or seuls **10 % environ** de l'énergie passent d'un maillon au suivant. Une alimentation plus végétale nourrit donc beaucoup plus de personnes par hectare. Ensuite, environ **un tiers** de la production mondiale est perdu ou gaspillé : réduire ces pertes est un levier au moins aussi puissant que l'augmentation des rendements. Enfin, la faim dépend surtout de l'**accès** et des **revenus** : il faut aussi **répartir**. Produire **autrement** (moins d'intrants, agroécologie) préserverait en outre la nappe et la rivière dont dépend la production future."}$exo$::jsonb),
  ('da99a042-bb91-5ee2-85aa-9be6570265d1'::uuid, 1, 'application', $exo${"titre":"Les leviers de la hausse des rendements","consigne":"Réponds à chaque question en quelques lignes.","enonce":"1. Cite **quatre** leviers qui ont permis d'augmenter les rendements agricoles depuis un siècle, et donne l'apport de chacun.\n2. Quel progrès a levé la principale limite minérale des cultures ?\n3. Donne **deux** effets de l'agriculture intensive sur l'environnement.","bareme":[{"critere":"Quatre leviers justes avec leur apport","points":10},{"critere":"Engrais de synthèse (fixation industrielle de l'azote)","points":4},{"critere":"Deux effets environnementaux justes","points":6}],"dureeMin":7,"corrige":"1. Quatre leviers parmi :\n- la **sélection variétale** : des variétés plus productives et plus résistantes ;\n- les **engrais de synthèse** : ils lèvent la principale limite minérale ;\n- la **mécanisation** : plus de surface travaillée par actif ;\n- l'**irrigation** : une saison de culture sécurisée ;\n- les **phytosanitaires** : moins de pertes ;\n- le **remembrement** : de grandes parcelles mécanisables.\n\n2. Les **engrais azotés de synthèse**, permis par la **fixation industrielle de l'azote**.\n\n3. Deux effets parmi : pollution par nitrates et phosphates (marées vertes, zones mortes littorales) ; résidus de pesticides dans les sols et les cours d'eau ; effondrement des insectes pollinisateurs et des oiseaux des champs ; perte de biodiversité (disparition des haies) ; tassement et érosion des sols ; surexploitation des nappes."}$exo$::jsonb),
  ('da99a042-bb91-5ee2-85aa-9be6570265d1'::uuid, 2, 'application', $exo${"titre":"Des coccinelles contre les pucerons","consigne":"Exploite les résultats de l'essai et réponds en justifiant par le cours.","enonce":"**Situation.** Un maraîcher compare trois serres de salades attaquées par des pucerons pendant un mois.\n\n| Serre | Méthode | Pucerons par plant (fin du mois) | Salades vendables |\n| 1 | Aucun traitement | 120 | 55 % |\n| 2 | Insecticide chaque semaine | 15 | 92 % |\n| 3 | Lâcher de coccinelles (prédateurs des pucerons) | 25 | 88 % |\n\n1. Quel est le rôle de la serre 1 ?\n2. Calcule, pour les serres 2 et 3, le gain de salades vendables par rapport à la serre 1.\n3. Nomme la méthode utilisée dans la serre 3 et explique son principe.\n4. La serre 2 donne le meilleur résultat. Donne **deux** raisons, tirées du cours, de préférer malgré tout la méthode de la serre 3.","bareme":[{"critere":"Serre 1 identifiée comme témoin","points":3},{"critere":"Gains calculés : +37 points et +33 points","points":4},{"critere":"Lutte biologique nommée et expliquée","points":5},{"critere":"Deux raisons justes (résidus, résistances, santé, auxiliaires, lutte intégrée)","points":8}],"dureeMin":12,"corrige":"1. La serre 1 est le **témoin** : sans traitement, elle montre ce qui se passe sans intervention, et permet de mesurer l'effet des deux méthodes.\n\n2. Serre 2 : 92 − 55 = **+37 points** de salades vendables. Serre 3 : 88 − 55 = **+33 points**. La lutte biologique donne presque le même gain.\n\n3. C'est la **lutte biologique** : on utilise un **ennemi naturel** du ravageur (la coccinelle mange les pucerons) pour contrôler sa population, sans produit chimique.\n\n4. Deux raisons parmi :\n- les **résidus** d'insecticide dans les salades exposent les consommateurs, et l'exposition **professionnelle** concerne le maraîcher ;\n- un traitement chaque semaine avec le même produit favorise l'apparition de pucerons **résistants** : l'efficacité future diminuera ;\n- l'insecticide tue aussi des insectes utiles, dont les **pollinisateurs** et les **auxiliaires** ;\n- la **lutte intégrée** recommande de réserver le traitement chimique au **dernier recours** : ici, la méthode biologique suffit presque.\n\nConclusion attendue : un rendement légèrement plus faible peut être préférable s'il préserve la santé et l'efficacité des traitements à long terme."}$exo$::jsonb),
  ('da99a042-bb91-5ee2-85aa-9be6570265d1'::uuid, 3, 'application', $exo${"titre":"Le triple arbitrage d'une agriculture durable","consigne":"Exploite les documents, puis rédige une argumentation structurée en t'appuyant sur le cours.","enonce":"**Document 1 — Évolution dans une région de grandes cultures (valeurs arrondies)**\n\n| | 1960 | 2020 |\n| Rendement du blé (t/ha) | 2,5 | 7,5 |\n| Longueur de haies (km pour 100 km²) | 120 | 40 |\n| Oiseaux des champs (indice) | 100 | 55 |\n\n**Document 2 — Dans un élevage de la région**, des antibiotiques ont longtemps été donnés à tous les animaux de façon préventive.\n\n1. Calcule par combien le rendement du blé a été multiplié, et le pourcentage de haies disparues.\n2. Relie la disparition des haies au déclin des oiseaux et à la perte d'**auxiliaires**, et explique en quoi cela peut fragiliser les rendements futurs.\n3. Explique le risque sanitaire du document 2 et qui il concerne.\n4. Rédige un paragraphe qui propose **trois** pratiques du cours pour maintenir les rendements tout en réduisant ces effets, et conclus sur les trois exigences d'une agriculture durable.","bareme":[{"critere":"Calculs justes : ×3 et 67 % de haies disparues","points":3},{"critere":"Haies → biodiversité, auxiliaires, pollinisateurs → rendements fragilisés","points":5},{"critere":"Antibiorésistance expliquée et reliée à la médecine humaine","points":4},{"critere":"Trois pratiques durables justes et expliquées","points":5},{"critere":"Conclusion : nourrir, préserver les milieux, faire vivre les producteurs","points":3}],"dureeMin":20,"corrige":"1. Rendement : 7,5 ÷ 2,5 = **3** : il a été multiplié par 3. Haies : (120 − 40) ÷ 120 × 100 ≈ **67 %** ont disparu (les deux tiers).\n\n2. Le **remembrement** a créé de grandes parcelles mécanisables en supprimant des haies. Or les haies abritent des oiseaux, des insectes pollinisateurs et des **auxiliaires** (prédateurs des ravageurs) : leur disparition explique en partie la perte de **biodiversité** (indice des oiseaux 100 → 55). Moins d'auxiliaires, c'est moins de **régulation naturelle** des ravageurs, donc plus de traitements ; moins de pollinisateurs, c'est une chaîne entière fragilisée. On ne peut pas augmenter durablement un rendement en détruisant ce qui le rend possible.\n\n3. L'usage massif et préventif d'antibiotiques en élevage sélectionne des bactéries **résistantes** : c'est l'**antibiorésistance**. Elle concerne la **médecine humaine**, car ces bactéries peuvent rendre inefficaces les antibiotiques utilisés pour soigner les humains.\n\n4. **Exemple de paragraphe**\nPour maintenir les rendements tout en réduisant ces effets, on peut replanter des **haies** et pratiquer l'**agroforesterie**, qui abritent les **auxiliaires** et offrent une régulation gratuite des ravageurs. La **lutte intégrée** combine les méthodes (rotations longues, lutte biologique, variétés résistantes) et réserve le traitement chimique au dernier recours. L'**agriculture de précision** n'applique un intrant que là où il est utile. Une agriculture durable doit tenir trois exigences à la fois : **nourrir**, **préserver les milieux** et **faire vivre** ceux qui produisent ; aucune solution technique ne dispense de cet arbitrage.\n\n(Toute pratique du cours justement expliquée est acceptée : rotations longues, variétés résistantes, couverture des sols.)"}$exo$::jsonb),
  ('642962cd-cd21-59a4-ac33-0ce8a478c9e5'::uuid, 1, 'application', $exo${"titre":"Les trois niveaux du sexe","consigne":"Réponds à chaque question en quelques lignes.","enonce":"1. Complète le tableau :\n\n| Niveau | Quand il se met en place | Ce qui le détermine |\n| Sexe chromosomique | ? | ? |\n| Sexe gonadique | ? | ? |\n| Sexe phénotypique | ? | ? |\n\n2. Quel chromosome l'ovule apporte-t-il toujours ? Et le spermatozoïde ?\n3. Cite **trois** caractères sexuels secondaires qui apparaissent à la puberté.","bareme":[{"critere":"Tableau complet et exact (fécondation, 7e semaine / SRY, hormones)","points":12},{"critere":"Chromosomes apportés par les gamètes","points":4},{"critere":"Trois caractères sexuels secondaires","points":4}],"dureeMin":7,"corrige":"1.\n| Niveau | Quand | Ce qui le détermine |\n| Sexe **chromosomique** | Dès la **fécondation** | La paire de chromosomes sexuels (XX ou XY) |\n| Sexe **gonadique** | Vers la **7e semaine** | La présence ou l'absence du gène **SRY** (porté par Y) |\n| Sexe **phénotypique** | Avant la naissance, **complété à la puberté** | Les **hormones** produites par les gonades |\n\n2. L'ovule apporte toujours un chromosome **X** ; le spermatozoïde apporte un **X** ou un **Y**.\n\n3. Trois caractères parmi : pilosité, mue de la voix, développement des seins, modification de la morphologie."}$exo$::jsonb),
  ('642962cd-cd21-59a4-ac33-0ce8a478c9e5'::uuid, 2, 'application', $exo${"titre":"De la cellule-œuf au fœtus","consigne":"Explique les étapes de la mise en place du sexe à partir de la situation.","enonce":"**Situation.** Deux embryons, Alpha et Bêta, sont observés à six semaines puis à douze semaines.\n\n| | Chromosomes sexuels | À 6 semaines | À 12 semaines |\n| Alpha | XY | Gonades indifférenciées, double ébauche de conduits | Testicules ; un jeu de conduits développé, l'autre régressé |\n| Bêta | XX | Gonades indifférenciées, double ébauche de conduits | Ovaires |\n\n1. Qu'est-ce qui, à la fécondation, a déterminé le sexe chromosomique d'Alpha ? Quel gamète l'a décidé ?\n2. Explique pourquoi les gonades d'Alpha sont devenues des testicules et non celles de Bêta.\n3. Chez Alpha, quelles hormones expliquent l'évolution des conduits ? Précise le rôle de chacune.\n4. Que signifie la phrase « un même point de départ, deux trajectoires » ?","bareme":[{"critere":"Sexe chromosomique : spermatozoïde porteur de Y","points":4},{"critere":"Gène SRY sur Y déclenche la différenciation en testicules","points":5},{"critere":"Testostérone (développe un jeu) et hormone antimüllérienne (fait régresser l'autre)","points":6},{"critere":"Mêmes ébauches embryonnaires pour les deux sexes expliquées","points":5}],"dureeMin":12,"corrige":"1. Le sexe chromosomique est fixé **dès la fécondation** par la paire de chromosomes sexuels. L'ovule apporte toujours un X : c'est donc le **spermatozoïde**, porteur d'un **Y**, qui a fait d'Alpha un embryon **XY**.\n\n2. Le chromosome Y porte le gène **SRY**, qui déclenche la différenciation des gonades indifférenciées en **testicules** vers la 7e semaine. Bêta (XX) n'a pas de Y, donc pas de SRY : ses gonades deviennent des **ovaires**.\n\n3. Les testicules fœtaux d'Alpha produisent :\n- la **testostérone**, qui **développe** un jeu de conduits ;\n- l'**hormone antimüllérienne**, qui fait **régresser** l'autre.\nC'est le sexe **phénotypique**, mis en place par les hormones.\n\n4. Avant la 7e semaine, tous les embryons ont des **gonades indifférenciées** et une **double ébauche** de conduits : le point de départ est le même. Les appareils génitaux masculin et féminin dérivent de ces **mêmes ébauches** ; c'est la présence ou non de SRY puis des hormones qui oriente vers l'une ou l'autre trajectoire."}$exo$::jsonb),
  ('642962cd-cd21-59a4-ac33-0ce8a478c9e5'::uuid, 3, 'application', $exo${"titre":"La puberté, dernière étape","consigne":"Exploite le document et rédige une réponse structurée qui relie les trois niveaux du sexe.","enonce":"**Document — Âge d'apparition des premiers signes pubertaires dans une classe de 30 élèves (enquête fictive)**\n\n| Âge des premiers signes | 10 ans | 11 ans | 12 ans | 13 ans | 14 ans | 15 ans |\n| Nombre d'élèves | 2 | 5 | 9 | 8 | 4 | 2 |\n\n1. Calcule le pourcentage d'élèves dont la puberté a commencé à 12 ou 13 ans. Quel est l'écart d'âge entre le plus précoce et le plus tardif ?\n2. Un élève inquiet dit : « Mes premiers signes sont arrivés à 15 ans, je ne suis pas normal. » Que lui répondre, en t'appuyant sur le document et sur le cours ?\n3. Explique ce qui déclenche la puberté et ce qu'on y acquiert (au moins trois éléments).\n4. Rédige un paragraphe qui montre que le sexe d'un individu « se construit de la fécondation à la puberté », en reprenant les trois niveaux dans l'ordre.","bareme":[{"critere":"Calculs justes : 17 élèves soit environ 57 %, écart de 5 ans","points":4},{"critere":"Réponse à l'élève : variabilité normale, fourchette 10-16 ans","points":4},{"critere":"Déclencheur hormonal et acquisitions (caractères secondaires, croissance, fonction reproductrice)","points":5},{"critere":"Paragraphe reliant sexe chromosomique, gonadique et phénotypique dans l'ordre","points":7}],"dureeMin":18,"corrige":"1. À 12 ou 13 ans : 9 + 8 = 17 élèves sur 30, soit 17 ÷ 30 × 100 ≈ **57 %**. Écart : 15 − 10 = **5 ans** entre le plus précoce et le plus tardif.\n\n2. Le document montre une grande **variabilité** : les premiers signes s'étalent de 10 à 15 ans dans une seule classe. Le cours indique que la puberté survient **entre 10 et 16 ans environ** et que cette variabilité d'un individu à l'autre est **normale**. 15 ans est dans la fourchette : l'élève n'a pas de raison de s'inquiéter (en cas de doute, un médecin ou l'infirmerie peuvent le rassurer). La puberté est aussi un bouleversement psychologique : image du corps, identité, relations.\n\n3. La puberté est déclenchée par une **élévation de la production hormonale**. On y acquiert : les **caractères sexuels secondaires** (pilosité, voix, seins, morphologie), une **croissance rapide**, et la **fonction reproductrice** (premières règles, premières éjaculations ; la production de gamètes commence).\n\n4. **Exemple de paragraphe**\nDès la **fécondation**, le sexe **chromosomique** est fixé : l'ovule apporte un X, le spermatozoïde un X ou un Y, et la cellule-œuf est XX ou XY. Vers la **7e semaine**, les gonades jusque-là indifférenciées deviennent des testicules si le gène **SRY** du chromosome Y est présent, des ovaires sinon : c'est le sexe **gonadique**. Les gonades produisent alors des **hormones** (testostérone, hormone antimüllérienne chez le fœtus masculin) qui orientent les conduits génitaux : c'est le sexe **phénotypique**, mis en place avant la naissance. Il n'est achevé qu'à la **puberté**, quand une nouvelle hausse hormonale fait apparaître les caractères sexuels secondaires et la fonction reproductrice."}$exo$::jsonb),
  ('7ee7c6a2-9323-5507-9fe7-b51faf3a1cad'::uuid, 1, 'application', $exo${"titre":"Réflexes et cerveau","consigne":"Réponds à chaque question en quelques lignes.","enonce":"1. Quels sont les **deux niveaux** de contrôle de la sexualité par le système nerveux ? Donne la structure et le mode de fonctionnement de chacun.\n2. Quel est le rôle du **système de récompense** et quel neurotransmetteur intervient ?\n3. Cite les **quatre** caractères d'un consentement valable.","bareme":[{"critere":"Moelle épinière (réflexes) et cerveau (modulation) décrits","points":8},{"critere":"Système de récompense et dopamine","points":5},{"critere":"Consentement nécessaire, libre, éclairé, révocable","points":7}],"dureeMin":7,"corrige":"1.\n- Le niveau **automatique** : la **moelle épinière** commande des **réflexes** — un stimulus, un circuit court, une réponse, sans décision consciente.\n- Le niveau **cérébral** : le **cerveau** **module** ces réflexes (système de récompense, cortex).\n\n2. Le système de récompense associe certains comportements au **plaisir**, par la **dopamine**, et favorise leur **répétition**.\n\n3. Le consentement est **nécessaire** (de chaque personne), **libre** (sans contrainte ni pression), **éclairé** (en connaissance de cause) et **révocable** à tout moment. Il ne se présume pas."}$exo$::jsonb),
  ('7ee7c6a2-9323-5507-9fe7-b51faf3a1cad'::uuid, 2, 'application', $exo${"titre":"Ce qui distingue la sexualité humaine","consigne":"Lis les documents et réponds aux questions en t'appuyant sur le cours.","enonce":"**Document 1.** Chez le cerf, l'activité sexuelle se limite à la période du rut, à l'automne, quand le taux de testostérone est au plus haut. En dehors de cette saison, les mâles ne s'intéressent pas aux femelles.\n\n**Document 2.** Chez l'être humain, l'activité sexuelle peut avoir lieu toute l'année, et elle dépend fortement du contexte : histoire personnelle, émotions, relation avec l'autre.\n\n1. Compare les deux documents : qu'est-ce qui gouverne le comportement sexuel dans chaque cas ?\n2. Quelle structure cérébrale explique, chez l'humain, l'importance de la mémoire, de l'imaginaire et de la relation ? Donne son rôle.\n3. Cite **trois** facteurs non hormonaux qui influencent la sexualité humaine.\n4. Explique pourquoi on dit que la sexualité humaine est « largement dissociée de la reproduction ».","bareme":[{"critere":"Comparaison : hormones et saisons chez le cerf / contrôle cérébral chez l'humain","points":5},{"critere":"Cortex et son rôle (mémoire, imaginaire, émotion, attention à l'autre)","points":5},{"critere":"Trois facteurs justes (histoire, apprentissages, culture, relation)","points":5},{"critere":"Dissociation reproduction / plaisir, lien, communication expliquée","points":5}],"dureeMin":11,"corrige":"1. Chez le cerf, le comportement sexuel est **strictement rythmé par les hormones et les saisons** (testostérone maximale au rut). Chez l'humain, il ne dépend pas des seules hormones : le **système nerveux**, et surtout le **cerveau**, le module selon le contexte.\n\n2. Le **cortex** : il intègre la **mémoire**, l'**imaginaire**, l'**anticipation**, les **émotions** et l'**attention portée à l'autre**.\n\n3. Trois facteurs parmi : l'**histoire personnelle** (qui façonne les attentes), les **apprentissages** (qui construisent les représentations), la **culture et les normes sociales** (qui encadrent), la **relation** (déterminante).\n\n4. Chez l'humain, l'activité sexuelle ne sert pas seulement à se reproduire : c'est aussi un comportement de **plaisir** (système de récompense, dopamine), de **lien** et de **communication**. Elle peut avoir lieu toute l'année, sans lien avec une période de fécondité : elle est donc largement dissociée de la reproduction."}$exo$::jsonb),
  ('7ee7c6a2-9323-5507-9fe7-b51faf3a1cad'::uuid, 3, 'application', $exo${"titre":"S'informer et respecter l'autre","consigne":"Analyse la situation et rédige une réponse argumentée qui mobilise le cours.","enonce":"**Situation.** Sur un forum, un élève de 15 ans écrit :\n\n> « Tout ce que je sais, je l'ai appris dans des vidéos pornographiques. Là-bas, personne ne demande rien : si on est en couple, c'est forcément oui. Et de toute façon, tout est une question d'hormones, on ne contrôle rien. »\n\n1. Relève **trois** idées fausses dans ce message.\n2. Pour chacune, explique en quoi elle est fausse en t'appuyant sur le cours (niveaux de contrôle, consentement, sources d'information).\n3. Indique à cet élève **trois** sources fiables d'information, et ce que chacune peut lui apporter.\n4. Rappelle ce que prévoit le droit face à une atteinte sexuelle imposée.","bareme":[{"critere":"Trois idées fausses relevées","points":3},{"critere":"Pornographie : production commerciale, ni documentaire ni modèle","points":4},{"critere":"Consentement : ne se présume pas, libre, éclairé, révocable, même en couple","points":5},{"critere":"Contrôle cérébral : le cerveau module les réflexes, pas seulement les hormones","points":4},{"critere":"Trois sources fiables et rappel de la sanction pénale","points":4}],"dureeMin":18,"corrige":"**1. Trois idées fausses**\n- La pornographie serait une source d'information.\n- En couple, le consentement serait automatique (« c'est forcément oui »).\n- Tout serait une question d'hormones, sans contrôle possible.\n\n**2. Réfutation**\n- Les représentations de la pornographie ne sont **ni un documentaire, ni un modèle** : ce sont des **productions commerciales**, souvent éloignées de la réalité des relations. Elles ne constituent pas une source fiable.\n- Le consentement est **nécessaire** de chaque personne, **libre**, **éclairé** et **révocable à tout moment**. Il **ne se présume pas** : être en couple ne vaut pas accord, et un oui peut être retiré.\n- La sexualité humaine n'est pas gouvernée par les seules hormones. La **moelle épinière** commande des réflexes, mais le **cerveau les module** : le **cortex** intègre mémoire, émotions, anticipation et **attention portée à l'autre**. Chacun reste responsable de son comportement.\n\n**3. Sources fiables**\n- Les **professionnels de santé** et l'**infirmerie scolaire** : un avis personnalisé.\n- Les **centres de santé sexuelle** : prévention, dépistage, contraception.\n- Les **sites publics d'information** : des repères vérifiés.\n\n**4.** Le **droit sanctionne pénalement** toute atteinte sexuelle imposée, ainsi que le **harcèlement**."}$exo$::jsonb),
  ('74a94870-17af-5500-ba9c-92d7324b8755'::uuid, 1, 'application', $exo${"titre":"La chaîne de commande hormonale","consigne":"Réponds à chaque question en quelques lignes.","enonce":"1. Définis une **hormone**.\n2. Complète la chaîne de commande : hypothalamus → ? → ? ; nomme les deux hormones produites par l'hypophyse.\n3. Chez la femme, quel événement déclenche le pic de LH, et vers quel jour du cycle ?\n4. Quel est le seul moyen de contraception qui protège aussi des IST ?","bareme":[{"critere":"Hormone définie (glande, sang, cellules cibles à récepteur)","points":5},{"critere":"Chaîne hypothalamus → hypophyse (FSH, LH) → gonades","points":6},{"critere":"Pic de LH : ovulation vers le 14e jour","points":5},{"critere":"Préservatif","points":4}],"dureeMin":7,"corrige":"1. Une **hormone** est une substance produite par une **glande**, transportée par le **sang**, qui agit à distance sur des **cellules cibles** possédant le **récepteur** correspondant.\n\n2. **Hypothalamus** (hormone de commande) → **hypophyse** → **gonades**. L'hypophyse sécrète les gonadostimulines : **FSH** et **LH**.\n\n3. Le pic de LH déclenche l'**ovulation**, vers le **14e jour** d'un cycle d'environ 28 jours.\n\n4. Le **préservatif** : c'est le seul moyen de contraception qui protège aussi des **IST**."}$exo$::jsonb),
  ('74a94870-17af-5500-ba9c-92d7324b8755'::uuid, 2, 'application', $exo${"titre":"Un taux de testostérone stable","consigne":"Exploite l'expérience et explique le mécanisme en t'appuyant sur le cours.","enonce":"**Expérience (sur un mammifère mâle).**\n\n| Situation | Taux de LH dans le sang | Taux de testostérone |\n| Animal témoin | Normal, stable | Normal, stable |\n| Après ablation des testicules | Très élevé | Presque nul |\n| Ablation + injection régulière de testostérone | Normal | Normal |\n\n1. Pourquoi la testostérone devient-elle presque nulle après l'ablation des testicules ?\n2. Décris l'évolution de la LH après l'ablation et propose une explication.\n3. Que montre la troisième ligne ? Nomme le mécanisme mis en évidence.\n4. Explique en quoi ce mécanisme maintient un taux de testostérone stable chez l'homme.","bareme":[{"critere":"Testicules = source de la testostérone","points":4},{"critere":"Hausse de LH expliquée par l'absence de frein","points":5},{"critere":"Rétrocontrôle négatif nommé et démontré par l'injection","points":6},{"critere":"Stabilité expliquée par la boucle de régulation","points":5}],"dureeMin":12,"corrige":"1. Les **testicules** (gonades) produisent la **testostérone** : sans eux, elle n'est plus fabriquée.\n\n2. Après l'ablation, la LH devient **très élevée**. En temps normal, la testostérone **freine** le complexe hypothalamo-hypophysaire ; sans testostérone, ce frein disparaît et l'hypophyse sécrète beaucoup plus de LH.\n\n3. En injectant de la testostérone, la LH redevient normale : c'est bien la **testostérone** qui freine la sécrétion de LH. C'est un **rétrocontrôle négatif** : une hormone freine en retour la structure qui l'a fait produire.\n\n4. Si la testostérone augmente, elle freine davantage l'hypothalamus et l'hypophyse : moins de LH, donc moins de testostérone produite. Si elle baisse, le frein se relâche : plus de LH, donc plus de testostérone. Le taux oscille autour d'une valeur **stable**, ce qui permet une production **continue** de spermatozoïdes."}$exo$::jsonb),
  ('74a94870-17af-5500-ba9c-92d7324b8755'::uuid, 3, 'application', $exo${"titre":"Le cycle de Clara et la pilule","consigne":"Exploite le document pour expliquer le cycle, puis le mode d'action d'une contraception hormonale.","enonce":"**Document — Évolution des hormones au cours d'un cycle de 28 jours (valeurs relatives)**\n\n| Jour | 2 | 7 | 12 | 14 | 18 | 22 | 27 |\n| FSH | moyenne | moyenne | moyenne | pic | faible | faible | en hausse |\n| LH | faible | faible | en hausse | **pic** | faible | faible | faible |\n| Œstrogènes | faibles | en hausse | élevés | élevés | moyens | moyens | faibles |\n| Progestérone | nulle | nulle | nulle | faible | élevée | élevée | en chute |\n| Muqueuse utérine | règles | s'épaissit | épaisse | épaisse | très épaisse | très épaisse | se détache |\n\n1. En t'appuyant sur le document, décris les grandes étapes du cycle (maturation du follicule, ovulation, préparation de la muqueuse, règles) en citant l'hormone qui intervient à chaque étape.\n2. Explique pourquoi les règles surviennent vers le 28e jour en l'absence de fécondation.\n3. Clara prend une pilule combinée (hormones de synthèse chaque jour). Explique comment elle empêche une grossesse, en utilisant la notion de rétrocontrôle.\n4. Pourquoi son médecin lui conseille-t-il aussi le préservatif avec un nouveau partenaire ?","bareme":[{"critere":"FSH → maturation du follicule ; pic de LH → ovulation vers J14","points":5},{"critere":"Œstrogènes puis progestérone → préparation de la muqueuse","points":4},{"critere":"Chute hormonale → élimination de la muqueuse, règles","points":3},{"critere":"Pilule : blocage de l'ovulation par rétrocontrôle et modification de la glaire","points":5},{"critere":"Préservatif seul à protéger des IST","points":3}],"dureeMin":20,"corrige":"**1. Les étapes du cycle**\n- **Première phase (J1 à J13)** : la **FSH** permet la **maturation d'un follicule** ovarien ; les œstrogènes augmentent (J7-J12) et la muqueuse s'épaissit.\n- **Vers le 14e jour** : un **pic de LH** (avec un pic de FSH) déclenche l'**ovulation**.\n- **Après l'ovulation (J15-J26)** : les ovaires sécrètent des **œstrogènes** puis surtout de la **progestérone** (élevée à J18-J22) : la **muqueuse utérine** devient très épaisse, prête à une éventuelle implantation.\n- **Fin du cycle** : la progestérone et les œstrogènes chutent (J27), la muqueuse se détache : ce sont les **règles**.\nLe cycle utérin suit, avec un léger décalage, le cycle ovarien : les hormones ovariennes les synchronisent.\n\n**2.** Sans fécondation, la sécrétion d'œstrogènes et de progestérone **chute** en fin de cycle. La muqueuse n'est plus entretenue : elle est éliminée, ce sont les règles, et un nouveau cycle commence.\n\n**3.** La pilule apporte chaque jour des **hormones de synthèse** proches des hormones ovariennes. Elles exercent un **rétrocontrôle négatif** sur le complexe hypothalamo-hypophysaire : la sécrétion de FSH et LH reste basse, il n'y a **pas de pic de LH**, donc **pas d'ovulation**. Elle **modifie aussi la glaire** cervicale, qui gêne le passage des spermatozoïdes. Elle est très efficace si elle est bien suivie.\n\n**4.** La pilule ne protège **pas des IST**. Le **préservatif**, barrière mécanique, est le **seul** moyen de contraception qui protège aussi des infections sexuellement transmissibles."}$exo$::jsonb),
  ('625b037d-3aed-5ce5-940a-92cf5ac8ac09'::uuid, 1, 'application', $exo${"titre":"Les familles d'agents pathogènes","consigne":"Réponds à chaque question en quelques lignes.","enonce":"1. Définis un **agent pathogène**.\n2. Cite les **quatre** grandes familles d'agents pathogènes et donne pour chacune une maladie.\n3. Quelle différence essentielle y a-t-il entre un virus et une bactérie ?\n4. Qu'est-ce qu'une transmission **vectorielle** ? Donne un exemple.","bareme":[{"critere":"Agent pathogène défini","points":3},{"critere":"Quatre familles avec une maladie juste chacune","points":8},{"critere":"Virus non cellulaire, parasite une cellule hôte ; bactérie cellule qui se multiplie seule","points":5},{"critere":"Transmission vectorielle définie avec un exemple juste","points":4}],"dureeMin":7,"corrige":"1. Un **agent pathogène** est un micro-organisme capable de provoquer une maladie chez son hôte.\n\n2.\n- **Bactéries** : tuberculose, salmonellose, angine à streptocoque, maladie de Lyme.\n- **Virus** : grippe, VIH, Covid-19, dengue.\n- **Champignons** microscopiques : mycoses.\n- **Protozoaires** : paludisme, toxoplasmose.\n\n3. Une **bactérie** est une **cellule** (procaryote) capable de se multiplier seule. Un **virus** n'est **pas une cellule** : il doit **parasiter une cellule hôte** pour se multiplier.\n\n4. Une transmission **vectorielle** : un **animal** transporte l'agent pathogène d'un hôte à l'autre. Ex. : le moustique *Anopheles* transmet le *Plasmodium* du paludisme ; la tique transmet la maladie de Lyme."}$exo$::jsonb),
  ('625b037d-3aed-5ce5-940a-92cf5ac8ac09'::uuid, 2, 'application', $exo${"titre":"Le moustique tigre remonte vers le nord","consigne":"Exploite les données et réponds en t'appuyant sur le cours.","enonce":"**Données (valeurs arrondies, fictives mais réalistes).** Nombre de départements de France métropolitaine où le moustique tigre (*Aedes albopictus*) est installé :\n\n| Année | 2010 | 2015 | 2020 | 2025 |\n| Départements colonisés | 10 | 30 | 60 | 80 |\n\n1. Décris l'évolution et calcule par combien le nombre de départements a été multiplié entre 2010 et 2025.\n2. Quelles maladies ce moustique peut-il transmettre, et quel type d'agent en est responsable ?\n3. Propose **trois** facteurs de l'environnement qui peuvent expliquer cette extension.\n4. Propose **deux** mesures de prévention, l'une collective, l'autre individuelle.","bareme":[{"critere":"Évolution décrite et facteur ×8 calculé","points":4},{"critere":"Dengue, chikungunya, Zika ; agents viraux","points":5},{"critere":"Trois facteurs environnementaux justes","points":6},{"critere":"Une mesure collective et une individuelle","points":5}],"dureeMin":11,"corrige":"1. Le nombre de départements colonisés **augmente fortement et régulièrement** : de 10 en 2010 à 80 en 2025, soit une multiplication par 80 ÷ 10 = **8**. Le moustique tigre est installé dans une grande partie de la France métropolitaine.\n\n2. Il peut transmettre la **dengue**, le **chikungunya** et le **Zika**, maladies dues à des **virus**.\n\n3. Trois facteurs parmi :\n- le **réchauffement climatique**, qui étend l'aire du moustique vers le nord (le climat fixe l'aire du vecteur) ;\n- les **eaux stagnantes** (soucoupes, gouttières, pneus) qui offrent des gîtes larvaires ;\n- l'**urbanisation**, qui rapproche hôtes et vecteurs ;\n- les **déplacements humains**, qui transportent le moustique et importent les agents.\n\n4. Collective : **éliminer les eaux stagnantes** à l'échelle d'une commune, **surveiller les cas**, vacciner quand un vaccin existe. Individuelle : **répulsifs**, **moustiquaires**, vêtements couvrants, vider les eaux stagnantes chez soi."}$exo$::jsonb),
  ('625b037d-3aed-5ce5-940a-92cf5ac8ac09'::uuid, 3, 'application', $exo${"titre":"Enquête sur trois malades","consigne":"Identifie l'agent et le mode de transmission dans chaque cas, puis rédige une synthèse argumentée.","enonce":"**Trois patients consultent le même médecin.**\n\n> **Cas A.** Yanis revient d'un séjour en Afrique tropicale, sans traitement préventif. Il a de fortes fièvres. Une analyse de sang montre un organisme **eucaryote unicellulaire** dans ses globules rouges.\n> **Cas B.** Émilie a fait une randonnée en forêt dans les Vosges. Quelques jours plus tard, une plaque rouge s'étend autour d'une petite morsure sur sa jambe. On identifie une **bactérie**.\n> **Cas C.** Paul a de la fièvre et des courbatures en plein hiver ; plusieurs collègues de son bureau ont les mêmes symptômes. L'agent **n'est pas une cellule**.\n\n1. Pour chaque cas, identifie la maladie probable, la famille de l'agent et le mode de transmission (et le vecteur s'il y en a un).\n2. Paul demande des antibiotiques. Le médecin refuse : pourquoi ?\n3. Explique pourquoi la lutte contre une maladie à vecteur est plus complexe qu'un simple problème de « transport » du microbe.\n4. Rédige un paragraphe montrant que la prévention **collective** compte autant que la protection **individuelle**, en prenant l'exemple du cas A ou du cas B.","bareme":[{"critere":"Cas A : paludisme, protozoaire Plasmodium, vectoriel par Anopheles","points":4},{"critere":"Cas B : maladie de Lyme, bactérie, vectoriel par la tique","points":3},{"critere":"Cas C : grippe, virus, transmission directe (gouttelettes, contact)","points":3},{"critere":"Refus d'antibiotiques justifié (virus non cellulaire)","points":3},{"critere":"Cycle du parasite dans le vecteur et paragraphe sur la prévention collective / individuelle","points":7}],"dureeMin":20,"corrige":"**1.**\n- **Cas A** : **paludisme**. Agent : un **protozoaire** (eucaryote unicellulaire) du genre ***Plasmodium***. Transmission **vectorielle** par le moustique ***Anopheles***.\n- **Cas B** : **maladie de Lyme**. Agent : une **bactérie**. Transmission **vectorielle** par la **tique**.\n- **Cas C** : **grippe** (probable). Agent : un **virus**. Transmission **directe** (gouttelettes, contacts) entre collègues ; indirecte par des objets acceptée.\n\n**2.** La grippe est due à un **virus**, qui n'est pas une cellule et doit parasiter une cellule hôte. Les antibiotiques n'agissent que sur les **bactéries** : ils seraient inefficaces ici.\n\n**3.** Un vecteur n'est pas seulement un moyen de transport : le parasite y accomplit souvent **une partie de son cycle** (c'est le cas du *Plasmodium* dans le moustique). Il faut donc agir à la fois sur l'agent, sur le vecteur et sur son environnement (gîtes, climat, contacts), ce qui rend la lutte plus complexe.\n\n**4. Exemple de paragraphe (cas A)**\nContre le paludisme, la protection individuelle est indispensable : **moustiquaires**, **répulsifs**, vêtements couvrants, traitement préventif pour le voyageur. Mais elle ne suffit pas : le moustique se reproduit dans les **eaux stagnantes**, et seule une action **collective** (élimination des gîtes larvaires, surveillance des cas, vaccination quand un vaccin existe) réduit durablement la population de vecteurs et la circulation du parasite. Chacun se protège mieux quand tout le monde agit : la prévention collective compte autant que la protection individuelle.\n\n(Le cas B est accepté : vêtements couvrants et inspection de la peau après une sortie en forêt / information et surveillance des cas.)"}$exo$::jsonb),
  ('0010119d-956f-5201-b8b5-69e3906ce682'::uuid, 1, 'application', $exo${"titre":"Mutualisme, commensalisme, parasitisme","consigne":"Réponds à chaque question en quelques lignes.","enonce":"1. Définis le **mutualisme**, le **commensalisme** et le **parasitisme**.\n2. Qu'est-ce que le **microbiote humain** ? Cite trois de ses sites.\n3. Cite **deux** fonctions du microbiote.","bareme":[{"critere":"Trois relations correctement définies","points":9},{"critere":"Microbiote défini avec trois sites","points":6},{"critere":"Deux fonctions justes","points":5}],"dureeMin":6,"corrige":"1.\n- **Mutualisme** (symbiose) : les **deux** partenaires y gagnent.\n- **Commensalisme** : l'un gagne, l'autre est **indifférent**.\n- **Parasitisme** : l'un gagne **aux dépens** de l'autre.\n\n2. Le **microbiote humain** est l'ensemble des micro-organismes vivant **sur et dans** le corps. Sites : intestin, peau, bouche, voies respiratoires, voies génitales.\n\n3. Deux fonctions parmi : **digestion** d'aliments que nous ne pouvons pas dégrader seuls ; **synthèse** de certaines vitamines ; **maturation immunitaire** (il éduque le système immunitaire) ; **effet barrière** (il occupe la place et empêche l'installation d'agents pathogènes)."}$exo$::jsonb),
  ('0010119d-956f-5201-b8b5-69e3906ce682'::uuid, 2, 'application', $exo${"titre":"Des haricots sans engrais azoté","consigne":"Exploite l'expérience et réponds en t'appuyant sur le cours.","enonce":"**Expérience.** On cultive des plants de haricot (une légumineuse) dans un sol **pauvre en azote**, sans aucun engrais, pendant six semaines.\n\n| Lot | Sol | Nodosités sur les racines | Masse sèche moyenne d'un plant |\n| 1 | Stérilisé | Aucune | 2,0 g |\n| 2 | Stérilisé puis enrichi en bactéries *Rhizobium* | Nombreuses | 5,0 g |\n\n1. Calcule par combien la masse du lot 2 est multipliée par rapport au lot 1.\n2. Quel est le seul facteur qui varie entre les deux lots ? Que peut-on en conclure ?\n3. Explique ce que chaque partenaire apporte à l'autre dans cette association. De quel type de relation s'agit-il ?\n4. Cite une autre symbiose du cours et ce qu'elle apporte.","bareme":[{"critere":"Calcul juste : ×2,5","points":3},{"critere":"Facteur unique identifié (présence de Rhizobium) et conclusion","points":5},{"critere":"Azote fixé de l'air contre sucre ; mutualisme nommé","points":7},{"critere":"Autre symbiose juste (mycorhizes ou ruminants) et son apport","points":5}],"dureeMin":12,"corrige":"1. 5,0 ÷ 2,0 = **2,5** : la masse est multipliée par 2,5.\n\n2. Seule la **présence des bactéries *Rhizobium*** varie (même plante, même sol pauvre en azote, même durée, pas d'engrais). On conclut que ces bactéries, associées aux racines (nodosités), permettent au haricot de pousser beaucoup mieux dans un sol pauvre en azote.\n\n3. La bactérie **fixe l'azote de l'air** et le fournit à la plante, qui manquait d'azote dans ce sol ; la plante fournit du **sucre** à la bactérie. Les deux y gagnent : c'est du **mutualisme** (une symbiose).\n\n4. Une autre symbiose parmi :\n- les **mycorhizes** (racines et champignons) : meilleure absorption d'eau et de minéraux pour la plupart des plantes ;\n- les **ruminants** et les micro-organismes du rumen : ils digèrent la **cellulose** que l'animal ne saurait dégrader."}$exo$::jsonb),
  ('0010119d-956f-5201-b8b5-69e3906ce682'::uuid, 3, 'application', $exo${"titre":"Un microbiote qui nous protège","consigne":"Exploite les documents et rédige une réponse structurée.","enonce":"**Document 1 — Souris infectées par une bactérie pathogène (*Salmonella*)**\n\n| Lot | Microbiote | Souris malades après infection |\n| A | Normal | 20 % |\n| B | Aucun (souris élevées sans germes) | 100 % |\n| C | Souris sans germes ayant reçu le microbiote de souris saines | 25 % |\n\n**Document 2.** Un nourrisson acquiert son microbiote à la naissance ; sa composition varie selon le mode d'accouchement, l'allaitement et l'environnement, puis se diversifie les premières années.\n\n**Document 3.** Chez un patient très immunodéprimé, un champignon présent habituellement dans la bouche sans provoquer de symptôme se met à proliférer et provoque une infection.\n\n1. Exploite le document 1 : que montre la comparaison des lots A et B, puis du lot C ? Quelle fonction du microbiote est mise en évidence ? Explique-la.\n2. D'après le document 2, explique pourquoi chaque individu possède un microbiote qui lui est propre.\n3. Quel qualificatif donne-t-on au champignon du document 3 ? Quelle leçon en tirer sur les relations entre espèces ?\n4. Conclus en un paragraphe sur l'idée que « tous les micro-organismes ne sont pas des ennemis ».","bareme":[{"critere":"Exploitation des lots A/B/C et effet barrière expliqué","points":6},{"critere":"Microbiote propre : naissance, allaitement, environnement, alimentation, âge","points":4},{"critere":"Micro-organisme opportuniste et changement de rôle expliqués","points":5},{"critere":"Conclusion argumentée (majorité neutre ou utile, fonctions, symbioses)","points":5}],"dureeMin":20,"corrige":"**1.** Sans microbiote (lot B), **100 %** des souris tombent malades, contre **20 %** avec un microbiote normal (lot A) : le microbiote protège contre la bactérie pathogène. Le lot C le confirme : en redonnant un microbiote à des souris sans germes, on retrouve presque la même protection (25 %). C'est bien le microbiote, et non une autre différence, qui protège. La fonction mise en évidence est l'**effet barrière** : en **occupant la place**, le microbiote empêche l'installation des agents pathogènes.\n\n**2.** Le microbiote se met en place **dès la naissance** et dépend du **mode d'accouchement**, de l'**allaitement** et de l'**environnement** ; il se **diversifie** les premières années, puis se stabilise tout en variant avec l'**alimentation**, l'**âge**, les **traitements** et le **mode de vie**. Ces facteurs étant différents pour chacun, chaque individu possède un microbiote qui lui est **propre**.\n\n**3.** C'est un micro-organisme **opportuniste** : habituellement inoffensif, il devient pathogène quand les défenses de l'hôte sont affaiblies. Une même espèce peut donc **changer de rôle** : la relation dépend aussi de l'état de l'hôte.\n\n**4. Exemple de conclusion**\nL'immense majorité des micro-organismes qui vivent avec nous sont **neutres ou utiles**. Le microbiote, dont le nombre de cellules est du même ordre de grandeur que celui des cellules du corps, nous aide à **digérer**, **synthétise** des vitamines, **éduque** notre système immunitaire et nous **protège** par l'effet barrière. Dans la nature, des symbioses comme celles des légumineuses et des *Rhizobium*, des mycorhizes ou du rumen rendent possibles les prairies, les forêts et l'élevage. Seule une minorité est pathogène, et certains ne le deviennent que lorsque les défenses faiblissent."}$exo$::jsonb),
  ('6530a7c1-37a2-5161-b514-5f5f4e147825'::uuid, 1, 'application', $exo${"titre":"Le microbiote intestinal","consigne":"Réponds à chaque question en quelques lignes.","enonce":"1. Où se concentre l'essentiel du microbiote intestinal ?\n2. Que produit le microbiote en dégradant les fibres alimentaires, et à quoi cela sert-il ?\n3. Cite **deux** vitamines (ou groupes de vitamines) qu'il contribue à synthétiser.\n4. Définis la **dysbiose** et cite deux facteurs qui peuvent la provoquer.","bareme":[{"critere":"Côlon","points":3},{"critere":"Acides gras à chaîne courte utilisés par la paroi intestinale","points":5},{"critere":"Vitamine K et vitamines du groupe B","points":4},{"critere":"Dysbiose définie avec deux facteurs justes","points":8}],"dureeMin":7,"corrige":"1. Dans le **côlon**.\n\n2. Nos enzymes ne savent pas digérer les fibres ; le microbiote les dégrade et en tire des **acides gras à chaîne courte**, utilisés par la **paroi intestinale**.\n\n3. La **vitamine K** et des **vitamines du groupe B**.\n\n4. La **dysbiose** est un **déséquilibre durable** de la composition du microbiote. Facteurs : les **antibiotiques** (qui détruisent aussi les bactéries utiles), une alimentation **pauvre en fibres** et riche en produits ultratransformés, certaines **infections**, le **stress chronique**."}$exo$::jsonb),
  ('6530a7c1-37a2-5161-b514-5f5f4e147825'::uuid, 2, 'application', $exo${"titre":"Le microbiote de Maxime après son angine","consigne":"Exploite les données et réponds en t'appuyant sur le cours.","enonce":"**Situation.** Maxime a pris un traitement antibiotique d'une semaine contre une angine bactérienne. On a mesuré la diversité de son microbiote intestinal (nombre d'espèces bactériennes détectées).\n\n| Moment | Avant | Fin du traitement | 1 mois après | 3 mois après |\n| Espèces détectées | 400 | 240 | 330 | 380 |\n\n1. Calcule la baisse en pourcentage à la fin du traitement, puis décris l'évolution ensuite.\n2. Explique pourquoi un antibiotique contre une angine agit aussi sur l'intestin.\n3. La sœur de Maxime a un rhume et réclame le même antibiotique. Que lui répondre ?\n4. Propose deux habitudes alimentaires qui aident à entretenir l'équilibre du microbiote, et explique la différence entre probiotique et prébiotique.","bareme":[{"critere":"Baisse de 40 % calculée et retour progressif décrit","points":4},{"critere":"Antibiotique non sélectif : détruit aussi les bactéries utiles","points":5},{"critere":"Antibiotique inefficace sur un virus (rhume)","points":5},{"critere":"Deux habitudes (fibres, aliments fermentés) et probiotique / prébiotique distingués","points":6}],"dureeMin":12,"corrige":"1. Baisse : 400 − 240 = 160 espèces ; 160 ÷ 400 × 100 = **40 %**. Ensuite, la diversité **remonte progressivement** (330 à un mois, 380 à trois mois) sans retrouver tout à fait sa valeur de départ au bout de trois mois.\n\n2. L'antibiotique est transporté dans tout l'organisme et agit sur les **bactéries** en général : il détruit la bactérie de l'angine, mais aussi des **bactéries utiles** du microbiote intestinal. C'est un facteur de **dysbiose**.\n\n3. Un rhume est dû à un **virus** : les antibiotiques n'agissent que sur les bactéries, ils seraient **inefficaces** et perturberaient inutilement son microbiote. Il faut un usage **raisonné** des antibiotiques.\n\n4. Habitudes : une alimentation **variée et riche en fibres** (légumes, légumineuses, céréales complètes, fruits) ; des **aliments fermentés** (yaourts…). Les **probiotiques** apportent des **micro-organismes vivants** ; les **prébiotiques** **nourrissent** ceux déjà présents (les fibres en sont un exemple)."}$exo$::jsonb),
  ('6530a7c1-37a2-5161-b514-5f5f4e147825'::uuid, 3, 'application', $exo${"titre":"Microbiote et santé : corrélation ou cause ?","consigne":"Analyse les documents avec rigueur et rédige une réponse argumentée.","enonce":"**Document 1 — Titre d'un article en ligne :** « Les bactéries de l'intestin rendent obèse ! »\n\n**Document 2 — Étude sur 500 adultes (fictive).** Les personnes atteintes d'obésité ont, en moyenne, un microbiote **moins diversifié** que les autres.\n\n**Document 3.** Un patient souffre d'infections récidivantes à *Clostridioides difficile* malgré plusieurs traitements antibiotiques. On lui fait une **transplantation de microbiote fécal** issue d'un donneur sain : les infections cessent.\n\n1. Le titre du document 1 est-il justifié par le document 2 ? Explique la différence entre une **association** et une **cause démontrée**, en citant ce que le cours dit du lien entre dysbiose et obésité.\n2. Propose une autre explication possible au résultat du document 2 (un facteur qui pourrait agir à la fois sur le poids et sur le microbiote).\n3. Explique le succès de la transplantation du document 3 en reliant les fonctions du microbiote et l'effet des antibiotiques.\n4. Conclus en expliquant pourquoi on dit que le microbiote intestinal est « un organe à part entière ».","bareme":[{"critere":"Titre non justifié : association et non cause démontrée","points":5},{"critere":"Facteur commun plausible issu du cours (alimentation pauvre en fibres, ultratransformés…)","points":4},{"critere":"Transplantation : rétablit un microbiote fonctionnel, effet barrière, antibiotiques qui détruisent les bactéries utiles","points":6},{"critere":"Conclusion : fonctions multiples, construction commune avec paroi et immunité","points":5}],"dureeMin":20,"corrige":"**1.** Non. Le document 2 montre seulement que deux faits **vont ensemble** : obésité et microbiote peu diversifié. C'est une **association** (une corrélation). Une **cause démontrée** exigerait de montrer que modifier le microbiote **provoque** la prise de poids. Le cours précise que la dysbiose est **associée** à l'obésité et au diabète de type 2, mais que ce n'est **pas une cause démontrée**. Le titre affirme donc plus que ce que montrent les données.\n\n**2.** Un facteur commun peut expliquer les deux : une alimentation **pauvre en fibres** et **riche en produits ultratransformés** peut à la fois favoriser la prise de poids et **appauvrir la diversité** du microbiote. D'autres facteurs sont acceptés (stress chronique, prises répétées d'antibiotiques) s'ils sont justifiés.\n\n**3.** Les antibiotiques répétés ont détruit aussi les **bactéries utiles** : le microbiote déséquilibré ne joue plus son **effet barrière**, et *Clostridioides difficile* s'installe et revient. La transplantation apporte le microbiote **fonctionnel** d'un donneur sain : ses bactéries **occupent de nouveau la place**, empêchent la bactérie pathogène de proliférer et rétablissent l'équilibre, là où les antibiotiques échouent. C'est aujourd'hui un **traitement reconnu** de ces infections récidivantes.\n\n**4.** Le microbiote intestinal n'est pas un simple passager : il **dégrade les fibres** (acides gras à chaîne courte pour la paroi), **synthétise** des vitamines (K, groupe B), **éduque l'immunité** intestinale et exerce un **effet barrière**. La paroi intestinale, le système immunitaire et le microbiote se **construisent ensemble**. Par ses fonctions propres et indispensables, il se comporte comme un organe à part entière."}$exo$::jsonb)
) AS v (chapter_id, difficulte, style, contenu)
JOIN public.chapters c ON c.id = v.chapter_id
ON CONFLICT (id) DO UPDATE
  SET style      = EXCLUDED.style,
      contenu    = EXCLUDED.contenu,
      difficulte = EXCLUDED.difficulte,
      origine    = 'catalogue';

